  e$subArea <- rt_recs(3, T_TSubarea)
  e$width <- 0
  e$area <- 0
  e$fracImperv <- 0
  e$slope <- 0
  e$curbLength <- 0
  e$initBuildup <- NULL
  e$landFactor <- NULL
  e$groundwater <- NULL
  e$gwLatFlowExpr <- NULL
  e$gwDeepFlowExpr <- NULL
  e$snowpack <- NULL
  e$nPervPattern <- 0
  e$dStorePattern <- 0
  e$infilPattern <- 0
  e$lidArea <- 0
  e$rainfall <- 0
  e$evapLoss <- 0
  e$infilLoss <- 0
  e$runon <- 0
  e$oldRunoff <- 0
  e$newRunoff <- 0
  e$oldSnowDepth <- 0
  e$newSnowDepth <- 0
  e$oldQual <- NULL
  e$newQual <- NULL
  e$pondedQual <- NULL
  e$totalLoad <- NULL
  e
}
K_TSubcatch <- function(s) {
  e <- T_TSubcatch()
  C_TSubcatch(e, s)
  e
}
C_TSubcatch <- function(d, s) {
  d$ID <- s$ID
  d$rptFlag <- s$rptFlag
  d$gage <- s$gage
  d$outNode <- s$outNode
  d$outSubcatch <- s$outSubcatch
  d$infilModel <- s$infilModel
  d$infil <- s$infil
  for (i in seq_along(s$subArea)) C_TSubarea(d$subArea[[i]], s$subArea[[i]])
  d$width <- s$width
  d$area <- s$area
  d$fracImperv <- s$fracImperv
  d$slope <- s$slope
  d$curbLength <- s$curbLength
  d$initBuildup <- s$initBuildup
  d$landFactor <- s$landFactor
  d$groundwater <- s$groundwater
  d$gwLatFlowExpr <- s$gwLatFlowExpr
  d$gwDeepFlowExpr <- s$gwDeepFlowExpr
  d$snowpack <- s$snowpack
  d$nPervPattern <- s$nPervPattern
  d$dStorePattern <- s$dStorePattern
  d$infilPattern <- s$infilPattern
  d$lidArea <- s$lidArea
  d$rainfall <- s$rainfall
  d$evapLoss <- s$evapLoss
  d$infilLoss <- s$infilLoss
  d$runon <- s$runon
  d$oldRunoff <- s$oldRunoff
  d$newRunoff <- s$newRunoff
  d$oldSnowDepth <- s$oldSnowDepth
  d$newSnowDepth <- s$newSnowDepth
  d$oldQual <- s$oldQual
  d$newQual <- s$newQual
  d$pondedQual <- s$pondedQual
  d$totalLoad <- s$totalLoad
  invisible(d)
}

