# climate.c:480
climate_validate <- function() {
  .G_Adjust <- Adjust; .G_Evap <- Evap; .G_Fclimate <- Fclimate; .G_Snow <- Snow; .G_Temp <- Temp; .G_UnitSystem <- UnitSystem
  pa <- 0
  if (((Wind$type == 1) || (.G_Evap$type == 4)) || (.G_Evap$type == 3)) {
    if (.G_Fclimate$mode == 0) {
      report_writeErrorMsg(336, .L0)
    }
  }
  if (.G_Fclimate$mode == 2) {
    climate_openFile()
  }
  if ((((!is.na(.c <- (.G_Snow$tipm < 0)) && .c) || (!is.na(.c <- (.G_Snow$tipm > 1)) && .c)) || (!is.na(.c <- (.G_Snow$rnm < 0)) && .c)) || (!is.na(.c <- (.G_Snow$rnm > 1)) && .c)) {
    report_writeErrorMsg(181, .L0)
  }
  a <- .G_Temp$anglat
  if ((!is.na(.c <- (a <= (-89.99))) && .c) || (!is.na(.c <- (a >= 89.99)) && .c)) {
    report_writeErrorMsg(181, .L0)
  } else {
    .G_Temp$tanAnglat <- tan((a * 3.141592654) / 180)
  }
  z <- .G_Temp$elev / 1000
  if (!is.na(.c <- (z <= 0)) && .c) {
    pa <- 29.9
  } else {
    pa <- (29.9 - (1.02 * z)) + (0.0032 * (if ((.p <- z) > -Inf || is.na(.p)) .p ^ 2.4 else rt_pow(.p, 2.4)))
  }
  .G_Temp$gamma <- 0.000359 * pa
  i <- 0
  while (i < 12) {
    if (.G_UnitSystem == 1) {
      {.e1 <- .G_Adjust$temp; .e1$v[[i + 1]] <- .G_Adjust$temp$v[[i + 1]] * (9 / 5)}
    }
    {.e2 <- .G_Adjust$evap; .e2$v[[i + 1]] <- .G_Adjust$evap$v[[i + 1]] / (UCF(2))}
    i <- i + 1
  }
}

# climate.c:531
climate_openFile <- function() {
  .G_Fclimate <- Fclimate; .G_FileData <- FileData; .G_FileDay <- FileDay; .G_FileLine <- FileLine; .G_FileMonth <- FileMonth; .G_FileValue <- FileValue; .G_FileYear <- FileYear; .G_Temp <- Temp
  i <- 0
  m <- 0
  y <- 0
  if (is.null((.G_Fclimate$file <- rt_fopen(.G_Fclimate$name, .L13)))) {
    report_writeErrorMsg(337, .G_Fclimate$name)
    return(invisible(NULL))
  }
  .G_FileValue$v[[1]] <- .G_Temp$ta
  .G_FileValue$v[[2]] <- .G_Temp$ta
  .G_FileValue$v[[3]] <- 0
  .G_FileValue$v[[4]] <- 0
  FileFormat <<- getFileFormat()
  if (FileFormat == 0) {
    report_writeErrorMsg(338, .G_Fclimate$name)
    return(invisible(NULL))
  }
  rt_rewind(.G_Fclimate$file)
  sstrncpy(.G_FileLine, .L0, 0)
  if (!is.na(.c <- (.G_Temp$fileStartDate == (-693594))) && .c) {
    datetime_decodeDate(StartDate$v, .G_FileYear, .G_FileMonth, .G_FileDay)
  } else {
    datetime_decodeDate(.G_Temp$fileStartDate, .G_FileYear, .G_FileMonth, .G_FileDay)
  }
  while (!(rt_feof(.G_Fclimate$file) != 0)) {
    sstrncpy(.G_FileLine, .L0, 0)
    {.BX_climate_openFile_y$v <- y; .BX_climate_openFile_m$v <- m; .r1 <- readFileLine(.BX_climate_openFile_y, .BX_climate_openFile_m); y <- .BX_climate_openFile_y$v; m <- .BX_climate_openFile_m$v; .r1}
    if ((y == .G_FileYear$v) && (m == .G_FileMonth$v)) {
      break
    }
  }
  if (rt_feof(.G_Fclimate$file) != 0) {
    report_writeErrorMsg(339, .G_Fclimate$name)
    return(invisible(NULL))
  }
  if (!(ErrorCode != 0)) {
    FileElapsedDays <<- 0
    FileLastDay <<- datetime_daysPerMonth(.G_FileYear$v, .G_FileMonth$v)
    readFileValues()
    i <- 0
    while (i <= 3) {
      if (!is.na(.c <- ((.G_FileData$v[[i + 1]])$v[[.G_FileDay$v + 1]] == (-10000000000))) && .c) {
        i <- i + 1
        next
      }
      .G_FileValue$v[[i + 1]] <- (.G_FileData$v[[i + 1]])$v[[.G_FileDay$v + 1]]
      i <- i + 1
    }
  }
}

# climate.c:598
climate_initState <- function() {
  .G_Evap <- Evap; .G_NextEvapDate <- NextEvapDate; .G_NextEvapRate <- NextEvapRate; .G_StartDate <- StartDate; .G_Tma <- Tma
  LastDay <<- -693594
  {.e1 <- Temp; .e1$tmax <- -10000000000}
  {.e2 <- Snow; .e2$removed <- 0}
  .G_NextEvapDate$v <- .G_StartDate$v
  .G_NextEvapRate$v <- 0
  if ((.G_Evap$type == 2) && (.G_Evap$tSeries >= 0)) {
    table_getFirstEntry(Tseries[[.G_Evap$tSeries + 1]], .G_NextEvapDate, .G_NextEvapRate)
    if (!is.na(.c <- (.G_NextEvapDate$v < .G_StartDate$v)) && .c) {
      setNextEvapDate(.G_StartDate$v)
    }
    .G_Evap$rate <- .G_NextEvapRate$v / (UCF(2))
    setNextEvapDate(.G_NextEvapDate$v)
  }
