# climate.c:671
setNextEvapDate <- function(theDate) {
  theDate
  .G_EndDateTime <- EndDateTime; .G_Evap <- Evap; .G_NextEvapDate <- NextEvapDate; .G_NextEvapRate <- NextEvapRate; .G_Tseries <- Tseries
  yr <- 0
