  d <- 0
  e <- 0
  if (!is.na(.c <- (.G_NextEvapDate$v > theDate)) && .c) {
    return(invisible(NULL))
  }
  .sw1 <- .G_Evap$type
  if (.sw1 == 0) {
    .G_NextEvapDate$v <- theDate + 365
  } else if (.sw1 == 1) {
    {.BX_setNextEvapDate_yr$v <- yr; .BX_setNextEvapDate_mon$v <- mon; .BX_setNextEvapDate_day$v <- day; .r2 <- datetime_decodeDate(theDate, .BX_setNextEvapDate_yr, .BX_setNextEvapDate_mon, .BX_setNextEvapDate_day); yr <- .BX_setNextEvapDate_yr$v; mon <- .BX_setNextEvapDate_mon$v; day <- .BX_setNextEvapDate_day$v; .r2}
    if (mon == 12) {
      mon <- 1
      yr <- yr + 1
    } else {
      mon <- mon + 1
    }
    .G_NextEvapDate$v <- datetime_encodeDate(yr, mon, 1)
  } else if (.sw1 == 2) {
    k <- .G_Evap$tSeries
    if (k >= 0) {
      .G_NextEvapDate$v <- theDate + 365
      while (({.BX_setNextEvapDate_d$v <- d; .BX_setNextEvapDate_e$v <- e; .r3 <- table_getNextEntry(.G_Tseries[[k + 1]], .BX_setNextEvapDate_d, .BX_setNextEvapDate_e); d <- .BX_setNextEvapDate_d$v; e <- .BX_setNextEvapDate_e$v; .r3} != 0) && (!is.na(.c <- (d <= .G_EndDateTime)) && .c)) {
        if (!is.na(.c <- (d >= theDate)) && .c) {
          .G_NextEvapDate$v <- d
          .G_NextEvapRate$v <- e
          break
        }
      }
    }
  } else if (.sw1 == 4) {
    .G_NextEvapDate$v <- floor(theDate) + 1
  } else {
    .G_NextEvapDate$v <- theDate + 365
  }
}

# climate.c:734
updateFileValues <- function(theDate) {
  theDate
  .G_FileData <- FileData; .G_FileDay <- FileDay; .G_FileMonth <- FileMonth; .G_FileValue <- FileValue; .G_FileYear <- FileYear
  i <- 0
  deltaDays <- if (is.na(.d <- floor(theDate) - (floor(StartDateTime))) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  if (deltaDays > FileElapsedDays) {
    FileElapsedDays <<- FileElapsedDays + 1
    .G_FileDay$v <- .G_FileDay$v + 1
    if (.G_FileDay$v > FileLastDay) {
      .G_FileMonth$v <- .G_FileMonth$v + 1
      if (.G_FileMonth$v > 12) {
        .G_FileMonth$v <- 1
        .G_FileYear$v <- .G_FileYear$v + 1
      }
      readFileValues()
      .G_FileDay$v <- 1
      FileLastDay <<- datetime_daysPerMonth(.G_FileYear$v, .G_FileMonth$v)
    }
    i <- 0
    while (i <= 3) {
      if (!is.na(.c <- ((.G_FileData$v[[i + 1]])$v[[.G_FileDay$v + 1]] == (-10000000000))) && .c) {
        i <- i + 1
        next
      }
      .G_FileValue$v[[i + 1]] <- (.G_FileData$v[[i + 1]])$v[[.G_FileDay$v + 1]]
      i <- i + 1
    }
  }
}

# climate.c:782
setTemp <- function(theDate) {
  theDate
  .G_Adjust <- Adjust; .G_FileValue <- FileValue; .G_Nobjects <- Nobjects; .G_Snow <- Snow; .G_Temp <- Temp; .G_Tma <- Tma
  j <- 0
  k <- 0
  day <- 0
  hour <- 0
  tmp <- 0
  mon <- datetime_monthOfYear(theDate)
  theDay <- floor(theDate)
  if (!is.na(.c <- (theDay > LastDay)) && .c) {
    day <- datetime_dayOfYear(theDate)
    if (.G_Temp$dataSource == 2) {
      Tmin <<- .G_FileValue$v[[1]] + .G_Adjust$temp$v[[mon]]
      Tmax <<- .G_FileValue$v[[2]] + .G_Adjust$temp$v[[mon]]
      if (!is.na(.c <- (Tmin > Tmax)) && .c) {
        tmp <- Tmin
        Tmin <<- Tmax
        Tmax <<- tmp
      }
      updateTempTimes(day)
      if (Evap$type == 3) {
        updateTempMoveAve(Tmin, Tmax)
        .G_FileValue$v[[3]] <- getTempEvap(day, .G_Tma$tAve, .G_Tma$tRng)
      }
    }
    .G_Snow$season <- sin(0.0172615 * (day - 81))
    j <- 0
    while (j < .G_Nobjects$v[[14]]) {
      snow_setMeltCoeffs(j, .G_Snow$season)
      j <- j + 1
    }
    LastDay <<- theDate
  }
  if (.G_Temp$dataSource == 2) {
    hour <- (theDate - theDay) * 24
    if (!is.na(.c <- (hour < Hrsr)) && .c) {
      .G_Temp$ta <- Tmin + ((Trng1 / 2) * (sin((3.141592654 / Dydif) * (Hrsr - hour))))
    } else if ((!is.na(.c <- (hour >= Hrsr)) && .c) && (!is.na(.c <- (hour <= Hrss)) && .c)) {
      .G_Temp$ta <- Tave + (Trng * (sin((3.141592654 / Dhrdy) * (Hrday - hour))))
    } else {
      .G_Temp$ta <- Tmax - (Trng * (sin((3.141592654 / Dydif) * (hour - Hrss))))
    }
  }
  if (.G_Temp$dataSource == 1) {
    k <- .G_Temp$tSeries
    if (k >= 0) {
      .G_Temp$ta <- table_tseriesLookup(Tseries[[k + 1]], theDate, 1)
      if (UnitSystem == 1) {
        .G_Temp$ta <- ((9 / 5) * .G_Temp$ta) + 32
      }
      .G_Temp$ta <- .G_Temp$ta + (.G_Adjust$temp$v[[mon]])
    }
  }
  .G_Temp$ea <- 8117500 * (exp((-7701.544) / (.G_Temp$ta + 405.0265)))
}

# climate.c:872
setEvap <- function(theDate) {
  theDate
  .G_Evap <- Evap; .G_FileValue <- FileValue; .G_Pattern <- Pattern
  mon <- datetime_monthOfYear(theDate)
  .sw1 <- .G_Evap$type
  if (.sw1 == 0) {
    .G_Evap$rate <- .G_Evap$monthlyEvap$v[[1]] / (UCF(2))
  } else if (.sw1 == 1) {
    .G_Evap$rate <- .G_Evap$monthlyEvap$v[[mon]] / (UCF(2))
  } else if (.sw1 == 2) {
    if (!is.na(.c <- (theDate >= NextEvapDate$v)) && .c) {
      .G_Evap$rate <- NextEvapRate$v / (UCF(2))
    }
  } else if (.sw1 == 4) {
    .G_Evap$rate <- .G_FileValue$v[[3]] / (UCF(2))
    .G_Evap$rate <- .G_Evap$rate * (.G_Evap$panCoeff$v[[mon]])
  } else if (.sw1 == 3) {
    .G_Evap$rate <- .G_FileValue$v[[3]] / (UCF(2))
  } else {
    .G_Evap$rate <- 0
  }
  .G_Evap$rate <- .G_Evap$rate + (Adjust$evap$v[[mon]])
  .G_Evap$recoveryFactor <- 1
  k <- .G_Evap$recoveryPattern
  if ((k >= 0) && ((.G_Pattern[[k + 1]])$type == 0)) {
    .G_Evap$recoveryFactor <- ((.G_Pattern[[k + 1]])$factor)$v[[mon]]
  }
}

