# climate.c:949
updateTempTimes <- function(day) {
  day
  .G_Temp <- Temp; .G_Tmax <- Tmax; .G_Tmin <- Tmin
  decl <- 0.40928 * (cos(0.017202 * (172 - day)))
  arg <- (-(tan(decl))) * .G_Temp$tanAnglat
  if (!is.na(.c <- (arg <= (-1))) && .c) {
    arg <- 3.141592654
  } else if (!is.na(.c <- (arg >= 1)) && .c) {
    arg <- 0
  } else {
    arg <- acos(arg)
  }
  hrang <- 3.8197 * arg
  Hrsr <<- (12 - hrang) + .G_Temp$dtlong
  Hrss <<- ((12 + hrang) + .G_Temp$dtlong) - 3
  Dhrdy <<- Hrsr - Hrss
  Dydif <<- (24 + Hrsr) - Hrss
  Hrday <<- (Hrsr + Hrss) / 2
  Tave <<- (.G_Tmin + .G_Tmax) / 2
  Trng <<- (.G_Tmax - .G_Tmin) / 2
  if (!is.na(.c <- (.G_Temp$tmax == (-10000000000))) && .c) {
    Trng1 <<- .G_Tmax - .G_Tmin
  } else {
    Trng1 <<- .G_Temp$tmax - .G_Tmin
  }
  .G_Temp$tmax <- .G_Tmax
}

# climate.c:981
getTempEvap <- function(day, tave, trng) {
  day; tave; trng
  a <- (2 * 3.141592654) / 365
  ta <- ((tave - 32) * 5) / 9
  tr <- (trng * 5) / 9
  lamda <- 2.5 - (0.002361 * ta)
  dr <- 1 + (0.033 * (cos(a * day)))
  phi <- ((Temp$anglat * 2) * 3.141592654) / 360
  del <- 0.4093 * (sin(a * (284 + day)))
  omega <- acos((-(tan(phi))) * (tan(del)))
  ra <- (37.6 * dr) * (((omega * (sin(phi))) * (sin(del))) + ((cos(phi) * (cos(del))) * (sin(omega))))
  e <- (((0.0023 * ra) / lamda) * (sqrt(tr))) * (ta + 17.8)
  if (!is.na(.c <- (e < 0)) && .c) {
    e <- 0
  }
  if (UnitSystem == 0) {
    e <- e / 25.4
  }
  return(e)
}

