    }
  }
  n <- {.BX_getFileFormat_y$v <- y; .BX_getFileFormat_m$v <- m; .BX_getFileFormat_d$v <- d; .r1 <- rt_sscanf(line, .L16, list(staID, list("i", .BX_getFileFormat_y), list("i", .BX_getFileFormat_m), list("i", .BX_getFileFormat_d), s)); y <- .BX_getFileFormat_y$v; m <- .BX_getFileFormat_m$v; d <- .BX_getFileFormat_d$v; .r1}
  if (n == 5) {
