# climate.c:1271
setTD3200FileValues <- function(i) {
  i
  .G_FileData <- FileData; .G_FileLine <- FileLine; .G_UnitSystem <- UnitSystem
  valCount <- rt_cbuf_from(.L0, 4)
  day <- rt_cbuf_from(.L0, 3)
  sign_ <- rt_cbuf_from(.L0, 2)
  value <- rt_cbuf_from(.L0, 6)
  flag2 <- rt_cbuf_from(.L0, 2)
  x <- 0
  j <- 0
  k <- 0
  d <- 0
  sstrncpy(valCount, rt_cadd(.G_FileLine, 27), 3)
  nValues <- rt_atoi(valCount)
  if (rt_i32(rt_strlen(.G_FileLine)) >= ((12 * nValues) + 30)) {
    j <- 0
    while (j < nValues) {
      k <- 30 + (j * 12)
      sstrncpy(day, rt_cadd(.G_FileLine, k), 2)
      sstrncpy(sign_, rt_cadd(.G_FileLine, (k + 4)), 1)
      sstrncpy(value, rt_cadd(.G_FileLine, (k + 5)), 5)
      sstrncpy(flag2, rt_cadd(.G_FileLine, (k + 11)), 1)
      d <- rt_atoi(day)
      if ((((rt_strcmp(value, .L19) != 0) && ((rt_cget(flag2, 0) == 48) || (rt_cget(flag2, 0) == 49))) && (d > 0)) && (d <= 31)) {
        x <- rt_atof(value)
        if (rt_cget(sign_, 0) == 45) {
          x <- -x
        }
        if (i == 2) {
          x <- x / 100
          if (.G_UnitSystem == 1) {
            x <- x * 25.4
          }
        }
        if (i == 3) {
          x <- x / 24
        }
        {.e1 <- .G_FileData$v[[i + 1]]; .e1$v[[d + 1]] <- x}
      }
      j <- j + 1
    }
  }
}

# climate.c:1336
parseDLY0204FileLine <- function() {
  .G_FileData <- FileData; .G_FileLine <- FileLine; .G_UnitSystem <- UnitSystem
  param <- rt_cbuf_from(.L0, 4)
  sign_ <- rt_cbuf_from(.L0, 2)
  value <- rt_cbuf_from(.L0, 6)
  code <- rt_cbuf_from(.L0, 2)
  x <- 0
  sstrncpy(param, rt_cadd(.G_FileLine, 13), 3)
  p <- rt_atoi(param)
  if (p == 1) {
    p <- 1
  } else if (p == 2) {
    p <- 0
  } else if (p == 151) {
    p <- 2
  } else {
    return(invisible(NULL))
  }
  if (rt_strlen(.G_FileLine) < 233) {
    return(invisible(NULL))
  }
  k <- 16
  j <- 1
  while (j <= 31) {
    sstrncpy(sign_, rt_cadd(.G_FileLine, k), 1)
    sstrncpy(value, rt_cadd(.G_FileLine, (k + 1)), 5)
    sstrncpy(code, rt_cadd(.G_FileLine, (k + 6)), 1)
    k <- k + 7
    if ((rt_strcmp(value, .L19) != 0) && (rt_strcmp(value, .L20) != 0)) {
      if (p == 1 || p == 0) {
        x <- rt_atof(value) / 10
        if (rt_cget(sign_, 0) == 45) {
          x <- -x
        }
        x <- ((9 / 5) * x) + 32
      } else if (p == 2) {
        x <- rt_atof(value) / 10
        if (.G_UnitSystem == 0) {
          x <- x / 25.4
        }
      } else {
        return(invisible(NULL))
      }
      {.e1 <- .G_FileData$v[[p + 1]]; .e1$v[[j + 1]] <- x}
    }
    j <- j + 1
  }
}

# climate.c:1401
isGhcndFormat <- function(line) {
  line
