# climate.c:1496
convertGhcndValue <- function(var_, v) {
  var_; v
  .G_FileTempUnits <- FileTempUnits; .G_FileWindType <- FileWindType; .G_UnitSystem <- UnitSystem
  .ft1 <- FALSE
  repeat {
    if (.ft1 || var_ == 0 || var_ == 1) {
      if (.G_FileTempUnits == 0) {
        return((((v / 10) * 9) / 5) + 32)
      } else if (.G_FileTempUnits == 1) {
        return(((v * 9) / 5) + 32)
      } else {
        return(v)
      }
      .ft1 <- TRUE
    }
    if (.ft1 || var_ == 2) {
      if (.G_FileTempUnits == 0) {
        v <- v / 10
        if (.G_UnitSystem == 0) {
          v <- v / 25.4
        }
        return(v)
      } else if (.G_FileTempUnits == 1) {
        if (.G_UnitSystem == 0) {
          v <- v / 25.4
        }
        return(v)
      } else {
        if (.G_UnitSystem == 1) {
          v <- v * 25.4
        }
        return(v)
      }
      .ft1 <- TRUE
    }
    if (.ft1 || var_ == 3) {
      if (.G_FileTempUnits == 0) {
        if (.G_FileWindType == 0) {
          return((v * 0.62137) / 24)
        } else {
          return((((v / 10) / 1000) * 0.62137) * 3600)
        }
      } else if (.G_FileTempUnits == 1) {
        if (.G_FileWindType == 0) {
          return((v * 0.62137) / 24)
        } else {
          return(((v / 1000) * 0.62137) * 3600)
        }
      } else {
        if (.G_FileWindType == 0) {
          return(v / 24)
        } else {
          return(v)
        }
      }
      .ft1 <- TRUE
    }
    if (.ft1 || (var_ != 0 && var_ != 1 && var_ != 2 && var_ != 3)) {
      return(v)
    }
    break
  }
}

# climate.c:1569
updateTempMoveAve <- function(tmin, tmax) {
  tmin; tmax
  .G_Tma <- Tma
  kount <- .G_Tma$count
  count <- kount
  ta <- (tmin + tmax) / 2
  tr <- abs(tmax - tmin)
  if (kount == .G_Tma$maxCount) {
    .G_Tma$tAve <- (((.G_Tma$tAve * count) + ta) - (.G_Tma$ta$v[[.G_Tma$front + 1]])) / count
    .G_Tma$tRng <- (((.G_Tma$tRng * count) + tr) - (.G_Tma$tr$v[[.G_Tma$front + 1]])) / count
    {.e1 <- .G_Tma$ta; .e1$v[[.G_Tma$front + 1]] <- ta}
    {.e2 <- .G_Tma$tr; .e2$v[[.G_Tma$front + 1]] <- tr}
    .G_Tma$front <- .G_Tma$front + 1
    if (!is.na(.c <- (.G_Tma$front == count)) && .c) {
      .G_Tma$front <- 0
    }
  } else {
    .G_Tma$tAve <- ((.G_Tma$tAve * count) + ta) / (count + 1)
    .G_Tma$tRng <- ((.G_Tma$tRng * count) + tr) / (count + 1)
    {.e3 <- .G_Tma$ta; .e3$v[[.G_Tma$front + 1]] <- ta}
    {.e4 <- .G_Tma$tr; .e4$v[[.G_Tma$front + 1]] <- tr}
    .G_Tma$count <- .G_Tma$count + 1
    .G_Tma$front <- .G_Tma$front + 1
    if (.G_Tma$count == .G_Tma$maxCount) {
      .G_Tma$front <- 0
    }
  }
}

