# controls.c:495
controls_evaluate <- function(currentTime, elapsedTime, tStep) {
  currentTime; elapsedTime; tStep
  .G_RuleCount <- RuleCount; .G_Rules <- Rules
  result <- 0
  p <- NULL
  a <- NULL
  CurrentDate <<- floor(currentTime)
  CurrentTime <<- currentTime - (floor(currentTime))
  ElapsedTime <<- elapsedTime
  if (.G_RuleCount == 0) {
    return(0)
  }
  clearActionList()
  r <- 0
  while (r < .G_RuleCount) {
    result <- 1
    p <- (.G_Rules[[r + 1]])$firstPremise
    while (!is.null(p)) {
      if (p$type == 3) {
        if (result == 0) {
          result <- evaluatePremise(p, tStep)
        }
      } else {
        if (result == 0) {
          break
        }
        result <- evaluatePremise(p, tStep)
      }
      p <- p$next_
    }
    if (result == 1) {
      a <- (.G_Rules[[r + 1]])$thenActions
    } else {
      a <- (.G_Rules[[r + 1]])$elseActions
    }
    while (!is.null(a)) {
      updateActionValue(a, currentTime, tStep)
      updateActionList(a)
      a <- a$next_
    }
    r <- r + 1
  }
  if (!is.null(ActionList)) {
    return(executeActionList(currentTime))
  } else {
    return(0)
  }
}

