    }
    if ((!is.na(.c <- (value$v < 1)) && .c) || (!is.na(.c <- (value$v > 7)) && .c)) {
      return(error_setInpError(213, token))
    }
  } else if (attrib == 20) {
    if (!(getDouble(token, value) != 0)) {
      return(error_setInpError(211, token))
    }
    if ((!is.na(.c <- (value$v < 1)) && .c) || (!is.na(.c <- (value$v > 12)) && .c)) {
      return(error_setInpError(213, token))
    }
  } else if (attrib == 18) {
    sstrncpy(strDate, token, 6)
