# controls.c:1111
getPIDSetting <- function(a, dt) {
  a; dt
  .G_ControlValue <- ControlValue; .G_Link <- Link; .G_SetPoint <- SetPoint
  i <- 0
  tolerance <- 0.0001
  dt <- dt * 1440
  e0 <- .G_SetPoint - .G_ControlValue
  if (!is.na(.c <- (abs(e0) > 1e-06)) && .c) {
    if (is.na(.c <- (.G_SetPoint != 0)) || .c) {
      e0 <- e0 / .G_SetPoint
    } else {
      e0 <- e0 / .G_ControlValue
    }
  }
  if (!is.na(.c <- (abs(e0 - a$e1) < tolerance)) && .c) {
    a$e2 <- 0
    a$e1 <- 0
  }
  p <- e0 - a$e1
  if (!is.na(.c <- (a$ki == 0)) && .c) {
    i <- 0
  } else {
    i <- (e0 * dt) / a$ki
  }
  d <- (a$kd * ((e0 - (2 * a$e1)) + a$e2)) / dt
  update <- a$kp * ((p + i) + d)
  if (!is.na(.c <- (abs(update) < tolerance)) && .c) {
    update <- 0
  }
  setting <- (.G_Link[[a$link + 1]])$targetSetting + update
  a$e2 <- a$e1
  a$e1 <- e0
  if (!is.na(.c <- (setting < 0)) && .c) {
    setting <- 0
  }
  if (((.G_Link[[a$link + 1]])$type != 1) && (!is.na(.c <- (setting > 1)) && .c)) {
    setting <- 1
  }
  return(setting)
}

