    if (!(!is.null(a1))) {
      break
    }
    if (a1$link == a$link) {
      if (!is.na(.c <- (priority > (.G_Rules[[a1$rule + 1]])$priority)) && .c) {
        listItem$action <- a
      }
      return(invisible(NULL))
    }
    listItem <- listItem$next_
  }
  if (!(!is.null(listItem))) {
    listItem <- T_TActionList()
    listItem$next_ <- ActionList
    ActionList <<- listItem
  }
  listItem$action <- a
}

