# controls.c:1405
compareTimes <- function(lhsValue, relation, rhsValue, halfStep) {
  lhsValue; relation; rhsValue; halfStep
  if (relation == 0) {
    if ((!is.na(.c <- (lhsValue >= (rhsValue - halfStep))) && .c) && (!is.na(.c <- (lhsValue < (rhsValue + halfStep))) && .c)) {
      return(1)
    }
    return(0)
  } else if (relation == 1) {
    if ((!is.na(.c <- (lhsValue < (rhsValue - halfStep))) && .c) || (!is.na(.c <- (lhsValue >= (rhsValue + halfStep))) && .c)) {
      return(1)
    }
    return(0)
  } else {
    return(compareValues(lhsValue, relation, rhsValue))
  }
}

# controls.c:1432
compareValues <- function(lhsValue, relation, rhsValue) {
  lhsValue; relation; rhsValue
  SetPoint <<- rhsValue
  ControlValue <<- lhsValue
  if (relation == 0) {
    if (!is.na(.c <- (lhsValue == rhsValue)) && .c) {
      return(1)
    }
  } else if (relation == 1) {
    if (is.na(.c <- (lhsValue != rhsValue)) || .c) {
      return(1)
    }
  } else if (relation == 2) {
    if (!is.na(.c <- (lhsValue < rhsValue)) && .c) {
      return(1)
    }
  } else if (relation == 3) {
    if (!is.na(.c <- (lhsValue <= rhsValue)) && .c) {
      return(1)
    }
  } else if (relation == 4) {
    if (!is.na(.c <- (lhsValue > rhsValue)) && .c) {
      return(1)
    }
  } else if (relation == 5) {
    if (!is.na(.c <- (lhsValue >= rhsValue)) && .c) {
      return(1)
    }
  }
  return(0)
}

