# culvert.c:174
culvert_getInflow <- function(j, q0, h) {
  j; q0; h
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Params <- Params
  condition <- 0
  y1 <- 0
  q_ <- 0
  culvert <- T_TCulvert()
  if ((.G_Link[[j + 1]])$type != 0) {
    return(q0)
  }
  culvert$xsect <- (.G_Link[[j + 1]])$xsect
  code <- culvert$xsect$culvertCode
  if ((code <= 0) || (code > MAX_CULVERT_CODE)) {
    return(q0)
  }
  k <- (.G_Link[[j + 1]])$subIndex
  culvert$yFull <- culvert$xsect$yFull
  culvert$ad <- culvert$xsect$aFull * (sqrt(culvert$yFull))
  if (code == 5 || code == 37 || code == 46) {
    culvert$scf <- (-7) * ((.G_Conduit[[k + 1]])$slope)
  } else {
    culvert$scf <- 0.5 * ((.G_Conduit[[k + 1]])$slope)
  }
  y <- h - ((Node[[(.G_Link[[j + 1]])$node1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1)
  y2 <- culvert$yFull * (((16 * ((.G_Params$v[[code + 1]])$v[[4]])) + (.G_Params$v[[code + 1]])$v[[5]]) - culvert$scf)
  if (!is.na(.c <- (y >= y2)) && .c) {
    q_ <- getSubmergedFlow(code, y, culvert)
    condition <- 2
  } else {
    y1 <- 0.95 * culvert$yFull
    if (!is.na(.c <- (y <= y1)) && .c) {
      q_ <- getUnsubmergedFlow(code, y, culvert)
      condition <- 1
    } else {
      q_ <- getTransitionFlow(code, y, y1, y2, culvert)
      condition <- 0
    }
  }
  if (!is.na(.c <- (q_ < q0)) && .c) {
    {.e1 <- .G_Link[[j + 1]]; .e1$inletControl <- 1}
    {.e2 <- .G_Link[[j + 1]]; .e2$dqdh <- culvert$dQdH}
    return(q_)
  } else {
    return(q0)
  }
}

# culvert.c:257
getUnsubmergedFlow <- function(code, h, culvert) {
  code; h; culvert
  .G_Params <- Params
  q_ <- 0
  culvert$kk <- (.G_Params$v[[code + 1]])$v[[2]]
