  z2 <- (.G_Link[[j + 1]])$offset2
  if ((.G_Node[[n1 + 1]])$type == 1) {
    z1 <- if (!is.na(.c <- (0 >= (z1 - ((.G_Node[[n1 + 1]])$newDepth)))) && .c) 0 else (z1 - ((.G_Node[[n1 + 1]])$newDepth))
  }
  if ((.G_Node[[n2 + 1]])$type == 1) {
    z2 <- if (!is.na(.c <- (0 >= (z2 - ((.G_Node[[n2 + 1]])$newDepth)))) && .c) 0 else (z2 - ((.G_Node[[n2 + 1]])$newDepth))
  }
