          flowClass <- 5
        }
      }
    } else {
      if (!is.na(.c <- (z2 > 0)) && .c) {
        yN$v <- link_getYnorm(j, abs(q_))
        yC$v <- link_getYcrit(j, abs(q_))
        ycMin <- if (!is.na(.c <- (yN$v <= yC$v)) && .c) yN$v else yC$v
        ycMax <- if (!is.na(.c <- (yN$v >= yC$v)) && .c) yN$v else yC$v
        if (!is.na(.c <- (y2 < ycMin)) && .c) {
          flowClass <- 6
        } else if (!is.na(.c <- (y2 < ycMax)) && .c) {
