findLocalLosses <- function(j, a1, a2, aMid, q_) {
  j; a1; a2; aMid; q_
  .G_Link <- Link
  losses <- 0
  q_ <- abs(q_)
  if (!is.na(.c <- (a1 > 0.0001)) && .c) {
    losses <- losses + ((.G_Link[[j + 1]])$cLossInlet * (q_ / a1))
  }
  if (!is.na(.c <- (a2 > 0.0001)) && .c) {
    losses <- losses + ((.G_Link[[j + 1]])$cLossOutlet * (q_ / a2))
  }
  if (!is.na(.c <- (aMid > 0.0001)) && .c) {
    losses <- losses + ((.G_Link[[j + 1]])$cLossAvg * (q_ / aMid))
  }
  return(losses)
}

