getSlotWidth <- function(xsect, y) {
  xsect; y
  yNorm <- y / xsect$yFull
  if (((SurchargeMethod != 1) || (xsect_isOpen(xsect$type) != 0)) || (!is.na(.c <- (yNorm < CrownCutoff)) && .c)) {
    return(0)
  }
  if (!is.na(.c <- (yNorm > 1.78)) && .c) {
    return(0.01 * xsect$wMax)
  }
  return((xsect$wMax * 0.5423) * (exp(-(if ((.p <- yNorm) > -Inf || is.na(.p)) .p ^ 2.4 else rt_pow(.p, 2.4)))))
}

# dwflow.c:592
dwflow_getWidth <- function(xsect, y) {
  xsect; y
  .G_CrownCutoff <- CrownCutoff
