  if (!is.na(.c <- (wSlot > 0)) && .c) {
    return(wSlot)
  }
  if ((!is.na(.c <- ((y / xsect$yFull) >= .G_CrownCutoff)) && .c) && (!(xsect_isOpen(xsect$type) != 0))) {
    y <- .G_CrownCutoff * xsect$yFull
