    j <- (.G_Link[[i + 1]])$node1
    z <- ((.G_Node[[j + 1]])$invertElev + (.G_Link[[i + 1]])$offset1) + ((.G_Link[[i + 1]])$xsect)$yFull
    {.e4 <- .G_Node[[j + 1]]; .e4$crownElev <- if (!is.na(.c <- (((.G_Node[[j + 1]])$crownElev) >= z)) && .c) ((.G_Node[[j + 1]])$crownElev) else z}
    j <- (.G_Link[[i + 1]])$node2
    z <- ((.G_Node[[j + 1]])$invertElev + (.G_Link[[i + 1]])$offset2) + ((.G_Link[[i + 1]])$xsect)$yFull
    {.e5 <- .G_Node[[j + 1]]; .e5$crownElev <- if (!is.na(.c <- (((.G_Node[[j + 1]])$crownElev) >= z)) && .c) ((.G_Node[[j + 1]])$crownElev) else z}
    {.e6 <- .G_Link[[i + 1]]; .e6$flowClass <- 0}
    {.e7 <- .G_Link[[i + 1]]; .e7$dqdh <- 0}
    i <- i + 1
  }
  if (SurchargeMethod == 1) {
    CrownCutoff <<- SLOT_CROWN_CUTOFF
  } else {
    CrownCutoff <<- EXTRAN_CROWN_CUTOFF
  }
}

