# dynwave.c:177
dynwave_validate <- function() {
  .G_HeadTol <- HeadTol; .G_MINTIMESTEP <- MINTIMESTEP; .G_MinRouteStep <- MinRouteStep; .G_MinSurfArea <- MinSurfArea; .G_RouteStep <- RouteStep
  if (!is.na(.c <- (.G_MinRouteStep$v > .G_RouteStep)) && .c) {
    .G_MinRouteStep$v <- .G_RouteStep
  }
  if (!is.na(.c <- (.G_MinRouteStep$v < .G_MINTIMESTEP)) && .c) {
    .G_MinRouteStep$v <- .G_MINTIMESTEP
  }
  if (!is.na(.c <- (.G_MinSurfArea$v == 0)) && .c) {
    .G_MinSurfArea$v <- DEFAULT_SURFAREA
  } else {
    .G_MinSurfArea$v <- .G_MinSurfArea$v / (UCF(3) * (UCF(3)))
  }
  if (!is.na(.c <- (.G_HeadTol$v == 0)) && .c) {
    .G_HeadTol$v <- DEFAULT_HEADTOL
  } else {
    .G_HeadTol$v <- .G_HeadTol$v / (UCF(3))
  }
  if (MaxTrials == 0) {
    MaxTrials <<- DEFAULT_MAXTRIALS
  }
}

# dynwave.c:195
dynwave_getRoutingStep <- function(fixedStep) {
  fixedStep
  if (!is.na(.c <- (CourantFactor$v == 0)) && .c) {
    return(fixedStep)
  }
  if (!is.na(.c <- (fixedStep < MINTIMESTEP)) && .c) {
    return(fixedStep)
  }
  if (!is.na(.c <- (VariableStep == 0)) && .c) {
    VariableStep <<- MinRouteStep$v
  } else {
    VariableStep <<- getVariableStep(fixedStep)
  }
  VariableStep <<- floor(1000 * VariableStep) / 1000
  return(VariableStep)
}

# dynwave.c:224
dynwave_execute <- function(tStep) {
  tStep
  .G_MaxTrials <- MaxTrials
  if (ErrorCode != 0) {
    return(0)
  }
  Steps <<- 0
  converged <- 0
  Omega <<- dynwave_OMEGA
  initRoutingStep()
  while (Steps < .G_MaxTrials) {
    initNodeStates()
    findLinkFlows(tStep)
    converged <- findNodeDepths(tStep)
    Steps <<- Steps + 1
    if (Steps > 1) {
      if (converged != 0) {
        break
      }
      findBypassedLinks()
    }
  }
  if (!(converged != 0)) {
    updateConvergenceStats()
  }
  findLimitedLinks()
  return(Steps)
}

# dynwave.c:266
updateConvergenceStats <- function() {
  .G_Nobjects <- Nobjects; .G_Xnode <- Xnode
  NonConvergeCount <<- NonConvergeCount + 1
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    stats_updateConvergenceStats(i, (.G_Xnode[[i + 1]])$converged)
    i <- i + 1
  }
}

# dynwave.c:276
initRoutingStep <- function() {
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Nlinks <- Nlinks; .G_Nobjects <- Nobjects; .G_Xnode <- Xnode
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    {.e1 <- .G_Xnode[[i + 1]]; .e1$converged <- 0}
    {.e2 <- .G_Xnode[[i + 1]]; .e2$dYdT <- 0}
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    {.e3 <- .G_Link[[i + 1]]; .e3$bypassed <- 0}
    {.e4 <- .G_Link[[i + 1]]; .e4$surfArea1 <- 0}
    {.e5 <- .G_Link[[i + 1]]; .e5$surfArea2 <- 0}
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nlinks$v[[1]]) {
    {.e6 <- .G_Conduit[[i + 1]]; .e6$a2 <- (.G_Conduit[[i + 1]])$a1}
    i <- i + 1
  }
}

# dynwave.c:297
initNodeStates <- function() {
  .G_AllowPonding <- AllowPonding; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Xnode <- Xnode
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if (.G_AllowPonding != 0) {
      {.e1 <- .G_Xnode[[i + 1]]; .e1$newSurfArea <- node_getPondedArea(i, (.G_Node[[i + 1]])$newDepth)}
    } else {
      {.e2 <- .G_Xnode[[i + 1]]; .e2$newSurfArea <- node_getSurfArea(i, (.G_Node[[i + 1]])$newDepth)}
    }
    {.e3 <- .G_Node[[i + 1]]; .e3$inflow <- 0}
    {.e4 <- .G_Node[[i + 1]]; .e4$outflow <- (.G_Node[[i + 1]])$losses}
    if (!is.na(.c <- ((.G_Node[[i + 1]])$newLatFlow >= 0)) && .c) {
      {.e5 <- .G_Node[[i + 1]]; .e5$inflow <- (.G_Node[[i + 1]])$inflow + ((.G_Node[[i + 1]])$newLatFlow)}
    } else {
      {.e6 <- .G_Node[[i + 1]]; .e6$outflow <- (.G_Node[[i + 1]])$outflow - ((.G_Node[[i + 1]])$newLatFlow)}
    }
    {.e7 <- .G_Xnode[[i + 1]]; .e7$sumdqdh <- 0}
    i <- i + 1
  }
}

# dynwave.c:335
findBypassedLinks <- function() {
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Xnode <- Xnode
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    if (((.G_Xnode[[(.G_Link[[i + 1]])$node1 + 1]])$converged != 0) && ((.G_Xnode[[(.G_Link[[i + 1]])$node2 + 1]])$converged != 0)) {
      {.e1 <- .G_Link[[i + 1]]; .e1$bypassed <- 1}
    } else {
      {.e2 <- .G_Link[[i + 1]]; .e2$bypassed <- 0}
    }
    i <- i + 1
  }
}

# dynwave.c:349
findLimitedLinks <- function() {
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node
  n1 <- 0
  n2 <- 0
  k <- 0
  h1 <- 0
  h2 <- 0
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    if (!(isTrueConduit(j) != 0)) {
      j <- j + 1
      next
    }
    k <- (.G_Link[[j + 1]])$subIndex
    {.e1 <- .G_Conduit[[k + 1]]; .e1$capacityLimited <- 0}
    if (!is.na(.c <- ((.G_Conduit[[k + 1]])$a1 >= ((.G_Link[[j + 1]])$xsect)$aFull)) && .c) {
      n1 <- (.G_Link[[j + 1]])$node1
      n2 <- (.G_Link[[j + 1]])$node2
      h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
      h2 <- (.G_Node[[n2 + 1]])$newDepth + (.G_Node[[n2 + 1]])$invertElev
      if (!is.na(.c <- ((h1 - h2) > (abs((.G_Conduit[[k + 1]])$slope) * ((.G_Conduit[[k + 1]])$length)))) && .c) {
        {.e2 <- .G_Conduit[[k + 1]]; .e2$capacityLimited <- 1}
      }
    }
    j <- j + 1
  }
}

# dynwave.c:382
findLinkFlows <- function(dt) {
  dt
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Omega <- Omega; .G_Steps <- Steps
  i <- 0
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    if ((isTrueConduit(i) != 0) && (!((.G_Link[[i + 1]])$bypassed != 0))) {
      dwflow_findConduitFlow(i, .G_Steps, .G_Omega, dt)
    }
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    if (isTrueConduit(i) != 0) {
      updateNodeFlows(i)
    }
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    if (!(isTrueConduit(i) != 0)) {
      if (!((.G_Link[[i + 1]])$bypassed != 0)) {
        findNonConduitFlow(i, dt)
      }
      updateNodeFlows(i)
    }
    i <- i + 1
  }
}

# dynwave.c:416
isTrueConduit <- function(j) {
  j
  .G_Link <- Link
  return(if (((.G_Link[[j + 1]])$type == 0) && (((.G_Link[[j + 1]])$xsect)$type != 0)) 1 else 0)
}

# dynwave.c:423
findNonConduitFlow <- function(i, dt) {
  i; dt
  .G_Link <- Link; .G_Omega <- Omega
  qLast <- (.G_Link[[i + 1]])$newFlow
  {.e1 <- .G_Link[[i + 1]]; .e1$dqdh <- 0}
  qNew <- link_getInflow(i)
  if ((.G_Link[[i + 1]])$type == 1) {
    qNew <- getModPumpFlow(i, qNew, dt)
  }
  findNonConduitSurfArea(i)
  if ((Steps > 0) && ((.G_Link[[i + 1]])$type != 1)) {
    qNew <- ((1 - .G_Omega) * qLast) + (.G_Omega * qNew)
    if (!is.na(.c <- ((qNew * qLast) < 0)) && .c) {
      qNew <- 0.001 * (if (!is.na(.c <- (qNew < 0)) && .c) (-1) else 1)
    }
  }
  {.e2 <- .G_Link[[i + 1]]; .e2$newFlow <- qNew}
}

# dynwave.c:458
getModPumpFlow <- function(i, q_, dt) {
  i; q_; dt
  .G_Link <- Link; .G_Node <- Node
  j <- (.G_Link[[i + 1]])$node1
  k <- (.G_Link[[i + 1]])$subIndex
  newNetInflow <- 0
  netFlowVolume <- 0
  y <- 0
  if (!is.na(.c <- (q_ == 0)) && .c) {
    return(q_)
  }
  if ((.G_Node[[j + 1]])$type == 2) {
    return(node_getMaxOutflow(j, q_, dt))
  }
  .sw1 <- (Pump[[k + 1]])$type
  if (.sw1 == 0) {
    return(node_getMaxOutflow(j, q_, dt))
  } else if (.sw1 == 1 || .sw1 == 3 || .sw1 == 2) {
    newNetInflow <- ((.G_Node[[j + 1]])$inflow - ((.G_Node[[j + 1]])$outflow)) - q_
    netFlowVolume <- (0.5 * ((.G_Node[[j + 1]])$oldNetInflow + newNetInflow)) * dt
    y <- (.G_Node[[j + 1]])$oldDepth + (netFlowVolume / ((Xnode[[j + 1]])$newSurfArea))
    if (!is.na(.c <- (y <= 0)) && .c) {
      return((.G_Node[[j + 1]])$inflow)
    }
  }
  return(q_)
}

# dynwave.c:503
findNonConduitSurfArea <- function(i) {
  i
  .G_Link <- Link; .G_Node <- Node
  if ((.G_Link[[i + 1]])$type == 2) {
    {.e1 <- .G_Link[[i + 1]]; .e1$surfArea1 <- (Orifice[[(.G_Link[[i + 1]])$subIndex + 1]])$surfArea / 2}
  } else {
    {.e2 <- .G_Link[[i + 1]]; .e2$surfArea1 <- 0}
  }
  {.e3 <- .G_Link[[i + 1]]; .e3$surfArea2 <- (.G_Link[[i + 1]])$surfArea1}
  if (((.G_Link[[i + 1]])$flowClass == 5) || ((.G_Node[[(.G_Link[[i + 1]])$node1 + 1]])$type == 2)) {
    {.e4 <- .G_Link[[i + 1]]; .e4$surfArea1 <- 0}
  }
  if (((.G_Link[[i + 1]])$flowClass == 6) || ((.G_Node[[(.G_Link[[i + 1]])$node2 + 1]])$type == 2)) {
    {.e5 <- .G_Link[[i + 1]]; .e5$surfArea2 <- 0}
  }
}

# dynwave.c:528
updateNodeFlows <- function(i) {
  i
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Node <- Node; .G_Xnode <- Xnode
  k <- 0
  barrels <- 1
  n1 <- (.G_Link[[i + 1]])$node1
  n2 <- (.G_Link[[i + 1]])$node2
  q_ <- (.G_Link[[i + 1]])$newFlow
  conduitLossRate <- 0
  if (!is.na(.c <- (q_ >= 0)) && .c) {
    {.e1 <- .G_Node[[n1 + 1]]; .e1$outflow <- (.G_Node[[n1 + 1]])$outflow + q_}
    {.e2 <- .G_Node[[n2 + 1]]; .e2$inflow <- (.G_Node[[n2 + 1]])$inflow + q_}
  } else {
    {.e3 <- .G_Node[[n1 + 1]]; .e3$inflow <- (.G_Node[[n1 + 1]])$inflow - q_}
    {.e4 <- .G_Node[[n2 + 1]]; .e4$outflow <- (.G_Node[[n2 + 1]])$outflow - q_}
  }
  if ((.G_Link[[i + 1]])$type == 0) {
    k <- (.G_Link[[i + 1]])$subIndex
    barrels <- (.G_Conduit[[k + 1]])$barrels
    conduitLossRate <- ((.G_Conduit[[k + 1]])$evapLossRate + (.G_Conduit[[k + 1]])$seepLossRate) * barrels
    if (!is.na(.c <- (conduitLossRate > 0)) && .c) {
      if (((.G_Node[[n1 + 1]])$type != 1) && ((.G_Node[[n2 + 1]])$type != 1)) {
        conduitLossRate <- conduitLossRate / 2
      }
      if ((.G_Node[[n1 + 1]])$type != 1) {
        {.e5 <- .G_Node[[n1 + 1]]; .e5$outflow <- (.G_Node[[n1 + 1]])$outflow + conduitLossRate}
      }
      if ((.G_Node[[n2 + 1]])$type != 1) {
        {.e6 <- .G_Node[[n2 + 1]]; .e6$outflow <- (.G_Node[[n2 + 1]])$outflow + conduitLossRate}
      }
    }
  }
  {.e7 <- .G_Xnode[[(.G_Link[[i + 1]])$node1 + 1]]; .e7$newSurfArea <- (.G_Xnode[[(.G_Link[[i + 1]])$node1 + 1]])$newSurfArea + ((.G_Link[[i + 1]])$surfArea1 * barrels)}
  {.e8 <- .G_Xnode[[(.G_Link[[i + 1]])$node2 + 1]]; .e8$newSurfArea <- (.G_Xnode[[(.G_Link[[i + 1]])$node2 + 1]])$newSurfArea + ((.G_Link[[i + 1]])$surfArea2 * barrels)}
  {.e9 <- .G_Xnode[[(.G_Link[[i + 1]])$node1 + 1]]; .e9$sumdqdh <- (.G_Xnode[[(.G_Link[[i + 1]])$node1 + 1]])$sumdqdh + ((.G_Link[[i + 1]])$dqdh)}
  if ((.G_Link[[i + 1]])$type == 1) {
    k <- (.G_Link[[i + 1]])$subIndex
    if ((Pump[[k + 1]])$type != 3) {
      {.e10 <- .G_Xnode[[n2 + 1]]; .e10$sumdqdh <- (.G_Xnode[[n2 + 1]])$sumdqdh + ((.G_Link[[i + 1]])$dqdh)}
    }
  } else {
    {.e11 <- .G_Xnode[[n2 + 1]]; .e11$sumdqdh <- (.G_Xnode[[n2 + 1]])$sumdqdh + ((.G_Link[[i + 1]])$dqdh)}
  }
}

# dynwave.c:593
findNodeDepths <- function(dt) {
  dt
  .G_HeadTol <- HeadTol; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Xnode <- Xnode
  yOld <- 0
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    link_setOutfallDepth(i)
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if ((.G_Node[[i + 1]])$type == 1) {
      i <- i + 1
      next
    }
    yOld <- (.G_Node[[i + 1]])$newDepth
    setNodeDepth(i, dt)
    {.e1 <- .G_Xnode[[i + 1]]; .e1$converged <- 1}
    if (!is.na(.c <- (abs(yOld - ((.G_Node[[i + 1]])$newDepth)) > .G_HeadTol$v)) && .c) {
      {.e2 <- .G_Xnode[[i + 1]]; .e2$converged <- 0}
    }
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if ((.G_Node[[i + 1]])$type == 1) {
      i <- i + 1
      next
    }
    if ((.G_Xnode[[i + 1]])$converged == 0) {
      return(0)
    }
    i <- i + 1
  }
  return(1)
}

# dynwave.c:636
setNodeDepth <- function(i, dt) {
  i; dt
  .G_MinSurfArea <- MinSurfArea; .G_Node <- Node; .G_Omega <- Omega; .G_Xnode <- Xnode
  isSurcharged <- 0
  dy <- 0
  yNew <- 0
  denom <- 0
  corr <- 0
  f <- 0
  canPond <- if ((AllowPonding != 0) && (!is.na(.c <- ((.G_Node[[i + 1]])$pondedArea > 0)) && .c)) 1 else 0
  isPonded <- if ((canPond != 0) && (!is.na(.c <- ((.G_Node[[i + 1]])$newDepth > (.G_Node[[i + 1]])$fullDepth)) && .c)) 1 else 0
  yCrown <- (.G_Node[[i + 1]])$crownElev - ((.G_Node[[i + 1]])$invertElev)
  yOld <- (.G_Node[[i + 1]])$oldDepth
  yLast <- (.G_Node[[i + 1]])$newDepth
  {.e1 <- .G_Node[[i + 1]]; .e1$overflow <- 0}
  surfArea <- (.G_Xnode[[i + 1]])$newSurfArea
  surfArea <- if (!is.na(.c <- (surfArea >= .G_MinSurfArea$v)) && .c) surfArea else .G_MinSurfArea$v
  dQ <- (.G_Node[[i + 1]])$inflow - ((.G_Node[[i + 1]])$outflow)
  dV <- (0.5 * ((.G_Node[[i + 1]])$oldNetInflow + dQ)) * dt
  if (SurchargeMethod == 0) {
    if (isPonded != 0) {
      isSurcharged <- 0
    } else if ((.G_Node[[i + 1]])$type == 2) {
      isSurcharged <- if ((!is.na(.c <- ((.G_Node[[i + 1]])$surDepth > 0)) && .c) && (!is.na(.c <- (yLast > (.G_Node[[i + 1]])$fullDepth)) && .c)) 1 else 0
    } else {
      isSurcharged <- if ((!is.na(.c <- (yCrown > 0)) && .c) && (!is.na(.c <- (yLast > yCrown)) && .c)) 1 else 0
    }
  }
  if (!(isSurcharged != 0)) {
    dy <- dV / surfArea
    yNew <- yOld + dy
    if (!(isPonded != 0)) {
      {.e2 <- .G_Xnode[[i + 1]]; .e2$oldSurfArea <- surfArea}
    }
    if (Steps > 0) {
      yNew <- ((1 - .G_Omega) * yLast) + (.G_Omega * yNew)
    }
    if ((isPonded != 0) && (!is.na(.c <- (yNew < (.G_Node[[i + 1]])$fullDepth)) && .c)) {
      yNew <- (.G_Node[[i + 1]])$fullDepth - 0.0001
    }
  } else {
    corr <- 1
    if ((.G_Node[[i + 1]])$degree < 0) {
      corr <- 0.6
    }
    denom <- (.G_Xnode[[i + 1]])$sumdqdh
    if (!is.na(.c <- (yLast < (1.25 * yCrown))) && .c) {
      f <- (yLast - yCrown) / yCrown
      denom <- denom + ((((.G_Xnode[[i + 1]])$oldSurfArea / dt) - ((.G_Xnode[[i + 1]])$sumdqdh)) * (exp((-15) * f)))
    }
    if (!is.na(.c <- (denom == 0)) && .c) {
      dy <- 0
    } else {
      dy <- (corr * dQ) / denom
    }
    yNew <- yLast + dy
    if (!is.na(.c <- (yNew < yCrown)) && .c) {
      yNew <- yCrown - 0.0001
    }
    if ((canPond != 0) && (!is.na(.c <- (yNew > (.G_Node[[i + 1]])$fullDepth)) && .c)) {
      yNew <- (.G_Node[[i + 1]])$fullDepth + 0.0001
    }
  }
  if (!is.na(.c <- (yNew < 0)) && .c) {
    yNew <- 0
  }
  yMax <- (.G_Node[[i + 1]])$fullDepth
  if (canPond == 0) {
    yMax <- yMax + ((.G_Node[[i + 1]])$surDepth)
  }
  if (!is.na(.c <- (yNew > yMax)) && .c) {
    yNew <- getFloodedDepth(i, canPond, dV, yNew, yMax, dt)
  } else {
    {.e3 <- .G_Node[[i + 1]]; .e3$newVolume <- node_getVolume(i, yNew)}
  }
  {.e4 <- .G_Xnode[[i + 1]]; .e4$dYdT <- abs(yNew - yOld) / dt}
  {.e5 <- .G_Node[[i + 1]]; .e5$newDepth <- yNew}
}

# dynwave.c:766
getFloodedDepth <- function(i, canPond, dV, yNew, yMax, dt) {
  i; canPond; dV; yNew; yMax; dt
  .G_Node <- Node
  if (canPond == 0) {
    {.e1 <- .G_Node[[i + 1]]; .e1$overflow <- dV / dt}
    {.e2 <- .G_Node[[i + 1]]; .e2$newVolume <- (.G_Node[[i + 1]])$fullVolume}
    yNew <- yMax
  } else {
    {.e3 <- .G_Node[[i + 1]]; .e3$newVolume <- if (!is.na(.c <- (((.G_Node[[i + 1]])$oldVolume + dV) >= ((.G_Node[[i + 1]])$fullVolume))) && .c) ((.G_Node[[i + 1]])$oldVolume + dV) else ((.G_Node[[i + 1]])$fullVolume)}
    {.e4 <- .G_Node[[i + 1]]; .e4$overflow <- ((.G_Node[[i + 1]])$newVolume - (if (!is.na(.c <- (((.G_Node[[i + 1]])$oldVolume) >= ((.G_Node[[i + 1]])$fullVolume))) && .c) ((.G_Node[[i + 1]])$oldVolume) else ((.G_Node[[i + 1]])$fullVolume))) / dt}
  }
  if (!is.na(.c <- ((.G_Node[[i + 1]])$overflow < 0.0001)) && .c) {
    {.e5 <- .G_Node[[i + 1]]; .e5$overflow <- 0}
  }
  return(yNew)
}

# dynwave.c:799
getVariableStep <- function(maxStep) {
  maxStep
  .G_MinRouteStep <- MinRouteStep
  minLink <- -1
  minNode <- -1
  tMin <- maxStep
  tMinLink <- {.BX_getVariableStep_minLink$v <- minLink; .r1 <- getLinkStep(tMin, .BX_getVariableStep_minLink); minLink <- .BX_getVariableStep_minLink$v; .r1}
  tMinNode <- {.BX_getVariableStep_minNode$v <- minNode; .r2 <- getNodeStep(tMinLink, .BX_getVariableStep_minNode); minNode <- .BX_getVariableStep_minNode$v; .r2}
  tMin <- tMinLink
  if (!is.na(.c <- (tMinNode < tMin)) && .c) {
    tMin <- tMinNode
    minLink <- -1
  }
  stats_updateCriticalTimeCount(minNode, minLink)
  if (!is.na(.c <- (tMin < .G_MinRouteStep$v)) && .c) {
    tMin <- .G_MinRouteStep$v
  }
  return(tMin)
}

# dynwave.c:836
getLinkStep <- function(tMin, minLink) {
  tMin; minLink
  .G_Conduit <- Conduit; .G_CourantFactor <- CourantFactor; .G_Link <- Link; .G_Nobjects <- Nobjects
  k <- 0
  q_ <- 0
  t <- 0
  tLink <- tMin
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    if ((.G_Link[[i + 1]])$type == 0) {
      k <- (.G_Link[[i + 1]])$subIndex
      q_ <- abs((.G_Link[[i + 1]])$newFlow) / ((.G_Conduit[[k + 1]])$barrels)
      if (((!is.na(.c <- (q_ <= 0.0001)) && .c) || (!is.na(.c <- ((.G_Conduit[[k + 1]])$a1 <= 0.0001)) && .c)) || (!is.na(.c <- ((.G_Link[[i + 1]])$froude <= 0.01)) && .c)) {
        i <- i + 1
        next
      }
      t <- ((.G_Link[[i + 1]])$newVolume / ((.G_Conduit[[k + 1]])$barrels)) / q_
      t <- (t * ((.G_Conduit[[k + 1]])$modLength)) / (link_getLength(i))
      t <- ((t * ((.G_Link[[i + 1]])$froude)) / (1 + (.G_Link[[i + 1]])$froude)) * .G_CourantFactor$v
      if (!is.na(.c <- (t < tLink)) && .c) {
        tLink <- t
        minLink$v <- i
      }
    }
    i <- i + 1
  }
  return(tLink)
}

# dynwave.c:881
getNodeStep <- function(tMin, minNode) {
  tMin; minNode
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Xnode <- Xnode
  maxDepth <- 0
  dYdT <- 0
  t1 <- 0
  tNode <- tMin
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if ((.G_Node[[i + 1]])$type == 1) {
      i <- i + 1
      next
    }
    if (!is.na(.c <- ((.G_Node[[i + 1]])$newDepth <= 0.0001)) && .c) {
      i <- i + 1
      next
    }
    if (!is.na(.c <- (((.G_Node[[i + 1]])$newDepth + 0.0001) >= ((.G_Node[[i + 1]])$crownElev - ((.G_Node[[i + 1]])$invertElev)))) && .c) {
      i <- i + 1
      next
    }
    maxDepth <- ((.G_Node[[i + 1]])$crownElev - ((.G_Node[[i + 1]])$invertElev)) * 0.25
    if (!is.na(.c <- (maxDepth < 0.0001)) && .c) {
      i <- i + 1
      next
    }
    dYdT <- (.G_Xnode[[i + 1]])$dYdT
    if (!is.na(.c <- (dYdT < 0.0001)) && .c) {
      i <- i + 1
      next
    }
    t1 <- maxDepth / dYdT
    if (!is.na(.c <- (t1 < tNode)) && .c) {
      tNode <- t1
      minNode$v <- i
    }
    i <- i + 1
  }
  return(tNode)
}

