# exfil.c:34
exfil_readStorageParams <- function(k, tok, ntoks, n) {
  k; tok; ntoks; n
  i <- 0
  x <- rt_ra(numeric(3))
  if (ntoks == (n + 1)) {
    if (!({.b1 <- rt_box(x$v[[2]]); .r2 <- getDouble(tok$v[[n + 1]], .b1); x$v[[2]] <- .b1$v; .r2} != 0)) {
      return(error_setInpError(211, tok$v[[n + 1]]))
    }
    x$v[[1]] <- 0
    x$v[[3]] <- 0
  } else if (ntoks < (n + 3)) {
    return(error_setInpError(203, .L0))
  } else {
    i <- 0
    while (i < 3) {
      if (!({.b3 <- rt_box(x$v[[i + 1]]); .r4 <- getDouble(tok$v[[(n + i) + 1]], .b3); x$v[[i + 1]] <- .b3$v; .r4} != 0)) {
        return(error_setInpError(211, tok$v[[(n + i) + 1]]))
      }
      i <- i + 1
    }
  }
  if (!is.na(.c <- (x$v[[2]] == 0)) && .c) {
    return(0)
  }
  return(createStorageExfil(k, x))
}

