    if (.sw1 == 0) {
      i <- (.G_Storage[[k + 1]])$aCurve
      exfil$btmArea <- 0
      exfil$bankMinDepth <- 0
      exfil$bankMaxDepth <- 0
      exfil$bankMaxArea <- 0
      if (i >= 0) {
        aCurve <- Curve[[i + 1]]
        {.e2 <- (.G_Storage[[k + 1]])$exfil; .e2$btmArea <- table_lookupEx(aCurve, 0)}
        {.BX_exfil_initState_d$v <- d; .BX_exfil_initState_a$v <- a; .r3 <- table_getFirstEntry(aCurve, .BX_exfil_initState_d, .BX_exfil_initState_a); d <- .BX_exfil_initState_d$v; a <- .BX_exfil_initState_a$v; .r3}
        alast <- a
        while ({.BX_exfil_initState_d$v <- d; .BX_exfil_initState_a$v <- a; .r4 <- table_getNextEntry(aCurve, .BX_exfil_initState_d, .BX_exfil_initState_a); d <- .BX_exfil_initState_d$v; a <- .BX_exfil_initState_a$v; .r4} != 0) {
          if (!is.na(.c <- (a < alast)) && .c) {
            break
          } else if (!is.na(.c <- (a > alast)) && .c) {
            exfil$bankMaxArea <- a
            exfil$bankMaxDepth <- d
          } else if (!is.na(.c <- (exfil$bankMaxArea == 0)) && .c) {
            exfil$bankMinDepth <- d
          } else {
            break
          }
          alast <- a
        }
        exfil$btmArea <- exfil$btmArea / (UCF(3) * (UCF(3)))
        exfil$bankMaxArea <- exfil$bankMaxArea / (UCF(3) * (UCF(3)))
        exfil$bankMinDepth <- exfil$bankMinDepth / (UCF(3))
        exfil$bankMaxDepth <- exfil$bankMaxDepth / (UCF(3))
      }
    } else if (.sw1 == 1) {
