    } else if (.sw1 == 2 || .sw1 == 3 || .sw1 == 5) {
      exfil$btmArea <- (.G_Storage[[k + 1]])$a0
      exfil$bankMinDepth <- 0
      exfil$bankMaxDepth <- 10000000000
      exfil$bankMaxArea <- 10000000000
    }
  }
}

# exfil.c:158
exfil_getLoss <- function(exfil, tStep, depth, area) {
  exfil; tStep; depth; area
  .G_Adjust <- Adjust
  exfilRate <- 0
  if (!is.na(.c <- (exfil$btmExfil$IMDmax == 0)) && .c) {
    exfilRate <- exfil$btmExfil$Ks * .G_Adjust$hydconFactor
  } else {
    exfilRate <- grnampt_getInfil(exfil$btmExfil, tStep, 0, depth, 3)
  }
  exfilRate <- exfilRate * exfil$btmArea
  if (!is.na(.c <- (depth > exfil$bankMinDepth)) && .c) {
    area <- (if (!is.na(.c <- (area <= exfil$bankMaxArea)) && .c) area else exfil$bankMaxArea) - exfil$btmArea
    if (!is.na(.c <- (area > 0)) && .c) {
      if (!is.na(.c <- (exfil$btmExfil$IMDmax == 0)) && .c) {
        exfilRate <- exfilRate + ((area * exfil$btmExfil$Ks) * .G_Adjust$hydconFactor)
      } else {
        if (!is.na(.c <- (depth > exfil$bankMaxDepth)) && .c) {
          depth <- (depth - exfil$bankMaxDepth) + ((exfil$bankMaxDepth - exfil$bankMinDepth) / 2)
        } else {
          depth <- (depth - exfil$bankMinDepth) / 2
        }
        exfilRate <- exfilRate + (area * (grnampt_getInfil(exfil$bankExfil, tStep, 0, depth, 3)))
      }
    }
  }
  return(exfilRate)
}

# exfil.c:218
createStorageExfil <- function(k, x) {
  k; x
  .G_Storage <- Storage
  exfil <- (.G_Storage[[k + 1]])$exfil
  if (is.null(exfil)) {
    exfil <- T_TExfil()
    if (is.null(exfil)) {
      return(error_setInpError(101, .L0))
    }
    {.e1 <- .G_Storage[[k + 1]]; .e1$exfil <- exfil}
    exfil$btmExfil <- NULL
    exfil$bankExfil <- NULL
    exfil$btmExfil <- T_TGrnAmpt()
    if (is.null(exfil$btmExfil)) {
      return(error_setInpError(101, .L0))
    }
    exfil$bankExfil <- T_TGrnAmpt()
    if (is.null(exfil$bankExfil)) {
      return(error_setInpError(101, .L0))
    }
  }
  if (!(grnampt_setParams(exfil$btmExfil, x) != 0)) {
    return(error_setInpError(211, .L0))
  }
  grnampt_setParams(exfil$bankExfil, x)
  return(0)
}

# findroot.c:20
findroot_Newton <- function(x1, x2, rts, xacc, func, p) {
  x1; x2; rts; xacc; func; p
  n <- 0
  df <- 0
  f <- 0
  temp <- 0
  x <- rts$v
  xlo <- x1
  xhi <- x2
  dxold <- abs(x2 - x1)
  dx <- dxold
  {.BX_findroot_Newton_f$v <- f; .BX_findroot_Newton_df$v <- df; .r1 <- func(x, .BX_findroot_Newton_f, .BX_findroot_Newton_df, p); f <- .BX_findroot_Newton_f$v; df <- .BX_findroot_Newton_df$v; .r1}
  n <- n + 1
  j <- 1
  while (j <= 60) {
    if ((!is.na(.c <- (((((x - xhi) * df) - f) * (((x - xlo) * df) - f)) >= 0)) && .c) || (!is.na(.c <- (abs(2 * f) > abs(dxold * df))) && .c)) {
      dxold <- dx
      dx <- 0.5 * (xhi - xlo)
      x <- xlo + dx
      if (!is.na(.c <- (xlo == x)) && .c) {
        break
      }
    } else {
      dxold <- dx
      dx <- f / df
      temp <- x
      x <- x - dx
      if (!is.na(.c <- (temp == x)) && .c) {
        break
      }
    }
    if (!is.na(.c <- (abs(dx) < xacc)) && .c) {
      break
    }
    {.BX_findroot_Newton_f$v <- f; .BX_findroot_Newton_df$v <- df; .r2 <- func(x, .BX_findroot_Newton_f, .BX_findroot_Newton_df, p); f <- .BX_findroot_Newton_f$v; df <- .BX_findroot_Newton_df$v; .r2}
    n <- n + 1
    if (!is.na(.c <- (f < 0)) && .c) {
      xlo <- x
    } else {
      xhi <- x
    }
    j <- j + 1
  }
  rts$v <- x
  if (n <= 60) {
    return(n)
  } else {
    return(0)
  }
}

# findroot.c:91
findroot_Ridder <- function(x1, x2, xacc, func, p) {
  x1; x2; xacc; func; p
  j <- 0
  fm <- 0
  fnew <- 0
  s <- 0
  xhi <- 0
  xlo <- 0
  xm <- 0
  xnew <- 0
  flo <- func(x1, p)
  fhi <- func(x2, p)
  if (!is.na(.c <- (flo == 0)) && .c) {
    return(x1)
  }
  if (!is.na(.c <- (fhi == 0)) && .c) {
    return(x2)
  }
  ans <- 0.5 * (x1 + x2)
  if (((!is.na(.c <- (flo > 0)) && .c) && (!is.na(.c <- (fhi < 0)) && .c)) || ((!is.na(.c <- (flo < 0)) && .c) && (!is.na(.c <- (fhi > 0)) && .c))) {
    xlo <- x1
    xhi <- x2
    j <- 1
    while (j <= 60) {
      xm <- 0.5 * (xlo + xhi)
      fm <- func(xm, p)
      s <- sqrt((fm * fm) - (flo * fhi))
      if (!is.na(.c <- (s == 0)) && .c) {
        return(ans)
      }
      xnew <- xm + ((xm - xlo) * (((if (!is.na(.c <- (flo >= fhi)) && .c) 1 else (-1)) * fm) / s))
      if (!is.na(.c <- (abs(xnew - ans) <= xacc)) && .c) {
        break
      }
      ans <- xnew
      fnew <- func(ans, p)
      if (is.na(.c <- ((if (!is.na(.c <- (fnew >= 0)) && .c) abs(fm) else (-(abs(fm)))) != fm)) || .c) {
        xlo <- xm
        flo <- fm
        xhi <- ans
        fhi <- fnew
      } else if (is.na(.c <- ((if (!is.na(.c <- (fnew >= 0)) && .c) abs(flo) else (-(abs(flo)))) != flo)) || .c) {
        xhi <- ans
        fhi <- fnew
      } else if (is.na(.c <- ((if (!is.na(.c <- (fnew >= 0)) && .c) abs(fhi) else (-(abs(fhi)))) != fhi)) || .c) {
        xlo <- ans
        flo <- fnew
      } else {
        return(ans)
      }
      if (!is.na(.c <- (abs(xhi - xlo) <= xacc)) && .c) {
        return(ans)
      }
      j <- j + 1
    }
    return(ans)
  }
  return(-(1e+20))
}

