  repeat {
    if ((.G_Gage[[j + 1]])$dataSource == 1) {
      if ((!is.null(.G_Frain$file)) && ((.G_Gage[[j + 1]])$currentFilePos < (.G_Gage[[j + 1]])$endFilePos)) {
        rt_fseek(.G_Frain$file, (.G_Gage[[j + 1]])$currentFilePos, 0)
        {.b2 <- rt_box((.G_Gage[[j + 1]])$nextDate); .r4 <- rt_fread1("d", 8, .b2, .G_Frain$file); {.e3 <- .G_Gage[[j + 1]]; .e3$nextDate <- .b2$v}; .r4}
        {.BX_getNextRainfall_vNext$v <- vNext; .r5 <- rt_fread1("f", 4, .BX_getNextRainfall_vNext, .G_Frain$file); vNext <- .BX_getNextRainfall_vNext$v; .r5}
        {.e6 <- .G_Gage[[j + 1]]; .e6$currentFilePos <- rt_ftell(.G_Frain$file)}
        rNext <- convertRainfall(j, vNext)
