      if (k >= 0) {
        if (!({.b7 <- rt_box((.G_Gage[[j + 1]])$nextDate); .BX_getNextRainfall_rNext$v <- rNext; .r9 <- table_getNextEntry(.G_Tseries[[k + 1]], .b7, .BX_getNextRainfall_rNext); {.e8 <- .G_Gage[[j + 1]]; .e8$nextDate <- .b7$v}; rNext <- .BX_getNextRainfall_rNext$v; .r9} != 0)) {
          return(0)
        }
        rNext <- convertRainfall(j, rNext)
      } else {
