# gage.c:674
convertRainfall <- function(j, r) {
  j; r
  .G_Gage <- Gage
  r1 <- 0
  .sw1 <- (.G_Gage[[j + 1]])$rainType
  if (.sw1 == 0) {
    r1 <- r
  } else if (.sw1 == 1) {
    r1 <- (r / ((.G_Gage[[j + 1]])$rainInterval)) * 3600
  } else if (.sw1 == 2) {
    if (!is.na(.c <- (r < (.G_Gage[[j + 1]])$rainAccum)) && .c) {
      r1 <- (r / ((.G_Gage[[j + 1]])$rainInterval)) * 3600
    } else {
      r1 <- ((r - ((.G_Gage[[j + 1]])$rainAccum)) / ((.G_Gage[[j + 1]])$rainInterval)) * 3600
    }
    {.e2 <- .G_Gage[[j + 1]]; .e2$rainAccum <- r}
  } else {
    r1 <- r
  }
  return((r1 * ((.G_Gage[[j + 1]])$unitsFactor)) * Adjust$rainFactor)
}

