# gwater.c:382
gwater_initState <- function(j) {
  j
  .G_XTOL <- XTOL
  a <- T_TAquifer()
  gw <- (Subcatch[[j + 1]])$groundwater
  if (!is.null(gw)) {
    C_TAquifer(a, Aquifer[[gw$aquifer + 1]])
    gw$theta <- gw$upperMoisture
    if (!is.na(.c <- (gw$theta >= a$porosity)) && .c) {
      gw$theta <- a$porosity - .G_XTOL
    }
    gw$lowerDepth <- gw$waterTableElev - gw$bottomElev
    if (!is.na(.c <- (gw$lowerDepth >= (gw$surfElev - gw$bottomElev))) && .c) {
      gw$lowerDepth <- (gw$surfElev - gw$bottomElev) - .G_XTOL
    }
    gw$oldFlow <- 0
    gw$newFlow <- 0
    gw$evapLoss <- 0
    gw$maxInfilVol <- ((gw$surfElev - gw$waterTableElev) * (a$porosity - gw$theta)) / (subcatch_getFracPerv(j))
  }
}

