# gwater.c:477
gwater_getGroundwater <- function(j, evap, infil, tStep) {
  j; evap; infil; tStep
  .G_Node <- Node; .G_Subcatch <- Subcatch; .G_XTOL <- XTOL
  x <- rt_ra(numeric(2))
  GW <<- (.G_Subcatch[[j + 1]])$groundwater
  if (is.null(GW)) {
    return(invisible(NULL))
  }
  LatFlowExpr <<- (.G_Subcatch[[j + 1]])$gwLatFlowExpr
  DeepFlowExpr <<- (.G_Subcatch[[j + 1]])$gwDeepFlowExpr
  C_TAquifer(A, Aquifer[[GW$aquifer + 1]])
  FracPerv <<- subcatch_getFracPerv(j)
  if (!is.na(.c <- (FracPerv <= 0)) && .c) {
    return(invisible(NULL))
  }
  Area <<- (.G_Subcatch[[j + 1]])$area
  infil <- (infil / Area) / tStep
  gwater_Infil <<- infil
  gwater_Tstep <<- tStep
  evap <- (evap / Area) / tStep
  MaxEvap <<- Evap$rate * FracPerv
  AvailEvap <<- if (!is.na(.c <- ((MaxEvap - evap) >= 0)) && .c) (MaxEvap - evap) else 0
  TotalDepth <<- GW$surfElev - GW$bottomElev
  if (!is.na(.c <- (TotalDepth <= 0)) && .c) {
    return(invisible(NULL))
  }
  n <- GW$node
  if (is.na(.c <- (GW$nodeElev != (-10000000000))) || .c) {
    Hstar <<- GW$nodeElev - GW$bottomElev
  } else {
    Hstar <<- (.G_Node[[n + 1]])$invertElev - GW$bottomElev
  }
  if (!is.na(.c <- (GW$fixedDepth > 0)) && .c) {
    Hsw <<- (GW$fixedDepth + (.G_Node[[n + 1]])$invertElev) - GW$bottomElev
  } else {
    Hsw <<- ((.G_Node[[n + 1]])$newDepth + (.G_Node[[n + 1]])$invertElev) - GW$bottomElev
  }
  x$v[[1]] <- GW$theta
  x$v[[2]] <- GW$lowerDepth
  vUpper <- (TotalDepth - x$v[[2]]) * (x$v[[1]] - A$fieldCapacity)
  vUpper <- if (!is.na(.c <- (0 >= vUpper)) && .c) 0 else vUpper
  MaxUpperPerc <<- vUpper / tStep
  MaxGWFlowPos <<- (x$v[[2]] * A$porosity) / tStep
  MaxGWFlowNeg <<- ((TotalDepth - x$v[[2]]) * (A$porosity - x$v[[1]])) / tStep
  nodeFlow <- ((.G_Node[[n + 1]])$inflow + ((.G_Node[[n + 1]])$newVolume / tStep)) / Area
  MaxGWFlowNeg <<- -(if (!is.na(.c <- (MaxGWFlowNeg <= nodeFlow)) && .c) MaxGWFlowNeg else nodeFlow)
  odesolve_integrate(x, 2, 0, tStep, GWTOL, tStep, getDxDt)
  x$v[[1]] <- if (!is.na(.c <- (x$v[[1]] >= A$wiltingPoint)) && .c) x$v[[1]] else A$wiltingPoint
  if (!is.na(.c <- (x$v[[1]] >= A$porosity)) && .c) {
    x$v[[1]] <- A$porosity - .G_XTOL
    x$v[[2]] <- TotalDepth - .G_XTOL
  }
  x$v[[2]] <- if (!is.na(.c <- (x$v[[2]] >= 0)) && .c) x$v[[2]] else 0
  if (!is.na(.c <- (x$v[[2]] >= TotalDepth)) && .c) {
    x$v[[2]] <- TotalDepth - .G_XTOL
  }
  {.e1 <- GW; .e1$theta <- x$v[[1]]}
  {.e2 <- GW; .e2$lowerDepth <- x$v[[2]]}
  getFluxes(GW$theta, GW$lowerDepth)
  {.e3 <- GW; .e3$oldFlow <- GW$newFlow}
  {.e4 <- GW; .e4$newFlow <- GWFlow}
  {.e5 <- GW; .e5$evapLoss <- UpperEvap + LowerEvap}
  {.e6 <- GW; .e6$maxInfilVol <- ((TotalDepth - x$v[[2]]) * (A$porosity - x$v[[1]])) / FracPerv}
  updateMassBal(Area, tStep)
  stats_updateGwaterStats(j, infil, GW$evapLoss, GWFlow, LowerLoss, GW$theta, (GW$lowerDepth + GW$bottomElev), tStep)
}

# gwater.c:605
updateMassBal <- function(area, tStep) {
  area; tStep
  .G_GW <- GW
  ft2sec <- area * tStep
  vInfil <- gwater_Infil * ft2sec
  vUpperEvap <- UpperEvap * ft2sec
  vLowerEvap <- LowerEvap * ft2sec
  vLowerPerc <- LowerLoss * ft2sec
  vGwater <- (0.5 * (.G_GW$oldFlow + .G_GW$newFlow)) * ft2sec
  massbal_updateGwaterTotals(vInfil, vUpperEvap, vLowerEvap, vLowerPerc, vGwater)
}

# gwater.c:631
getFluxes <- function(theta, lowerDepth) {
  theta; lowerDepth
  .G_DeepFlowExpr <- DeepFlowExpr; .G_LatFlowExpr <- LatFlowExpr; .G_MaxGWFlowNeg <- MaxGWFlowNeg; .G_MaxGWFlowPos <- MaxGWFlowPos; .G_MaxUpperPerc <- MaxUpperPerc; .G_TotalDepth <- TotalDepth; .G_gwater_Tstep <- gwater_Tstep
  lowerDepth <- if (!is.na(.c <- (lowerDepth >= 0)) && .c) lowerDepth else 0
  lowerDepth <- if (!is.na(.c <- (lowerDepth <= .G_TotalDepth)) && .c) lowerDepth else .G_TotalDepth
  upperDepth <- .G_TotalDepth - lowerDepth
  Hgw <<- lowerDepth
  Theta <<- theta
  gwater_getEvapRates(theta, upperDepth)
  UpperPerc <<- getUpperPerc(theta, upperDepth)
  UpperPerc <<- if (!is.na(.c <- (UpperPerc <= .G_MaxUpperPerc)) && .c) UpperPerc else .G_MaxUpperPerc
  if (!is.null(.G_DeepFlowExpr)) {
    LowerLoss <<- mathexpr_eval(.G_DeepFlowExpr, gwater_getVariableValue) / (UCF(0))
  } else {
    LowerLoss <<- (A$lowerLossCoeff * lowerDepth) / .G_TotalDepth
  }
  LowerLoss <<- if (!is.na(.c <- (LowerLoss <= (lowerDepth / .G_gwater_Tstep))) && .c) LowerLoss else (lowerDepth / .G_gwater_Tstep)
  GWFlow <<- getGWFlow(lowerDepth)
  if (!is.null(.G_LatFlowExpr)) {
    GWFlow <<- GWFlow + (mathexpr_eval(.G_LatFlowExpr, gwater_getVariableValue) / (UCF(9)))
  }
  if (!is.na(.c <- (GWFlow >= 0)) && .c) {
    GWFlow <<- if (!is.na(.c <- (GWFlow <= .G_MaxGWFlowPos)) && .c) GWFlow else .G_MaxGWFlowPos
  } else {
    GWFlow <<- if (!is.na(.c <- (GWFlow >= .G_MaxGWFlowNeg)) && .c) GWFlow else .G_MaxGWFlowNeg
  }
}

# gwater.c:677
getDxDt <- function(t, x, dxdt) {
  t; x; dxdt
  getFluxes(x$v[[1]], x$v[[2]])
  qUpper <- (gwater_Infil - UpperEvap) - UpperPerc
  qLower <- ((UpperPerc - LowerLoss) - LowerEvap) - GWFlow
  denom <- TotalDepth - x$v[[2]]
  if (!is.na(.c <- (denom > 0)) && .c) {
    dxdt$v[[1]] <- qUpper / denom
  } else {
    dxdt$v[[1]] <- 0
  }
  denom <- A$porosity - x$v[[1]]
  if (!is.na(.c <- (denom > 0)) && .c) {
    dxdt$v[[2]] <- qLower / denom
  } else {
    dxdt$v[[2]] <- 0
  }
}

# gwater.c:713
gwater_getEvapRates <- function(theta, upperDepth) {
  theta; upperDepth
  .G_A <- A; .G_AvailEvap <- AvailEvap; .G_MaxEvap <- MaxEvap
  month <- 0
  lowerFrac <- 0
  UpperEvap <<- 0
  LowerEvap <<- 0
  if (!is.na(.c <- (gwater_Infil > 0)) && .c) {
    return(invisible(NULL))
  }
  upperFrac <- .G_A$upperEvapFrac
  f <- 1
  p <- .G_A$upperEvapPat
  if (p >= 0) {
    month <- datetime_monthOfYear(getDateTime(NewRunoffTime))
    f <- ((Pattern[[p + 1]])$factor)$v[[month]]
  }
  upperFrac <- upperFrac * f
  if (!is.na(.c <- (theta > .G_A$wiltingPoint)) && .c) {
    UpperEvap <<- upperFrac * .G_MaxEvap
    UpperEvap <<- if (!is.na(.c <- (UpperEvap <= .G_AvailEvap)) && .c) UpperEvap else .G_AvailEvap
  }
  if (!is.na(.c <- (.G_A$lowerEvapDepth > 0)) && .c) {
    lowerFrac <- (.G_A$lowerEvapDepth - upperDepth) / .G_A$lowerEvapDepth
    lowerFrac <- if (!is.na(.c <- (0 >= lowerFrac)) && .c) 0 else lowerFrac
    lowerFrac <- if (!is.na(.c <- (lowerFrac <= 1)) && .c) lowerFrac else 1
    LowerEvap <<- (lowerFrac * (1 - upperFrac)) * .G_MaxEvap
    LowerEvap <<- if (!is.na(.c <- (LowerEvap <= (.G_AvailEvap - UpperEvap))) && .c) LowerEvap else (.G_AvailEvap - UpperEvap)
  }
}

# gwater.c:769
getUpperPerc <- function(theta, upperDepth) {
  theta; upperDepth
  .G_A <- A
  if ((!is.na(.c <- (upperDepth <= 0)) && .c) || (!is.na(.c <- (theta <= .G_A$fieldCapacity)) && .c)) {
    return(0)
  }
  delta <- theta - .G_A$porosity
  hydcon <- .G_A$conductivity * (exp(delta * .G_A$conductSlope))
  delta <- theta - .G_A$fieldCapacity
  dhdz <- 1 + (((.G_A$tensionSlope * 2) * delta) / upperDepth)
  HydCon <<- hydcon
  return(hydcon * dhdz)
}

# gwater.c:799
getGWFlow <- function(lowerDepth) {
  lowerDepth
  .G_GW <- GW; .G_Hstar <- Hstar; .G_Hsw <- Hsw
  t1 <- 0
  t2 <- 0
  if (!is.na(.c <- (lowerDepth <= .G_Hstar)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (.G_GW$b1 == 0)) && .c) {
    t1 <- .G_GW$a1
  } else {
    t1 <- .G_GW$a1 * (rt_pow((lowerDepth - .G_Hstar) * (UCF(3)), .G_GW$b1))
  }
  if (!is.na(.c <- (.G_GW$b2 == 0)) && .c) {
    t2 <- .G_GW$a2
  } else if (!is.na(.c <- (.G_Hsw > .G_Hstar)) && .c) {
    t2 <- .G_GW$a2 * (rt_pow((.G_Hsw - .G_Hstar) * (UCF(3)), .G_GW$b2))
  } else {
    t2 <- 0
  }
  t3 <- (((.G_GW$a3 * lowerDepth) * .G_Hsw) * (UCF(3))) * (UCF(3))
  q_ <- ((t1 - t2) + t3) / (UCF(9))
  if ((!is.na(.c <- (q_ < 0)) && .c) && (is.na(.c <- (.G_GW$a3 != 0)) || .c)) {
    q_ <- 0
  }
  return(q_)
}

