# gwater.c:850
gwater_getVariableValue <- function(varIndex) {
  varIndex
  .G_A <- A
  if (varIndex == 0) {
    return(Hgw * (UCF(3)))
  } else if (varIndex == 1) {
    return(Hsw * (UCF(3)))
  } else if (varIndex == 2) {
    return(Hstar * (UCF(3)))
  } else if (varIndex == 3) {
    return(TotalDepth * (UCF(3)))
  } else if (varIndex == 4) {
    return(.G_A$conductivity * (UCF(0)))
  } else if (varIndex == 5) {
    return(HydCon * (UCF(0)))
  } else if (varIndex == 6) {
    return(Theta)
  } else if (varIndex == 7) {
    return(.G_A$porosity)
  } else if (varIndex == 8) {
    return(gwater_Infil * (UCF(0)))
  } else if (varIndex == 9) {
    return(UpperPerc * (UCF(0)))
  } else if (varIndex == 10) {
    return(Area * (UCF(4)))
  } else {
    return(0)
  }
}

# hash.c:24
samestr <- function(s1, s2) {
  s1; s2
  i <- 0
  while ((if (((rt_cget(s1, i)) >= 97) && ((rt_cget(s1, i)) <= 122)) (rt_band((rt_cget(s1, i)), (-32 - 1))) else (rt_cget(s1, i))) == (if (((rt_cget(s2, i)) >= 97) && ((rt_cget(s2, i)) <= 122)) (rt_band((rt_cget(s2, i)), (-32 - 1))) else (rt_cget(s2, i)))) {
    if ((!(rt_cget(s1, (i + 1)) != 0)) && (!(rt_cget(s2, (i + 1)) != 0))) {
      return(1)
    }
    i <- i + 1
  }
  return(0)
}

# hash.c:33
hash <- function(str) {
  str
  sum1 <- 0
  sum2 <- 0
  while (0 != rt_cget(str, 0)) {
    sum1 <- (sum1 + ((if (((rt_cget(str, 0)) >= 97) && ((rt_cget(str, 0)) <= 122)) (rt_band((rt_cget(str, 0)), (-32 - 1))) else (rt_cget(str, 0))) %% 4294967296)) %% 4294967296
    str <- rt_cadd(str, 1)
    if (255 <= sum1) {
      sum1 <- (sum1 - 255) %% 4294967296
    }
    sum2 <- sum2 + sum1
  }
  check1 <- sum2 %% 4294967296
  check1 <- (check1 - trunc(check1 / 255) * 255) %% 4294967296
  check1 <- (255 - (rt_imod(((sum1 + check1) %% 4294967296), 255))) %% 4294967296
  sum1 <- (255 - (rt_imod(((sum1 + check1) %% 4294967296), 255))) %% 4294967296
  return(rt_imod((rt_bor(((check1 * 256) %% 4294967296), sum1)), 1999))
}

