# hash.c:59
HTinsert <- function(ht, key, data) {
  ht; key; data
  i <- hash(key)
  if (i >= 1999) {
    return(0)
  }
  entry <- T_HTentry()
  if (is.null(entry)) {
    return(0)
  }
  entry$key <- key
  entry$data <- data
  entry$next_ <- ht$v[[i + 1]]
  ht$v[i + 1] <- list(entry)
  return(1)
}

# hash.c:73
HTfind <- function(ht, key) {
  ht; key
  i <- hash(key)
  if (i >= 1999) {
    return(-1)
  }
  entry <- ht$v[[i + 1]]
  while (!is.null(entry)) {
    if (samestr(entry$key, key) != 0) {
      return(entry$data)
    }
    entry <- entry$next_
  }
  return(-1)
}

