  i <- findmatch(tok$v[[ntoks]], InfilModelWords)
  if (i >= 0) {
    m <- i
    ntoks <- ntoks - 1
  }
  if (m == 0) {
    n <- 5
  } else if (m == 1) {
    n <- 5
  } else if (m == 2) {
    n <- 4
  } else if (m == 3) {
    n <- 4
  } else if (m == 4) {
    n <- 4
  } else {
    return(0)
  }
  if (ntoks < n) {
    return(error_setInpError(203, .L0))
  }
  i <- 0
  while (i < 5) {
    x$v[[i + 1]] <- 0
    i <- i + 1
  }
  i <- 1
  while (i < n) {
    if (!({.b1 <- rt_box(x$v[[i]]); .r2 <- getDouble(tok$v[[i + 1]], .b1); x$v[[i]] <- .b1$v; .r2} != 0)) {
      return(error_setInpError(211, tok$v[[i + 1]]))
    }
    i <- i + 1
  }
  if (((m == 0) || (m == 1)) && (ntoks > n)) {
    if (!({.b3 <- rt_box(x$v[[n]]); .r4 <- getDouble(tok$v[[n + 1]], .b3); x$v[[n]] <- .b3$v; .r4} != 0)) {
      return(error_setInpError(211, tok$v[[n + 1]]))
    }
  }
  {.e5 <- .G_Subcatch[[j + 1]]; .e5$infil <- j}
  {.e6 <- .G_Subcatch[[j + 1]]; .e6$infilModel <- m}
  if (m == 0 || m == 1) {
    status <- horton_setParams((.G_Infil[[j + 1]])$horton, x)
  } else if (m == 2 || m == 3) {
    status <- grnampt_setParams((.G_Infil[[j + 1]])$grnAmpt, x)
  } else if (m == 4) {
    status <- curvenum_setParams((.G_Infil[[j + 1]])$curveNum, x)
  } else {
    status <- 1
  }
  if (!(status != 0)) {
    return(error_setInpError(235, .L0))
  }
  return(0)
}

