# infil.c:325
horton_setParams <- function(infil, p) {
  infil; p
  k <- 0
  while (k < 5) {
    if (!is.na(.c <- (p$v[[k + 1]] < 0)) && .c) {
      return(0)
    }
    k <- k + 1
  }
  infil$f0 <- p$v[[1]] / (UCF(0))
  infil$fmin <- p$v[[2]] / (UCF(0))
  infil$decay <- p$v[[3]] / 3600
  if (!is.na(.c <- (p$v[[4]] == 0)) && .c) {
    p$v[[4]] <- 1e-06
  }
  infil$regen <- ((-(rt_log(1 - 0.98))) / p$v[[4]]) / 86400
  infil$Fmax <- p$v[[5]] / (UCF(1))
  if (!is.na(.c <- (infil$f0 < infil$fmin)) && .c) {
    return(0)
  }
  return(1)
}

