# infil.c:384
horton_getInfil <- function(infil, tstep, irate, depth) {
  infil; tstep; irate; depth
  .G_InfilFactor <- InfilFactor
  iter <- 0
  fa <- 0
  fp <- 0
  Fp <- 0
  F1 <- 0
  t1 <- 0
  tlim <- 0
  ex <- 0
  kt <- 0
  FF <- 0
  FF1 <- 0
  r <- 0
  f0 <- infil$f0 * .G_InfilFactor
  fmin <- infil$fmin * .G_InfilFactor
  Fmax <- infil$Fmax
  tp <- infil$tp
  df <- f0 - fmin
  kd <- infil$decay
  kr <- infil$regen * Evap$recoveryFactor
  if (((!is.na(.c <- (df < 0)) && .c) || (!is.na(.c <- (kd < 0)) && .c)) || (!is.na(.c <- (kr < 0)) && .c)) {
    return(0)
  }
  if ((!is.na(.c <- (df == 0)) && .c) || (!is.na(.c <- (kd == 0)) && .c)) {
    fp <- f0
    fa <- irate + (depth / tstep)
    if (!is.na(.c <- (fp > fa)) && .c) {
      fp <- fa
    }
    return(if (!is.na(.c <- (0 >= fp)) && .c) 0 else fp)
  }
  fa <- irate + (depth / tstep)
  if (!is.na(.c <- (fa > 1e-10)) && .c) {
    t1 <- tp + tstep
    tlim <- 16 / kd
    if (!is.na(.c <- (tp >= tlim)) && .c) {
      Fp <- (fmin * tp) + (df / kd)
      F1 <- Fp + (fmin * tstep)
    } else {
      Fp <- (fmin * tp) + ((df / kd) * (1 - (exp((-kd) * tp))))
      F1 <- (fmin * t1) + ((df / kd) * (1 - (exp((-kd) * t1))))
    }
    fp <- (F1 - Fp) / tstep
    fp <- if (!is.na(.c <- (fp >= fmin)) && .c) fp else fmin
    if (!is.na(.c <- (fp > fa)) && .c) {
      fp <- fa
    }
    if (!is.na(.c <- (t1 > tlim)) && .c) {
      tp <- t1
    } else if (!is.na(.c <- (fp < fa)) && .c) {
      tp <- t1
    } else {
      F1 <- Fp + (fp * tstep)
      tp <- tp + (tstep / 2)
      iter <- 1
      while (iter <= 20) {
        kt <- if (!is.na(.c <- (60 <= (kd * tp))) && .c) 60 else (kd * tp)
        ex <- exp(-kt)
        FF <- ((fmin * tp) + ((df / kd) * (1 - ex))) - F1
        FF1 <- fmin + (df * ex)
        r <- FF / FF1
        tp <- tp - r
        if (!is.na(.c <- (abs(r) <= (0.001 * tstep))) && .c) {
          break
        }
        iter <- iter + 1
      }
    }
    if (!is.na(.c <- (Fmax > 0)) && .c) {
      if (!is.na(.c <- ((infil$Fe + (fp * tstep)) > Fmax)) && .c) {
        fp <- (Fmax - infil$Fe) / tstep
      }
      fp <- if (!is.na(.c <- (fp >= 0)) && .c) fp else 0
      infil$Fe <- infil$Fe + (fp * tstep)
    }
  } else if (!is.na(.c <- (kr > 0)) && .c) {
    r <- exp((-kr) * tstep)
    tp <- 1 - (exp((-kd) * tp))
    tp <- (-(rt_log(1 - (r * tp)))) / kd
    if (!is.na(.c <- (Fmax > 0)) && .c) {
      infil$Fe <- (fmin * tp) + ((df / kd) * (1 - (exp((-kd) * tp))))
    }
  }
  infil$tp <- tp
  return(fp)
}

# infil.c:496
modHorton_getInfil <- function(infil, tstep, irate, depth) {
  infil; tstep; irate; depth
  .G_InfilFactor <- InfilFactor
  f <- 0
  fp <- 0
  fa <- 0
  f0 <- infil$f0 * .G_InfilFactor
  fmin <- infil$fmin * .G_InfilFactor
  df <- f0 - fmin
  kd <- infil$decay
  kr <- infil$regen * Evap$recoveryFactor
  if (((!is.na(.c <- (df < 0)) && .c) || (!is.na(.c <- (kd < 0)) && .c)) || (!is.na(.c <- (kr < 0)) && .c)) {
    return(0)
  }
  if ((!is.na(.c <- (df == 0)) && .c) || (!is.na(.c <- (kd == 0)) && .c)) {
    fp <- f0
    fa <- irate + (depth / tstep)
    if (!is.na(.c <- (fp > fa)) && .c) {
      fp <- fa
    }
    return(if (!is.na(.c <- (0 >= fp)) && .c) 0 else fp)
  }
  fa <- irate + (depth / tstep)
  if (!is.na(.c <- (fa > 1e-10)) && .c) {
    if ((!is.na(.c <- (infil$Fmax > 0)) && .c) && (!is.na(.c <- (infil$Fe >= infil$Fmax)) && .c)) {
      return(0)
    }
    fp <- f0 - (kd * infil$Fe)
    fp <- if (!is.na(.c <- (fp >= fmin)) && .c) fp else fmin
    f <- if (!is.na(.c <- (fa <= fp)) && .c) fa else fp
    infil$Fe <- infil$Fe + ((if (!is.na(.c <- ((f - fmin) >= 0)) && .c) (f - fmin) else 0) * tstep)
    if (!is.na(.c <- (infil$Fmax > 0)) && .c) {
      infil$Fe <- if (!is.na(.c <- (infil$Fe >= infil$Fmax)) && .c) infil$Fe else infil$Fmax
    }
  } else if (!is.na(.c <- (kr > 0)) && .c) {
    infil$Fe <- infil$Fe * (exp((-kr) * tstep))
    infil$Fe <- if (!is.na(.c <- (infil$Fe >= 0)) && .c) infil$Fe else 0
  }
  return(f)
}

