# infil.c:574
grnampt_setParams <- function(infil, p) {
  infil; p
  if ((((!is.na(.c <- (p$v[[1]] < 0)) && .c) || (!is.na(.c <- (p$v[[2]] <= 0)) && .c)) || (!is.na(.c <- (p$v[[3]] < 0)) && .c)) || (!is.na(.c <- (p$v[[3]] > 1)) && .c)) {
    return(0)
  }
  infil$S <- p$v[[1]] / (UCF(1))
  infil$Ks <- p$v[[2]] / (UCF(0))
