# infil.c:632
grnampt_getInfil <- function(infil, tstep, irate, depth, modelType) {
  infil; tstep; irate; depth; modelType
  Fumax <<- (infil$IMDmax * infil$Lu) * (sqrt(InfilFactor))
  infil$T_ <- infil$T_ - tstep
  if (infil$Sat != 0) {
    return(grnampt_getSatInfil(infil, tstep, irate, depth))
  } else {
    return(grnampt_getUnsatInfil(infil, tstep, irate, depth, modelType))
  }
}

# infil.c:660
grnampt_getUnsatInfil <- function(infil, tstep, irate, depth, modelType) {
  infil; tstep; irate; depth; modelType
  .G_Evap <- Evap; .G_Fumax <- Fumax; .G_InfilFactor <- InfilFactor
  dF <- 0
  kr <- 0
  ks <- infil$Ks * .G_InfilFactor
  lu <- infil$Lu * (sqrt(.G_InfilFactor))
  ia <- irate + (depth / tstep)
  if (!is.na(.c <- (ia < 1e-10)) && .c) {
    ia <- 0
  }
  if (!is.na(.c <- (ia == 0)) && .c) {
    if (!is.na(.c <- (infil$Fu <= 0)) && .c) {
      return(0)
    }
    kr <- (lu / 90000) * .G_Evap$recoveryFactor
    dF <- (kr * .G_Fumax) * tstep
    infil$F_ <- infil$F_ - dF
    infil$Fu <- infil$Fu - dF
    if (!is.na(.c <- (infil$Fu <= 0)) && .c) {
      infil$Fu <- 0
      infil$F_ <- 0
      infil$IMD <- infil$IMDmax
      return(0)
    }
    if (!is.na(.c <- (infil$T_ <= 0)) && .c) {
      infil$IMD <- (.G_Fumax - infil$Fu) / lu
      infil$F_ <- 0
    }
    return(0)
  }
  if (!is.na(.c <- (ia <= ks)) && .c) {
    dF <- ia * tstep
    infil$F_ <- infil$F_ + dF
    infil$Fu <- infil$Fu + dF
    infil$Fu <- if (!is.na(.c <- (infil$Fu <= .G_Fumax)) && .c) infil$Fu else .G_Fumax
    if ((modelType == 2) && (!is.na(.c <- (infil$T_ <= 0)) && .c)) {
      infil$IMD <- (.G_Fumax - infil$Fu) / lu
      infil$F_ <- 0
    }
    return(ia)
  }
  infil$T_ <- (5400 / lu) / .G_Evap$recoveryFactor
  Fs <- ((ks * (infil$S + depth)) * infil$IMD) / (ia - ks)
  if (!is.na(.c <- (infil$F_ > Fs)) && .c) {
    infil$Sat <- 1
    return(grnampt_getSatInfil(infil, tstep, irate, depth))
  }
  if (!is.na(.c <- ((infil$F_ + (ia * tstep)) < Fs)) && .c) {
    dF <- ia * tstep
    infil$F_ <- infil$F_ + dF
    infil$Fu <- infil$Fu + dF
    infil$Fu <- if (!is.na(.c <- (infil$Fu <= .G_Fumax)) && .c) infil$Fu else .G_Fumax
    return(ia)
  }
  ts <- tstep - ((Fs - infil$F_) / ia)
  if (!is.na(.c <- (ts <= 0)) && .c) {
    ts <- 0
  }
  c1 <- (infil$S + depth) * infil$IMD
  F2 <- grnampt_getF2(Fs, c1, ks, ts)
  if (!is.na(.c <- (F2 > (Fs + (ia * ts)))) && .c) {
    F2 <- Fs + (ia * ts)
  }
  dF <- F2 - infil$F_
  infil$F_ <- F2
  infil$Fu <- infil$Fu + dF
  infil$Fu <- if (!is.na(.c <- (infil$Fu <= .G_Fumax)) && .c) infil$Fu else .G_Fumax
  infil$Sat <- 1
  return(dF / tstep)
}

# infil.c:767
grnampt_getSatInfil <- function(infil, tstep, irate, depth) {
  infil; tstep; irate; depth
  .G_Fumax <- Fumax; .G_InfilFactor <- InfilFactor
  ks <- infil$Ks * .G_InfilFactor
  lu <- infil$Lu * (sqrt(.G_InfilFactor))
  ia <- irate + (depth / tstep)
  if (!is.na(.c <- (ia < 1e-10)) && .c) {
    return(0)
  }
  infil$T_ <- (5400 / lu) / Evap$recoveryFactor
  c1 <- (infil$S + depth) * infil$IMD
  F2 <- grnampt_getF2(infil$F_, c1, ks, tstep)
  dF <- F2 - infil$F_
  if (!is.na(.c <- (dF > (ia * tstep))) && .c) {
    dF <- ia * tstep
    infil$Sat <- 0
  }
  infil$F_ <- infil$F_ + dF
  infil$Fu <- infil$Fu + dF
  infil$Fu <- if (!is.na(.c <- (infil$Fu <= .G_Fumax)) && .c) infil$Fu else .G_Fumax
  return(dF / tstep)
}

# infil.c:813
grnampt_getF2 <- function(f1, c1, ks, ts) {
  f1; c1; ks; ts
  f2 <- f1
  df2 <- 0
  f2min <- f1 + (ks * ts)
  if (!is.na(.c <- (c1 == 0)) && .c) {
    return(f2min)
  }
  if ((!is.na(.c <- (ts < 10)) && .c) && (!is.na(.c <- (f1 > (0.01 * c1))) && .c)) {
    f2 <- f1 + ((ks * (1 + (c1 / f1))) * ts)
    return(if (!is.na(.c <- (f2 >= f2min)) && .c) f2 else f2min)
  }
  c2 <- (c1 * (rt_log(f1 + c1))) - (ks * ts)
  i <- 1
  while (i <= 20) {
    df2 <- (((f2 - f1) - (c1 * (rt_log(f2 + c1)))) + c2) / (1 - (c1 / (f2 + c1)))
    if (!is.na(.c <- (abs(df2) < 1e-05)) && .c) {
      return(if (!is.na(.c <- (f2 >= f2min)) && .c) f2 else f2min)
    }
    f2 <- f2 - df2
    i <- i + 1
  }
  return(f2min)
}

# infil.c:861
curvenum_setParams <- function(infil, p) {
  infil; p
  if (!is.na(.c <- (p$v[[1]] < 10)) && .c) {
    p$v[[1]] <- 10
  }
  if (!is.na(.c <- (p$v[[1]] > 99)) && .c) {
    p$v[[1]] <- 99
  }
  infil$Smax <- ((1000 / p$v[[1]]) - 10) / 12
  if (!is.na(.c <- (infil$Smax < 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (p$v[[3]] > 0)) && .c) {
    infil$regen <- 1 / (p$v[[3]] * 86400)
  } else {
    return(0)
  }
  infil$Tmax <- 0.06 / infil$regen
  return(1)
}

