# infil.c:925
curvenum_getInfil <- function(infil, tstep, irate, depth) {
  infil; tstep; irate; depth
  F1 <- 0
  f1 <- 0
  fa <- irate + (depth / tstep)
  if (!is.na(.c <- (irate > 1e-10)) && .c) {
    if (!is.na(.c <- (infil$T_ >= infil$Tmax)) && .c) {
      infil$P <- 0
      infil$F_ <- 0
      infil$f <- 0
      infil$Se <- infil$S
    }
    infil$T_ <- 0
    infil$P <- infil$P + (irate * tstep)
    F1 <- infil$P * (1 - (infil$P / (infil$P + infil$Se)))
    f1 <- (F1 - infil$F_) / tstep
    if ((!is.na(.c <- (f1 < 0)) && .c) || (!is.na(.c <- (infil$S <= 0)) && .c)) {
      f1 <- 0
    }
  } else {
    if ((!is.na(.c <- (depth > 0.004167)) && .c) && (!is.na(.c <- (infil$S > 0)) && .c)) {
      f1 <- infil$f
      if (!is.na(.c <- ((f1 * tstep) > infil$S)) && .c) {
        f1 <- infil$S / tstep
      }
    } else {
      infil$T_ <- infil$T_ + tstep
    }
  }
  if (!is.na(.c <- (f1 > 0)) && .c) {
    f1 <- if (!is.na(.c <- (f1 <= fa)) && .c) f1 else fa
    f1 <- if (!is.na(.c <- (f1 >= 0)) && .c) f1 else 0
    infil$F_ <- infil$F_ + (f1 * tstep)
