inflow_setExtInflow <- function(j, param, type, tseries, basePat, cf, baseline, sf) {
  j; param; type; tseries; basePat; cf; baseline; sf
  .G_Node <- Node
  inflow <- (.G_Node[[j + 1]])$extInflow
  while (!is.null(inflow)) {
    if (inflow$param == param) {
      break
    }
    inflow <- inflow$next_
  }
  if (is.null(inflow)) {
    inflow <- T_TExtInflow()
    if (is.null(inflow)) {
      return(error_setInpError(101, .L0))
    }
    inflow$next_ <- (.G_Node[[j + 1]])$extInflow
    {.e1 <- .G_Node[[j + 1]]; .e1$extInflow <- inflow}
  }
  inflow$param <- param
  inflow$type <- type
  inflow$tSeries <- tseries
  inflow$cFactor <- cf
  inflow$sFactor <- sf
  inflow$baseline <- baseline
  inflow$basePat <- basePat
  return(0)
}

