# inflow.c:456
getPatternFactor <- function(p, month, day, hour) {
  p; month; day; hour
  .G_Pattern <- Pattern
  .sw1 <- (.G_Pattern[[p + 1]])$type
  if (.sw1 == 0) {
    if ((month >= 0) && (month < 12)) {
      return(((.G_Pattern[[p + 1]])$factor)$v[[month + 1]])
    }
  } else if (.sw1 == 1) {
    if ((day >= 0) && (day < 7)) {
      return(((.G_Pattern[[p + 1]])$factor)$v[[day + 1]])
    }
  } else if (.sw1 == 2) {
    if ((hour >= 0) && (hour < 24)) {
      return(((.G_Pattern[[p + 1]])$factor)$v[[hour + 1]])
    }
  } else if (.sw1 == 3) {
    if ((day == 0) || (day == 6)) {
      if ((hour >= 0) && (hour < 24)) {
        return(((.G_Pattern[[p + 1]])$factor)$v[[hour + 1]])
      }
    }
  }
  return(1)
}

