    return(invisible(NULL))
  }
  prevInlet <- FirstInlet
  inlet <- FirstInlet
  while (!is.null(inlet)) {
    inletValid <- 0
    i <- inlet$linkIndex
    xsect <<- (.G_Link[[i + 1]])$xsect
    inletType <- (.G_InletDesigns[[inlet$designIndex + 1]])$type
    if (inletType == 6) {
      j <- (.G_InletDesigns[[inlet$designIndex + 1]])$customCurve
      if (j >= 0) {
        if (((.G_Curve[[j + 1]])$curveType == 1) || ((.G_Curve[[j + 1]])$curveType == 3)) {
          inletValid <- 1
        }
      }
    } else if (((xsect$type == 5) || (xsect$type == 4)) && ((inletType == 4) || (inletType == 5))) {
      inletValid <- 1
    } else if (((xsect$type == 25) && (inletType != 4)) && (inletType != 5)) {
      inletValid <- 1
    }
    if (inletValid != 0) {
      {.e1 <- .G_Node[[(.G_Link[[i + 1]])$node2 + 1]]; .e1$inlet <- 1}
      {.e2 <- .G_Node[[inlet$nodeIndex + 1]]; .e2$inlet <- 2}
      inlet$backflow <- 0
      getConduitGeometry(inlet)
      inlet$flowFactor <- ((0.56 / n) * (if ((.p <- SL) > -Inf || is.na(.p)) .p ^ 0.5 else rt_pow(.p, 0.5))) * (if ((.p <- Sx) > -Inf || is.na(.p)) .p ^ 1.67 else rt_pow(.p, 1.67))
      prevInlet <- inlet
      inlet <- inlet$nextInlet
    } else {
      report_writeWarningMsg(.L187, (.G_Link[[i + 1]])$ID)
      if (identical(inlet, FirstInlet)) {
        FirstInlet <<- inlet$nextInlet
        prevInlet <- FirstInlet
        NULL
        inlet <- FirstInlet
      } else {
        prevInlet$nextInlet <- inlet$nextInlet
        NULL
        inlet <- prevInlet$nextInlet
      }
      {.e3 <- .G_Link[[i + 1]]; .e3$inlet <- NULL}
    }
  }
  getBackflowRatios()
}

