    placement <- getInletPlacement(inlet, j)
    if ((.G_InletDesigns[[inlet$designIndex + 1]])$type == 6) {
      q_ <- abs((.G_Link[[i + 1]])$newFlow)
      inlet$flowCapture <- getCustomCapturedFlow(inlet, q_, (.G_Node[[j + 1]])$newDepth)
    } else if (placement == 1) {
      q_ <- abs((.G_Link[[i + 1]])$newFlow)
      inlet$flowCapture <- getOnGradeCapturedFlow(inlet, q_, (.G_Node[[j + 1]])$newDepth)
    } else {
      q_ <- (.G_Node[[j + 1]])$inflow
      inlet$flowCapture <- getOnSagCapturedFlow(inlet, q_, (.G_Node[[j + 1]])$newDepth)
    }
    if (!is.na(.c <- (abs(inlet$flowCapture) < 0.0001)) && .c) {
      inlet$flowCapture <- 0
    }
    .G_InletFlow$v[[j + 1]] <- .G_InletFlow$v[[j + 1]] + inlet$flowCapture
    inlet$backflow <- (.G_Node[[m + 1]])$overflow * inlet$backflowRatio
    if (!is.na(.c <- (abs(inlet$backflow) < 0.0001)) && .c) {
      inlet$backflow <- 0
    }
    inlet <- inlet$nextInlet
  }
  inlet <- .G_FirstInlet
  while (!is.null(inlet)) {
    i <- inlet$linkIndex
    j <- (.G_Link[[i + 1]])$node2
    m <- inlet$nodeIndex
    if ((.G_RouteModel != 4) && (getInletPlacement(inlet, j) == 2)) {
      q_ <- (.G_Node[[j + 1]])$newVolume / tStep
      q_ <- q_ + (if (!is.na(.c <- (((.G_Node[[j + 1]])$inflow) >= 0)) && .c) ((.G_Node[[j + 1]])$inflow) else 0)
      if (!is.na(.c <- (.G_InletFlow$v[[j + 1]] > q_)) && .c) {
        inlet$flowCapture <- inlet$flowCapture * (q_ / (.G_InletFlow$v[[j + 1]]))
      }
    }
    {.e3 <- .G_Node[[j + 1]]; .e3$newLatFlow <- (.G_Node[[j + 1]])$newLatFlow - (inlet$flowCapture - inlet$backflow)}
    {.e4 <- .G_Node[[m + 1]]; .e4$newLatFlow <- (.G_Node[[m + 1]])$newLatFlow + inlet$flowCapture}
    if (!is.na(.c <- (getDateTime(.G_NewRoutingTime) > .G_ReportStart)) && .c) {
      updateInletStats(inlet, abs((.G_Link[[i + 1]])$newFlow))
    }
    inlet <- inlet$nextInlet
  }
}

