        {.e4 <- (.G_Node[[j + 1]])$newQual; .e4$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + (qNet * (((.G_Node[[m + 1]])$oldQual)$v[[p + 1]]))}
