  .G_FirstInlet <- FirstInlet; .G_IgnoreQuality <- IgnoreQuality; .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_StepFlowTotals <- StepFlowTotals; .G_StepQualTotals <- StepQualTotals
