initInletStats <- function(inlet) {
  inlet
  if (!is.null(inlet)) {
    inlet$flowCapture <- 0
    inlet$backflow <- 0
    {.e1 <- inlet$stats; .e1$flowPeriods <- 0}
    {.e2 <- inlet$stats; .e2$capturePeriods <- 0}
    {.e3 <- inlet$stats; .e3$backflowPeriods <- 0}
    {.e4 <- inlet$stats; .e4$peakFlow <- 0}
    {.e5 <- inlet$stats; .e5$peakFlowCapture <- 0}
