# inlet.c:985
updateInletStats <- function(inlet, q_) {
  inlet; q_
  qCapture <- inlet$flowCapture
  qBackflow <- inlet$backflow
  qNet <- qCapture - qBackflow
  qBypass <- q_ - qNet
  fCapture <- 0
  if ((!is.na(.c <- (q_ < 0.001)) && .c) && (!is.na(.c <- (qBackflow <= 0)) && .c)) {
    return(invisible(NULL))
  }
  {.e1 <- inlet$stats; .e1$flowPeriods <- inlet$stats$flowPeriods + 1}
  if (!is.na(.c <- (qNet > 0)) && .c) {
    {.e2 <- inlet$stats; .e2$capturePeriods <- inlet$stats$capturePeriods + 1}
    fCapture <- qNet / q_
    fCapture <- if (!is.na(.c <- (fCapture <= 1)) && .c) fCapture else 1
    {.e3 <- inlet$stats; .e3$avgFlowCapture <- inlet$stats$avgFlowCapture + fCapture}
    if (!is.na(.c <- (qBypass > 0.001)) && .c) {
      {.e4 <- inlet$stats; .e4$bypassFreq <- inlet$stats$bypassFreq + 1}
    }
  } else {
    {.e5 <- inlet$stats; .e5$backflowPeriods <- inlet$stats$backflowPeriods + 1}
  }
  if (!is.na(.c <- (q_ > inlet$stats$peakFlow)) && .c) {
    {.e6 <- inlet$stats; .e6$peakFlow <- q_}
    {.e7 <- inlet$stats; .e7$peakFlowCapture <- fCapture * 100}
  }
}

