# inlet.c:1055
writeStreetStats <- function(link) {
  link
  .G_Frpt <- Frpt; .G_Link <- Link; .G_LinkStats <- LinkStats; .G_Street <- Street
  placement <- 0
  fp <- 0
  cp <- 0
  afc <- 0
  bpf <- 0
  k <- (.G_Link[[link + 1]])$subIndex
  t <- ((.G_Link[[link + 1]])$xsect)$transect
  inlet <- (.G_Link[[link + 1]])$inlet
  maxFlow <- (.G_LinkStats[[link + 1]])$maxFlow
  maxDepth <- (.G_LinkStats[[link + 1]])$maxDepth
  maxSpread <- xsect_getWofY((.G_Link[[link + 1]])$xsect, maxDepth) / ((.G_Street[[t + 1]])$sides)
  maxSpread <- if (!is.na(.c <- (maxSpread <= ((.G_Street[[t + 1]])$width))) && .c) maxSpread else ((.G_Street[[t + 1]])$width)
  rt_fprintf(.G_Frpt$file, .L194, list((.G_Link[[link + 1]])$ID))
  rt_fprintf(.G_Frpt$file, .L195, list(maxFlow * (UCF(10))))
  rt_fprintf(.G_Frpt$file, .L195, list(maxSpread * (UCF(3))))
  rt_fprintf(.G_Frpt$file, .L195, list(maxDepth * (UCF(3))))
  if (!is.null(inlet)) {
    rt_fprintf(.G_Frpt$file, .L196, list((InletDesigns[[inlet$designIndex + 1]])$ID))
    placement <- getInletPlacement(inlet, (.G_Link[[inlet$linkIndex + 1]])$node2)
    if (placement == 1) {
      rt_fprintf(.G_Frpt$file, .L197, list())
    } else {
      rt_fprintf(.G_Frpt$file, .L198, list())
    }
    rt_fprintf(.G_Frpt$file, .L199, list(inlet$numInlets))
    fp <- inlet$stats$flowPeriods / 100
    if (!is.na(.c <- (fp > 0)) && .c) {
      cp <- inlet$stats$capturePeriods / 100
      rt_fprintf(.G_Frpt$file, .L200, list(inlet$stats$peakFlowCapture))
      if (!is.na(.c <- (cp > 0)) && .c) {
        afc <- inlet$stats$avgFlowCapture / cp
        bpf <- inlet$stats$bypassFreq / cp
      }
      rt_fprintf(.G_Frpt$file, .L200, list(afc))
      rt_fprintf(.G_Frpt$file, .L200, list(bpf))
      rt_fprintf(.G_Frpt$file, .L200, list(inlet$stats$backflowPeriods / fp))
      rt_fprintf(.G_Frpt$file, .L200, list(((((maxFlow / ((.G_Street[[t + 1]])$sides)) * (UCF(10))) * 0.01) * inlet$stats$peakFlowCapture) / inlet$numInlets))
      rt_fprintf(.G_Frpt$file, .L200, list(((maxFlow * (UCF(10))) * 0.01) * (100 - inlet$stats$peakFlowCapture)))
    }
  }
}

