# inlet.c:1147
getConduitGeometry <- function(inlet) {
  inlet
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Street <- Street
  linkIndex <- inlet$linkIndex
  t <- 0
  k <- (.G_Link[[linkIndex + 1]])$subIndex
  SL <<- (.G_Conduit[[k + 1]])$slope
  Beta <<- (.G_Conduit[[k + 1]])$beta
  xsect <<- (.G_Link[[linkIndex + 1]])$xsect
  if (xsect$type == 25) {
    t <- xsect$transect
    Sx <<- (.G_Street[[t + 1]])$slope
    a <<- (.G_Street[[t + 1]])$gutterDepression
    W <<- (.G_Street[[t + 1]])$gutterWidth
    n <<- (.G_Street[[t + 1]])$roughness
    Nsides <<- (.G_Street[[t + 1]])$sides
    Tcrown <<- (.G_Street[[t + 1]])$width
    Qfactor <<- inlet$flowFactor
    if ((!is.null(inlet)) && (!is.na(.c <- ((inlet$localDepress * inlet$localWidth) > 0)) && .c)) {
      a <<- a + inlet$localDepress
      W <<- inlet$localWidth
    }
    if (!is.na(.c <- ((W * a) > 0)) && .c) {
      Sw <<- Sx + (a / W)
    } else {
      Sw <<- Sx
    }
  } else {
    a <<- 0
    W <<- 0
    n <<- (.G_Conduit[[k + 1]])$roughness
    Nsides <<- 1
    Sx <<- 0.01
    Sw <<- Sx
  }
}

# inlet.c:1200
getFlowSpread <- function(Q) {
  Q
  .G_Sx <- Sx; .G_Tcrown <- Tcrown; .G_W <- W; .G_a <- a
  iter <- 0
  f1 <- 0
  Sr <- 0
  Ts1 <- 0
  Ts2 <- 0
  Tw <- 0
  Qs <- 0
  Eo <- 0
  f <- Qfactor
  if (!is.na(.c <- (.G_a == 0)) && .c) {
    Ts1 <- if ((.p <- Q / f) > -Inf || is.na(.p)) .p ^ 0.375 else rt_pow(.p, 0.375)
  } else {
    f1 <- f * (if ((.p <- (.G_a / .G_W) / .G_Sx) > -Inf || is.na(.p)) .p ^ 1.67 else rt_pow(.p, 1.67))
    Tw <- if ((.p <- Q / f1) > -Inf || is.na(.p)) .p ^ 0.375 else rt_pow(.p, 0.375)
    if (!is.na(.c <- (Tw <= .G_W)) && .c) {
      Ts1 <- Tw
    } else {
      Sr <- (.G_Sx + (.G_a / .G_W)) / .G_Sx
      iter <- 1
      Ts1 <- (if ((.p <- Q / f) > -Inf || is.na(.p)) .p ^ 0.375 else rt_pow(.p, 0.375)) - .G_W
      if (!is.na(.c <- (Ts1 <= 0)) && .c) {
        Ts1 <- Tw - .G_W
      }
      while (iter < 11) {
        Eo <- getEo(Sr, Ts1, .G_W)
        Qs <- (1 - Eo) * Q
        Ts2 <- if ((.p <- Qs / f) > -Inf || is.na(.p)) .p ^ 0.375 else rt_pow(.p, 0.375)
        if (!is.na(.c <- (abs(Ts2 - Ts1) < 0.01)) && .c) {
          break
        }
        Ts1 <- Ts2
        iter <- iter + 1
      }
      Ts1 <- Ts2 + .G_W
    }
  }
  return(if (!is.na(.c <- (Ts1 <= .G_Tcrown)) && .c) Ts1 else .G_Tcrown)
}

# inlet.c:1248
getEo <- function(Sr, Ts, w) {
  Sr; Ts; w
  x <- Sr / (Ts / w)
  x <- (if ((.p <- 1 + x) > -Inf || is.na(.p)) .p ^ 2.67 else rt_pow(.p, 2.67)) - 1
  x <- 1 + (Sr / x)
  return(1 / x)
}

# inlet.c:1267
getOnGradeCapturedFlow <- function(inlet, q_, d) {
  inlet; q_; d
  qc <- 0
  if (inlet$numInlets == 0) {
    return(0)
  }
  linkIndex <- inlet$linkIndex
  qApproach <- q_
  if (!is.na(.c <- (qApproach < 0.001)) && .c) {
    return(0)
  }
  getConduitGeometry(inlet)
  qApproach <- qApproach / Nsides
  qBypassed <- qApproach
  qCaptured <- 0
  qMax <- 10000000000
  if (!is.na(.c <- (inlet$flowLimit > 0)) && .c) {
    qMax <- inlet$flowLimit
  }
  i <- 1
  while (i <= inlet$numInlets) {
    qc <- getOnGradeInletCapture(inlet$designIndex, qBypassed, d) * inlet$clogFactor
    qc <- if (!is.na(.c <- (qc <= qMax)) && .c) qc else qMax
    qc <- if (!is.na(.c <- (qc <= qBypassed)) && .c) qc else qBypassed
    qCaptured <- qCaptured + qc
    qBypassed <- qBypassed - qc
    if (!is.na(.c <- (qBypassed < 0.001)) && .c) {
      break
    }
    i <- i + 1
  }
  return(qCaptured <- (qCaptured * Nsides))
}

# inlet.c:1325
getOnGradeInletCapture <- function(i, Q, d) {
  i; Q; d
  .G_InletDesigns <- InletDesigns
  Q1 <- Q
  Qc <- 0
  Lsweep <- 0
  Lcurb <- 0
  Lgrate <- 0
  if ((.G_InletDesigns[[i + 1]])$type == 5) {
    Qc <- getOnSagInletCapture(i, d)
    return(if (!is.na(.c <- (Qc <= Q)) && .c) Qc else Q)
  }
  if ((.G_InletDesigns[[i + 1]])$type == 4) {
    Qc <- getGrateInletCapture(i, Q)
    return(if (!is.na(.c <- (Qc <= Q)) && .c) Qc else Q)
  }
  T_ <<- getFlowSpread(Q)
  if ((.G_InletDesigns[[i + 1]])$type == 3) {
    Qc <- getCurbInletCapture(Q, ((.G_InletDesigns[[i + 1]])$slottedInlet)$length)
    return(if (!is.na(.c <- (Qc <= Q)) && .c) Qc else Q)
  }
  Lcurb <- ((.G_InletDesigns[[i + 1]])$curbInlet)$length
  Lgrate <- ((.G_InletDesigns[[i + 1]])$grateInlet)$length
  if (!is.na(.c <- (Lcurb > 0)) && .c) {
    Lsweep <- Lcurb - Lgrate
    if (!is.na(.c <- (Lsweep > 0)) && .c) {
      Qc <- getCurbInletCapture(Q1, Lsweep)
      Q1 <- Q1 - Qc
    }
  }
  if ((!is.na(.c <- (Lgrate > 0)) && .c) && (!is.na(.c <- (Q1 > 0)) && .c)) {
    if (is.na(.c <- (Q1 != Q)) || .c) {
      T_ <<- getFlowSpread(Q1)
    }
    Qc <- Qc + (getGrateInletCapture(i, Q1))
  }
  return(Qc)
}

# inlet.c:1387
getGrateInletCapture <- function(i, Q) {
  i; Q
  .G_Beta <- Beta; .G_InletDesigns <- InletDesigns; .G_Qfactor <- Qfactor; .G_Tcrown <- Tcrown; .G_W <- W; .G_a <- a; .G_xsect <- xsect
  A <- 0
  Y <- 0
  Eo <- 0
  Vo <- 0
  Qo <- Q
  Rf <- 1
  Rs <- 0
  Lg <- ((.G_InletDesigns[[i + 1]])$grateInlet)$length
  Wg <- ((.G_InletDesigns[[i + 1]])$grateInlet)$width
  if ((.G_xsect$type == 5) || (.G_xsect$type == 4)) {
    A <- xsect_getAofS(.G_xsect, (Q / .G_Beta))
    Y <- xsect_getYofA(.G_xsect, A)
    T_ <<- xsect_getWofY(.G_xsect, Y)
    Eo <- ((.G_Beta * (if ((.p <- Y * Wg) > -Inf || is.na(.p)) .p ^ 1.67 else rt_pow(.p, 1.67))) / (if ((.p <- Wg + (2 * Y)) > -Inf || is.na(.p)) .p ^ 0.67 else rt_pow(.p, 0.67))) / Q
    if (((!is.na(.c <- (Wg > (0.99 * .G_xsect$yBot))) && .c) && (.G_xsect$type == 5)) && (!is.na(.c <- (.G_xsect$sBot > 0)) && .c)) {
      Wg <- .G_xsect$yBot
      Sx <<- 1 / .G_xsect$sBot
    }
  } else if (!is.na(.c <- (.G_a == 0)) && .c) {
    A <- ((T_ * T_) * Sx) / 2
    Eo <- getGutterFlowRatio(Wg)
    if (!is.na(.c <- (T_ >= .G_Tcrown)) && .c) {
      Qo <- .G_Qfactor * (if ((.p <- .G_Tcrown) > -Inf || is.na(.p)) .p ^ 2.67 else rt_pow(.p, 2.67))
    }
  } else {
    if (!is.na(.c <- (T_ <= .G_W)) && .c) {
      A <- ((T_ * T_) * Sw) / 2
    } else {
      A <- (((T_ * T_) * Sx) + (.G_a * .G_W)) / 2
    }
    Eo <- getGutterFlowRatio(.G_W)
    if (!is.na(.c <- (Eo < 1)) && .c) {
      if (!is.na(.c <- (T_ >= .G_Tcrown)) && .c) {
        Qo <- (.G_Qfactor * (if ((.p <- .G_Tcrown) > -Inf || is.na(.p)) .p ^ 2.67 else rt_pow(.p, 2.67))) / (1 - Eo)
      }
      Eo <- Eo * (getGutterAreaRatio(Wg, A))
    }
  }
  V <- Qo / A
  grateType <- ((.G_InletDesigns[[i + 1]])$grateInlet)$type
  if ((grateType < 0) || (grateType == 7)) {
    Vo <- ((.G_InletDesigns[[i + 1]])$grateInlet)$splashVeloc
  } else {
    Vo <- getSplashOverVelocity(grateType, Lg)
  }
  if (!is.na(.c <- (V > Vo)) && .c) {
    Rf <- 1 - (0.09 * (V - Vo))
  }
  if (!is.na(.c <- (Eo < 1)) && .c) {
    Rs <- 1 / (1 + (((0.15 * (if ((.p <- V) > -Inf || is.na(.p)) .p ^ 1.8 else rt_pow(.p, 1.8))) / Sx) / (if ((.p <- Lg) > -Inf || is.na(.p)) .p ^ 2.3 else rt_pow(.p, 2.3))))
  }
  return(Q * ((Rf * Eo) + (Rs * (1 - Eo))))
}

# inlet.c:1477
getCurbInletCapture <- function(Q, L) {
  Q; L
  .G_Sx <- Sx; .G_W <- W; .G_a <- a
  Se <- .G_Sx
  Sr <- 0
  Eo <- 0
  E <- 1
  if (!is.na(.c <- (.G_a > 0)) && .c) {
    Sr <- Sw / .G_Sx
    Eo <- getEo(Sr, (T_ - .G_W), .G_W)
    Se <- .G_Sx + ((.G_a / .G_W) * Eo)
  }
  Lt <- ((0.6 * (if ((.p <- Q) > -Inf || is.na(.p)) .p ^ 0.42 else rt_pow(.p, 0.42))) * (if ((.p <- SL) > -Inf || is.na(.p)) .p ^ 0.3 else rt_pow(.p, 0.3))) * (if ((.p <- 1 / (n * Se)) > -Inf || is.na(.p)) .p ^ 0.6 else rt_pow(.p, 0.6))
  if (!is.na(.c <- (L < Lt)) && .c) {
    E <- 1 - (L / Lt)
    E <- 1 - (if ((.p <- E) > -Inf || is.na(.p)) .p ^ 1.8 else rt_pow(.p, 1.8))
  }
  E <- if (!is.na(.c <- (E <= 1)) && .c) E else 1
  E <- if (!is.na(.c <- (E >= 0)) && .c) E else 0
  return(E * Q)
}

# inlet.c:1518
getGutterFlowRatio <- function(w) {
  w
  .G_T_ <- T_
  if (!is.na(.c <- (.G_T_ <= w)) && .c) {
    return(1)
  } else if (!is.na(.c <- (a > 0)) && .c) {
    return(getEo((Sw / Sx), (.G_T_ - w), w))
  } else {
    return(1 - (if ((.p <- 1 - (w / .G_T_)) > -Inf || is.na(.p)) .p ^ 2.67 else rt_pow(.p, 2.67)))
  }
}

# inlet.c:1535
getGutterAreaRatio <- function(Wg, A) {
  Wg; A
  .G_Sx <- Sx; .G_T_ <- T_; .G_W <- W
  if (!is.na(.c <- (Wg >= .G_W)) && .c) {
    return(1)
  }
  if (!is.na(.c <- (.G_T_ <= Wg)) && .c) {
    return(1)
  }
  if (!is.na(.c <- (.G_T_ <= .G_W)) && .c) {
    return(Wg / .G_T_)
  }
  As <- (0.5 * ((.G_T_ - .G_W) * (.G_T_ - .G_W))) * .G_Sx
  Ag <- Wg * (((.G_T_ * .G_Sx) + a) - ((Wg * Sw) / 2))
  return(Ag / (A - As))
}

# inlet.c:1557
getSplashOverVelocity <- function(grateType, L) {
  grateType; L
  .G_SplashCoeffs <- SplashCoeffs
  return((((.G_SplashCoeffs$v[[grateType + 1]])$v[[1]] + ((.G_SplashCoeffs$v[[grateType + 1]])$v[[2]] * L)) - (((.G_SplashCoeffs$v[[grateType + 1]])$v[[3]] * L) * L)) + ((((.G_SplashCoeffs$v[[grateType + 1]])$v[[4]] * L) * L) * L))
}

# inlet.c:1574
getOnSagCapturedFlow <- function(inlet, q_, d) {
  inlet; q_; d
  qCaptured <- 0
  qMax <- 10000000000
  if (inlet$numInlets == 0) {
    return(0)
  }
  totalInlets <- Nsides * inlet$numInlets
  linkIndex <- inlet$linkIndex
  designIndex <- inlet$designIndex
  getConduitGeometry(inlet)
  if (!is.na(.c <- (inlet$flowLimit > 0)) && .c) {
    qMax <- inlet$flowLimit
  }
  qCaptured <- getOnSagInletCapture(designIndex, abs(d))
  qCaptured <- qCaptured * inlet$clogFactor
  qCaptured <- if (!is.na(.c <- (qCaptured <= qMax)) && .c) qCaptured else qMax
  qCaptured <- qCaptured * totalInlets
  return(qCaptured)
}

# inlet.c:1610
getOnSagInletCapture <- function(i, d) {
  i; d
  .G_InletDesigns <- InletDesigns
  Lsweep <- 0
  Lcurb <- 0
  Lgrate <- 0
  Qsw <- 0
  Qso <- 0
  Qgw <- 0
  Qgo <- 0
  Qcw <- 0
  Qco <- 0
  if (!is.na(.c <- (((.G_InletDesigns[[i + 1]])$slottedInlet)$length > 0)) && .c) {
    return(getOnSagSlottedFlow(i, d))
  }
  Lgrate <- ((.G_InletDesigns[[i + 1]])$grateInlet)$length
  if (!is.na(.c <- (Lgrate > 0)) && .c) {
    {.BX_getOnSagInletCapture_Qgw$v <- Qgw; .BX_getOnSagInletCapture_Qgo$v <- Qgo; .r1 <- findOnSagGrateFlows(i, d, .BX_getOnSagInletCapture_Qgw, .BX_getOnSagInletCapture_Qgo); Qgw <- .BX_getOnSagInletCapture_Qgw$v; Qgo <- .BX_getOnSagInletCapture_Qgo$v; .r1}
  }
  Lcurb <- ((.G_InletDesigns[[i + 1]])$curbInlet)$length
  if (!is.na(.c <- (Lcurb > 0)) && .c) {
    Lsweep <- Lcurb - Lgrate
    if (!is.na(.c <- (Lsweep > 0)) && .c) {
      {.BX_getOnSagInletCapture_Qsw$v <- Qsw; .BX_getOnSagInletCapture_Qso$v <- Qso; .r2 <- findOnSagCurbFlows(i, d, Lsweep, .BX_getOnSagInletCapture_Qsw, .BX_getOnSagInletCapture_Qso); Qsw <- .BX_getOnSagInletCapture_Qsw$v; Qso <- .BX_getOnSagInletCapture_Qso$v; .r2}
    }
    if (!is.na(.c <- (Qgo > 0)) && .c) {
      {.BX_getOnSagInletCapture_Qcw$v <- Qcw; .BX_getOnSagInletCapture_Qco$v <- Qco; .r3 <- findOnSagCurbFlows(i, d, Lgrate, .BX_getOnSagInletCapture_Qcw, .BX_getOnSagInletCapture_Qco); Qcw <- .BX_getOnSagInletCapture_Qcw$v; Qco <- .BX_getOnSagInletCapture_Qco$v; .r3}
    }
  }
  return((((Qgw + Qgo) + Qsw) + Qso) + Qco)
}

# inlet.c:1644
findOnSagGrateFlows <- function(i, d, Qw, Qo) {
  i; d; Qw; Qo
  .G_InletDesigns <- InletDesigns; .G_Sw <- Sw
  grateType <- ((.G_InletDesigns[[i + 1]])$grateInlet)$type
  Lg <- ((.G_InletDesigns[[i + 1]])$grateInlet)$length
  Wg <- ((.G_InletDesigns[[i + 1]])$grateInlet)$width
  P <- 0
  Ao <- 0
  di <- 0
  if ((.G_InletDesigns[[i + 1]])$type == 4) {
    di <- d
    P <- 2 * (Lg + Wg)
  } else {
    if (!is.na(.c <- (d <= (Wg * .G_Sw))) && .c) {
      Wg <- d / .G_Sw
    }
    di <- d - ((Wg / 2) * .G_Sw)
    P <- Lg + (2 * Wg)
  }
  if (grateType == 7) {
    Ao <- (Lg * Wg) * (((.G_InletDesigns[[i + 1]])$grateInlet)$fracOpenArea)
  } else {
    Ao <- (Lg * Wg) * (GrateOpeningRatios$v[[grateType + 1]])
  }
  if (!is.na(.c <- (d <= ((1.79 * Ao) / P))) && .c) {
    Qw$v <- (3 * P) * (if ((.p <- di) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
  } else {
    Qo$v <- (0.67 * Ao) * (sqrt((2 * 32.16) * di))
  }
}

# inlet.c:1703
findOnSagCurbFlows <- function(i, d, L, Qw, Qo) {
  i; d; L; Qw; Qo
  .G_InletDesigns <- InletDesigns; .G_a <- a
  throatAngle <- ((.G_InletDesigns[[i + 1]])$curbInlet)$throatAngle
  h <- ((.G_InletDesigns[[i + 1]])$curbInlet)$height
  Qweir <- 0
  P <- 0
  dweir <- 0
  if (!is.na(.c <- (L <= 0)) && .c) {
    return(invisible(NULL))
  }
  if ((.G_InletDesigns[[i + 1]])$type == 5) {
    L <- L * 4
  }
  dorif <- 1.4 * h
  if (!is.na(.c <- (d > dorif)) && .c) {
    Qo$v <- getCurbOrificeFlow(d, h, L, throatAngle)
    return(invisible(NULL))
  }
  if ((!is.na(.c <- (.G_a == 0)) && .c) || (!is.na(.c <- (L > 12)) && .c)) {
    dweir <- h
    if (!is.na(.c <- (d < dweir)) && .c) {
      Qw$v <- (3 * L) * (if ((.p <- d) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
      return(invisible(NULL))
    } else {
      Qweir <- (3 * L) * (if ((.p <- dweir) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    }
  } else {
    P <- L + (1.8 * W)
    dweir <- h + .G_a
    if (!is.na(.c <- (d < dweir)) && .c) {
      Qw$v <- (2.3 * P) * (if ((.p <- d) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
      return(invisible(NULL))
    } else {
      Qweir <- (2.3 * P) * (if ((.p <- dweir) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    }
  }
  Qorif <- getCurbOrificeFlow(dorif, h, L, throatAngle)
  r <- (d - dweir) / (dorif - dweir)
  Qw$v <- (1 - r) * Qweir
  Qo$v <- r * Qorif
}

# inlet.c:1764
getCurbOrificeFlow <- function(di, h, L, throatAngle) {
  di; h; L; throatAngle
  d <- di
  if (throatAngle == 0) {
    d <- di - (h / 2)
  } else if (throatAngle == 1) {
    d <- di - ((h / 2) * 0.7071)
  }
  return(((0.67 * h) * L) * (sqrt((2 * 32.16) * d)))
}

# inlet.c:1785
getOnSagSlottedFlow <- function(i, d) {
  i; d
  .G_InletDesigns <- InletDesigns
  L <- ((.G_InletDesigns[[i + 1]])$slottedInlet)$length
  w <- ((.G_InletDesigns[[i + 1]])$slottedInlet)$width
  if (!is.na(.c <- (d <= (2.587 * w))) && .c) {
    return((2.48 * L) * (if ((.p <- d) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5)))
  } else {
    return(((0.8 * L) * w) * (sqrt(64.32 * d)))
  }
}

# inlet.c:1805
getBackflowRatios <- function() {
  .G_FirstInlet <- FirstInlet
  area <- 0
  f <- 0
  n <- 0
  inletNodes <- rt_recs(rt_u64(Nobjects$v[[3]]), T_TInletNode)
  if (is.null(inletNodes)) {
    return(invisible(NULL))
  }
  inlet <- .G_FirstInlet
  while (!is.null(inlet)) {
    n <- inlet$nodeIndex
    {.e1 <- inletNodes[[n + 1]]; .e1$numInletLinks <- (inletNodes[[n + 1]])$numInletLinks + 1}
    area <- getInletArea(inlet)
    if (!is.na(.c <- (area > 0)) && .c) {
      {.e2 <- inletNodes[[n + 1]]; .e2$numStdInletLinks <- (inletNodes[[n + 1]])$numStdInletLinks + 1}
      {.e3 <- inletNodes[[n + 1]]; .e3$totalInletArea <- (inletNodes[[n + 1]])$totalInletArea + area}
    } else {
      {.e4 <- inletNodes[[n + 1]]; .e4$numCustomInlets <- (inletNodes[[n + 1]])$numCustomInlets + inlet$numInlets}
    }
    inlet <- inlet$nextInlet
  }
  inlet <- .G_FirstInlet
  while (!is.null(inlet)) {
    n <- inlet$nodeIndex
    f <- (inletNodes[[n + 1]])$numStdInletLinks / ((inletNodes[[n + 1]])$numInletLinks)
    area <- getInletArea(inlet)
    if (!is.na(.c <- (area == 0)) && .c) {
      inlet$backflowRatio <- (inlet$numInlets / ((inletNodes[[n + 1]])$numCustomInlets)) * (1 - f)
    } else {
      inlet$backflowRatio <- (area / ((inletNodes[[n + 1]])$totalInletArea)) * f
    }
    inlet <- inlet$nextInlet
  }
  NULL
}

# inlet.c:1870
getInletArea <- function(inlet) {
  inlet
  .G_InletDesigns <- InletDesigns
  area <- 0
  i <- inlet$designIndex
  grateType <- ((.G_InletDesigns[[i + 1]])$grateInlet)$type
  if (!is.na(.c <- (((.G_InletDesigns[[i + 1]])$grateInlet)$length > 0)) && .c) {
    area <- ((.G_InletDesigns[[i + 1]])$grateInlet)$length * (((.G_InletDesigns[[i + 1]])$grateInlet)$width)
    if (grateType == 7) {
      area <- area * (((.G_InletDesigns[[i + 1]])$grateInlet)$fracOpenArea)
    } else {
      area <- area * (GrateOpeningRatios$v[[grateType + 1]])
    }
  }
  curbLength <- ((.G_InletDesigns[[i + 1]])$curbInlet)$length - (((.G_InletDesigns[[i + 1]])$grateInlet)$length)
  if (!is.na(.c <- (curbLength > 0)) && .c) {
    area <- area + (curbLength * (((.G_InletDesigns[[i + 1]])$curbInlet)$height))
  }
  if (!is.na(.c <- (((.G_InletDesigns[[i + 1]])$slottedInlet)$length > 0)) && .c) {
    area <- ((.G_InletDesigns[[i + 1]])$slottedInlet)$length * (((.G_InletDesigns[[i + 1]])$slottedInlet)$width)
  }
  return((area * inlet$numInlets) * inlet$clogFactor)
}

# inlet.c:1902
getCustomCapturedFlow <- function(inlet, q_, d) {
  inlet; q_; d
  .G_Curve <- Curve
  i <- inlet$designIndex
  j <- 0
  sides <- 1
  qIncrement <- 0
  qMax <- 10000000000
  if (inlet$numInlets == 0) {
    return(0)
  }
  qMax <- 10000000000
  if (!is.na(.c <- (inlet$flowLimit > 0)) && .c) {
    qMax <- inlet$flowLimit
  }
  xsect <<- (Link[[inlet$linkIndex + 1]])$xsect
  if (xsect$type == 25) {
    sides <- (Street[[xsect$transect + 1]])$sides
  }
  qApproach <- q_ / sides
  qBypassed <- qApproach
  qCaptured <- 0
  c_ <- (InletDesigns[[i + 1]])$customCurve
  if (c_ >= 0) {
    if ((.G_Curve[[c_ + 1]])$curveType == 1) {
      j <- 1
      while (j <= inlet$numInlets) {
        qIncrement <- (inlet$clogFactor * (table_lookupEx(.G_Curve[[c_ + 1]], (qBypassed * (UCF(10)))))) / (UCF(10))
        qIncrement <- if (!is.na(.c <- (qIncrement <= qMax)) && .c) qIncrement else qMax
        qIncrement <- if (!is.na(.c <- (qIncrement <= qBypassed)) && .c) qIncrement else qBypassed
        qCaptured <- qCaptured + qIncrement
        qBypassed <- qBypassed - qIncrement
        if (!is.na(.c <- (qBypassed < 0.001)) && .c) {
          break
        }
        j <- j + 1
      }
    } else if ((.G_Curve[[c_ + 1]])$curveType == 3) {
      qCaptured <- ((inlet$numInlets * inlet$clogFactor) * (table_lookupEx(.G_Curve[[c_ + 1]], (d * (UCF(3)))))) / (UCF(10))
    }
    qCaptured <- qCaptured * sides
  }
  return(qCaptured)
}

# input.c:69
input_countObjects <- function() {
  .G_Finp <- Finp; .G_MAXERRS <- MAXERRS; .G_Nlinks <- Nlinks; .G_Nnodes <- Nnodes; .G_Nobjects <- Nobjects; .G_SectWords <- SectWords
  line <- rt_cbuf(1025)
  wLine <- rt_cbuf(1025)
  tok <- NULL
  sect <- -1
  newsect <- 0
  errcode <- 0
  errsum <- 0
  lineCount <- 0
  if (ErrorCode != 0) {
    return(ErrorCode)
  }
  error_setInpError(0, .L0)
  i <- 0
  while (i < 18) {
    .G_Nobjects$v[[i + 1]] <- 0
    i <- i + 1
  }
  i <- 0
  while (i < 5) {
    .G_Nnodes$v[[i + 1]] <- 0
    i <- i + 1
  }
  i <- 0
  while (i < 5) {
    .G_Nlinks$v[[i + 1]] <- 0
    i <- i + 1
  }
  controls_init()
  while (!is.null(rt_fgets(line, 1024, .G_Finp$file))) {
    lineCount <- lineCount + 1
    sstrncpy(wLine, line, 1024)
    tok <- rt_strtok(wLine, .L184)
    if (is.null(tok)) {
      next
    }
    if (rt_cget(tok, 0) == 59) {
      next
    }
    if (rt_cget(tok, 0) == 91) {
      newsect <- findmatch(tok, .G_SectWords)
      if (newsect >= 0) {
        sect <- newsect
        next
      } else {
        sect <- -1
        errcode <- 205
      }
    }
    if (sect == 1) {
      errcode <- readOption(line)
    } else if (sect >= 0) {
      errcode <- addObject(sect, tok)
    }
    if (errcode != 0) {
      report_writeInputErrorMsg(errcode, sect, line, lineCount)
      errsum <- errsum + 1
      if (errsum >= .G_MAXERRS) {
        break
      }
    }
  }
  if (errsum > 0) {
    ErrorCode <<- 200
  }
  return(ErrorCode)
}

# input.c:141
input_readData <- function() {
  .G_Finp <- Finp; .G_MAXERRS <- MAXERRS; .G_Mlinks <- Mlinks; .G_Mnodes <- Mnodes; .G_Mobjects <- Mobjects; .G_Nobjects <- Nobjects; .G_SectWords <- SectWords; .G_StartDate <- StartDate; .G_StartTime <- StartTime; .G_Tok <- Tok; .G_Tseries <- Tseries
  line <- rt_cbuf(1025)
  wLine <- rt_cbuf(1025)
  comment <- NULL
  newsect <- 0
  inperr <- 0
  lineLength <- 0
  lineCount <- 0
  if (ErrorCode != 0) {
    return(ErrorCode)
  }
  error_setInpError(0, .L0)
  i <- 0
  while (i < 18) {
    .G_Mobjects$v[[i + 1]] <- 0
    i <- i + 1
  }
  i <- 0
  while (i < 5) {
    .G_Mnodes$v[[i + 1]] <- 0
    i <- i + 1
  }
  i <- 0
  while (i < 5) {
    .G_Mlinks$v[[i + 1]] <- 0
    i <- i + 1
  }
  Mevents <<- 0
  i <- 0
  while (i < .G_Nobjects$v[[9]]) {
    {.e1 <- .G_Tseries[[i + 1]]; .e1$lastDate <- .G_StartDate$v + .G_StartTime$v}
    i <- i + 1
  }
  sect <- 0
  errsum <- 0
  rt_rewind(.G_Finp$file)
  while (!is.null(rt_fgets(line, 1024, .G_Finp$file))) {
    lineCount <- lineCount + 1
    sstrncpy(wLine, line, 1024)
    Ntokens <<- getTokens(wLine)
    if (Ntokens == 0) {
      next
    }
    if (rt_cget(.G_Tok$v[[1]], 0) == 59) {
      next
    }
    lineLength <- rt_i32(rt_strlen(line))
    if (lineLength >= 1024) {
      comment <- rt_strchr(line, 59)
      if (!is.null(comment)) {
        lineLength <- rt_i32(rt_cdiff(comment, line))
      }
      if (lineLength >= 1024) {
        inperr <- 201
        report_writeInputErrorMsg(inperr, sect, line, lineCount)
        errsum <- errsum + 1
      }
    }
    if (rt_cget(.G_Tok$v[[1]], 0) == 91) {
      newsect <- findmatch(.G_Tok$v[[1]], .G_SectWords)
      if (newsect >= 0) {
        if (sect == 22) {
          transect_validate((.G_Nobjects$v[[11]] - 1))
        }
        sect <- newsect
        next
      } else {
        inperr <- error_setInpError(205, .G_Tok$v[[1]])
        report_writeInputErrorMsg(inperr, sect, line, lineCount)
        errsum <- errsum + 1
        break
      }
    } else {
      inperr <- parseLine(sect, line)
      if (inperr > 0) {
        errsum <- errsum + 1
        if (errsum > .G_MAXERRS) {
          report_writeLine(.L201)
        } else {
          report_writeInputErrorMsg(inperr, sect, line, lineCount)
        }
      }
    }
    if (errsum > .G_MAXERRS) {
      break
    }
  }
  if (errsum > 0) {
    ErrorCode <<- 200
  }
  return(ErrorCode)
}

