# input.c:637
readControl <- function(tok, ntoks) {
  tok; ntoks
  .G_Mobjects <- Mobjects; .G_Tok <- Tok
  if (ntoks < 2) {
    return(error_setInpError(203, .L0))
  }
  if (match_(tok$v[[1]], .L29) != 0) {
    return(controls_addVariable(tok, ntoks))
  }
  if (match_(tok$v[[1]], .L30) != 0) {
    return(controls_addExpression(tok, ntoks))
  }
  keyword <- findmatch(tok$v[[1]], RuleKeyWords)
  if (keyword < 0) {
    return(error_setInpError(205, tok$v[[1]]))
  }
  if (keyword == 0) {
    if (!(project_addObject(9, tok$v[[2]], .G_Mobjects$v[[10]]) != 0)) {
      return(error_setInpError(207, .G_Tok$v[[2]]))
    }
    .G_Mobjects$v[[10]] <- .G_Mobjects$v[[10]] + 1
  }
  index <- .G_Mobjects$v[[10]] - 1
  if (index < 0) {
    return(error_setInpError(217, .L0))
  }
  return(controls_addRuleClause(index, keyword, .G_Tok, Ntokens))
}

