readTitle <- function(line) {
  line
  .G_Title <- Title
  n <- 0
  i <- 0
  while (i < 3) {
    if (rt_strlen(.G_Title$v[[i + 1]]) == 0) {
      n <- rt_i32(rt_strlen(line))
      if (rt_cget(line, (n - 1)) == 10) {
        rt_cset(line, (n - 1), 32)
      }
      sstrncpy(.G_Title$v[[i + 1]], line, 1024)
      break
    }
    i <- i + 1
  }
  return(0)
}

