readEvent <- function(tok, ntoks) {
  tok; ntoks
  .G_Event <- Event
  x <- rt_ra(numeric(4))
  if (ntoks < 4) {
    return(error_setInpError(203, .L0))
  }
  if (!({.b1 <- rt_box(x$v[[1]]); .r2 <- datetime_strToDate(tok$v[[1]], .b1); x$v[[1]] <- .b1$v; .r2} != 0)) {
    return(error_setInpError(213, tok$v[[1]]))
  }
  if (!({.b3 <- rt_box(x$v[[2]]); .r4 <- datetime_strToTime(tok$v[[2]], .b3); x$v[[2]] <- .b3$v; .r4} != 0)) {
    return(error_setInpError(213, tok$v[[2]]))
  }
  if (!({.b5 <- rt_box(x$v[[3]]); .r6 <- datetime_strToDate(tok$v[[3]], .b5); x$v[[3]] <- .b5$v; .r6} != 0)) {
    return(error_setInpError(213, tok$v[[3]]))
  }
  if (!({.b7 <- rt_box(x$v[[4]]); .r8 <- datetime_strToTime(tok$v[[4]], .b7); x$v[[4]] <- .b7$v; .r8} != 0)) {
    return(error_setInpError(213, tok$v[[4]]))
  }
  {.e9 <- .G_Event[[Mevents + 1]]; .e9$start <- x$v[[1]] + x$v[[2]]}
  {.e10 <- .G_Event[[Mevents + 1]]; .e10$end <- x$v[[3]] + x$v[[4]]}
  if (!is.na(.c <- ((.G_Event[[Mevents + 1]])$start >= (.G_Event[[Mevents + 1]])$end)) && .c) {
    return(error_setInpError(213, .L204))
  }
  Mevents <<- Mevents + 1
  return(0)
}

# input.c:779
findmatch <- function(s, keyword) {
  s; keyword
  i <- 0
  while (!is.null(keyword$v[[i + 1]])) {
    if (match_(s, keyword$v[[i + 1]]) != 0) {
      return(i)
    }
    i <- i + 1
  }
  return(-1)
}

# input.c:798
match_ <- function(str, substr_) {
  str; substr_
  i <- 0
  j <- 0
  if (!(rt_cget(substr_, 0) != 0)) {
    return(0)
  }
  k <- 0
  while (rt_cget(str, k) != 0) {
    if (rt_cget(str, k) != 32) {
      break
    }
    k <- k + 1
  }
  i <- k; j <- 0
  while (rt_cget(substr_, j) != 0) {
    if ((!(rt_cget(str, i) != 0)) || ((if (((rt_cget(str, i)) >= 97) && ((rt_cget(str, i)) <= 122)) (rt_band((rt_cget(str, i)), (-32 - 1))) else (rt_cget(str, i))) != (if (((rt_cget(substr_, j)) >= 97) && ((rt_cget(substr_, j)) <= 122)) (rt_band((rt_cget(substr_, j)), (-32 - 1))) else (rt_cget(substr_, j))))) {
      return(0)
    }
    i <- i + 1; j <- j + 1
  }
  return(1)
}

