getInt <- function(s, y) {
  s; y
  x <- 0
  if ({.BX_getInt_x$v <- x; .r1 <- getDouble(s, .BX_getInt_x); x <- .BX_getInt_x$v; .r1} != 0) {
    if (!is.na(.c <- (x < 0)) && .c) {
      x <- x - 0.01
    } else {
      x <- x + 0.01
    }
    y$v <- if (is.na(.d <- x) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
    return(1)
  }
  y$v <- 0
  return(0)
}

