# input.c:882
getTokens <- function(s) {
  s
  .G_Tok <- Tok
  m <- 0
  n <- 0
  while (n < 40) {
    .G_Tok$v[n + 1] <- list(NULL)
    n <- n + 1
  }
  n <- 0
  c_ <- rt_strchr(s, 59)
  if (!is.null(c_)) {
    rt_cset(c_, 0, 0)
  }
  len <- rt_i32(rt_strlen(s))
  while ((len > 0) && (n < 40)) {
    m <- rt_i32(rt_strcspn(s, .L184))
    if (m == 0) {
      s <- rt_cadd(s, 1)
    } else {
      if (rt_cget(s, 0) == 34) {
        s <- rt_cadd(s, 1)
        len <- len - 1
        m <- rt_i32(rt_strcspn(s, .L205))
      }
      rt_cset(s, m, 0)
      .G_Tok$v[n + 1] <- list(s)
      n <- n + 1
      s <- rt_cadd(s, (m + 1))
    }
    len <- len - (m + 1)
  }
  return(n)
}

