# kinwave.c:57
kinwave_execute <- function(j, qinflow, qoutflow, tStep) {
  j; qinflow; qoutflow; tStep
  .G_Conduit <- Conduit; .G_Link <- Link; .G_WT <- WT; .G_WX <- WX
  result <- 1
  dxdt <- 0
  dq <- 0
  ain <- 0
  aout <- 0
  qout <- 0
  qoutflow$v <- qinflow$v
  if ((.G_Link[[j + 1]])$type != 0) {
    return(result)
  }
  if (((.G_Link[[j + 1]])$xsect)$type == 0) {
    return(result)
  }
  pXsect <<- (.G_Link[[j + 1]])$xsect
  Qfull <<- (.G_Link[[j + 1]])$qFull
  Afull <<- ((.G_Link[[j + 1]])$xsect)$aFull
  k <- (.G_Link[[j + 1]])$subIndex
  Beta1 <<- (.G_Conduit[[k + 1]])$beta / Qfull
  q1 <- (.G_Conduit[[k + 1]])$q1 / Qfull
  q2 <- (.G_Conduit[[k + 1]])$q2 / Qfull
  qin <- (qinflow$v / ((.G_Conduit[[k + 1]])$barrels)) / Qfull
  q3 <- link_getLossRate(j, 2, (qin * Qfull), tStep) / Qfull
  a1 <- (.G_Conduit[[k + 1]])$a1 / Afull
  a2 <- (.G_Conduit[[k + 1]])$a2 / Afull
  if (!is.na(.c <- (qin >= 1)) && .c) {
    ain <- 1
  } else {
    ain <- xsect_getAofS(pXsect, (qin / Beta1)) / Afull
  }
  if ((!is.na(.c <- (qin <= 1e-06)) && .c) && (!is.na(.c <- (q2 <= 1e-06)) && .c)) {
    qout <- 0
    aout <- 0
  } else {
    dxdt <- ((link_getLength(j) / tStep) * Afull) / Qfull
    dq <- q2 - q1
    C1 <<- (dxdt * .G_WT) / .G_WX
    C2 <<- (1 - .G_WT) * (ain - a1)
    C2 <<- C2 - (.G_WT * a2)
    C2 <<- (C2 * dxdt) / .G_WX
    C2 <<- (C2 + (((1 - .G_WX) / .G_WX) * dq)) - qin
    C2 <<- C2 + (q3 / .G_WX)
    aout <- a2
    result <- {.BX_kinwave_execute_aout$v <- aout; .r1 <- solveContinuity(qin, ain, .BX_kinwave_execute_aout); aout <- .BX_kinwave_execute_aout$v; .r1}
    if (result == (-1)) {
      report_writeErrorMsg(103, (.G_Link[[j + 1]])$ID)
      return(1)
    }
    if (result <= 0) {
      result <- 1
    }
    qout <- Beta1 * (xsect_getSofA(pXsect, (aout * Afull)))
    if (!is.na(.c <- (qin > 1)) && .c) {
      qin <- 1
    }
  }
  {.e2 <- .G_Conduit[[k + 1]]; .e2$q1 <- qin * Qfull}
  {.e3 <- .G_Conduit[[k + 1]]; .e3$a1 <- ain * Afull}
  {.e4 <- .G_Conduit[[k + 1]]; .e4$q2 <- qout * Qfull}
  {.e5 <- .G_Conduit[[k + 1]]; .e5$a2 <- aout * Afull}
  {.e6 <- .G_Conduit[[k + 1]]; .e6$fullState <- link_getFullState((.G_Conduit[[k + 1]])$a1, (.G_Conduit[[k + 1]])$a2, Afull)}
  qinflow$v <- (.G_Conduit[[k + 1]])$q1 * ((.G_Conduit[[k + 1]])$barrels)
  qoutflow$v <- (.G_Conduit[[k + 1]])$q2 * ((.G_Conduit[[k + 1]])$barrels)
  return(result)
}

# kinwave.c:170
solveContinuity <- function(qin, ain, aout) {
  qin; ain; aout
  .G_C1 <- C1; .G_C2 <- C2; .G_pXsect <- pXsect
  n <- 0
  aTmp <- 0
  fLo <- 0
  tol <- EPSIL
  aHi <- 1
  fHi <- (1 + .G_C1) + .G_C2
  aLo <- xsect_getAmax(.G_pXsect) / Afull
  if (!is.na(.c <- (aLo < aHi)) && .c) {
    fLo <- ((Beta1 * .G_pXsect$sMax) + (.G_C1 * aLo)) + .G_C2
  } else {
    fLo <- fHi
  }
  if (!is.na(.c <- ((fHi * fLo) > 0)) && .c) {
    aHi <- aLo
    fHi <- fLo
    aLo <- 0
    fLo <- .G_C2
  }
  if (!is.na(.c <- ((fHi * fLo) <= 0)) && .c) {
    if ((!is.na(.c <- (aout$v < aLo)) && .c) || (!is.na(.c <- (aout$v > aHi)) && .c)) {
      aout$v <- 0.5 * (aLo + aHi)
    }
    if (!is.na(.c <- (fLo > fHi)) && .c) {
      aTmp <- aLo
      aLo <- aHi
      aHi <- aTmp
    }
    n <- findroot_Newton(aLo, aHi, aout, tol, evalContinuity, NULL)
    if (n <= 0) {
      n <- -1
    }
  } else if (!is.na(.c <- (fLo < 0)) && .c) {
    if (!is.na(.c <- (qin > 1)) && .c) {
      aout$v <- ain
    } else {
      aout$v <- 1
    }
    n <- -2
  } else if (!is.na(.c <- (fLo > 0)) && .c) {
    aout$v <- 0
    n <- -3
  } else {
    n <- -1
  }
  return(n)
}

# kinwave.c:261
evalContinuity <- function(a, f, df, p) {
  a; f; df; p
  .G_Afull <- Afull; .G_Beta1 <- Beta1; .G_C1 <- C1; .G_pXsect <- pXsect
  f$v <- ((.G_Beta1 * (xsect_getSofA(.G_pXsect, (a * .G_Afull)))) + (.G_C1 * a)) + C2
  df$v <- ((.G_Beta1 * .G_Afull) * (xsect_getdSdA(.G_pXsect, (a * .G_Afull)))) + .G_C1
}

# landuse.c:51
landuse_readParams <- function(j, tok, ntoks) {
  j; tok; ntoks
  .G_Landuse <- Landuse
  if (ntoks < 1) {
    return(error_setInpError(203, .L0))
  }
  id <- project_findID(5, tok$v[[1]])
  if (is.null(id)) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  {.e1 <- .G_Landuse[[j + 1]]; .e1$ID <- id}
  if (ntoks > 1) {
    if (ntoks < 4) {
