# landuse.c:355
landuse_getInitBuildup <- function(landFactor, initBuildup, area, curb) {
  landFactor; initBuildup; area; curb
  .G_Landuse <- Landuse; .G_Nobjects <- Nobjects; .G_StartDateTime <- StartDateTime
  p <- 0
  f <- 0
  fArea <- 0
  fCurb <- 0
  buildup <- 0
  startDrySeconds <- StartDryDays * 86400
  i <- 0
  while (i < .G_Nobjects$v[[6]]) {
    {.e1 <- landFactor[[i + 1]]; .e1$lastSwept <- .G_StartDateTime - ((.G_Landuse[[i + 1]])$sweepDays0)}
    f <- (landFactor[[i + 1]])$fraction
    fArea <- (f * area) * (UCF(4))
    fCurb <- f * curb
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      buildup <- 0
      if (!is.na(.c <- (initBuildup$v[[p + 1]] > 0)) && .c) {
        buildup <- initBuildup$v[[p + 1]] * fArea
      } else {
        buildup <- landuse_getBuildup(i, p, fArea, fCurb, buildup, startDrySeconds)
      }
      {.e2 <- (landFactor[[i + 1]])$buildup; .e2$v[[p + 1]] <- buildup}
      p <- p + 1
    }
    i <- i + 1
  }
}

# landuse.c:411
landuse_getBuildup <- function(i, p, area, curb, buildup, tStep) {
  i; p; area; curb; buildup; tStep
  .G_Landuse <- Landuse
  if (((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType == 0) || (!is.na(.c <- (tStep == 0)) && .c)) {
    return(buildup)
  }
  n <- (((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$normalizer
  perUnit <- 1
  if (n == 0) {
    perUnit <- area
  }
  if (n == 1) {
    perUnit <- curb
  }
  if (!is.na(.c <- (perUnit == 0)) && .c) {
    return(0)
  }
  if ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType == 4) {
    return(landuse_getExternalBuildup(i, p, (buildup / perUnit), tStep) * perUnit)
  }
  days <- landuse_getBuildupDays(i, p, (buildup / perUnit))
  days <- days + (tStep / 86400)
  return(landuse_getBuildupMass(i, p, days) * perUnit)
}

# landuse.c:458
landuse_getBuildupDays <- function(i, p, buildup) {
  i; p; buildup
  .G_Landuse <- Landuse
  c0 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[1]]
  c1 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[2]]
  c2 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[3]]
  if (!is.na(.c <- (buildup == 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (buildup >= c0)) && .c) {
    return((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$maxDays)
  }
  .sw1 <- (((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType
  if (.sw1 == 1) {
    if (!is.na(.c <- ((c1 * c2) == 0)) && .c) {
      return(0)
    } else {
      return(rt_pow(buildup / c1, 1 / c2))
    }
  } else if (.sw1 == 2) {
    if (!is.na(.c <- ((c0 * c1) == 0)) && .c) {
      return(0)
    } else {
      return((-(rt_log(1 - (buildup / c0)))) / c1)
    }
  } else if (.sw1 == 3) {
    if (!is.na(.c <- (c0 == 0)) && .c) {
      return(0)
    } else {
      return((buildup * c2) / (c0 - buildup))
    }
  } else {
    return(0)
  }
}

# landuse.c:494
landuse_getBuildupMass <- function(i, p, days) {
  i; p; days
  .G_Landuse <- Landuse
  b <- 0
  c0 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[1]]
  c1 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[2]]
  c2 <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[3]]
  if (!is.na(.c <- (days == 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (days >= (((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$maxDays)) && .c) {
    return(c0)
  }
  .sw1 <- (((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType
  if (.sw1 == 1) {
    b <- c1 * (rt_pow(days, c2))
    if (!is.na(.c <- (b > c0)) && .c) {
      b <- c0
    }
  } else if (.sw1 == 2) {
    b <- c0 * (1 - (exp((-days) * c1)))
  } else if (.sw1 == 3) {
    b <- (days * c0) / (c2 + days)
  } else {
    b <- 0
  }
  return(b)
}

# landuse.c:532
landuse_getAvgBmpEffic <- function(j, p) {
  j; p
  .G_Landuse <- Landuse; .G_Nobjects <- Nobjects; .G_Subcatch <- Subcatch
  r <- 0
  i <- 0
  while (i < .G_Nobjects$v[[6]]) {
    r <- r + ((((.G_Subcatch[[j + 1]])$landFactor)[[i + 1]])$fraction * ((((.G_Landuse[[i + 1]])$washoffFunc)[[p + 1]])$bmpEffic))
    i <- i + 1
  }
  return(r)
}

# landuse.c:553
landuse_getWashoffLoad <- function(i, p, area, landFactor, runoff, vOutflow) {
  i; p; area; landFactor; runoff; vOutflow
  .G_Landuse <- Landuse; .G_Pollut <- Pollut
  buildup <- ((landFactor[[i + 1]])$buildup)$v[[p + 1]]
  landuseArea <- (landFactor[[i + 1]])$fraction * area
  washoffQual <- landuse_getWashoffQual(i, p, buildup, runoff, landuseArea)
  washoffLoad <- (((washoffQual * vOutflow) * landuseArea) / area) * ((.G_Pollut[[p + 1]])$mcf)
  if (((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType != 0) || (!is.na(.c <- (buildup > washoffLoad)) && .c)) {
    washoffLoad <- if (!is.na(.c <- (washoffLoad <= buildup)) && .c) washoffLoad else buildup
    buildup <- buildup - washoffLoad
    {.e1 <- (landFactor[[i + 1]])$buildup; .e1$v[[p + 1]] <- buildup}
  } else {
    massbal_updateLoadingTotals(0, p, washoffLoad)
    {.e2 <- (landFactor[[i + 1]])$buildup; .e2$v[[p + 1]] <- 0}
  }
  bmpRemoval <- (((.G_Landuse[[i + 1]])$washoffFunc)[[p + 1]])$bmpEffic * washoffLoad
  if (!is.na(.c <- (bmpRemoval > 0)) && .c) {
    massbal_updateLoadingTotals(3, p, bmpRemoval)
    washoffLoad <- washoffLoad - bmpRemoval
  }
  return(washoffLoad / ((.G_Pollut[[p + 1]])$mcf))
}

# landuse.c:612
landuse_getWashoffQual <- function(i, p, buildup, runoff, area) {
  i; p; buildup; runoff; area
  .G_Landuse <- Landuse
  cWashoff <- 0
  coeff <- (((.G_Landuse[[i + 1]])$washoffFunc)[[p + 1]])$coeff
  expon <- (((.G_Landuse[[i + 1]])$washoffFunc)[[p + 1]])$expon
  func <- (((.G_Landuse[[i + 1]])$washoffFunc)[[p + 1]])$funcType
  if ((func == 0) || (!is.na(.c <- (runoff == 0)) && .c)) {
    return(0)
  }
  if (((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$funcType != 0) && (!is.na(.c <- (buildup == 0)) && .c)) {
    return(0)
  }
  if (func == 1) {
    cWashoff <- ((coeff * (rt_pow(runoff * (UCF(0)), expon))) * buildup) / ((Pollut[[p + 1]])$mcf)
    cWashoff <- cWashoff / (runoff * area)
  } else if (func == 2) {
    cWashoff <- coeff * (rt_pow(runoff * area, expon - 1))
  } else if (func == 3) {
    cWashoff <- coeff
  }
  return(cWashoff)
}

# landuse.c:665
landuse_getCoPollutLoad <- function(p, washoff) {
  p; washoff
  .G_Pollut <- Pollut
