  k <- (.G_Pollut[[p + 1]])$coPollut
  if (k >= 0) {
    w <- (.G_Pollut[[p + 1]])$coFraction * (washoff$v[[k + 1]])
    massbal_updateLoadingTotals(0, p, (w * ((.G_Pollut[[p + 1]])$mcf)))
    return(w)
  }
  return(0)
}

# landuse.c:693
landuse_getExternalBuildup <- function(i, p, buildup, tStep) {
  i; p; buildup; tStep
  .G_Landuse <- Landuse; .G_NewRunoffTime <- NewRunoffTime
  maxBuildup <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[1]]
  sf <- ((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[2]]
  ts <- if (is.na(.d <- floor(((((.G_Landuse[[i + 1]])$buildupFunc)[[p + 1]])$coeff)$v[[3]])) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  rate <- 0
  if (!is.na(.c <- (.G_NewRunoffTime == 0)) && .c) {
    return(0)
  }
  if (ts >= 0) {
    rate <- sf * (table_tseriesLookup(Tseries[[ts + 1]], getDateTime(.G_NewRunoffTime), 0))
  }
  buildup <- buildup + ((rate * tStep) / 86400)
  buildup <- if (!is.na(.c <- (buildup <= maxBuildup)) && .c) buildup else maxBuildup
  return(buildup)
}

# lid.c:237
lid_create <- function(lidCount, subcatchCount) {
  lidCount; subcatchCount
  .G_Nobjects <- Nobjects
  LidProcs <<- NULL
  LidGroups <<- NULL
  LidCount <<- lidCount
  GroupCount <<- subcatchCount
  if (GroupCount > 0) {
    LidGroups <<- rt_ra(vector("list", rt_u64(GroupCount)))
    if (is.null(LidGroups)) {
      ErrorCode <<- 101
      return(invisible(NULL))
    }
  }
  j <- 0
  while (j < GroupCount) {
    {.e1 <- LidGroups; .e1$v[j + 1] <- list(NULL)}
    j <- j + 1
  }
  if (LidCount == 0) {
    return(invisible(NULL))
  }
  LidProcs <<- rt_recs(rt_u64(LidCount), T_TLidProc)
  if (is.null(LidProcs)) {
    ErrorCode <<- 101
    return(invisible(NULL))
  }
  j <- 0
  while (j < LidCount) {
    {.e2 <- LidProcs[[j + 1]]; .e2$lidType <- -1}
    {.e3 <- (LidProcs[[j + 1]])$surface; .e3$thickness <- 0}
    {.e4 <- (LidProcs[[j + 1]])$surface; .e4$voidFrac <- 1}
    {.e5 <- (LidProcs[[j + 1]])$surface; .e5$roughness <- 0}
    {.e6 <- (LidProcs[[j + 1]])$surface; .e6$surfSlope <- 0}
    {.e7 <- (LidProcs[[j + 1]])$pavement; .e7$thickness <- 0}
    {.e8 <- (LidProcs[[j + 1]])$soil; .e8$thickness <- 0}
    {.e9 <- (LidProcs[[j + 1]])$storage; .e9$thickness <- 0}
    {.e10 <- (LidProcs[[j + 1]])$storage; .e10$kSat <- 0}
    {.e11 <- (LidProcs[[j + 1]])$drain; .e11$coeff <- 0}
    {.e12 <- (LidProcs[[j + 1]])$drain; .e12$offset <- 0}
    {.e13 <- (LidProcs[[j + 1]])$drainMat; .e13$thickness <- 0}
    {.e14 <- (LidProcs[[j + 1]])$drainMat; .e14$roughness <- 0}
    {.e15 <- LidProcs[[j + 1]]; .e15$drainRmvl <- NULL}
    {.e16 <- LidProcs[[j + 1]]; .e16$drainRmvl <- rt_ra(numeric(rt_u64(.G_Nobjects$v[[5]])))}
    if (is.null((LidProcs[[j + 1]])$drainRmvl)) {
      ErrorCode <<- 101
      return(invisible(NULL))
    }
    j <- j + 1
  }
}

# lid.c:304
lid_delete <- function() {
  j <- 0
  while (j < GroupCount) {
    freeLidGroup(j)
    j <- j + 1
  }
  if (!is.null(LidGroups)) {
    NULL
    LidGroups <<- NULL
  }
  j <- 0
  while (j < LidCount) {
    if (!is.null((LidProcs[[j + 1]])$drainRmvl)) {
      NULL
      {.e1 <- LidProcs[[j + 1]]; .e1$drainRmvl <- NULL}
    }
    j <- j + 1
  }
  if (!is.null(LidProcs)) {
    NULL
    LidProcs <<- NULL
  }
  GroupCount <<- 0
  LidCount <<- 0
}

# lid.c:322
freeLidGroup <- function(j) {
  j
  .G_LidGroups <- LidGroups
  lidGroup <- .G_LidGroups$v[[j + 1]]
  lidUnit <- NULL
  nextLidUnit <- NULL
  if (is.null(lidGroup)) {
    return(invisible(NULL))
  }
  lidList <- lidGroup$lidList
  while (!is.null(lidList)) {
    lidUnit <- lidList$lidUnit
    if (!is.null(lidUnit$rptFile)) {
      if (!is.null(lidUnit$rptFile$file)) {
        rt_fclose(lidUnit$rptFile$file)
      }
      NULL
    }
    nextLidUnit <- lidList$nextLidUnit
    NULL
    NULL
    lidList <- nextLidUnit
  }
  NULL
  .G_LidGroups$v[j + 1] <- list(NULL)
}

# lid.c:355
lid_readProcParams <- function(toks, ntoks) {
  toks; ntoks
  .G_LidProcs <- LidProcs
  if (ntoks < 2) {
    return(error_setInpError(203, .L0))
  }
  j <- project_findObject(15, toks$v[[1]])
  if (j < 0) {
    return(error_setInpError(209, toks$v[[1]]))
  }
  if (is.null((.G_LidProcs[[j + 1]])$ID)) {
    {.e1 <- .G_LidProcs[[j + 1]]; .e1$ID <- project_findID(15, toks$v[[1]])}
  }
  m <- findmatch(toks$v[[2]], LidTypeWords)
  if (m >= 0) {
    {.e2 <- .G_LidProcs[[j + 1]]; .e2$lidType <- m}
    return(0)
  } else {
    m <- findmatch(toks$v[[2]], LidLayerWords)
  }
  if (m == 0) {
    return(readSurfaceData(j, toks, ntoks))
  } else if (m == 1) {
    return(readSoilData(j, toks, ntoks))
  } else if (m == 2) {
    return(readStorageData(j, toks, ntoks))
  } else if (m == 3) {
    return(readPavementData(j, toks, ntoks))
  } else if (m == 5) {
    return(readDrainData(j, toks, ntoks))
  } else if (m == 4) {
    return(readDrainMatData(j, toks, ntoks))
  } else if (m == 6) {
    return(readRemovalsData(j, toks, ntoks))
  }
  return(error_setInpError(205, toks$v[[2]]))
}

# lid.c:415
lid_readGroupParams <- function(toks, ntoks) {
  toks; ntoks
  x <- rt_ra(numeric(6))
  fname <- NULL
  drainSubcatch <- -1
  drainNode <- -1
  if (ntoks < 8) {
    return(error_setInpError(203, .L0))
  }
  j <- project_findObject(1, toks$v[[1]])
  if (j < 0) {
    return(error_setInpError(209, toks$v[[1]]))
  }
  k <- project_findObject(15, toks$v[[2]])
  if (k < 0) {
    return(error_setInpError(209, toks$v[[2]]))
  }
  n <- rt_atoi(toks$v[[3]])
  if (n < 0) {
    return(error_setInpError(211, toks$v[[3]]))
  }
  if (n == 0) {
    return(0)
  }
  i <- 3
  while (i <= 7) {
    if ((!({.b1 <- rt_box(x$v[[(i - 3) + 1]]); .r2 <- getDouble(toks$v[[i + 1]], .b1); x$v[[(i - 3) + 1]] <- .b1$v; .r2} != 0)) || (!is.na(.c <- (x$v[[(i - 3) + 1]] < 0)) && .c)) {
      return(error_setInpError(211, toks$v[[i + 1]]))
    }
    i <- i + 1
  }
  i <- 2
  while (i <= 3) {
    if (!is.na(.c <- (x$v[[i + 1]] > 100)) && .c) {
      return(error_setInpError(211, toks$v[[(i + 3) + 1]]))
    }
    i <- i + 1
  }
  if ((ntoks >= 9) && (rt_strcmp(toks$v[[9]], .L275) != 0)) {
    fname <- toks$v[[9]]
  }
  if ((ntoks >= 10) && (rt_strcmp(toks$v[[10]], .L275) != 0)) {
    drainSubcatch <- project_findObject(1, toks$v[[10]])
    if (drainSubcatch < 0) {
      drainNode <- project_findObject(2, toks$v[[10]])
      if (drainNode < 0) {
        return(error_setInpError(209, toks$v[[10]]))
      }
    }
  }
  x$v[[6]] <- 0
  if (ntoks >= 11) {
    if (((!({.b3 <- rt_box(x$v[[6]]); .r4 <- getDouble(toks$v[[11]], .b3); x$v[[6]] <- .b3$v; .r4} != 0)) || (!is.na(.c <- (x$v[[6]] < 0)) && .c)) || (!is.na(.c <- (x$v[[6]] > 100)) && .c)) {
      return(error_setInpError(211, toks$v[[11]]))
    }
  }
  return(addLidUnit(j, k, n, x, fname, drainSubcatch, drainNode))
}

# lid.c:499
addLidUnit <- function(j, k, n, x, fname, drainSubcatch, drainNode) {
  j; k; n; x; fname; drainSubcatch; drainNode
  .G_LidGroups <- LidGroups
  lidGroup <- .G_LidGroups$v[[j + 1]]
  if (!(!is.null(lidGroup))) {
    lidGroup <- T_LidGroup()
    if (!(!is.null(lidGroup))) {
      return(error_setInpError(101, .L0))
    }
    lidGroup$lidList <- NULL
    .G_LidGroups$v[j + 1] <- list(lidGroup)
  }
  lidUnit <- T_TLidUnit()
  if (!(!is.null(lidUnit))) {
    return(error_setInpError(101, .L0))
  }
  lidUnit$rptFile <- NULL
  lidList <- T_TLidList()
  if (!(!is.null(lidList))) {
    NULL
    return(error_setInpError(101, .L0))
  }
  lidList$lidUnit <- lidUnit
  lidList$nextLidUnit <- lidGroup$lidList
  lidGroup$lidList <- lidList
  lidUnit$lidIndex <- k
  lidUnit$number <- n
  lidUnit$area <- x$v[[1]] / ((UCF(3)) * (UCF(3)))
  lidUnit$fullWidth <- x$v[[2]] / (UCF(3))
  lidUnit$initSat <- x$v[[3]] / 100
  lidUnit$fromImperv <- x$v[[4]] / 100
  lidUnit$toPerv <- if (!is.na(.c <- (x$v[[5]] > 0)) && .c) 1 else 0
  lidUnit$fromPerv <- x$v[[6]] / 100
  lidUnit$drainSubcatch <- drainSubcatch
  lidUnit$drainNode <- drainNode
  if (!is.null(fname)) {
    if (!(createLidRptFile(lidUnit, fname) != 0)) {
      return(error_setInpError(305, fname))
    }
  }
  return(0)
}

# lid.c:567
createLidRptFile <- function(lidUnit, fname) {
  lidUnit; fname
  rptFile <- T_TLidRptFile()
  if (is.null(rptFile)) {
    return(0)
  }
  lidUnit$rptFile <- rptFile
  rptFile$file <- rt_fopen(fname, .L171)
  if (is.null(rptFile$file)) {
    return(0)
  }
  return(1)
}

