  rt_fprintf(.G_Frpt$file, .L281, list())
  j <- 0
  while (j < .G_GroupCount) {
    lidGroup <- .G_LidGroups$v[[j + 1]]
    if (is.null(lidGroup)) {
      j <- j + 1
      next
    }
    lidList <- lidGroup$lidList
    while (!is.null(lidList)) {
      lidUnit <- lidList$lidUnit
      k <- lidUnit$lidIndex
      pctArea <- ((lidUnit$area * lidUnit$number) / ((.G_Subcatch[[j + 1]])$area)) * 100
      rt_fprintf(.G_Frpt$file, .L282, list((.G_Subcatch[[j + 1]])$ID, (.G_LidProcs[[k + 1]])$ID))
      rt_fprintf(.G_Frpt$file, .L283, list(lidUnit$number, lidUnit$area * ((UCF(3)) * (UCF(3))), lidUnit$fullWidth * (UCF(3)), pctArea, lidUnit$fromImperv * 100, lidUnit$fromPerv * 100))
      lidList <- lidList$nextLidUnit
    }
