  }
}

# lid.c:932
validateLidProc <- function(j) {
  j
  .G_LidProcs <- LidProcs; .G_Msg <- Msg
  layerMissing <- 0
  if ((.G_LidProcs[[j + 1]])$lidType < 0) {
    report_writeErrorMsg(183, (.G_LidProcs[[j + 1]])$ID)
    return(invisible(NULL))
  }
  .sw1 <- (.G_LidProcs[[j + 1]])$lidType
  if (.sw1 == 0 || .sw1 == 1) {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$thickness <= 0)) && .c) {
      layerMissing <- 1
    }
  } else if (.sw1 == 2) {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$thickness <= 0)) && .c) {
      layerMissing <- 1
    }
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$drainMat)$thickness <= 0)) && .c) {
      layerMissing <- 1
    }
  } else if (.sw1 == 4) {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$thickness <= 0)) && .c) {
      layerMissing <- 1
    }
  } else if (.sw1 == 3) {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$storage)$thickness <= 0)) && .c) {
      layerMissing <- 1
    }
  }
  if (layerMissing != 0) {
    report_writeErrorMsg(184, (.G_LidProcs[[j + 1]])$ID)
    return(invisible(NULL))
  }
  if ((.G_LidProcs[[j + 1]])$lidType == 4) {
    if (((((!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$thickness <= 0)) && .c) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$kSat <= 0)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$voidFrac <= 0)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$voidFrac > 1)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$impervFrac > 1)) && .c)) {
      sstrncpy(.G_Msg, (.G_LidProcs[[j + 1]])$ID, 1024)
      sstrcat(.G_Msg, .L284, 1024)
      report_writeErrorMsg(185, .G_Msg)
    }
  }
  if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$thickness > 0)) && .c) {
    if (((((!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$porosity <= 0)) && .c) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$fieldCap >= ((.G_LidProcs[[j + 1]])$soil)$porosity)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$wiltPoint >= ((.G_LidProcs[[j + 1]])$soil)$fieldCap)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$kSat <= 0)) && .c)) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$soil)$kSlope < 0)) && .c)) {
      sstrncpy(.G_Msg, (.G_LidProcs[[j + 1]])$ID, 1024)
      sstrcat(.G_Msg, .L285, 1024)
      report_writeErrorMsg(185, .G_Msg)
    }
  }
  if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$storage)$thickness > 0)) && .c) {
    if ((!is.na(.c <- (((.G_LidProcs[[j + 1]])$storage)$voidFrac <= 0)) && .c) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$storage)$voidFrac > 1)) && .c)) {
      sstrncpy(.G_Msg, (.G_LidProcs[[j + 1]])$ID, 1024)
      sstrcat(.G_Msg, .L286, 1024)
      report_writeErrorMsg(185, .G_Msg)
    }
  } else {
    {.e2 <- (.G_LidProcs[[j + 1]])$storage; .e2$voidFrac <- 1}
    {.e3 <- (.G_LidProcs[[j + 1]])$drain; .e3$offset <- 0}
  }
  if ((!is.na(.c <- (((.G_LidProcs[[j + 1]])$drain)$hOpen > 0)) && .c) && (!is.na(.c <- (((.G_LidProcs[[j + 1]])$drain)$hOpen <= ((.G_LidProcs[[j + 1]])$drain)$hClose)) && .c)) {
    sstrncpy(.G_Msg, (.G_LidProcs[[j + 1]])$ID, 1024)
    sstrcat(.G_Msg, .L287, 1024)
    report_writeErrorMsg(185, .G_Msg)
  }
  if ((.G_LidProcs[[j + 1]])$lidType == 6) {
    if ((!is.na(.c <- ((((.G_LidProcs[[j + 1]])$surface)$roughness * (((.G_LidProcs[[j + 1]])$surface)$surfSlope)) <= 0)) && .c) || (!is.na(.c <- (((.G_LidProcs[[j + 1]])$surface)$thickness == 0)) && .c)) {
      sstrncpy(.G_Msg, (.G_LidProcs[[j + 1]])$ID, 1024)
      sstrcat(.G_Msg, .L288, 1024)
      report_writeErrorMsg(185, .G_Msg)
    } else {
      {.e4 <- (.G_LidProcs[[j + 1]])$surface; .e4$alpha <- (1.49 * (sqrt(((.G_LidProcs[[j + 1]])$surface)$surfSlope))) / (((.G_LidProcs[[j + 1]])$surface)$roughness)}
    }
  } else {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$surface)$roughness > 0)) && .c) {
      {.e5 <- (.G_LidProcs[[j + 1]])$surface; .e5$alpha <- (1.49 / (((.G_LidProcs[[j + 1]])$surface)$roughness)) * (sqrt(((.G_LidProcs[[j + 1]])$surface)$surfSlope))}
    } else {
      {.e6 <- (.G_LidProcs[[j + 1]])$surface; .e6$alpha <- 0}
    }
  }
  if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$drainMat)$roughness > 0)) && .c) {
    {.e7 <- (.G_LidProcs[[j + 1]])$drainMat; .e7$alpha <- (1.49 / (((.G_LidProcs[[j + 1]])$drainMat)$roughness)) * (sqrt(((.G_LidProcs[[j + 1]])$surface)$surfSlope))}
  } else {
    {.e8 <- (.G_LidProcs[[j + 1]])$drainMat; .e8$alpha <- 0}
  }
  if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$pavement)$thickness > 0)) && .c) {
    {.e9 <- (.G_LidProcs[[j + 1]])$pavement; .e9$clogFactor <- ((.G_LidProcs[[j + 1]])$pavement)$clogFactor * ((((.G_LidProcs[[j + 1]])$pavement)$thickness * (((.G_LidProcs[[j + 1]])$pavement)$voidFrac)) * (1 - (((.G_LidProcs[[j + 1]])$pavement)$impervFrac)))}
  }
  if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$storage)$thickness > 0)) && .c) {
    {.e10 <- (.G_LidProcs[[j + 1]])$storage; .e10$clogFactor <- ((.G_LidProcs[[j + 1]])$storage)$clogFactor * (((.G_LidProcs[[j + 1]])$storage)$thickness * (((.G_LidProcs[[j + 1]])$storage)$voidFrac))}
  } else {
    {.e11 <- (.G_LidProcs[[j + 1]])$storage; .e11$clogFactor <- 0}
  }
  {.e12 <- (.G_LidProcs[[j + 1]])$surface; .e12$canOverflow <- 1}
  .sw13 <- (.G_LidProcs[[j + 1]])$lidType
  if (.sw13 == 7) {
    {.e14 <- (.G_LidProcs[[j + 1]])$surface; .e14$canOverflow <- 0}
  } else if (.sw13 == 3 || .sw13 == 4 || .sw13 == 0 || .sw13 == 1 || .sw13 == 2) {
    if (!is.na(.c <- (((.G_LidProcs[[j + 1]])$surface)$alpha > 0)) && .c) {
      {.e15 <- (.G_LidProcs[[j + 1]])$surface; .e15$canOverflow <- 0}
    }
  }
  if ((.G_LidProcs[[j + 1]])$lidType == 5) {
    {.e16 <- (.G_LidProcs[[j + 1]])$storage; .e16$voidFrac <- 1}
    {.e17 <- (.G_LidProcs[[j + 1]])$storage; .e17$kSat <- 0}
  }
  if ((.G_LidProcs[[j + 1]])$lidType == 2) {
    {.e18 <- (.G_LidProcs[[j + 1]])$storage; .e18$thickness <- ((.G_LidProcs[[j + 1]])$drainMat)$thickness}
    {.e19 <- (.G_LidProcs[[j + 1]])$storage; .e19$voidFrac <- ((.G_LidProcs[[j + 1]])$drainMat)$voidFrac}
    {.e20 <- (.G_LidProcs[[j + 1]])$storage; .e20$clogFactor <- 0}
    {.e21 <- (.G_LidProcs[[j + 1]])$storage; .e21$kSat <- 0}
  }
}

# lid.c:1113
validateLidGroup <- function(j) {
  j
  .G_LidProcs <- LidProcs; .G_Msg <- Msg; .G_Subcatch <- Subcatch
  k <- 0
  p <- rt_ra(numeric(3))
  totalArea <- (.G_Subcatch[[j + 1]])$area
  totalLidArea <- 0
  fromImperv <- 0
  fromPerv <- 0
  lidUnit <- NULL
  lidGroup <- LidGroups$v[[j + 1]]
  if (is.null(lidGroup)) {
    return(invisible(NULL))
  }
  lidList <- lidGroup$lidList
  while (!is.null(lidList)) {
    lidUnit <- lidList$lidUnit
    k <- lidUnit$lidIndex
    totalLidArea <- totalLidArea + (lidUnit$area * lidUnit$number)
    fromImperv <- fromImperv + lidUnit$fromImperv
    fromPerv <- fromPerv + lidUnit$fromPerv
    {.e1 <- lidUnit$soilInfil; .e1$Ks <- 0}
    if (!is.na(.c <- (((.G_LidProcs[[k + 1]])$soil)$thickness > 0)) && .c) {
      p$v[[1]] <- ((.G_LidProcs[[k + 1]])$soil)$suction * (UCF(1))
      p$v[[2]] <- ((.G_LidProcs[[k + 1]])$soil)$kSat * (UCF(0))
      p$v[[3]] <- (((.G_LidProcs[[k + 1]])$soil)$porosity - (((.G_LidProcs[[k + 1]])$soil)$wiltPoint)) * (1 - lidUnit$initSat)
      if (grnampt_setParams(lidUnit$soilInfil, p) == 0) {
        sstrncpy(.G_Msg, (.G_LidProcs[[k + 1]])$ID, 1024)
        sstrcat(.G_Msg, .L285, 1024)
        report_writeErrorMsg(185, .G_Msg)
      }
    }
    if ((.G_LidProcs[[k + 1]])$lidType == 6) {
      if (((.G_Subcatch[[j + 1]])$infilModel == 2) || ((.G_Subcatch[[j + 1]])$infilModel == 3)) {
        grnampt_getParams(j, p)
        if (grnampt_setParams(lidUnit$soilInfil, p) == 0) {
          sstrncpy(.G_Msg, (.G_LidProcs[[k + 1]])$ID, 1024)
          sstrcat(.G_Msg, .L289, 1024)
          report_writeErrorMsg(185, .G_Msg)
        }
      }
      if (!is.na(.c <- (lidUnit$fullWidth <= 0)) && .c) {
        sstrncpy(.G_Msg, (.G_LidProcs[[k + 1]])$ID, 1024)
        sstrcat(.G_Msg, .L290, 1024)
        report_writeErrorMsg(185, .G_Msg)
      }
    }
    if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$fracImperv >= 0.999)) && .c) {
      lidUnit$toPerv <- 0
    }
    if ((lidUnit$drainNode == (-1)) && (lidUnit$drainSubcatch == (-1))) {
      lidUnit$drainNode <- (.G_Subcatch[[j + 1]])$outNode
      lidUnit$drainSubcatch <- (.G_Subcatch[[j + 1]])$outSubcatch
    }
    lidList <- lidList$nextLidUnit
  }
  if (!is.na(.c <- (totalLidArea > (1.001 * totalArea))) && .c) {
    report_writeErrorMsg(187, (.G_Subcatch[[j + 1]])$ID)
  }
  if ((!is.na(.c <- (fromImperv > 1.001)) && .c) || (!is.na(.c <- (fromPerv > 1.001)) && .c)) {
    report_writeErrorMsg(188, (.G_Subcatch[[j + 1]])$ID)
  }
  if (!is.na(.c <- (totalLidArea > (0.999 * totalArea))) && .c) {
    totalLidArea <- totalArea
  }
  {.e2 <- .G_Subcatch[[j + 1]]; .e2$lidArea <- totalLidArea}
}

# lid.c:1211
lid_initState <- function() {
  .G_GroupCount <- GroupCount; .G_LidGroups <- LidGroups; .G_LidProcs <- LidProcs; .G_Subcatch <- Subcatch; .G_Title <- Title
  i <- 0
  k <- 0
  lidUnit <- NULL
  lidList <- NULL
  lidGroup <- NULL
  initVol <- 0
  initDryTime <- StartDryDays * 86400
  HasWetLids <<- 0
  j <- 0
  while (j < .G_GroupCount) {
    lidGroup <- .G_LidGroups$v[[j + 1]]
    if (is.null(lidGroup)) {
      j <- j + 1
      next
    }
    lidGroup$pervArea <- 0
    lidGroup$flowToPerv <- 0
    lidGroup$oldDrainFlow <- 0
    lidGroup$newDrainFlow <- 0
    lidList <- lidGroup$lidList
    while (!is.null(lidList)) {
      lidUnit <- lidList$lidUnit
      k <- lidUnit$lidIndex
      lidUnit$surfaceDepth <- 0
      lidUnit$storageDepth <- 0
      lidUnit$soilMoisture <- 0
      lidUnit$paveDepth <- 0
      lidUnit$dryTime <- initDryTime
      lidUnit$volTreated <- 0
      lidUnit$nextRegenDay <- ((.G_LidProcs[[k + 1]])$pavement)$regenDays
      initVol <- 0
      if (!is.na(.c <- (((.G_LidProcs[[k + 1]])$soil)$thickness > 0)) && .c) {
        lidUnit$soilMoisture <- ((.G_LidProcs[[k + 1]])$soil)$wiltPoint + (lidUnit$initSat * (((.G_LidProcs[[k + 1]])$soil)$porosity - (((.G_LidProcs[[k + 1]])$soil)$wiltPoint)))
        initVol <- initVol + (lidUnit$soilMoisture * (((.G_LidProcs[[k + 1]])$soil)$thickness))
      }
      if (!is.na(.c <- (((.G_LidProcs[[k + 1]])$storage)$thickness > 0)) && .c) {
        lidUnit$storageDepth <- lidUnit$initSat * (((.G_LidProcs[[k + 1]])$storage)$thickness)
        initVol <- initVol + (lidUnit$storageDepth * (((.G_LidProcs[[k + 1]])$storage)$voidFrac))
      }
      if (!is.na(.c <- (lidUnit$initSat > 0)) && .c) {
        HasWetLids <<- 1
      }
      lidproc_initWaterBalance(lidUnit, initVol)
      lidUnit$volTreated <- 0
      if (!is.null(lidUnit$rptFile)) {
        initLidRptFile(.G_Title$v[[1]], (.G_LidProcs[[k + 1]])$ID, (.G_Subcatch[[j + 1]])$ID, lidUnit)
      }
      lidUnit$oldDrainFlow <- 0
      lidUnit$newDrainFlow <- 0
      i <- 0
      while (i < 4) {
        {.e1 <- lidUnit$oldFluxRates; .e1$v[[i + 1]] <- 0}
        i <- i + 1
      }
      if (!is.na(.c <- (lidUnit$soilInfil$Ks > 0)) && .c) {
        grnampt_initState(lidUnit$soilInfil)
      }
      if (isLidPervious(lidUnit$lidIndex) != 0) {
        lidGroup$pervArea <- lidGroup$pervArea + (lidUnit$area * lidUnit$number)
      }
      lidList <- lidList$nextLidUnit
    }
    j <- j + 1
  }
}

