    while (!is.null(lidList)) {
      {.e3 <- lidList$lidUnit; .e3$oldDrainFlow <- lidList$lidUnit$newDrainFlow}
      {.e4 <- lidList$lidUnit; .e4$newDrainFlow <- 0}
      lidList <- lidList$nextLidUnit
    }
  }
}

# lid.c:1326
isLidPervious <- function(k) {
  k
  .G_LidProcs <- LidProcs
  return(if ((!is.na(.c <- (((.G_LidProcs[[k + 1]])$storage)$thickness == 0)) && .c) || (!is.na(.c <- (((.G_LidProcs[[k + 1]])$storage)$kSat > 0)) && .c)) 1 else 0)
}

# lid.c:1339
getSurfaceDepth <- function(j) {
  j
  .G_LidProcs <- LidProcs; .G_Subcatch <- Subcatch
  k <- 0
  depth <- 0
  lidUnit <- NULL
  lidGroup <- LidGroups$v[[j + 1]]
  if (is.null(lidGroup)) {
    return(0)
  }
  if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$lidArea == 0)) && .c) {
    return(0)
  }
  lidList <- lidGroup$lidList
  while (!is.null(lidList)) {
    lidUnit <- lidList$lidUnit
    k <- lidUnit$lidIndex
    depth <- depth + (((lidUnit$surfaceDepth * (((.G_LidProcs[[k + 1]])$surface)$voidFrac)) * lidUnit$area) * lidUnit$number)
    lidList <- lidList$nextLidUnit
  }
  return(depth / ((.G_Subcatch[[j + 1]])$lidArea))
}

