# lid.c:1442
lid_addDrainLoads <- function(j, c_, tStep) {
  j; c_; tStep
  .G_LidProcs <- LidProcs; .G_Nobjects <- Nobjects; .G_Pollut <- Pollut
  isRunoffLoad <- 0
  p <- 0
  r <- 0
  w <- 0
  lidUnit <- NULL
  lidList <- NULL
  lidGroup <- LidGroups$v[[j + 1]]
  if (!is.null(lidGroup)) {
    lidList <- lidGroup$lidList
    while (!is.null(lidList)) {
      lidUnit <- lidList$lidUnit
      isRunoffLoad <- if ((lidUnit$drainNode >= 0) || (lidUnit$drainSubcatch == j)) 1 else 0
      if (!(lidUnit$toPerv != 0)) {
        p <- 0
        while (p < .G_Nobjects$v[[5]]) {
          w <- (((lidUnit$newDrainFlow * (c_$v[[p + 1]])) * tStep) * 28.317) * ((.G_Pollut[[p + 1]])$mcf)
          r <- ((.G_LidProcs[[lidUnit$lidIndex + 1]])$drainRmvl)$v[[p + 1]]
          massbal_updateLoadingTotals(3, p, (r * w))
          if (isRunoffLoad != 0) {
            massbal_updateLoadingTotals(5, p, (w * (1 - r)))
          }
          p <- p + 1
        }
      }
      lidList <- lidList$nextLidUnit
    }
  }
}

# lid.c:1497
lid_addDrainRunon <- function(j) {
  j
  .G_LidProcs <- LidProcs; .G_Nobjects <- Nobjects; .G_Subcatch <- Subcatch
  i <- 0
  k <- 0
  p <- 0
  q_ <- 0
  w <- 0
  lidUnit <- NULL
  lidList <- NULL
  lidGroup <- LidGroups$v[[j + 1]]
  if (!is.null(lidGroup)) {
    lidList <- lidGroup$lidList
    while (!is.null(lidList)) {
      lidUnit <- lidList$lidUnit
      i <- lidUnit$lidIndex
      k <- lidUnit$drainSubcatch
      if ((k >= 0) && (k != j)) {
        q_ <- lidUnit$oldDrainFlow
        subcatch_addRunonFlow(k, q_)
        p <- 0
        while (p < .G_Nobjects$v[[5]]) {
          w <- (q_ * (((.G_Subcatch[[j + 1]])$oldQual)$v[[p + 1]])) * 28.317
          w <- w * (1 - (((.G_LidProcs[[i + 1]])$drainRmvl)$v[[p + 1]]))
          {.e1 <- (.G_Subcatch[[k + 1]])$newQual; .e1$v[[p + 1]] <- ((.G_Subcatch[[k + 1]])$newQual)$v[[p + 1]] + w}
          p <- p + 1
        }
      }
      lidList <- lidList$nextLidUnit
    }
  }
}

# lid.c:1549
lid_addDrainInflow <- function(j, f) {
  j; f
  .G_LidProcs <- LidProcs; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Subcatch <- Subcatch
  i <- 0
  k <- 0
  p <- 0
  q_ <- 0
  w <- 0
  w1 <- 0
  w2 <- 0
  lidUnit <- NULL
  lidList <- NULL
  lidGroup <- LidGroups$v[[j + 1]]
  if (!is.null(lidGroup)) {
    lidList <- lidGroup$lidList
    while (!is.null(lidList)) {
      lidUnit <- lidList$lidUnit
      i <- lidUnit$lidIndex
      k <- lidUnit$drainNode
      if (k >= 0) {
        q_ <- ((1 - f) * lidUnit$oldDrainFlow) + (f * lidUnit$newDrainFlow)
