# lid.c:1609
lid_getRunoff <- function(j, tStep) {
  j; tStep
  .G_Evap <- Evap; .G_Subcatch <- Subcatch
  lidUnit <- NULL
  lidArea <- 0
  qImperv <- 0
  qPerv <- 0
  lidInflow <- 0
  qRunoff <- 0
  qDrain <- 0
  qReturn <- 0
  theLidGroup <- LidGroups$v[[j + 1]]
  if (!(!is.null(theLidGroup))) {
    return(invisible(NULL))
  }
  lidList <- theLidGroup$lidList
  if (!(!is.null(lidList))) {
    return(invisible(NULL))
  }
  lid_EvapRate <<- .G_Evap$rate
  if ((.G_Evap$dryOnly != 0) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$rainfall > 0)) && .c)) {
    lid_EvapRate <<- 0
  }
  findNativeInfil(j, tStep)
  if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$area > (.G_Subcatch[[j + 1]])$lidArea)) && .c) {
    qImperv <- getImpervAreaRunoff(j)
    qPerv <- getPervAreaRunoff(j)
  }
  while (!is.null(lidList)) {
    lidUnit <- lidList$lidUnit
    lidArea <- lidUnit$area * lidUnit$number
    if (!is.na(.c <- (lidArea > 0)) && .c) {
      lidInflow <- ((qImperv * lidUnit$fromImperv) + (qPerv * lidUnit$fromPerv)) / lidArea
      VlidIn <<- VlidIn + ((lidInflow * lidArea) * tStep)
      lidInflow <- lidInflow + getRainInflow(j, lidUnit)
      if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$area == (.G_Subcatch[[j + 1]])$lidArea)) && .c) {
        lidInflow <- lidInflow + ((.G_Subcatch[[j + 1]])$runon)
      }
      {.BX_lid_getRunoff_qRunoff$v <- qRunoff; .BX_lid_getRunoff_qDrain$v <- qDrain; .BX_lid_getRunoff_qReturn$v <- qReturn; .r1 <- evalLidUnit(j, lidUnit, lidArea, lidInflow, tStep, .BX_lid_getRunoff_qRunoff, .BX_lid_getRunoff_qDrain, .BX_lid_getRunoff_qReturn); qRunoff <- .BX_lid_getRunoff_qRunoff$v; qDrain <- .BX_lid_getRunoff_qDrain$v; qReturn <- .BX_lid_getRunoff_qReturn$v; .r1}
    }
    lidList <- lidList$nextLidUnit
  }
  theLidGroup$newDrainFlow <- qDrain
  theLidGroup$flowToPerv <- qReturn
  VlidOut <<- qRunoff * tStep
  VlidDrain <<- qDrain * tStep
  VlidReturn <<- qReturn * tStep
}

# lid.c:1697
findNativeInfil <- function(j, tStep) {
  j; tStep
  .G_Subcatch <- Subcatch
  nonLidArea <- (.G_Subcatch[[j + 1]])$area - ((.G_Subcatch[[j + 1]])$lidArea)
  if ((!is.na(.c <- (nonLidArea > 0)) && .c) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$fracImperv < 1)) && .c)) {
    NativeInfil <<- (Vinfil / nonLidArea) / tStep
  } else {
    NativeInfil <<- infil_getInfil(j, tStep, (.G_Subcatch[[j + 1]])$rainfall, (.G_Subcatch[[j + 1]])$runon, getSurfaceDepth(j))
  }
  if ((!(IgnoreGwater != 0)) && (!is.null((.G_Subcatch[[j + 1]])$groundwater))) {
    lid_MaxNativeInfil <<- ((.G_Subcatch[[j + 1]])$groundwater)$maxInfilVol / tStep
  } else {
    lid_MaxNativeInfil <<- 10000000000
  }
}

# lid.c:1734
getRainInflow <- function(j, lidUnit) {
  j; lidUnit
  lidProc <- LidProcs[[lidUnit$lidIndex + 1]]
  if ((lidProc$lidType == 5) && (lidProc$storage$covered == 1)) {
