# lid.c:1751
getImpervAreaRunoff <- function(j) {
  j
  .G_Subcatch <- Subcatch
  q_ <- 0
  i <- 0
  while (i <= 1) {
    q_ <- q_ + ((((.G_Subcatch[[j + 1]])$subArea)[[i + 1]])$runoff * ((((.G_Subcatch[[j + 1]])$subArea)[[i + 1]])$fArea))
    i <- i + 1
  }
  if (((((.G_Subcatch[[j + 1]])$subArea)[[1]])$routeTo == 2) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$fracImperv < 1)) && .c)) {
    q_ <- q_ * ((((.G_Subcatch[[j + 1]])$subArea)[[1]])$fOutlet)
  }
  nonLidArea <- (.G_Subcatch[[j + 1]])$area - ((.G_Subcatch[[j + 1]])$lidArea)
  return(q_ * nonLidArea)
}

# lid.c:1781
getPervAreaRunoff <- function(j) {
  j
  .G_Subcatch <- Subcatch
  q_ <- 0
  q_ <- (((.G_Subcatch[[j + 1]])$subArea)[[3]])$runoff * ((((.G_Subcatch[[j + 1]])$subArea)[[3]])$fArea)
  if (((((.G_Subcatch[[j + 1]])$subArea)[[3]])$routeTo == 1) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$fracImperv > 0)) && .c)) {
    q_ <- q_ * ((((.G_Subcatch[[j + 1]])$subArea)[[3]])$fOutlet)
  }
  nonLidArea <- (.G_Subcatch[[j + 1]])$area - ((.G_Subcatch[[j + 1]])$lidArea)
  return(q_ * nonLidArea)
}

# lid.c:1807
evalLidUnit <- function(j, lidUnit, lidArea, lidInflow, tStep, qRunoff, qDrain, qReturn) {
  j; lidUnit; lidArea; lidInflow; tStep; qRunoff; qDrain; qReturn
  .G_Subcatch <- Subcatch
  lidDrain <- 0
  lidProc <- LidProcs[[lidUnit$lidIndex + 1]]
  lidEvap <- 0
  lidInfil <- 0
  lidRunoff <- {.BX_evalLidUnit_lidEvap$v <- lidEvap; .BX_evalLidUnit_lidInfil$v <- lidInfil; .BX_evalLidUnit_lidDrain$v <- lidDrain; .r1 <- lidproc_getOutflow(lidUnit, lidProc, lidInflow, lid_EvapRate, NativeInfil, lid_MaxNativeInfil, tStep, .BX_evalLidUnit_lidEvap, .BX_evalLidUnit_lidInfil, .BX_evalLidUnit_lidDrain); lidEvap <- .BX_evalLidUnit_lidEvap$v; lidInfil <- .BX_evalLidUnit_lidInfil$v; lidDrain <- .BX_evalLidUnit_lidDrain$v; .r1} * lidArea
  lidDrain <- lidDrain * lidArea
  if ((lidUnit$toPerv != 0) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$area > (.G_Subcatch[[j + 1]])$lidArea)) && .c)) {
    qReturn$v <- qReturn$v + lidRunoff
    lidRunoff <- 0
    if ((lidUnit$drainNode == (.G_Subcatch[[j + 1]])$outNode) && (lidUnit$drainSubcatch == (.G_Subcatch[[j + 1]])$outSubcatch)) {
      qReturn$v <- qReturn$v + lidDrain
      lidDrain <- 0
    }
  }
  if (lidUnit$drainNode >= 0) {
    massbal_updateRunoffTotals(4, (lidDrain * tStep))
  }
  lidUnit$newDrainFlow <- lidDrain
  Vevap <<- Vevap + ((lidEvap * tStep) * lidArea)
  VlidInfil <<- VlidInfil + ((lidInfil * tStep) * lidArea)
  if (isLidPervious(lidUnit$lidIndex) != 0) {
    Vpevap <<- Vpevap + ((lidEvap * tStep) * lidArea)
  }
  if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$rainfall > 2.31481e-08)) && .c) {
    lidUnit$dryTime <- 0
  } else {
    lidUnit$dryTime <- lidUnit$dryTime + tStep
  }
  lidproc_saveResults(lidUnit, UCF(0), UCF(1))
  qRunoff$v <- qRunoff$v + lidRunoff
  qDrain$v <- qDrain$v + lidDrain
}

