  if (UnitSystem == 0) {
    rt_fprintf(.G_Frpt$file, .L293, list())
  } else {
    rt_fprintf(.G_Frpt$file, .L294, list())
  }
  rt_fprintf(.G_Frpt$file, .L295, list())
  j <- 0
  while (j < .G_GroupCount) {
