      rt_fprintf(.G_Frpt$file, .L296, list((.G_Subcatch[[j + 1]])$ID, (.G_LidProcs[[k + 1]])$ID))
      rt_fprintf(.G_Frpt$file, .L297, list(lidUnit$waterBalance$inflow * ucf, lidUnit$waterBalance$evap * ucf, lidUnit$waterBalance$infil * ucf, lidUnit$waterBalance$surfFlow * ucf, lidUnit$waterBalance$drainFlow * ucf, lidUnit$waterBalance$initVol * ucf, lidUnit$waterBalance$finalVol * ucf))
      inflow <- lidUnit$waterBalance$initVol + lidUnit$waterBalance$inflow
      outflow <- (((lidUnit$waterBalance$finalVol + lidUnit$waterBalance$evap) + lidUnit$waterBalance$infil) + lidUnit$waterBalance$surfFlow) + lidUnit$waterBalance$drainFlow
      if (!is.na(.c <- (inflow > 0)) && .c) {
        err <- (inflow - outflow) / inflow
      } else {
        err <- 1
      }
      rt_fprintf(.G_Frpt$file, .L298, list(err * 100))
      lidList <- lidList$nextLidUnit
    }
