# lidproc.c:197
lidproc_getOutflow <- function(lidUnit, lidProc, inflow, evap, infil, maxInfil, tStep, lidEvap, lidInfil, lidDrain) {
  lidUnit; lidProc; inflow; evap; infil; maxInfil; tStep; lidEvap; lidInfil; lidDrain
  .G_Xold <- Xold
  x <- rt_ra(numeric(4))
  xOld <- rt_ra(numeric(4))
  xPrev <- rt_ra(numeric(4))
  xMin <- rt_ra(numeric(4))
  xMax <- rt_ra(numeric(4))
  fOld <- rt_ra(numeric(4))
  f <- rt_ra(numeric(4))
  xTol <- rt_ra(c(0.00328, 0.00328, 0.00328, 0.00328))
  omega <- 0
  fluxRates <- NULL
  theLidProc <<- lidProc
  theLidUnit <<- lidUnit
  lidproc_EvapRate <<- evap
  lidproc_MaxNativeInfil <<- maxInfil
  lidproc_Tstep <<- tStep
  x$v[[1]] <- theLidUnit$surfaceDepth
  x$v[[2]] <- theLidUnit$soilMoisture
  x$v[[3]] <- theLidUnit$storageDepth
  x$v[[4]] <- theLidUnit$paveDepth
  SurfaceVolume <<- 0
  PaveVolume <<- 0
  SoilVolume <<- 0
  StorageVolume <<- 0
  SurfaceInflow <<- inflow
  SurfaceInfil <<- 0
  SurfaceEvap <<- 0
  SurfaceOutflow <<- 0
  PaveEvap <<- 0
  PavePerc <<- 0
  SoilEvap <<- 0
  SoilPerc <<- 0
  StorageInflow <<- 0
  StorageExfil <<- 0
  StorageEvap <<- 0
  StorageDrain <<- 0
  i <- 0
  while (i < 4) {
    f$v[[i + 1]] <- 0
    fOld$v[[i + 1]] <- theLidUnit$oldFluxRates$v[[i + 1]]
    xMin$v[[i + 1]] <- 0
    xMax$v[[i + 1]] <- 10000000000
    .G_Xold$v[[i + 1]] <- x$v[[i + 1]]
    i <- i + 1
  }
  if (theLidProc$lidType == 4) {
    SurfaceInfil <<- 0
  } else if (!is.na(.c <- (theLidUnit$soilInfil$Ks > 0)) && .c) {
    SurfaceInfil <<- grnampt_getInfil(theLidUnit$soilInfil, lidproc_Tstep, SurfaceInflow, theLidUnit$surfaceDepth, 3)
  } else {
    SurfaceInfil <<- infil
  }
  if (!is.na(.c <- (theLidProc$soil$thickness > 0)) && .c) {
    xMin$v[[2]] <- theLidProc$soil$wiltPoint
    xMax$v[[2]] <- theLidProc$soil$porosity
  }
  if (!is.na(.c <- (theLidProc$pavement$thickness > 0)) && .c) {
    xMax$v[[4]] <- theLidProc$pavement$thickness
  }
  if (!is.na(.c <- (theLidProc$storage$thickness > 0)) && .c) {
    xMax$v[[3]] <- theLidProc$storage$thickness
  }
  if (theLidProc$lidType == 2) {
    xMax$v[[3]] <- theLidProc$drainMat$thickness
  }
  .sw1 <- theLidProc$lidType
  if (.sw1 == 0 || .sw1 == 1) {
    fluxRates <- biocellFluxRates
  } else if (.sw1 == 2) {
    fluxRates <- greenRoofFluxRates
  } else if (.sw1 == 3) {
    fluxRates <- trenchFluxRates
  } else if (.sw1 == 4) {
    fluxRates <- pavementFluxRates
  } else if (.sw1 == 5) {
    fluxRates <- barrelFluxRates
  } else if (.sw1 == 7) {
    fluxRates <- roofFluxRates
  } else if (.sw1 == 6) {
    fluxRates <- swaleFluxRates
    omega <- 0.5
  } else {
    return(0)
  }
  i <- modpuls_solve(4, x, xOld, xPrev, xMin, xMax, xTol, fOld, f, tStep, omega, fluxRates)
  if ((theLidProc$surface$canOverflow != 0) || (!is.na(.c <- (theLidUnit$fullWidth == 0)) && .c)) {
    SurfaceOutflow <<- SurfaceOutflow + ({.b2 <- rt_box(x$v[[1]]); .r3 <- getSurfaceOverflowRate(.b2); x$v[[1]] <- .b2$v; .r3})
  }
  {.e4 <- theLidUnit; .e4$surfaceDepth <- x$v[[1]]}
  {.e5 <- theLidUnit; .e5$paveDepth <- x$v[[4]]}
  {.e6 <- theLidUnit; .e6$soilMoisture <- x$v[[2]]}
  {.e7 <- theLidUnit; .e7$storageDepth <- x$v[[3]]}
  i <- 0
  while (i < 4) {
    {.e8 <- theLidUnit$oldFluxRates; .e8$v[[i + 1]] <- f$v[[i + 1]]}
    i <- i + 1
  }
  lidEvap$v <- ((SurfaceEvap + PaveEvap) + SoilEvap) + StorageEvap
  lidInfil$v <- StorageExfil
  lidDrain$v <- StorageDrain
  return(SurfaceOutflow)
}

# lidproc.c:360
lidproc_saveResults <- function(lidUnit, ucfRainfall, ucfRainDepth) {
  lidUnit; ucfRainfall; ucfRainDepth
  .G_NewRunoffTime <- NewRunoffTime; .G_StorageDrain <- StorageDrain; .G_StorageExfil <- StorageExfil; .G_SurfaceInflow <- SurfaceInflow; .G_SurfaceOutflow <- SurfaceOutflow; .G_theLidUnit <- theLidUnit
  ucf <- 0
  rptVars <- rt_ra(numeric(12))
  isDry <- 0
  timeStamp <- rt_cbuf(22)
  elapsedHrs <- 0
  totalEvap <- ((SurfaceEvap + PaveEvap) + SoilEvap) + StorageEvap
  totalVolume <- ((SurfaceVolume + PaveVolume) + SoilVolume) + StorageVolume
  updateWaterBalance(.G_theLidUnit, .G_SurfaceInflow, totalEvap, .G_StorageExfil, .G_SurfaceOutflow, .G_StorageDrain, totalVolume)
  if (((((!is.na(.c <- (.G_SurfaceInflow < 2.3e-08)) && .c) && (!is.na(.c <- (.G_SurfaceOutflow < 2.3e-08)) && .c)) && (!is.na(.c <- (.G_StorageDrain < 2.3e-08)) && .c)) && (!is.na(.c <- (.G_StorageExfil < 2.3e-08)) && .c)) && (!is.na(.c <- (totalEvap < 2.3e-08)) && .c)) {
    isDry <- 1
  }
  if (!(isDry != 0)) {
    HasWetLids <<- 1
  }
  if (!is.null(lidUnit$rptFile)) {
    ucf <- ucfRainfall
    rptVars$v[[1]] <- .G_SurfaceInflow * ucf
    rptVars$v[[2]] <- totalEvap * ucf
    rptVars$v[[3]] <- SurfaceInfil * ucf
    rptVars$v[[4]] <- PavePerc * ucf
    rptVars$v[[5]] <- SoilPerc * ucf
    rptVars$v[[6]] <- .G_StorageExfil * ucf
    rptVars$v[[7]] <- .G_SurfaceOutflow * ucf
    rptVars$v[[8]] <- .G_StorageDrain * ucf
    ucf <- ucfRainDepth
    rptVars$v[[9]] <- .G_theLidUnit$surfaceDepth * ucf
    rptVars$v[[10]] <- .G_theLidUnit$paveDepth * ucf
    rptVars$v[[11]] <- .G_theLidUnit$soilMoisture
    rptVars$v[[12]] <- .G_theLidUnit$storageDepth * ucf
    if ((!(isDry != 0)) && (.G_theLidUnit$rptFile$wasDry > 1)) {
      rt_fprintf(.G_theLidUnit$rptFile$file, .L169, list(.G_theLidUnit$rptFile$results))
    }
    elapsedHrs <- (.G_NewRunoffTime / 1000) / 3600
    datetime_getTimeStamp(1, getDateTime(.G_NewRunoffTime), 21, timeStamp)
    rt_snprintf(.G_theLidUnit$rptFile$results, 256, .L304, list(timeStamp, elapsedHrs, rptVars$v[[1]], rptVars$v[[2]], rptVars$v[[3]], rptVars$v[[4]], rptVars$v[[5]], rptVars$v[[6]], rptVars$v[[7]], rptVars$v[[8]], rptVars$v[[9]], rptVars$v[[10]], rptVars$v[[11]], rptVars$v[[12]]))
    if (isDry != 0) {
      if (.G_theLidUnit$rptFile$wasDry == 0) {
        rt_fprintf(.G_theLidUnit$rptFile$file, .L169, list(.G_theLidUnit$rptFile$results))
      }
      {.e1 <- .G_theLidUnit$rptFile; .e1$wasDry <- .G_theLidUnit$rptFile$wasDry + 1}
    } else {
      rt_fprintf(.G_theLidUnit$rptFile$file, .L169, list(.G_theLidUnit$rptFile$results))
      {.e2 <- .G_theLidUnit$rptFile; .e2$wasDry <- 0}
    }
  }
}

# lidproc.c:469
roofFluxRates <- function(x, f) {
  x; f
  .G_theLidProc <- theLidProc
  surfaceDepth <- x$v[[1]]
  lidproc_getEvapRates(surfaceDepth, 0, 0, 0, 1)
  SurfaceVolume <<- surfaceDepth
  SurfaceInfil <<- 0
  if (!is.na(.c <- (.G_theLidProc$surface$alpha > 0)) && .c) {
    SurfaceOutflow <<- getSurfaceOutflowRate(surfaceDepth)
  } else {
    {.BX_roofFluxRates_surfaceDepth$v <- surfaceDepth; .r1 <- getSurfaceOverflowRate(.BX_roofFluxRates_surfaceDepth); surfaceDepth <- .BX_roofFluxRates_surfaceDepth$v; .r1}
  }
  StorageDrain <<- if (!is.na(.c <- ((.G_theLidProc$drain$coeff / (UCF(0))) <= SurfaceOutflow)) && .c) (.G_theLidProc$drain$coeff / (UCF(0))) else SurfaceOutflow
  SurfaceOutflow <<- SurfaceOutflow - StorageDrain
  f$v[[1]] <- ((SurfaceInflow - SurfaceEvap) - StorageDrain) - SurfaceOutflow
}

# lidproc.c:491
greenRoofFluxRates <- function(x, f) {
