  .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc
  soilThickness <- .G_theLidProc$soil$thickness
  storageThickness <- .G_theLidProc$storage$thickness
  soilPorosity <- .G_theLidProc$soil$porosity
  storageVoidFrac <- .G_theLidProc$storage$voidFrac
  soilFieldCap <- .G_theLidProc$soil$fieldCap
  soilWiltPoint <- .G_theLidProc$soil$wiltPoint
  surfaceDepth <- x$v[[1]]
  soilTheta <- x$v[[2]]
  storageDepth <- x$v[[3]]
  SurfaceVolume <<- surfaceDepth * .G_theLidProc$surface$voidFrac
  SoilVolume <<- soilTheta * soilThickness
  StorageVolume <<- storageDepth * storageVoidFrac
  availVolume <- SoilVolume - (soilWiltPoint * soilThickness)
  lidproc_getEvapRates(SurfaceVolume, 0, availVolume, StorageVolume, 1)
  if (!is.na(.c <- (soilTheta >= soilPorosity)) && .c) {
    StorageEvap <<- 0
  }
  SoilPerc <<- getSoilPercRate(soilTheta)
  availVolume <- (soilTheta - soilFieldCap) * soilThickness
  maxRate <- ((if (!is.na(.c <- (availVolume >= 0)) && .c) availVolume else 0) / .G_lidproc_Tstep) - SoilEvap
  SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
  SoilPerc <<- if (!is.na(.c <- (SoilPerc >= 0)) && .c) SoilPerc else 0
  StorageExfil <<- 0
  StorageDrain <<- getDrainMatOutflow(storageDepth)
  if ((!is.na(.c <- (soilTheta >= soilPorosity)) && .c) && (!is.na(.c <- (storageDepth >= storageThickness)) && .c)) {
    maxRate <- if (!is.na(.c <- (SoilPerc <= StorageDrain)) && .c) SoilPerc else StorageDrain
    SoilPerc <<- maxRate
    StorageDrain <<- maxRate
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
  } else {
    maxRate <- ((storageDepth * storageVoidFrac) / .G_lidproc_Tstep) - StorageEvap
    if (!is.na(.c <- (storageDepth >= storageThickness)) && .c) {
      maxRate <- maxRate + SoilPerc
    }
    maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
    StorageDrain <<- if (!is.na(.c <- (StorageDrain <= maxRate)) && .c) StorageDrain else maxRate
    maxRate <- ((((storageThickness - storageDepth) * storageVoidFrac) / .G_lidproc_Tstep) + StorageDrain) + StorageEvap
    SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
    maxRate <- ((((soilPorosity - soilTheta) * soilThickness) / .G_lidproc_Tstep) + SoilPerc) + SoilEvap
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
  }
  SurfaceOutflow <<- getSurfaceOutflowRate(surfaceDepth)
  f$v[[1]] <- (((SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow) / .G_theLidProc$surface$voidFrac
  f$v[[2]] <- ((SurfaceInfil - SoilEvap) - SoilPerc) / .G_theLidProc$soil$thickness
  f$v[[3]] <- ((SoilPerc - StorageEvap) - StorageDrain) / .G_theLidProc$storage$voidFrac
}

# lidproc.c:589
biocellFluxRates <- function(x, f) {
  x; f
  .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc
  soilThickness <- .G_theLidProc$soil$thickness
  soilPorosity <- .G_theLidProc$soil$porosity
  soilFieldCap <- .G_theLidProc$soil$fieldCap
  soilWiltPoint <- .G_theLidProc$soil$wiltPoint
  storageThickness <- .G_theLidProc$storage$thickness
  storageVoidFrac <- .G_theLidProc$storage$voidFrac
  surfaceDepth <- x$v[[1]]
  soilTheta <- x$v[[2]]
  storageDepth <- x$v[[3]]
  SurfaceVolume <<- surfaceDepth * .G_theLidProc$surface$voidFrac
  SoilVolume <<- soilTheta * soilThickness
  StorageVolume <<- storageDepth * storageVoidFrac
  availVolume <- SoilVolume - (soilWiltPoint * soilThickness)
  lidproc_getEvapRates(SurfaceVolume, 0, availVolume, StorageVolume, 1)
  if (!is.na(.c <- (soilTheta >= soilPorosity)) && .c) {
    StorageEvap <<- 0
  }
  SoilPerc <<- getSoilPercRate(soilTheta)
  availVolume <- (soilTheta - soilFieldCap) * soilThickness
  maxRate <- ((if (!is.na(.c <- (availVolume >= 0)) && .c) availVolume else 0) / .G_lidproc_Tstep) - SoilEvap
  SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
  SoilPerc <<- if (!is.na(.c <- (SoilPerc >= 0)) && .c) SoilPerc else 0
  StorageExfil <<- getStorageExfilRate()
  StorageDrain <<- 0
  if (!is.na(.c <- (.G_theLidProc$drain$coeff > 0)) && .c) {
    StorageDrain <<- getStorageDrainRate(storageDepth, soilTheta, 0, surfaceDepth)
  }
  if (!is.na(.c <- (storageThickness == 0)) && .c) {
    StorageEvap <<- 0
    maxRate <- if (!is.na(.c <- (SoilPerc <= StorageExfil)) && .c) SoilPerc else StorageExfil
    SoilPerc <<- maxRate
    StorageExfil <<- maxRate
    maxRate <- ((((soilPorosity - soilTheta) * soilThickness) / .G_lidproc_Tstep) + SoilPerc) + SoilEvap
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
  } else {
    if ((!is.na(.c <- (soilTheta >= soilPorosity)) && .c) && (!is.na(.c <- (storageDepth >= storageThickness)) && .c)) {
      maxRate <- StorageExfil + StorageDrain
      if (!is.na(.c <- (SoilPerc < maxRate)) && .c) {
        maxRate <- SoilPerc
        if (!is.na(.c <- (maxRate > StorageExfil)) && .c) {
          StorageDrain <<- maxRate - StorageExfil
        } else {
          StorageExfil <<- maxRate
          StorageDrain <<- 0
        }
      } else {
        SoilPerc <<- maxRate
      }
      SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
    } else {
      maxRate <- (SoilPerc - StorageEvap) + ((storageDepth * storageVoidFrac) / .G_lidproc_Tstep)
      StorageExfil <<- if (!is.na(.c <- (StorageExfil <= maxRate)) && .c) StorageExfil else maxRate
      StorageExfil <<- if (!is.na(.c <- (StorageExfil >= 0)) && .c) StorageExfil else 0
      if (!is.na(.c <- (StorageDrain > 0)) && .c) {
        maxRate <- (-StorageExfil) - StorageEvap
        if (!is.na(.c <- (storageDepth >= storageThickness)) && .c) {
          maxRate <- maxRate + SoilPerc
        }
        if (!is.na(.c <- (.G_theLidProc$drain$offset <= storageDepth)) && .c) {
          maxRate <- maxRate + (((storageDepth - .G_theLidProc$drain$offset) * storageVoidFrac) / .G_lidproc_Tstep)
        }
        maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
        StorageDrain <<- if (!is.na(.c <- (StorageDrain <= maxRate)) && .c) StorageDrain else maxRate
      }
      maxRate <- ((StorageExfil + StorageDrain) + StorageEvap) + (((storageThickness - storageDepth) * storageVoidFrac) / .G_lidproc_Tstep)
      SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
      maxRate <- ((((soilPorosity - soilTheta) * soilThickness) / .G_lidproc_Tstep) + SoilPerc) + SoilEvap
      SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
    }
  }
  SurfaceOutflow <<- getSurfaceOutflowRate(surfaceDepth)
  f$v[[1]] <- (((SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow) / .G_theLidProc$surface$voidFrac
  f$v[[2]] <- ((SurfaceInfil - SoilEvap) - SoilPerc) / .G_theLidProc$soil$thickness
  if (!is.na(.c <- (storageThickness == 0)) && .c) {
    f$v[[3]] <- 0
  } else {
    f$v[[3]] <- (((SoilPerc - StorageEvap) - StorageExfil) - StorageDrain) / .G_theLidProc$storage$voidFrac
  }
}

# lidproc.c:735
trenchFluxRates <- function(x, f) {
  x; f
  .G_SurfaceInflow <- SurfaceInflow; .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc
  storageThickness <- .G_theLidProc$storage$thickness
  storageVoidFrac <- .G_theLidProc$storage$voidFrac
  surfaceDepth <- x$v[[1]]
  storageDepth <- x$v[[3]]
  SurfaceVolume <<- surfaceDepth * .G_theLidProc$surface$voidFrac
  SoilVolume <<- 0
  StorageVolume <<- storageDepth * storageVoidFrac
  availVolume <- (storageThickness - storageDepth) * storageVoidFrac
  lidproc_getEvapRates(SurfaceVolume, 0, 0, StorageVolume, 1)
  if (!is.na(.c <- (surfaceDepth > 0)) && .c) {
    StorageEvap <<- 0
  }
  StorageInflow <<- .G_SurfaceInflow + (SurfaceVolume / .G_lidproc_Tstep)
  StorageExfil <<- getStorageExfilRate()
  StorageDrain <<- 0
  if (!is.na(.c <- (.G_theLidProc$drain$coeff > 0)) && .c) {
    StorageDrain <<- getStorageDrainRate(storageDepth, 0, 0, surfaceDepth)
  }
  maxRate <- (StorageInflow - StorageEvap) + ((storageDepth * storageVoidFrac) / .G_lidproc_Tstep)
  StorageExfil <<- if (!is.na(.c <- (StorageExfil <= maxRate)) && .c) StorageExfil else maxRate
  StorageExfil <<- if (!is.na(.c <- (StorageExfil >= 0)) && .c) StorageExfil else 0
  if (!is.na(.c <- (StorageDrain > 0)) && .c) {
    maxRate <- (-StorageExfil) - StorageEvap
    if (!is.na(.c <- (storageDepth >= storageThickness)) && .c) {
      maxRate <- maxRate + StorageInflow
    }
    if (!is.na(.c <- (.G_theLidProc$drain$offset <= storageDepth)) && .c) {
      maxRate <- maxRate + (((storageDepth - .G_theLidProc$drain$offset) * storageVoidFrac) / .G_lidproc_Tstep)
    }
    maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
    StorageDrain <<- if (!is.na(.c <- (StorageDrain <= maxRate)) && .c) StorageDrain else maxRate
  }
  maxRate <- (((((storageThickness - storageDepth) * storageVoidFrac) / .G_lidproc_Tstep) + StorageExfil) + StorageEvap) + StorageDrain
  StorageInflow <<- if (!is.na(.c <- (StorageInflow <= maxRate)) && .c) StorageInflow else maxRate
  SurfaceInfil <<- StorageInflow
  SurfaceOutflow <<- getSurfaceOutflowRate(surfaceDepth)
  f$v[[1]] <- (((.G_SurfaceInflow - SurfaceEvap) - StorageInflow) - SurfaceOutflow) / .G_theLidProc$surface$voidFrac
  f$v[[3]] <- (((StorageInflow - StorageEvap) - StorageExfil) - StorageDrain) / .G_theLidProc$storage$voidFrac
  f$v[[2]] <- 0
}

# lidproc.c:823
pavementFluxRates <- function(x, f) {
  x; f
  .G_SurfaceInflow <- SurfaceInflow; .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc
  pervFrac <- 1 - .G_theLidProc$pavement$impervFrac
  storageInflow <- 0
  paveVoidFrac <- .G_theLidProc$pavement$voidFrac * pervFrac
  paveThickness <- .G_theLidProc$pavement$thickness
  soilThickness <- .G_theLidProc$soil$thickness
  soilPorosity <- .G_theLidProc$soil$porosity
  soilFieldCap <- .G_theLidProc$soil$fieldCap
  soilWiltPoint <- .G_theLidProc$soil$wiltPoint
  storageThickness <- .G_theLidProc$storage$thickness
  storageVoidFrac <- .G_theLidProc$storage$voidFrac
  surfaceDepth <- x$v[[1]]
  paveDepth <- x$v[[4]]
  soilTheta <- x$v[[2]]
  storageDepth <- x$v[[3]]
  SurfaceVolume <<- surfaceDepth * .G_theLidProc$surface$voidFrac
  PaveVolume <<- paveDepth * paveVoidFrac
  SoilVolume <<- soilTheta * soilThickness
  StorageVolume <<- storageDepth * storageVoidFrac
  availVolume <- SoilVolume - (soilWiltPoint * soilThickness)
  lidproc_getEvapRates(SurfaceVolume, PaveVolume, availVolume, StorageVolume, pervFrac)
  if ((!is.na(.c <- (paveDepth >= paveThickness)) && .c) || ((!is.na(.c <- (soilThickness > 0)) && .c) && (!is.na(.c <- (soilTheta >= soilPorosity)) && .c))) {
    StorageEvap <<- 0
  }
  SurfaceInfil <<- .G_SurfaceInflow + (SurfaceVolume / .G_lidproc_Tstep)
  PavePerc <<- getPavementPermRate() * pervFrac
  SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= PavePerc)) && .c) SurfaceInfil else PavePerc
  maxRate <- ((PaveVolume / .G_lidproc_Tstep) + SurfaceInfil) - PaveEvap
  maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
  PavePerc <<- if (!is.na(.c <- (PavePerc <= maxRate)) && .c) PavePerc else maxRate
  if (!is.na(.c <- (soilThickness > 0)) && .c) {
    SoilPerc <<- getSoilPercRate(soilTheta)
    availVolume <- (soilTheta - soilFieldCap) * soilThickness
    maxRate <- ((if (!is.na(.c <- (availVolume >= 0)) && .c) availVolume else 0) / .G_lidproc_Tstep) - SoilEvap
    SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
    SoilPerc <<- if (!is.na(.c <- (SoilPerc >= 0)) && .c) SoilPerc else 0
  } else {
    SoilPerc <<- PavePerc
  }
  StorageExfil <<- getStorageExfilRate()
  StorageDrain <<- 0
  if (!is.na(.c <- (.G_theLidProc$drain$coeff > 0)) && .c) {
    StorageDrain <<- getStorageDrainRate(storageDepth, soilTheta, paveDepth, surfaceDepth)
  }
  if (((!is.na(.c <- (soilThickness == 0)) && .c) && (!is.na(.c <- (storageDepth >= storageThickness)) && .c)) && (!is.na(.c <- (paveDepth >= paveThickness)) && .c)) {
    maxRate <- (StorageEvap + StorageDrain) + StorageExfil
    if (!is.na(.c <- (PavePerc > maxRate)) && .c) {
      PavePerc <<- maxRate
    } else {
      StorageExfil <<- if (!is.na(.c <- (StorageExfil <= PavePerc)) && .c) StorageExfil else PavePerc
      StorageDrain <<- PavePerc - StorageExfil
    }
    SoilPerc <<- PavePerc
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= PavePerc)) && .c) SurfaceInfil else PavePerc
  } else if ((((!is.na(.c <- (soilThickness > 0)) && .c) && (!is.na(.c <- (storageDepth >= storageThickness)) && .c)) && (!is.na(.c <- (soilTheta >= soilPorosity)) && .c)) && (!is.na(.c <- (paveDepth >= paveThickness)) && .c)) {
    maxRate <- StorageExfil + StorageDrain
    if (!is.na(.c <- (SoilPerc < maxRate)) && .c) {
      maxRate <- SoilPerc
    } else {
      maxRate <- if (!is.na(.c <- (maxRate <= PavePerc)) && .c) maxRate else PavePerc
    }
    if (!is.na(.c <- (maxRate > StorageExfil)) && .c) {
      StorageDrain <<- maxRate - StorageExfil
    } else {
      StorageExfil <<- maxRate
      StorageDrain <<- 0
    }
    SoilPerc <<- maxRate
    PavePerc <<- maxRate
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= PavePerc)) && .c) SurfaceInfil else PavePerc
  } else if (((!is.na(.c <- (soilThickness > 0)) && .c) && (!is.na(.c <- (storageDepth >= storageThickness)) && .c)) && (!is.na(.c <- (soilTheta >= soilPorosity)) && .c)) {
    maxRate <- StorageDrain + StorageExfil
    if (!is.na(.c <- (SoilPerc > maxRate)) && .c) {
      SoilPerc <<- maxRate
    } else {
      StorageExfil <<- if (!is.na(.c <- (StorageExfil <= SoilPerc)) && .c) StorageExfil else SoilPerc
      StorageDrain <<- SoilPerc - StorageExfil
    }
    PavePerc <<- if (!is.na(.c <- (PavePerc <= SoilPerc)) && .c) PavePerc else SoilPerc
    availVolume <- (paveThickness - paveDepth) * paveVoidFrac
    maxRate <- ((availVolume / .G_lidproc_Tstep) + PavePerc) + PaveEvap
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
  } else if (((!is.na(.c <- (soilThickness > 0)) && .c) && (!is.na(.c <- (paveDepth >= paveThickness)) && .c)) && (!is.na(.c <- (soilTheta >= soilPorosity)) && .c)) {
    PavePerc <<- if (!is.na(.c <- (PavePerc <= SoilPerc)) && .c) PavePerc else SoilPerc
    SoilPerc <<- PavePerc
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= PavePerc)) && .c) SurfaceInfil else PavePerc
    maxRate <- if (!is.na(.c <- ((((StorageVolume / .G_lidproc_Tstep) + SoilPerc) - StorageEvap) >= 0)) && .c) (((StorageVolume / .G_lidproc_Tstep) + SoilPerc) - StorageEvap) else 0
    StorageExfil <<- if (!is.na(.c <- (StorageExfil <= maxRate)) && .c) StorageExfil else maxRate
  } else {
    maxRate <- (SoilPerc - StorageEvap) + (StorageVolume / .G_lidproc_Tstep)
    maxRate <- if (!is.na(.c <- (0 >= maxRate)) && .c) 0 else maxRate
    StorageExfil <<- if (!is.na(.c <- (StorageExfil <= maxRate)) && .c) StorageExfil else maxRate
    if (!is.na(.c <- (StorageDrain > 0)) && .c) {
      maxRate <- (-StorageExfil) - StorageEvap
      if (!is.na(.c <- (storageDepth >= storageThickness)) && .c) {
        maxRate <- maxRate + SoilPerc
      }
      if (!is.na(.c <- (.G_theLidProc$drain$offset <= storageDepth)) && .c) {
        maxRate <- maxRate + (((storageDepth - .G_theLidProc$drain$offset) * storageVoidFrac) / .G_lidproc_Tstep)
      }
      maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
      StorageDrain <<- if (!is.na(.c <- (StorageDrain <= maxRate)) && .c) StorageDrain else maxRate
    }
    availVolume <- (storageThickness - storageDepth) * storageVoidFrac
    maxRate <- (((availVolume / .G_lidproc_Tstep) + StorageEvap) + StorageDrain) + StorageExfil
    maxRate <- if (!is.na(.c <- (maxRate >= 0)) && .c) maxRate else 0
    if (!is.na(.c <- (soilThickness > 0)) && .c) {
      SoilPerc <<- if (!is.na(.c <- (SoilPerc <= maxRate)) && .c) SoilPerc else maxRate
      maxRate <- (((soilPorosity - soilTheta) * soilThickness) / .G_lidproc_Tstep) + SoilPerc
    }
    PavePerc <<- if (!is.na(.c <- (PavePerc <= maxRate)) && .c) PavePerc else maxRate
    availVolume <- (paveThickness - paveDepth) * paveVoidFrac
    maxRate <- ((availVolume / .G_lidproc_Tstep) + PavePerc) + PaveEvap
    SurfaceInfil <<- if (!is.na(.c <- (SurfaceInfil <= maxRate)) && .c) SurfaceInfil else maxRate
  }
  SurfaceOutflow <<- getSurfaceOutflowRate(surfaceDepth)
  f$v[[1]] <- ((.G_SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow
  f$v[[4]] <- ((SurfaceInfil - PaveEvap) - PavePerc) / paveVoidFrac
  if (!is.na(.c <- (.G_theLidProc$soil$thickness > 0)) && .c) {
    f$v[[2]] <- ((PavePerc - SoilEvap) - SoilPerc) / soilThickness
    storageInflow <- SoilPerc
  } else {
    f$v[[2]] <- 0
    storageInflow <- PavePerc
    SoilPerc <<- 0
  }
  f$v[[3]] <- (((storageInflow - StorageEvap) - StorageExfil) - StorageDrain) / storageVoidFrac
}

# lidproc.c:1061
swaleFluxRates <- function(x, f) {
  x; f
  .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc; .G_theLidUnit <- theLidUnit
  hydRadius <- 0
  depth <- x$v[[1]]
  depth <- if (!is.na(.c <- (depth <= .G_theLidProc$surface$thickness)) && .c) depth else .G_theLidProc$surface$thickness
  dStore <- 0
  slope <- .G_theLidProc$surface$sideSlope
  topWidth <- .G_theLidUnit$fullWidth
  topWidth <- if (!is.na(.c <- (topWidth >= 0.5)) && .c) topWidth else 0.5
  botWidth <- topWidth - ((2 * slope) * .G_theLidProc$surface$thickness)
  if (!is.na(.c <- (botWidth < 0.5)) && .c) {
    botWidth <- 0.5
    slope <- (0.5 * (topWidth - 0.5)) / .G_theLidProc$surface$thickness
  }
  lidArea <- .G_theLidUnit$area
  length_ <- lidArea / topWidth
  surfWidth <- botWidth + ((2 * slope) * depth)
  surfArea <- length_ * surfWidth
  flowArea <- (depth * (botWidth + (slope * depth))) * .G_theLidProc$surface$voidFrac
  volume <- length_ * flowArea
  surfInflow <- SurfaceInflow * lidArea
  SurfaceEvap <<- lidproc_EvapRate * surfArea
  SurfaceEvap <<- if (!is.na(.c <- (SurfaceEvap <= (volume / .G_lidproc_Tstep))) && .c) SurfaceEvap else (volume / .G_lidproc_Tstep)
  StorageExfil <<- SurfaceInfil * surfArea
  xDepth <- depth - dStore
  if (!is.na(.c <- (xDepth <= 1e-10)) && .c) {
    SurfaceOutflow <<- 0
  } else {
    flowArea <- flowArea - ((dStore * (botWidth + (slope * dStore))) * .G_theLidProc$surface$voidFrac)
    if (!is.na(.c <- (flowArea < 1e-10)) && .c) {
      SurfaceOutflow <<- 0
    } else {
      botWidth <- botWidth + ((2 * dStore) * slope)
      hydRadius <- botWidth + ((2 * xDepth) * (sqrt(1 + (slope * slope))))
      hydRadius <- flowArea / hydRadius
      SurfaceOutflow <<- (.G_theLidProc$surface$alpha * flowArea) * (if ((.p <- hydRadius) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666))
    }
  }
  dVdT <- ((surfInflow - SurfaceEvap) - StorageExfil) - SurfaceOutflow
  if ((!is.na(.c <- (depth == .G_theLidProc$surface$thickness)) && .c) && (!is.na(.c <- (dVdT > 0)) && .c)) {
    SurfaceOutflow <<- SurfaceOutflow + dVdT
    dVdT <- 0
  }
  SurfaceEvap <<- SurfaceEvap / lidArea
  StorageExfil <<- StorageExfil / lidArea
  SurfaceOutflow <<- SurfaceOutflow / lidArea
  f$v[[1]] <- dVdT / surfArea
  f$v[[2]] <- 0
  f$v[[3]] <- 0
  SurfaceVolume <<- volume / lidArea
  SoilVolume <<- 0
  StorageVolume <<- 0
}

# lidproc.c:1176
barrelFluxRates <- function(x, f) {
  x; f
  .G_SurfaceInflow <- SurfaceInflow; .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc
  storageDepth <- x$v[[3]]
  head <- 0
  maxValue <- 0
  SurfaceVolume <<- 0
  SoilVolume <<- 0
  StorageVolume <<- storageDepth
  SurfaceInfil <<- 0
  SurfaceOutflow <<- 0
  StorageDrain <<- 0
  if ((!is.na(.c <- (.G_theLidProc$drain$delay == 0)) && .c) || (!is.na(.c <- (theLidUnit$dryTime >= .G_theLidProc$drain$delay)) && .c)) {
    head <- storageDepth - .G_theLidProc$drain$offset
    if (!is.na(.c <- (head > 0)) && .c) {
      StorageDrain <<- getStorageDrainRate(storageDepth, 0, 0, 0)
      maxValue <- head / .G_lidproc_Tstep
      StorageDrain <<- if (!is.na(.c <- (StorageDrain <= maxValue)) && .c) StorageDrain else maxValue
    }
  }
  StorageInflow <<- .G_SurfaceInflow
  maxValue <- ((.G_theLidProc$storage$thickness - storageDepth) / .G_lidproc_Tstep) + StorageDrain
  StorageInflow <<- if (!is.na(.c <- (StorageInflow <= maxValue)) && .c) StorageInflow else maxValue
  SurfaceInfil <<- StorageInflow
  f$v[[1]] <- .G_SurfaceInflow - StorageInflow
  f$v[[3]] <- StorageInflow - StorageDrain
  f$v[[2]] <- 0
}

# lidproc.c:1226
getSurfaceOutflowRate <- function(depth) {
  depth
  .G_lidproc_Tstep <- lidproc_Tstep; .G_theLidProc <- theLidProc; .G_theLidUnit <- theLidUnit
  delta <- depth - .G_theLidProc$surface$thickness
  if (!is.na(.c <- (delta < 0)) && .c) {
    return(0)
  }
  outflow <- ((.G_theLidProc$surface$alpha * (if ((.p <- delta) > -Inf || is.na(.p)) .p ^ 1.6666666666666667 else rt_pow(.p, 1.6666666666666667))) * .G_theLidUnit$fullWidth) / .G_theLidUnit$area
  outflow <- if (!is.na(.c <- (outflow <= (delta / .G_lidproc_Tstep))) && .c) outflow else (delta / .G_lidproc_Tstep)
  return(outflow)
}

# lidproc.c:1251
getPavementPermRate <- function() {
  .G_theLidProc <- theLidProc; .G_theLidUnit <- theLidUnit
  permReduction <- 0
  clogFactor <- .G_theLidProc$pavement$clogFactor
  regenDays <- .G_theLidProc$pavement$regenDays
  if (!is.na(.c <- (clogFactor > 0)) && .c) {
    if (!is.na(.c <- (regenDays > 0)) && .c) {
      if (!is.na(.c <- (((OldRunoffTime / 1000) / 86400) >= .G_theLidUnit$nextRegenDay)) && .c) {
        .G_theLidUnit$volTreated <- .G_theLidUnit$volTreated * (1 - .G_theLidProc$pavement$regenDegree)
        .G_theLidUnit$nextRegenDay <- .G_theLidUnit$nextRegenDay + regenDays
      }
    }
    permReduction <- .G_theLidUnit$volTreated / clogFactor
    permReduction <- if (!is.na(.c <- (permReduction <= 1)) && .c) permReduction else 1
  }
  return(.G_theLidProc$pavement$kSat * (1 - permReduction))
}

# lidproc.c:1293
getSoilPercRate <- function(theta) {
  theta
  .G_theLidProc <- theLidProc
  if (!is.na(.c <- (theta <= .G_theLidProc$soil$fieldCap)) && .c) {
    return(0)
  }
  delta <- .G_theLidProc$soil$porosity - theta
  return(.G_theLidProc$soil$kSat * (exp((-delta) * .G_theLidProc$soil$kSlope)))
}

# lidproc.c:1313
getStorageExfilRate <- function() {
  .G_lidproc_MaxNativeInfil <- lidproc_MaxNativeInfil; .G_theLidProc <- theLidProc
  infil <- 0
  clogFactor <- 0
  if (!is.na(.c <- (.G_theLidProc$storage$kSat == 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (.G_lidproc_MaxNativeInfil == 0)) && .c) {
    return(0)
  }
  clogFactor <- .G_theLidProc$storage$clogFactor
  if (!is.na(.c <- (clogFactor > 0)) && .c) {
    clogFactor <- theLidUnit$waterBalance$inflow / clogFactor
    clogFactor <- if (!is.na(.c <- (clogFactor <= 1)) && .c) clogFactor else 1
  }
  infil <- .G_theLidProc$storage$kSat * (1 - clogFactor)
  return(if (!is.na(.c <- (infil <= .G_lidproc_MaxNativeInfil)) && .c) infil else .G_lidproc_MaxNativeInfil)
}

# lidproc.c:1344
getStorageDrainRate <- function(storageDepth, soilTheta, paveDepth, surfaceDepth) {
  storageDepth; soilTheta; paveDepth; surfaceDepth
  .G_theLidProc <- theLidProc; .G_theLidUnit <- theLidUnit
  curve <- .G_theLidProc$drain$qCurve
  head <- storageDepth
  outflow <- 0
  paveThickness <- .G_theLidProc$pavement$thickness
  soilThickness <- .G_theLidProc$soil$thickness
  soilPorosity <- .G_theLidProc$soil$porosity
  soilFieldCap <- .G_theLidProc$soil$fieldCap
  storageThickness <- .G_theLidProc$storage$thickness
  if (!is.na(.c <- (storageDepth >= storageThickness)) && .c) {
    if (!is.na(.c <- (soilThickness > 0)) && .c) {
      if (!is.na(.c <- (soilTheta > soilFieldCap)) && .c) {
        head <- head + (((soilTheta - soilFieldCap) / (soilPorosity - soilFieldCap)) * soilThickness)
        if (!is.na(.c <- (soilTheta >= soilPorosity)) && .c) {
          if (!is.na(.c <- (paveThickness > 0)) && .c) {
            head <- head + paveDepth
            if (!is.na(.c <- (paveDepth >= paveThickness)) && .c) {
              head <- head + surfaceDepth
            }
          } else {
            head <- head + surfaceDepth
          }
        }
      }
    } else if (!is.na(.c <- (paveThickness > 0)) && .c) {
      head <- head + paveDepth
      if (!is.na(.c <- (paveDepth >= paveThickness)) && .c) {
        head <- head + surfaceDepth
      }
    }
  }
  if ((!is.na(.c <- (.G_theLidUnit$oldDrainFlow == 0)) && .c) && (!is.na(.c <- (head <= .G_theLidProc$drain$hOpen)) && .c)) {
    return(0)
  }
  if ((!is.na(.c <- (.G_theLidUnit$oldDrainFlow > 0)) && .c) && (!is.na(.c <- (head <= .G_theLidProc$drain$hClose)) && .c)) {
    return(0)
  }
  head <- head - .G_theLidProc$drain$offset
  if (!is.na(.c <- (head > 1e-10)) && .c) {
    head <- head * (UCF(1))
    outflow <- .G_theLidProc$drain$coeff * (rt_pow(head, .G_theLidProc$drain$expon))
    if (curve >= 0) {
      outflow <- outflow * (table_lookup(Curve[[curve + 1]], head))
    }
    outflow <- outflow / (UCF(0))
  }
  return(outflow)
}

# lidproc.c:1436
getDrainMatOutflow <- function(depth) {
  depth
  .G_theLidProc <- theLidProc; .G_theLidUnit <- theLidUnit
  result <- SoilPerc
  if (!is.na(.c <- (.G_theLidProc$drainMat$alpha > 0)) && .c) {
    result <- (((.G_theLidProc$drainMat$alpha * (if ((.p <- depth) > -Inf || is.na(.p)) .p ^ 1.6666666666666667 else rt_pow(.p, 1.6666666666666667))) * .G_theLidUnit$fullWidth) / .G_theLidUnit$area) * .G_theLidProc$drainMat$voidFrac
  }
  return(result)
}

# lidproc.c:1458
lidproc_getEvapRates <- function(surfaceVol, paveVol, soilVol, storageVol, pervFrac) {
  surfaceVol; paveVol; soilVol; storageVol; pervFrac
  .G_lidproc_Tstep <- lidproc_Tstep
  availEvap <- lidproc_EvapRate
  SurfaceEvap <<- if (!is.na(.c <- (availEvap <= (surfaceVol / .G_lidproc_Tstep))) && .c) availEvap else (surfaceVol / .G_lidproc_Tstep)
  SurfaceEvap <<- if (!is.na(.c <- (0 >= SurfaceEvap)) && .c) 0 else SurfaceEvap
  availEvap <- if (!is.na(.c <- (0 >= (availEvap - SurfaceEvap))) && .c) 0 else (availEvap - SurfaceEvap)
  availEvap <- availEvap * pervFrac
  if (!is.na(.c <- (SurfaceInfil > 0)) && .c) {
    PaveEvap <<- 0
    SoilEvap <<- 0
    StorageEvap <<- 0
  } else {
    PaveEvap <<- if (!is.na(.c <- (availEvap <= (paveVol / .G_lidproc_Tstep))) && .c) availEvap else (paveVol / .G_lidproc_Tstep)
    availEvap <- if (!is.na(.c <- (0 >= (availEvap - PaveEvap))) && .c) 0 else (availEvap - PaveEvap)
    SoilEvap <<- if (!is.na(.c <- (availEvap <= (soilVol / .G_lidproc_Tstep))) && .c) availEvap else (soilVol / .G_lidproc_Tstep)
    availEvap <- if (!is.na(.c <- (0 >= (availEvap - SoilEvap))) && .c) 0 else (availEvap - SoilEvap)
    StorageEvap <<- if (!is.na(.c <- (availEvap <= (storageVol / .G_lidproc_Tstep))) && .c) availEvap else (storageVol / .G_lidproc_Tstep)
  }
}

# lidproc.c:1503
getSurfaceOverflowRate <- function(surfaceDepth) {
  surfaceDepth
  .G_theLidProc <- theLidProc
  delta <- surfaceDepth$v - .G_theLidProc$surface$thickness
  if (!is.na(.c <- (delta <= 0)) && .c) {
    return(0)
  }
  surfaceDepth$v <- .G_theLidProc$surface$thickness
  return((delta * .G_theLidProc$surface$voidFrac) / lidproc_Tstep)
}

# lidproc.c:1518
updateWaterBalance <- function(lidUnit, inflow, evap, infil, surfFlow, drainFlow, storage) {
  lidUnit; inflow; evap; infil; surfFlow; drainFlow; storage
  .G_lidproc_Tstep <- lidproc_Tstep
  lidUnit$volTreated <- lidUnit$volTreated + (inflow * .G_lidproc_Tstep)
  {.e1 <- lidUnit$waterBalance; .e1$inflow <- lidUnit$waterBalance$inflow + (inflow * .G_lidproc_Tstep)}
  {.e2 <- lidUnit$waterBalance; .e2$evap <- lidUnit$waterBalance$evap + (evap * .G_lidproc_Tstep)}
  {.e3 <- lidUnit$waterBalance; .e3$infil <- lidUnit$waterBalance$infil + (infil * .G_lidproc_Tstep)}
  {.e4 <- lidUnit$waterBalance; .e4$surfFlow <- lidUnit$waterBalance$surfFlow + (surfFlow * .G_lidproc_Tstep)}
  {.e5 <- lidUnit$waterBalance; .e5$drainFlow <- lidUnit$waterBalance$drainFlow + (drainFlow * .G_lidproc_Tstep)}
  {.e6 <- lidUnit$waterBalance; .e6$finalVol <- storage}
}

# lidproc.c:1544
modpuls_solve <- function(n, x, xOld, xPrev, xMin, xMax, xTol, qOld, q_, dt, omega, derivs) {
  n; x; xOld; xPrev; xMin; xMax; xTol; qOld; q_; dt; omega; derivs
  canStop <- 0
  steps <- 1
  maxSteps <- 20
  i <- 0
  while (i < n) {
    xOld$v[[i + 1]] <- x$v[[i + 1]]
    xPrev$v[[i + 1]] <- x$v[[i + 1]]
    i <- i + 1
  }
  while (steps < maxSteps) {
    canStop <- 1
    derivs(x, q_)
    i <- 0
    while (i < n) {
      x$v[[i + 1]] <- xOld$v[[i + 1]] + (((omega * (qOld$v[[i + 1]])) + ((1 - omega) * (q_$v[[i + 1]]))) * dt)
      x$v[[i + 1]] <- if (!is.na(.c <- ((x$v[[i + 1]]) <= (xMax$v[[i + 1]]))) && .c) (x$v[[i + 1]]) else (xMax$v[[i + 1]])
      x$v[[i + 1]] <- if (!is.na(.c <- ((x$v[[i + 1]]) >= (xMin$v[[i + 1]]))) && .c) (x$v[[i + 1]]) else (xMin$v[[i + 1]])
      if ((!is.na(.c <- (omega > 0)) && .c) && (!is.na(.c <- (abs(x$v[[i + 1]] - (xPrev$v[[i + 1]])) > xTol$v[[i + 1]])) && .c)) {
        canStop <- 0
      }
      xPrev$v[[i + 1]] <- x$v[[i + 1]]
      i <- i + 1
    }
    if (canStop != 0) {
      return(steps)
    }
    steps <- steps + 1
  }
  return(0)
}

# link.c:137
link_readParams <- function(j, type, k, tok, ntoks) {
  j; type; k; tok; ntoks
  if (type == 0) {
    return(conduit_readParams(j, k, tok, ntoks))
  } else if (type == 1) {
    return(pump_readParams(j, k, tok, ntoks))
  } else if (type == 2) {
    return(orifice_readParams(j, k, tok, ntoks))
  } else if (type == 3) {
    return(weir_readParams(j, k, tok, ntoks))
  } else if (type == 4) {
    return(outlet_readParams(j, k, tok, ntoks))
  } else {
    return(0)
  }
}

# link.c:162
link_readXsectParams <- function(tok, ntoks) {
  tok; ntoks
  .G_Conduit <- Conduit; .G_Link <- Link
  i <- 0
  x <- rt_ra(numeric(4))
  if (ntoks < 3) {
    return(error_setInpError(203, .L0))
  }
  j <- project_findObject(3, tok$v[[1]])
  if (j < 0) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  k <- findmatch(tok$v[[2]], XsectTypeWords)
  if (k < 0) {
    return(error_setInpError(205, tok$v[[2]]))
  }
  if ((.G_Link[[j + 1]])$type == 0) {
    {.e1 <- .G_Conduit[[(.G_Link[[j + 1]])$subIndex + 1]]; .e1$barrels <- 1}
  }
  {.e2 <- (.G_Link[[j + 1]])$xsect; .e2$culvertCode <- 0}
  if (k == 22) {
    i <- project_findObject(10, tok$v[[3]])
    if (i < 0) {
      return(error_setInpError(209, tok$v[[3]]))
    }
    {.e3 <- (.G_Link[[j + 1]])$xsect; .e3$type <- k}
    {.e4 <- (.G_Link[[j + 1]])$xsect; .e4$transect <- i}
    return(0)
  } else if (k == 25) {
    i <- project_findObject(16, tok$v[[3]])
    if (i < 0) {
      return(error_setInpError(209, tok$v[[3]]))
    }
    {.e5 <- (.G_Link[[j + 1]])$xsect; .e5$type <- k}
    {.e6 <- (.G_Link[[j + 1]])$xsect; .e6$transect <- i}
    return(0)
  } else {
    if (ntoks < 6) {
      return(error_setInpError(203, .L0))
    }
    if (k == 23) {
      if ((!({.b7 <- rt_box(x$v[[1]]); .r8 <- getDouble(tok$v[[3]], .b7); x$v[[1]] <- .b7$v; .r8} != 0)) || (!is.na(.c <- (x$v[[1]] <= 0)) && .c)) {
        return(error_setInpError(211, tok$v[[3]]))
      }
      i <- project_findObject(7, tok$v[[4]])
      if (i < 0) {
        return(error_setInpError(209, tok$v[[4]]))
      }
      {.e9 <- (.G_Link[[j + 1]])$xsect; .e9$type <- k}
      {.e10 <- (.G_Link[[j + 1]])$xsect; .e10$transect <- i}
      {.e11 <- (.G_Link[[j + 1]])$xsect; .e11$yFull <- x$v[[1]] / (UCF(3))}
    } else {
      i <- 2
      while (i <= 5) {
        if (!({.b12 <- rt_box(x$v[[(i - 2) + 1]]); .r13 <- getDouble(tok$v[[i + 1]], .b12); x$v[[(i - 2) + 1]] <- .b12$v; .r13} != 0)) {
          return(error_setInpError(211, tok$v[[i + 1]]))
        }
        i <- i + 1
      }
    }
    if (((.G_Link[[j + 1]])$type != 0) && (k == 4)) {
      x$v[[3]] <- 0
      x$v[[4]] <- 0
    }
    if (!(xsect_setParams((.G_Link[[j + 1]])$xsect, k, x, UCF(3)) != 0)) {
      return(error_setInpError(211, .L0))
    }
    if (((.G_Link[[j + 1]])$type == 0) && (ntoks >= 7)) {
      i <- rt_atoi(tok$v[[7]])
      if (i <= 0) {
        return(error_setInpError(211, tok$v[[7]]))
      } else {
        {.e14 <- .G_Conduit[[(.G_Link[[j + 1]])$subIndex + 1]]; .e14$barrels <- i}
      }
    }
    if (((.G_Link[[j + 1]])$type == 0) && (ntoks >= 8)) {
      i <- rt_atoi(tok$v[[8]])
      if (i < 0) {
        return(error_setInpError(211, tok$v[[8]]))
      } else {
        {.e15 <- (.G_Link[[j + 1]])$xsect; .e15$culvertCode <- i}
      }
    }
  }
  return(0)
}

# link.c:271
link_readLossParams <- function(tok, ntoks) {
  tok; ntoks
  .G_Link <- Link
  x <- rt_ra(numeric(3))
  seepRate <- 0
  if (ntoks < 4) {
    return(error_setInpError(203, .L0))
  }
  j <- project_findObject(3, tok$v[[1]])
  if (j < 0) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  i <- 1
  while (i <= 3) {
    if ((!({.b1 <- rt_box(x$v[[i]]); .r2 <- getDouble(tok$v[[i + 1]], .b1); x$v[[i]] <- .b1$v; .r2} != 0)) || (!is.na(.c <- (x$v[[i]] < 0)) && .c)) {
      return(error_setInpError(211, tok$v[[i + 1]]))
    }
    i <- i + 1
  }
  k <- 0
  if (ntoks >= 5) {
    k <- findmatch(tok$v[[5]], NoYesWords)
    if (k < 0) {
      return(error_setInpError(205, tok$v[[5]]))
    }
  }
  if (ntoks >= 6) {
    if (!({.BX_link_readLossParams_seepRate$v <- seepRate; .r3 <- getDouble(tok$v[[6]], .BX_link_readLossParams_seepRate); seepRate <- .BX_link_readLossParams_seepRate$v; .r3} != 0)) {
      return(error_setInpError(211, tok$v[[6]]))
    }
  }
  {.e4 <- .G_Link[[j + 1]]; .e4$cLossInlet <- x$v[[1]]}
  {.e5 <- .G_Link[[j + 1]]; .e5$cLossOutlet <- x$v[[2]]}
  {.e6 <- .G_Link[[j + 1]]; .e6$cLossAvg <- x$v[[3]]}
  {.e7 <- .G_Link[[j + 1]]; .e7$hasFlapGate <- k}
  {.e8 <- .G_Link[[j + 1]]; .e8$seepRate <- seepRate / (UCF(0))}
  return(0)
}

# link.c:315
link_setParams <- function(j, type, n1, n2, k, x) {
  j; type; n1; n2; k; x
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Orifice <- Orifice; .G_Outlet <- Outlet; .G_Pump <- Pump; .G_Weir <- Weir
  {.e1 <- .G_Link[[j + 1]]; .e1$node1 <- n1}
  {.e2 <- .G_Link[[j + 1]]; .e2$node2 <- n2}
  {.e3 <- .G_Link[[j + 1]]; .e3$type <- type}
  {.e4 <- .G_Link[[j + 1]]; .e4$subIndex <- k}
  {.e5 <- .G_Link[[j + 1]]; .e5$offset1 <- 0}
  {.e6 <- .G_Link[[j + 1]]; .e6$offset2 <- 0}
  {.e7 <- .G_Link[[j + 1]]; .e7$q0 <- 0}
  {.e8 <- .G_Link[[j + 1]]; .e8$qFull <- 0}
  {.e9 <- .G_Link[[j + 1]]; .e9$setting <- 1}
  {.e10 <- .G_Link[[j + 1]]; .e10$targetSetting <- 1}
  {.e11 <- .G_Link[[j + 1]]; .e11$hasFlapGate <- 0}
  {.e12 <- .G_Link[[j + 1]]; .e12$qLimit <- 0}
  {.e13 <- .G_Link[[j + 1]]; .e13$direction <- 1}
  if (type == 0) {
    {.e14 <- .G_Conduit[[k + 1]]; .e14$length <- x$v[[1]] / (UCF(3))}
    {.e15 <- .G_Conduit[[k + 1]]; .e15$modLength <- (.G_Conduit[[k + 1]])$length}
    {.e16 <- .G_Conduit[[k + 1]]; .e16$roughness <- x$v[[2]]}
    {.e17 <- .G_Link[[j + 1]]; .e17$offset1 <- x$v[[3]] / (UCF(3))}
    {.e18 <- .G_Link[[j + 1]]; .e18$offset2 <- x$v[[4]] / (UCF(3))}
    {.e19 <- .G_Link[[j + 1]]; .e19$q0 <- x$v[[5]] / (UCF(10))}
    {.e20 <- .G_Link[[j + 1]]; .e20$qLimit <- x$v[[6]] / (UCF(10))}
  } else if (type == 1) {
    {.e21 <- .G_Pump[[k + 1]]; .e21$pumpCurve <- if (is.na(.d <- x$v[[1]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
    {.e22 <- .G_Link[[j + 1]]; .e22$hasFlapGate <- 0}
    {.e23 <- .G_Pump[[k + 1]]; .e23$initSetting <- x$v[[2]]}
    {.e24 <- .G_Pump[[k + 1]]; .e24$yOn <- x$v[[3]] / (UCF(3))}
    {.e25 <- .G_Pump[[k + 1]]; .e25$yOff <- x$v[[4]] / (UCF(3))}
    {.e26 <- .G_Pump[[k + 1]]; .e26$xMin <- 0}
    {.e27 <- .G_Pump[[k + 1]]; .e27$xMax <- 0}
  } else if (type == 2) {
    {.e28 <- .G_Orifice[[k + 1]]; .e28$type <- if (is.na(.d <- x$v[[1]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
    {.e29 <- .G_Link[[j + 1]]; .e29$offset1 <- x$v[[2]] / (UCF(3))}
    {.e30 <- .G_Link[[j + 1]]; .e30$offset2 <- (.G_Link[[j + 1]])$offset1}
    {.e31 <- .G_Orifice[[k + 1]]; .e31$cDisch <- x$v[[3]]}
    {.e32 <- .G_Link[[j + 1]]; .e32$hasFlapGate <- if (!is.na(.c <- (x$v[[4]] > 0)) && .c) 1 else 0}
    {.e33 <- .G_Orifice[[k + 1]]; .e33$orate <- x$v[[5]] * 3600}
  } else if (type == 3) {
    {.e34 <- .G_Weir[[k + 1]]; .e34$type <- if (is.na(.d <- x$v[[1]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
    {.e35 <- .G_Link[[j + 1]]; .e35$offset1 <- x$v[[2]] / (UCF(3))}
    {.e36 <- .G_Link[[j + 1]]; .e36$offset2 <- (.G_Link[[j + 1]])$offset1}
    {.e37 <- .G_Weir[[k + 1]]; .e37$cDisch1 <- x$v[[3]]}
    {.e38 <- .G_Link[[j + 1]]; .e38$hasFlapGate <- if (!is.na(.c <- (x$v[[4]] > 0)) && .c) 1 else 0}
    {.e39 <- .G_Weir[[k + 1]]; .e39$endCon <- x$v[[5]]}
    {.e40 <- .G_Weir[[k + 1]]; .e40$cDisch2 <- x$v[[6]]}
    {.e41 <- .G_Weir[[k + 1]]; .e41$canSurcharge <- if (is.na(.d <- x$v[[7]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
    {.e42 <- .G_Weir[[k + 1]]; .e42$roadWidth <- x$v[[8]] / (UCF(3))}
    {.e43 <- .G_Weir[[k + 1]]; .e43$roadSurface <- if (is.na(.d <- x$v[[9]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
    {.e44 <- .G_Weir[[k + 1]]; .e44$cdCurve <- if (is.na(.d <- x$v[[10]]) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)}
  } else if (type == 4) {
    {.e45 <- .G_Link[[j + 1]]; .e45$offset1 <- x$v[[1]] / (UCF(3))}
    {.e46 <- .G_Link[[j + 1]]; .e46$offset2 <- (.G_Link[[j + 1]])$offset1}
    {.e47 <- .G_Outlet[[k + 1]]; .e47$qCoeff <- x$v[[2]]}
    {.e48 <- .G_Outlet[[k + 1]]; .e48$qExpon <- x$v[[3]]}
