    if (!is.na(.c <- (((.G_Node[[(.G_Link[[j + 1]])$node1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1) < (.G_Node[[(.G_Link[[j + 1]])$node2 + 1]])$invertElev)) && .c) {
