    }
  }
  if (((.G_Link[[j + 1]])$type == 1) || (((.G_Link[[j + 1]])$type == 2) && ((Orifice[[(.G_Link[[j + 1]])$subIndex + 1]])$type == 1))) {
    return(invisible(NULL))
  }
  n <- (.G_Link[[j + 1]])$node1
  if (((.G_Node[[n + 1]])$type != 2) || (!is.na(.c <- ((.G_Node[[n + 1]])$surDepth > 0)) && .c)) {
    {.e4 <- .G_Node[[n + 1]]; .e4$fullDepth <- if (!is.na(.c <- (((.G_Node[[n + 1]])$fullDepth) >= ((.G_Link[[j + 1]])$offset1 + ((.G_Link[[j + 1]])$xsect)$yFull))) && .c) ((.G_Node[[n + 1]])$fullDepth) else ((.G_Link[[j + 1]])$offset1 + ((.G_Link[[j + 1]])$xsect)$yFull)}
  }
  n <- (.G_Link[[j + 1]])$node2
  if ((((.G_Node[[n + 1]])$type != 2) || (!is.na(.c <- ((.G_Node[[n + 1]])$surDepth > 0)) && .c)) && ((.G_Link[[j + 1]])$type == 0)) {
    {.e5 <- .G_Node[[n + 1]]; .e5$fullDepth <- if (!is.na(.c <- (((.G_Node[[n + 1]])$fullDepth) >= ((.G_Link[[j + 1]])$offset2 + ((.G_Link[[j + 1]])$xsect)$yFull))) && .c) ((.G_Node[[n + 1]])$fullDepth) else ((.G_Link[[j + 1]])$offset2 + ((.G_Link[[j + 1]])$xsect)$yFull)}
  }
