link_getResults <- function(j, f, x) {
  j; f; x
  .G_Link <- Link; .G_Nobjects <- Nobjects
  p <- 0
  f1 <- 1 - f
  y <- (f1 * ((.G_Link[[j + 1]])$oldDepth)) + (f * ((.G_Link[[j + 1]])$newDepth))
  q_ <- (f1 * ((.G_Link[[j + 1]])$oldFlow)) + (f * ((.G_Link[[j + 1]])$newFlow))
  v <- (f1 * ((.G_Link[[j + 1]])$oldVolume)) + (f * ((.G_Link[[j + 1]])$newVolume))
  u <- link_getVelocity(j, q_, y)
  c_ <- 0
  if ((.G_Link[[j + 1]])$type == 0) {
    if (((.G_Link[[j + 1]])$xsect)$type != 0) {
      c_ <- xsect_getAofY((.G_Link[[j + 1]])$xsect, y) / (((.G_Link[[j + 1]])$xsect)$aFull)
    }
  } else {
    c_ <- (.G_Link[[j + 1]])$setting
  }
  if (((.G_Link[[j + 1]])$type == 1) && (!is.na(.c <- (((.G_Link[[j + 1]])$oldFlow * ((.G_Link[[j + 1]])$newFlow)) == 0)) && .c)) {
    if (!is.na(.c <- (f >= f1)) && .c) {
      q_ <- (.G_Link[[j + 1]])$newFlow
    } else {
      q_ <- (.G_Link[[j + 1]])$oldFlow
    }
  }
  y <- y * (UCF(3))
  v <- v * (UCF(5))
  q_ <- q_ * (UCF(10) * ((.G_Link[[j + 1]])$direction))
  u <- u * (UCF(3) * ((.G_Link[[j + 1]])$direction))
  x$v[[2]] <- rt_f32(y)
  x$v[[1]] <- rt_f32(q_)
  x$v[[3]] <- rt_f32(u)
  x$v[[4]] <- rt_f32(v)
  x$v[[5]] <- rt_f32(c_)
  if (!(IgnoreQuality != 0)) {
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      c_ <- (f1 * (((.G_Link[[j + 1]])$oldQual)$v[[p + 1]])) + (f * (((.G_Link[[j + 1]])$newQual)$v[[p + 1]]))
      x$v[[(5 + p) + 1]] <- rt_f32(c_)
      p <- p + 1
    }
  }
}

