  if (n1 < 0) {
    return(error_setInpError(209, tok$v[[2]]))
  }
  n2 <- project_findObject(2, tok$v[[3]])
  if (n2 < 0) {
    return(error_setInpError(209, tok$v[[3]]))
  }
  if (!({.b1 <- rt_box(x$v[[1]]); .r2 <- getDouble(tok$v[[4]], .b1); x$v[[1]] <- .b1$v; .r2} != 0)) {
    return(error_setInpError(211, tok$v[[4]]))
  }
  if (!({.b3 <- rt_box(x$v[[2]]); .r4 <- getDouble(tok$v[[5]], .b3); x$v[[2]] <- .b3$v; .r4} != 0)) {
    return(error_setInpError(211, tok$v[[5]]))
  }
  if ((.G_LinkOffsets == 1) && (rt_cget(tok$v[[6]], 0) == 42)) {
    x$v[[3]] <- -10000000000
  } else if (!({.b5 <- rt_box(x$v[[3]]); .r6 <- getDouble(tok$v[[6]], .b5); x$v[[3]] <- .b5$v; .r6} != 0)) {
    return(error_setInpError(211, tok$v[[6]]))
  }
  if ((.G_LinkOffsets == 1) && (rt_cget(tok$v[[7]], 0) == 42)) {
    x$v[[4]] <- -10000000000
  } else if (!({.b7 <- rt_box(x$v[[4]]); .r8 <- getDouble(tok$v[[7]], .b7); x$v[[4]] <- .b7$v; .r8} != 0)) {
    return(error_setInpError(211, tok$v[[7]]))
  }
  x$v[[5]] <- 0
  if (ntoks >= 8) {
    if (!({.b9 <- rt_box(x$v[[5]]); .r10 <- getDouble(tok$v[[8]], .b9); x$v[[5]] <- .b9$v; .r10} != 0)) {
      return(error_setInpError(211, tok$v[[8]]))
    }
  }
  x$v[[6]] <- 0
  if (ntoks >= 9) {
    if (!({.b11 <- rt_box(x$v[[6]]); .r12 <- getDouble(tok$v[[9]], .b11); x$v[[6]] <- .b11$v; .r12} != 0)) {
      return(error_setInpError(211, tok$v[[9]]))
    }
  }
  {.e13 <- Link[[j + 1]]; .e13$ID <- id}
  link_setParams(j, 0, n1, n2, k, x)
  return(0)
}

