    {.e2 <- .G_Conduit[[k + 1]]; .e2$roughness <- (Street[[((.G_Link[[j + 1]])$xsect)$transect + 1]])$roughness}
  }
  if (((.G_Link[[j + 1]])$xsect)$type == 24) {
