    }
    if (!is.na(.c <- (((.G_Link[[j + 1]])$xsect)$rBot <= 0)) && .c) {
      report_writeErrorMsg(119, (.G_Link[[j + 1]])$ID)
    }
  }
  if (!is.na(.c <- ((.G_Conduit[[k + 1]])$length <= 0)) && .c) {
