# link.c:1217
conduit_getLengthFactor <- function(j, k, roughness) {
  j; k; roughness
  .G_LengtheningStep <- LengtheningStep; .G_Link <- Link; .G_RouteStep <- RouteStep
  tStep <- 0
  yFull <- ((.G_Link[[j + 1]])$xsect)$yFull
  if (xsect_isOpen(((.G_Link[[j + 1]])$xsect)$type) != 0) {
    yFull <- ((.G_Link[[j + 1]])$xsect)$aFull / (xsect_getWofY((.G_Link[[j + 1]])$xsect, yFull))
  }
  vFull <- (((1.486 / roughness) * (((.G_Link[[j + 1]])$xsect)$sFull)) * (sqrt(abs((Conduit[[k + 1]])$slope)))) / (((.G_Link[[j + 1]])$xsect)$aFull)
