    tStep <- .G_RouteStep
  } else {
    tStep <- if (!is.na(.c <- (.G_RouteStep <= .G_LengtheningStep)) && .c) .G_RouteStep else .G_LengtheningStep
  }
  ratio <- ((sqrt(32.2 * yFull) + vFull) * tStep) / (conduit_getLength(j))
  if (!is.na(.c <- (ratio > 1)) && .c) {
