# link.c:1258
conduit_getSlope <- function(j) {
  j
  .G_Link <- Link; .G_MIN_DELTA_Z <- MIN_DELTA_Z; .G_MinSlope <- MinSlope; .G_Node <- Node; .G_RouteModel <- RouteModel
