  length_ <- conduit_getLength(j)
  elev1 <- (.G_Link[[j + 1]])$offset1 + (.G_Node[[(.G_Link[[j + 1]])$node1 + 1]])$invertElev
  elev2 <- (.G_Link[[j + 1]])$offset2 + (.G_Node[[(.G_Link[[j + 1]])$node2 + 1]])$invertElev
  delta <- abs(elev1 - elev2)
  if (!is.na(.c <- (delta < .G_MIN_DELTA_Z)) && .c) {
    report_writeWarningMsg(.L308, (.G_Link[[j + 1]])$ID)
    delta <- .G_MIN_DELTA_Z
  }
  if (!is.na(.c <- (delta >= length_)) && .c) {
    report_writeWarningMsg(.L309, (.G_Link[[j + 1]])$ID)
    slope <- delta / length_
  } else {
    slope <- delta / (sqrt((length_ * length_) - (delta * delta)))
  }
  if ((!is.na(.c <- (.G_MinSlope$v > 0)) && .c) && (!is.na(.c <- (slope < .G_MinSlope$v)) && .c)) {
    report_writeWarningMsg(.L310, (.G_Link[[j + 1]])$ID)
