# link.c:1334
conduit_getLossRate <- function(j, routeModel, q_, tstep) {
  j; routeModel; q_; tstep
  .G_Conduit <- Conduit; .G_Evap <- Evap; .G_Link <- Link
  xsect <- NULL
  depth <- 0.5 * ((.G_Link[[j + 1]])$oldDepth + (.G_Link[[j + 1]])$newDepth)
  length_ <- 0
  width <- 0
  topWidth <- 0
  evapLossRate <- 0
  seepLossRate <- 0
  totalLossRate <- 0
  if (!is.na(.c <- (depth > 0.0001)) && .c) {
    xsect <- (.G_Link[[j + 1]])$xsect
    length_ <- conduit_getLength(j)
    if ((xsect_isOpen(xsect$type) != 0) && (!is.na(.c <- (.G_Evap$rate > 0)) && .c)) {
      topWidth <- xsect_getWofY(xsect, depth)
      evapLossRate <- (topWidth * length_) * .G_Evap$rate
    }
    if (!is.na(.c <- ((.G_Link[[j + 1]])$seepRate > 0)) && .c) {
      if (xsect$type == 3) {
        width <- xsect$wMax
      } else {
        if (!is.na(.c <- (depth >= xsect$ywMax)) && .c) {
          depth <- xsect$ywMax
        }
        width <- xsect_getWofY(xsect, depth)
      }
      seepLossRate <- ((.G_Link[[j + 1]])$seepRate * width) * length_
      seepLossRate <- seepLossRate * Adjust$hydconFactor
    }
    totalLossRate <- evapLossRate + seepLossRate
    if (routeModel == 4) {
      q_ <- (.G_Link[[j + 1]])$newVolume / tstep
    } else {
      q_ <- if (!is.na(.c <- (q_ < 0)) && .c) (-q_) else q_
    }
    if (!is.na(.c <- (totalLossRate > q_)) && .c) {
      evapLossRate <- (evapLossRate * q_) / totalLossRate
      seepLossRate <- (seepLossRate * q_) / totalLossRate
      totalLossRate <- q_
    }
  }
  {.e1 <- .G_Conduit[[(.G_Link[[j + 1]])$subIndex + 1]]; .e1$evapLossRate <- evapLossRate}
  {.e2 <- .G_Conduit[[(.G_Link[[j + 1]])$subIndex + 1]]; .e2$seepLossRate <- seepLossRate}
  return(totalLossRate)
}

# link.c:1406
pump_readParams <- function(j, k, tok, ntoks) {
