  }
  n2 <- project_findObject(2, tok$v[[3]])
  if (n2 < 0) {
    return(error_setInpError(209, tok$v[[3]]))
  }
  x$v[[1]] <- -1
  if (ntoks >= 4) {
    if (!(strcomp(tok$v[[4]], .L275) != 0)) {
      m <- project_findObject(7, tok$v[[4]])
      if (m < 0) {
        return(error_setInpError(209, tok$v[[4]]))
      }
      x$v[[1]] <- m
    }
  }
  x$v[[2]] <- 1
  if (ntoks >= 5) {
    m <- findmatch(tok$v[[5]], OffOnWords)
    if (m < 0) {
      return(error_setInpError(205, tok$v[[5]]))
    }
    x$v[[2]] <- m
  }
  x$v[[3]] <- 0
  if (ntoks >= 6) {
    if ((!({.b1 <- rt_box(x$v[[3]]); .r2 <- getDouble(tok$v[[6]], .b1); x$v[[3]] <- .b1$v; .r2} != 0)) || (!is.na(.c <- (x$v[[3]] < 0)) && .c)) {
      return(error_setInpError(211, tok$v[[6]]))
    }
  }
  x$v[[4]] <- 0
  if (ntoks >= 7) {
    if ((!({.b3 <- rt_box(x$v[[4]]); .r4 <- getDouble(tok$v[[7]], .b3); x$v[[4]] <- .b3$v; .r4} != 0)) || (!is.na(.c <- (x$v[[4]] < 0)) && .c)) {
      return(error_setInpError(211, tok$v[[7]]))
    }
  }
  {.e5 <- Link[[j + 1]]; .e5$ID <- id}
  link_setParams(j, 1, n1, n2, k, x)
  return(0)
}

