# link.c:1548
pump_getInflow <- function(j) {
  j
  .G_Curve <- Curve; .G_Link <- Link; .G_Node <- Node; .G_Pump <- Pump
  vol <- 0
  depth <- 0
  head <- 0
  qIn <- 0
  qIn1 <- 0
  dh <- 0.001
  s <- 1
  k <- (.G_Link[[j + 1]])$subIndex
  m <- (.G_Pump[[k + 1]])$pumpCurve
  n1 <- (.G_Link[[j + 1]])$node1
  n2 <- (.G_Link[[j + 1]])$node2
  {.e1 <- .G_Link[[j + 1]]; .e1$flowClass <- 0}
  {.e2 <- .G_Link[[j + 1]]; .e2$setting <- (.G_Link[[j + 1]])$targetSetting}
  if (!is.na(.c <- ((.G_Link[[j + 1]])$setting == 0)) && .c) {
    return(0)
  }
  if ((.G_Pump[[k + 1]])$type == 5) {
    qIn <- (.G_Node[[n1 + 1]])$inflow + (.G_Node[[n1 + 1]])$overflow
  } else {
    .sw3 <- (.G_Curve[[m + 1]])$curveType
    if (.sw3 == 7) {
      vol <- (.G_Node[[n1 + 1]])$newVolume * (UCF(5))
      qIn <- table_intervalLookup(.G_Curve[[m + 1]], vol) / (UCF(10))
      if ((!is.na(.c <- (vol < (.G_Pump[[k + 1]])$xMin)) && .c) || (!is.na(.c <- (vol > (.G_Pump[[k + 1]])$xMax)) && .c)) {
        {.e4 <- .G_Link[[j + 1]]; .e4$flowClass <- 1}
      }
    } else if (.sw3 == 8) {
      depth <- (.G_Node[[n1 + 1]])$newDepth * (UCF(3))
      qIn <- table_intervalLookup(.G_Curve[[m + 1]], depth) / (UCF(10))
      if ((!is.na(.c <- (depth < (.G_Pump[[k + 1]])$xMin)) && .c) || (!is.na(.c <- (depth > (.G_Pump[[k + 1]])$xMax)) && .c)) {
        {.e5 <- .G_Link[[j + 1]]; .e5$flowClass <- 1}
      }
    } else if (.sw3 == 9 || .sw3 == 11) {
      if ((.G_Curve[[m + 1]])$curveType == 11) {
        s <- (.G_Link[[j + 1]])$setting
      }
      head <- ((((.G_Node[[n2 + 1]])$newDepth + (.G_Node[[n2 + 1]])$invertElev) - ((.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev)) / s) / s
      head <- (if (!is.na(.c <- (head >= 0)) && .c) head else 0) * (UCF(3))
      qIn <- table_lookup(.G_Curve[[m + 1]], head) / (UCF(10))
      {.e6 <- .G_Link[[j + 1]]; .e6$dqdh <- (((-(table_getSlope(.G_Curve[[m + 1]], head))) * (UCF(3))) / (UCF(10))) / s}
      if ((!is.na(.c <- (head < (.G_Pump[[k + 1]])$xMin)) && .c) || (!is.na(.c <- (head > (.G_Pump[[k + 1]])$xMax)) && .c)) {
        {.e7 <- .G_Link[[j + 1]]; .e7$flowClass <- 1}
      }
    } else if (.sw3 == 10) {
      depth <- (.G_Node[[n1 + 1]])$newDepth
      qIn <- table_lookup(.G_Curve[[m + 1]], (depth * (UCF(3)))) / (UCF(10))
      qIn1 <- table_lookup(.G_Curve[[m + 1]], ((depth + dh) * (UCF(3)))) / (UCF(10))
      {.e8 <- .G_Link[[j + 1]]; .e8$dqdh <- (qIn1 - qIn) / dh}
      depth <- depth * (UCF(3))
      if (!is.na(.c <- (depth < (.G_Pump[[k + 1]])$xMin)) && .c) {
        {.e9 <- .G_Link[[j + 1]]; .e9$flowClass <- 2}
      }
      if (!is.na(.c <- (depth > (.G_Pump[[k + 1]])$xMax)) && .c) {
        {.e10 <- .G_Link[[j + 1]]; .e10$flowClass <- 1}
      }
    } else {
      qIn <- 0
    }
  }
  if (!is.na(.c <- (qIn < 0)) && .c) {
    qIn <- 0
  }
  return(qIn * ((.G_Link[[j + 1]])$setting))
}

