# link.c:1729
orifice_setSetting <- function(j, tstep) {
  j; tstep
  .G_Link <- Link; .G_Orifice <- Orifice
  k <- (.G_Link[[j + 1]])$subIndex
  delta <- 0
  step <- 0
  if ((!is.na(.c <- ((.G_Orifice[[k + 1]])$orate == 0)) && .c) || (!is.na(.c <- (tstep == 0)) && .c)) {
    {.e1 <- .G_Link[[j + 1]]; .e1$setting <- (.G_Link[[j + 1]])$targetSetting}
  } else {
    delta <- (.G_Link[[j + 1]])$targetSetting - ((.G_Link[[j + 1]])$setting)
    step <- tstep / ((.G_Orifice[[k + 1]])$orate)
    if (!is.na(.c <- ((step + 0.001) >= abs(delta))) && .c) {
      {.e2 <- .G_Link[[j + 1]]; .e2$setting <- (.G_Link[[j + 1]])$targetSetting}
    } else {
      {.e3 <- .G_Link[[j + 1]]; .e3$setting <- (.G_Link[[j + 1]])$setting + ((if (!is.na(.c <- (delta < 0)) && .c) (-1) else 1) * step)}
    }
  }
  h <- (.G_Link[[j + 1]])$setting * (((.G_Link[[j + 1]])$xsect)$yFull)
  f <- xsect_getAofY((.G_Link[[j + 1]])$xsect, h) * (sqrt(2 * 32.2))
  {.e4 <- .G_Orifice[[k + 1]]; .e4$cOrif <- (.G_Orifice[[k + 1]])$cDisch * f}
  {.e5 <- .G_Orifice[[k + 1]]; .e5$cWeir <- orifice_getWeirCoeff(j, k, h) * f}
}

# link.c:1766
orifice_getWeirCoeff <- function(j, k, h) {
  j; k; h
  .G_Link <- Link; .G_Orifice <- Orifice
  w <- 0
  aOverL <- 0
  if ((.G_Orifice[[k + 1]])$type == 1) {
    if (((.G_Link[[j + 1]])$xsect)$type == 1) {
      aOverL <- h / 4
    } else {
      w <- ((.G_Link[[j + 1]])$xsect)$wMax
      aOverL <- (h * w) / (2 * (h + w))
    }
    h <- ((.G_Orifice[[k + 1]])$cDisch / 0.414) * aOverL
    {.e1 <- .G_Orifice[[k + 1]]; .e1$hCrit <- h}
  } else {
    {.e2 <- .G_Orifice[[k + 1]]; .e2$hCrit <- h}
    h <- h / 2
  }
  return((.G_Orifice[[k + 1]])$cDisch * (sqrt(h)))
}

# link.c:1812
orifice_getInflow <- function(j) {
  j
  .G_Link <- Link; .G_Node <- Node; .G_Orifice <- Orifice
  head <- 0
  h1 <- 0
  h2 <- 0
  f <- 0
  hcrest <- 0
  hcrown <- 0
  hmidpt <- 0
  ratio <- 0
  n1 <- (.G_Link[[j + 1]])$node1
  n2 <- (.G_Link[[j + 1]])$node2
  k <- (.G_Link[[j + 1]])$subIndex
  if (RouteModel == 4) {
    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n2 + 1]])$newDepth + (.G_Node[[n2 + 1]])$invertElev
  } else {
    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n1 + 1]])$invertElev
  }
  dir <- if (!is.na(.c <- (h1 >= h2)) && .c) 1 else (-1)
  y1 <- (.G_Node[[n1 + 1]])$newDepth
  if (!is.na(.c <- (dir < 0)) && .c) {
    head <- h1
    h1 <- h2
    h2 <- head
    y1 <- (.G_Node[[n2 + 1]])$newDepth
  }
  if ((.G_Orifice[[k + 1]])$type == 1) {
    hcrest <- (.G_Node[[n1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1
    if (!is.na(.c <- (h1 < hcrest)) && .c) {
      head <- 0
    } else if (!is.na(.c <- (h2 > hcrest)) && .c) {
      head <- h1 - h2
    } else {
      head <- h1 - hcrest
    }
    f <- head / ((.G_Orifice[[k + 1]])$hCrit)
    f <- if (!is.na(.c <- (f <= 1)) && .c) f else 1
  } else {
    hcrest <- (.G_Node[[n1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1
    hcrown <- hcrest + (((.G_Link[[j + 1]])$xsect)$yFull * ((.G_Link[[j + 1]])$setting))
    hmidpt <- (hcrest + hcrown) / 2
    if ((!is.na(.c <- (h1 < hcrown)) && .c) && (!is.na(.c <- (hcrown > hcrest)) && .c)) {
      f <- (h1 - hcrest) / (hcrown - hcrest)
    } else {
      f <- 1
    }
    if (!is.na(.c <- (f < 1)) && .c) {
      head <- h1 - hcrest
    } else if (!is.na(.c <- (h2 < hmidpt)) && .c) {
      head <- h1 - hmidpt
    } else {
      head <- h1 - h2
    }
  }
  if (((!is.na(.c <- (head <= 0.0001)) && .c) || (!is.na(.c <- (y1 <= 0.0001)) && .c)) || (link_setFlapGate(j, n1, n2, dir) != 0)) {
    {.e1 <- .G_Link[[j + 1]]; .e1$newDepth <- 0}
    {.e2 <- .G_Link[[j + 1]]; .e2$flowClass <- 0}
    {.e3 <- .G_Orifice[[k + 1]]; .e3$surfArea <- 0.0001 * ((.G_Orifice[[k + 1]])$length)}
    {.e4 <- .G_Link[[j + 1]]; .e4$dqdh <- 0}
    return(0)
  }
  {.e5 <- .G_Link[[j + 1]]; .e5$flowClass <- 3}
  if (!is.na(.c <- (hcrest > h2)) && .c) {
    if (!is.na(.c <- (dir == 1)) && .c) {
      {.e6 <- .G_Link[[j + 1]]; .e6$flowClass <- 6}
    } else {
      {.e7 <- .G_Link[[j + 1]]; .e7$flowClass <- 5}
    }
  }
  y1 <- ((.G_Link[[j + 1]])$xsect)$yFull * ((.G_Link[[j + 1]])$setting)
  if ((.G_Orifice[[k + 1]])$type == 0) {
    {.e8 <- .G_Link[[j + 1]]; .e8$newDepth <- y1 * f}
    {.e9 <- .G_Orifice[[k + 1]]; .e9$surfArea <- xsect_getWofY((.G_Link[[j + 1]])$xsect, (.G_Link[[j + 1]])$newDepth) * ((.G_Orifice[[k + 1]])$length)}
  } else {
    {.e10 <- .G_Link[[j + 1]]; .e10$newDepth <- y1}
    {.e11 <- .G_Orifice[[k + 1]]; .e11$surfArea <- xsect_getAofY((.G_Link[[j + 1]])$xsect, y1)}
  }
  q_ <- dir * (orifice_getFlow(j, k, head, f, (.G_Link[[j + 1]])$hasFlapGate))
  if ((!is.na(.c <- (f < 1)) && .c) && (!is.na(.c <- (h2 > hcrest)) && .c)) {
    ratio <- (h2 - hcrest) / (h1 - hcrest)
    q_ <- q_ * (if ((.p <- 1 - (if ((.p <- ratio) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))) > -Inf || is.na(.p)) .p ^ 0.385 else rt_pow(.p, 0.385))
  }
  return(q_)
}

# link.c:1938
orifice_getFlow <- function(j, k, head, f, hasFlapGate) {
  j; k; head; f; hasFlapGate
  .G_Link <- Link; .G_Orifice <- Orifice
  area <- 0
  q_ <- 0
  veloc <- 0
  hLoss <- 0
  if ((!is.na(.c <- (head == 0)) && .c) || (!is.na(.c <- (f <= 0)) && .c)) {
    {.e1 <- .G_Link[[j + 1]]; .e1$dqdh <- 0}
    return(0)
  } else if (!is.na(.c <- (f < 1)) && .c) {
    q_ <- (.G_Orifice[[k + 1]])$cWeir * (if ((.p <- f) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    {.e2 <- .G_Link[[j + 1]]; .e2$dqdh <- (1.5 * q_) / (f * ((.G_Orifice[[k + 1]])$hCrit))}
  } else {
    q_ <- (.G_Orifice[[k + 1]])$cOrif * (sqrt(head))
    {.e3 <- .G_Link[[j + 1]]; .e3$dqdh <- q_ / (2 * head)}
  }
  if (hasFlapGate != 0) {
    area <- xsect_getAofY((.G_Link[[j + 1]])$xsect, ((.G_Link[[j + 1]])$setting * (((.G_Link[[j + 1]])$xsect)$yFull)))
    veloc <- q_ / area
    hLoss <- (((4 / 32.2) * veloc) * veloc) * (exp(((-1.15) * veloc) / (sqrt(head))))
    if (!is.na(.c <- (f < 1)) && .c) {
      f <- f - (hLoss / ((.G_Orifice[[k + 1]])$hCrit))
      if (!is.na(.c <- (f < 0)) && .c) {
        f <- 0
      }
    } else {
      head <- head - hLoss
      if (!is.na(.c <- (head < 0)) && .c) {
        head <- 0
      }
    }
    q_ <- orifice_getFlow(j, k, head, f, 0)
  }
  return(q_)
}

