  {.e7 <- .G_Weir[[k + 1]]; .e7$length <- if (!is.na(.c <- (200 >= ((.G_Weir[[k + 1]])$length))) && .c) 200 else ((.G_Weir[[k + 1]])$length)}
  {.e8 <- .G_Weir[[k + 1]]; .e8$surfArea <- 0}
  head <- ((.G_Link[[j + 1]])$xsect)$yFull
  {.BX_weir_validate_q1$v <- q1; .BX_weir_validate_q2$v <- q2; .r9 <- weir_getFlow(j, k, head, 1, 0, .BX_weir_validate_q1, .BX_weir_validate_q2); q1 <- .BX_weir_validate_q1$v; q2 <- .BX_weir_validate_q2$v; .r9}
  q_ <- q1 + q2
