    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n2 + 1]])$newDepth + (.G_Node[[n2 + 1]])$invertElev
  } else {
    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n1 + 1]])$invertElev
  }
  dir <- if (!is.na(.c <- (h1 > h2)) && .c) 1 else (-1)
  if (!is.na(.c <- (dir < 0)) && .c) {
    head <- h1
    h1 <- h2
    h2 <- head
  }
  hcrest <- (.G_Node[[n1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1
  hcrown <- hcrest + ((.G_Link[[j + 1]])$xsect)$yFull
  if ((.G_Weir[[k + 1]])$type == 4) {
    return(roadway_getInflow(j, dir, hcrest, h1, h2))
  }
  hcrest <- hcrest + ((1 - ((.G_Link[[j + 1]])$setting)) * (((.G_Link[[j + 1]])$xsect)$yFull))
  head <- h1 - hcrest
  {.e1 <- .G_Link[[j + 1]]; .e1$dqdh <- 0}
  if (((!is.na(.c <- (head <= 0.0001)) && .c) || (!is.na(.c <- (hcrest >= hcrown)) && .c)) || (link_setFlapGate(j, n1, n2, dir) != 0)) {
    {.e2 <- .G_Link[[j + 1]]; .e2$newDepth <- 0}
    {.e3 <- .G_Link[[j + 1]]; .e3$flowClass <- 0}
    return(0)
  }
  {.e4 <- .G_Link[[j + 1]]; .e4$flowClass <- 3}
  if (!is.na(.c <- (hcrest > h2)) && .c) {
    if (!is.na(.c <- (dir == 1)) && .c) {
      {.e5 <- .G_Link[[j + 1]]; .e5$flowClass <- 6}
    } else {
      {.e6 <- .G_Link[[j + 1]]; .e6$flowClass <- 5}
    }
  }
  y <- ((.G_Link[[j + 1]])$xsect)$yFull - (hcrown - (if (!is.na(.c <- (h1 <= hcrown)) && .c) h1 else hcrown))
  {.e7 <- .G_Weir[[k + 1]]; .e7$surfArea <- xsect_getWofY((.G_Link[[j + 1]])$xsect, y) * ((.G_Weir[[k + 1]])$length)}
  if (!is.na(.c <- (h1 >= hcrown)) && .c) {
    if ((.G_Weir[[k + 1]])$canSurcharge != 0) {
      y <- (hcrest + hcrown) / 2
