        head <- h1 - y
      } else {
        head <- h1 - h2
      }
      y <- hcrown - hcrest
      q1 <- weir_getOrificeFlow(j, head, y, (.G_Weir[[k + 1]])$cSurcharge)
      {.e8 <- .G_Link[[j + 1]]; .e8$newDepth <- y}
      return(dir * q1)
    } else {
      head <- hcrown - hcrest
    }
  }
  {.BX_weir_getInflow_q1$v <- q1; .BX_weir_getInflow_q2$v <- q2; .r9 <- weir_getFlow(j, k, head, dir, (.G_Link[[j + 1]])$hasFlapGate, .BX_weir_getInflow_q1, .BX_weir_getInflow_q2); q1 <- .BX_weir_getInflow_q1$v; q2 <- .BX_weir_getInflow_q2$v; .r9}
  if (!is.na(.c <- (h2 > hcrest)) && .c) {
    ratio <- (h2 - hcrest) / (h1 - hcrest)
    q1 <- q1 * (if ((.p <- 1 - (rt_pow(ratio, weirPower$v[[(.G_Weir[[k + 1]])$type + 1]]))) > -Inf || is.na(.p)) .p ^ 0.385 else rt_pow(.p, 0.385))
    if (!is.na(.c <- (q2 > 0)) && .c) {
      q2 <- q2 * (if ((.p <- 1 - (rt_pow(ratio, weirPower$v[[3]]))) > -Inf || is.na(.p)) .p ^ 0.385 else rt_pow(.p, 0.385))
    }
  }
  {.e10 <- .G_Link[[j + 1]]; .e10$newDepth <- if (!is.na(.c <- ((h1 - hcrest) <= (((.G_Link[[j + 1]])$xsect)$yFull))) && .c) (h1 - hcrest) else (((.G_Link[[j + 1]])$xsect)$yFull)}
  return(dir * (q1 + q2))
}

# link.c:2321
weir_getFlow <- function(j, k, head, dir, hasFlapGate, q1, q2) {
  j; k; head; dir; hasFlapGate; q1; q2
  .G_Link <- Link; .G_Weir <- Weir
  y <- 0
  hLoss <- 0
  area <- 0
  veloc <- 0
  cdCurve <- (.G_Weir[[k + 1]])$cdCurve
  cDisch1 <- (.G_Weir[[k + 1]])$cDisch1
  q1$v <- 0
  q2$v <- 0
  {.e1 <- .G_Link[[j + 1]]; .e1$dqdh <- 0}
  if (!is.na(.c <- (head <= 0)) && .c) {
    return(invisible(NULL))
  }
  length_ <- ((.G_Link[[j + 1]])$xsect)$wMax * (UCF(3))
  h <- head * (UCF(3))
  if (cdCurve >= 0) {
    cDisch1 <- table_lookup(Curve[[cdCurve + 1]], h)
  }
  wType <- (.G_Weir[[k + 1]])$type
  if ((wType == 2) && (!is.na(.c <- ((.G_Link[[j + 1]])$setting < 1)) && .c)) {
    wType <- 3
  }
  if (wType == 0) {
    length_ <- length_ - ((0.1 * ((.G_Weir[[k + 1]])$endCon)) * h)
    length_ <- if (!is.na(.c <- (length_ >= 0)) && .c) length_ else 0
    q1$v <- (cDisch1 * length_) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
  } else if (wType == 1) {
    length_ <- length_ - ((0.1 * ((.G_Weir[[k + 1]])$endCon)) * h)
    length_ <- if (!is.na(.c <- (length_ >= 0)) && .c) length_ else 0
    if (!is.na(.c <- (dir < 0)) && .c) {
      q1$v <- (cDisch1 * length_) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    } else {
      q1$v <- (cDisch1 * (if ((.p <- length_) > -Inf || is.na(.p)) .p ^ 0.83 else rt_pow(.p, 0.83))) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 1.67 else rt_pow(.p, 1.67))
    }
  } else if (wType == 2) {
    q1$v <- (cDisch1 * ((.G_Weir[[k + 1]])$slope)) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 2.5 else rt_pow(.p, 2.5))
  } else if (wType == 3) {
    y <- (1 - ((.G_Link[[j + 1]])$setting)) * (((.G_Link[[j + 1]])$xsect)$yFull)
    length_ <- xsect_getWofY((.G_Link[[j + 1]])$xsect, y) * (UCF(3))
    q1$v <- (cDisch1 * length_) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    q2$v <- ((.G_Weir[[k + 1]])$cDisch2 * ((.G_Weir[[k + 1]])$slope)) * (if ((.p <- h) > -Inf || is.na(.p)) .p ^ 2.5 else rt_pow(.p, 2.5))
  }
  if (UnitSystem == 1) {
    q1$v <- q1$v / 0.028317
    q2$v <- q2$v / 0.028317
  }
  if (hasFlapGate != 0) {
    area <- weir_getOpenArea(j, head)
    if (!is.na(.c <- (area > 1e-06)) && .c) {
      veloc <- (q1$v + q2$v) / area
      hLoss <- (((4 / 32.2) * veloc) * veloc) * (exp(((-1.15) * veloc) / (sqrt(head))))
      head <- head - hLoss
      if (!is.na(.c <- (head < 0)) && .c) {
        head <- 0
      }
      weir_getFlow(j, k, head, dir, 0, q1, q2)
    }
  }
  {.e2 <- .G_Link[[j + 1]]; .e2$dqdh <- weir_getdqdh(k, dir, head, q1$v, q2$v)}
}

# link.c:2432
weir_getOrificeFlow <- function(j, head, y, cOrif) {
  j; head; y; cOrif
  .G_Link <- Link
  a <- 0
  v <- 0
  hloss <- 0
  q_ <- cOrif * (sqrt(head))
  if ((.G_Link[[j + 1]])$hasFlapGate != 0) {
    a <- weir_getOpenArea(j, y)
    if (!is.na(.c <- (a > 0)) && .c) {
      v <- q_ / a
      hloss <- (((4 / 32.2) * v) * v) * (exp(((-1.15) * v) / (sqrt(y))))
      head <- head - hloss
      head <- if (!is.na(.c <- (head >= 0)) && .c) head else 0
      q_ <- cOrif * (sqrt(head))
    }
  }
  if (!is.na(.c <- (head > 0)) && .c) {
    {.e1 <- .G_Link[[j + 1]]; .e1$dqdh <- q_ / (2 * head)}
  } else {
    {.e2 <- .G_Link[[j + 1]]; .e2$dqdh <- 0}
  }
  return(q_)
}

# link.c:2467
weir_getOpenArea <- function(j, y) {
  j; y
  .G_Link <- Link
  z <- (1 - ((.G_Link[[j + 1]])$setting)) * (((.G_Link[[j + 1]])$xsect)$yFull)
  zy <- z + y
  zy <- if (!is.na(.c <- (zy <= (((.G_Link[[j + 1]])$xsect)$yFull))) && .c) zy else (((.G_Link[[j + 1]])$xsect)$yFull)
  return(xsect_getAofY((.G_Link[[j + 1]])$xsect, zy) - (xsect_getAofY((.G_Link[[j + 1]])$xsect, z)))
}

# link.c:2492
weir_getdqdh <- function(k, dir, h, q1, q2) {
  k; dir; h; q1; q2
  if (!is.na(.c <- (abs(h) < 0.0001)) && .c) {
    return(0)
  }
  q1h <- abs(q1 / h)
  q2h <- abs(q2 / h)
  .sw1 <- (Weir[[k + 1]])$type
  if (.sw1 == 0) {
    return(1.5 * q1h)
  } else if (.sw1 == 1) {
    if (!is.na(.c <- (dir < 0)) && .c) {
      return(1.5 * q1h)
    } else {
      return(1.67 * q1h)
    }
  } else if (.sw1 == 2) {
    if (!is.na(.c <- (q2h == 0)) && .c) {
      return(2.5 * q1h)
    } else {
      return((1.5 * q1h) + (2.5 * q2h))
    }
  } else if (.sw1 == 3) {
    return((1.5 * q1h) + (2.5 * q2h))
  }
  return(0)
}

# link.c:2524
outlet_readParams <- function(j, k, tok, ntoks) {
  j; k; tok; ntoks
  .G_LinkOffsets <- LinkOffsets
  i <- 0
  n <- 0
  x <- rt_ra(numeric(6))
  if (ntoks < 6) {
    return(error_setInpError(203, .L0))
  }
  id <- project_findID(3, tok$v[[1]])
  if (is.null(id)) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  n1 <- project_findObject(2, tok$v[[2]])
  if (n1 < 0) {
    return(error_setInpError(209, tok$v[[2]]))
  }
  n2 <- project_findObject(2, tok$v[[3]])
  if (n2 < 0) {
    return(error_setInpError(209, tok$v[[3]]))
  }
  if ((.G_LinkOffsets == 1) && (rt_cget(tok$v[[4]], 0) == 42)) {
    x$v[[1]] <- -10000000000
  } else {
    if (!({.b1 <- rt_box(x$v[[1]]); .r2 <- getDouble(tok$v[[4]], .b1); x$v[[1]] <- .b1$v; .r2} != 0)) {
      return(error_setInpError(211, tok$v[[4]]))
    }
    if ((.G_LinkOffsets == 0) && (!is.na(.c <- (x$v[[1]] < 0)) && .c)) {
      x$v[[1]] <- 0
    }
  }
  m <- findmatch(tok$v[[5]], RelationWords)
  if (m < 0) {
    return(error_setInpError(205, tok$v[[5]]))
  }
  x$v[[2]] <- 0
  x$v[[3]] <- 0
  x$v[[4]] <- -1
  x$v[[5]] <- 0
  x$v[[6]] <- 0
  s <- rt_strtok(tok$v[[5]], .L313)
  s <- rt_strtok(NULL, .L313)
  if (strcomp(s, .L314) != 0) {
    x$v[[6]] <- 1
  }
  if (m == 1) {
    if (ntoks < 7) {
      return(error_setInpError(203, .L0))
    }
    if (!({.b3 <- rt_box(x$v[[2]]); .r4 <- getDouble(tok$v[[6]], .b3); x$v[[2]] <- .b3$v; .r4} != 0)) {
      return(error_setInpError(211, tok$v[[6]]))
    }
    if (!({.b5 <- rt_box(x$v[[3]]); .r6 <- getDouble(tok$v[[7]], .b5); x$v[[3]] <- .b5$v; .r6} != 0)) {
      return(error_setInpError(211, tok$v[[7]]))
    }
    n <- 7
  } else {
    i <- project_findObject(7, tok$v[[6]])
    if (i < 0) {
      return(error_setInpError(209, tok$v[[6]]))
    }
    x$v[[4]] <- i
    n <- 6
  }
  if (ntoks > n) {
    i <- findmatch(tok$v[[n + 1]], NoYesWords)
    if (i < 0) {
      return(error_setInpError(205, tok$v[[n + 1]]))
    }
    x$v[[5]] <- i
  }
  {.e7 <- Link[[j + 1]]; .e7$ID <- id}
  link_setParams(j, 4, n1, n2, k, x)
  return(0)
}

# link.c:2608
outlet_getInflow <- function(j) {
  j
  .G_Link <- Link; .G_Node <- Node; .G_RouteModel <- RouteModel
  head <- 0
  h1 <- 0
  h2 <- 0
  n1 <- (.G_Link[[j + 1]])$node1
  n2 <- (.G_Link[[j + 1]])$node2
  k <- (.G_Link[[j + 1]])$subIndex
  if (.G_RouteModel == 4) {
    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n2 + 1]])$newDepth + (.G_Node[[n2 + 1]])$invertElev
  } else {
    h1 <- (.G_Node[[n1 + 1]])$newDepth + (.G_Node[[n1 + 1]])$invertElev
    h2 <- (.G_Node[[n1 + 1]])$invertElev
  }
  dir <- if (!is.na(.c <- (h1 >= h2)) && .c) 1 else (-1)
  y1 <- (.G_Node[[n1 + 1]])$newDepth
  if (!is.na(.c <- (dir < 0)) && .c) {
    y1 <- h1
    h1 <- h2
    h2 <- y1
    y1 <- (.G_Node[[n2 + 1]])$newDepth
  }
  hcrest <- (.G_Node[[n1 + 1]])$invertElev + (.G_Link[[j + 1]])$offset1
  if (((Outlet[[k + 1]])$curveType == 1) && (.G_RouteModel == 4)) {
    head <- h1 - (if (!is.na(.c <- (h2 >= hcrest)) && .c) h2 else hcrest)
  } else {
    head <- h1 - hcrest
  }
  if (((!is.na(.c <- (head <= 0.0001)) && .c) || (!is.na(.c <- (y1 <= 0.0001)) && .c)) || (link_setFlapGate(j, n1, n2, dir) != 0)) {
    {.e1 <- .G_Link[[j + 1]]; .e1$newDepth <- 0}
    {.e2 <- .G_Link[[j + 1]]; .e2$flowClass <- 0}
    return(0)
  }
  {.e3 <- .G_Link[[j + 1]]; .e3$newDepth <- head}
  {.e4 <- .G_Link[[j + 1]]; .e4$flowClass <- 3}
  return((dir * ((.G_Link[[j + 1]])$setting)) * (outlet_getFlow(k, head)))
}

# link.c:2672
outlet_getFlow <- function(k, head) {
  k; head
  .G_Outlet <- Outlet
  h <- head * (UCF(3))
  m <- (.G_Outlet[[k + 1]])$qCurve
  if (m >= 0) {
    return(table_lookup(Curve[[m + 1]], h) / (UCF(10)))
  } else {
    return(((.G_Outlet[[k + 1]])$qCoeff * (rt_pow(h, (.G_Outlet[[k + 1]])$qExpon))) / (UCF(10)))
  }
}

