  .G_FlowTotals$iiInflow <- 0
  .G_FlowTotals$exInflow <- 0
  .G_FlowTotals$flooding <- 0
  .G_FlowTotals$outflow <- 0
  .G_FlowTotals$evapLoss <- 0
  .G_FlowTotals$seepLoss <- 0
  .G_FlowTotals$reacted <- 0
  .G_FlowTotals$initStorage <- 0
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
