    j <- j + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    .G_FlowTotals$initStorage <- .G_FlowTotals$initStorage + ((.G_Link[[j + 1]])$newVolume)
    j <- j + 1
  }
  C_TRoutingTotals(StepFlowTotals, .G_FlowTotals)
  LoadingTotals <<- NULL
  QualTotals <<- NULL
  StepQualTotals <<- NULL
  NodeInflow <<- NULL
  NodeOutflow <<- NULL
  n <- .G_Nobjects$v[[5]]
  if (n > 0) {
    LoadingTotals <<- rt_recs(rt_u64(n), T_TLoadingTotals)
    if (is.null(LoadingTotals)) {
      report_writeErrorMsg(101, .L0)
      return(ErrorCode)
    }
    j <- 0
    while (j < n) {
      {.e1 <- LoadingTotals[[j + 1]]; .e1$initLoad <- massbal_getBuildup(j)}
      {.e2 <- LoadingTotals[[j + 1]]; .e2$buildup <- 0}
      {.e3 <- LoadingTotals[[j + 1]]; .e3$deposition <- 0}
      {.e4 <- LoadingTotals[[j + 1]]; .e4$sweeping <- 0}
      {.e5 <- LoadingTotals[[j + 1]]; .e5$infil <- 0}
      {.e6 <- LoadingTotals[[j + 1]]; .e6$bmpRemoval <- 0}
      {.e7 <- LoadingTotals[[j + 1]]; .e7$runoff <- 0}
      {.e8 <- LoadingTotals[[j + 1]]; .e8$finalLoad <- 0}
      j <- j + 1
    }
  }
  if (n > 0) {
    QualTotals <<- rt_recs(rt_u64(n), T_TRoutingTotals)
    StepQualTotals <<- rt_recs(rt_u64(n), T_TRoutingTotals)
    if ((is.null(QualTotals)) || (is.null(StepQualTotals))) {
      report_writeErrorMsg(101, .L0)
      return(ErrorCode)
    }
  }
  j <- 0
  while (j < n) {
    {.e9 <- QualTotals[[j + 1]]; .e9$dwInflow <- 0}
    {.e10 <- QualTotals[[j + 1]]; .e10$wwInflow <- 0}
    {.e11 <- QualTotals[[j + 1]]; .e11$gwInflow <- 0}
    {.e12 <- QualTotals[[j + 1]]; .e12$exInflow <- 0}
    {.e13 <- QualTotals[[j + 1]]; .e13$flooding <- 0}
    {.e14 <- QualTotals[[j + 1]]; .e14$outflow <- 0}
    {.e15 <- QualTotals[[j + 1]]; .e15$evapLoss <- 0}
    {.e16 <- QualTotals[[j + 1]]; .e16$seepLoss <- 0}
    {.e17 <- QualTotals[[j + 1]]; .e17$reacted <- 0}
    {.e18 <- QualTotals[[j + 1]]; .e18$initStorage <- massbal_getStoredMass(j)}
    j <- j + 1
  }
  massbal_initTimeStepTotals()
  if (.G_Nobjects$v[[3]] > 0) {
    NodeInflow <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
    if (is.null(NodeInflow)) {
      report_writeErrorMsg(101, .L0)
      return(ErrorCode)
