# massbal.c:262
massbal_report <- function() {
  .G_IgnoreQuality <- IgnoreQuality; .G_MAX_FLOW_BALANCE_ERR <- MAX_FLOW_BALANCE_ERR; .G_MAX_RUNOFF_BALANCE_ERR <- MAX_RUNOFF_BALANCE_ERR; .G_Nobjects <- Nobjects; .G_RptFlags <- RptFlags; .G_Subcatch <- Subcatch
  j <- 0
  gwArea <- 0
  if (.G_Nobjects$v[[2]] > 0) {
    if ((!is.na(.c <- (massbal_getRunoffError() > .G_MAX_RUNOFF_BALANCE_ERR)) && .c) || (.G_RptFlags$continuity == 1)) {
      report_writeRunoffError(RunoffTotals, TotalArea)
    }
    if ((.G_Nobjects$v[[5]] > 0) && (!(.G_IgnoreQuality != 0))) {
      if ((!is.na(.c <- (massbal_getLoadingError() > .G_MAX_RUNOFF_BALANCE_ERR)) && .c) || (.G_RptFlags$continuity == 1)) {
        report_writeLoadingError(LoadingTotals)
      }
    }
  }
  if ((.G_Nobjects$v[[12]] > 0) && (!(IgnoreGwater != 0))) {
    if ((!is.na(.c <- (massbal_getGwaterError() > .G_MAX_RUNOFF_BALANCE_ERR)) && .c) || (.G_RptFlags$continuity == 1)) {
      j <- 0
      while (j < .G_Nobjects$v[[2]]) {
        if (!is.null((.G_Subcatch[[j + 1]])$groundwater)) {
          gwArea <- gwArea + ((.G_Subcatch[[j + 1]])$area)
        }
        j <- j + 1
      }
      if (!is.na(.c <- (gwArea > 0)) && .c) {
        report_writeGwaterError(GwaterTotals, gwArea)
      }
    }
  }
  if ((.G_Nobjects$v[[3]] > 0) && (!(IgnoreRouting != 0))) {
    if ((!is.na(.c <- (massbal_getFlowError() > .G_MAX_FLOW_BALANCE_ERR)) && .c) || (.G_RptFlags$continuity == 1)) {
      report_writeFlowError(FlowTotals)
    }
    if ((.G_Nobjects$v[[5]] > 0) && (!(.G_IgnoreQuality != 0))) {
      if ((!is.na(.c <- (massbal_getQualError() > .G_MAX_FLOW_BALANCE_ERR)) && .c) || (.G_RptFlags$continuity == 1)) {
        report_writeQualError(QualTotals)
      }
    }
  }
}

# massbal.c:316
massbal_getBuildup <- function(p) {
  p
  .G_Nobjects <- Nobjects; .G_Pollut <- Pollut; .G_Subcatch <- Subcatch
  i <- 0
  load <- 0
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    i <- 0
    while (i < .G_Nobjects$v[[6]]) {
      load <- load + (((((.G_Subcatch[[j + 1]])$landFactor)[[i + 1]])$buildup)$v[[p + 1]])
      i <- i + 1
    }
    load <- load + (((.G_Subcatch[[j + 1]])$pondedQual)$v[[p + 1]] * ((.G_Pollut[[p + 1]])$mcf))
    j <- j + 1
  }
  return(load)
}

# massbal.c:339
massbal_updateRunoffTotals <- function(flowType, v) {
  flowType; v
  .G_RunoffTotals <- RunoffTotals
  if (flowType == 0) {
    .G_RunoffTotals$rainfall <- .G_RunoffTotals$rainfall + v
  } else if (flowType == 1) {
    .G_RunoffTotals$evap <- .G_RunoffTotals$evap + v
  } else if (flowType == 2) {
    .G_RunoffTotals$infil <- .G_RunoffTotals$infil + v
  } else if (flowType == 3) {
    .G_RunoffTotals$runoff <- .G_RunoffTotals$runoff + v
  } else if (flowType == 4) {
    .G_RunoffTotals$drains <- .G_RunoffTotals$drains + v
  } else if (flowType == 5) {
    .G_RunoffTotals$runon <- .G_RunoffTotals$runon + v
  }
}

# massbal.c:360
massbal_updateGwaterTotals <- function(vInfil, vUpperEvap, vLowerEvap, vLowerPerc, vGwater) {
  vInfil; vUpperEvap; vLowerEvap; vLowerPerc; vGwater
  .G_GwaterTotals <- GwaterTotals
  .G_GwaterTotals$infil <- .G_GwaterTotals$infil + vInfil
  .G_GwaterTotals$upperEvap <- .G_GwaterTotals$upperEvap + vUpperEvap
  .G_GwaterTotals$lowerEvap <- .G_GwaterTotals$lowerEvap + vLowerEvap
  .G_GwaterTotals$lowerPerc <- .G_GwaterTotals$lowerPerc + vLowerPerc
  .G_GwaterTotals$gwater <- .G_GwaterTotals$gwater + vGwater
}

# massbal.c:381
massbal_initTimeStepTotals <- function() {
  .G_Nobjects <- Nobjects; .G_StepFlowTotals <- StepFlowTotals; .G_StepQualTotals <- StepQualTotals
  C_TRoutingTotals(OldStepFlowTotals, .G_StepFlowTotals)
  .G_StepFlowTotals$dwInflow <- 0
  .G_StepFlowTotals$wwInflow <- 0
  .G_StepFlowTotals$gwInflow <- 0
  .G_StepFlowTotals$iiInflow <- 0
  .G_StepFlowTotals$exInflow <- 0
  .G_StepFlowTotals$flooding <- 0
