    {.e2 <- .G_QualTotals[[j + 1]]; .e2$wwInflow <- (.G_QualTotals[[j + 1]])$wwInflow + ((.G_StepQualTotals[[j + 1]])$wwInflow * tStep)}
    {.e3 <- .G_QualTotals[[j + 1]]; .e3$gwInflow <- (.G_QualTotals[[j + 1]])$gwInflow + ((.G_StepQualTotals[[j + 1]])$gwInflow * tStep)}
    {.e4 <- .G_QualTotals[[j + 1]]; .e4$iiInflow <- (.G_QualTotals[[j + 1]])$iiInflow + ((.G_StepQualTotals[[j + 1]])$iiInflow * tStep)}
    {.e5 <- .G_QualTotals[[j + 1]]; .e5$exInflow <- (.G_QualTotals[[j + 1]])$exInflow + ((.G_StepQualTotals[[j + 1]])$exInflow * tStep)}
