# massbal.c:638
massbal_getStorage <- function(isFinalStorage) {
  isFinalStorage
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_NodeOutflow <- NodeOutflow
  totalStorage <- 0
  nodeStorage <- 0
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    nodeStorage <- (.G_Node[[j + 1]])$newVolume
    if (isFinalStorage != 0) {
      .G_NodeOutflow$v[[j + 1]] <- .G_NodeOutflow$v[[j + 1]] + nodeStorage
    }
    totalStorage <- totalStorage + nodeStorage
    j <- j + 1
  }
  if ((isFinalStorage != 0) && (RouteModel == 1)) {
    return(totalStorage)
  }
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    totalStorage <- totalStorage + ((.G_Link[[j + 1]])$newVolume)
    j <- j + 1
  }
  return(totalStorage)
}

