massbal_getSysFlows <- function(f, sysFlows) {
  f; sysFlows
  .G_OldStepFlowTotals <- OldStepFlowTotals; .G_StepFlowTotals <- StepFlowTotals
  f1 <- 1 - f
  sysFlows$v[[6]] <- ((f1 * .G_OldStepFlowTotals$dwInflow) + (f * .G_StepFlowTotals$dwInflow)) * (UCF(10))
  sysFlows$v[[7]] <- ((f1 * .G_OldStepFlowTotals$gwInflow) + (f * .G_StepFlowTotals$gwInflow)) * (UCF(10))
  sysFlows$v[[8]] <- ((f1 * .G_OldStepFlowTotals$iiInflow) + (f * .G_StepFlowTotals$iiInflow)) * (UCF(10))
  sysFlows$v[[9]] <- ((f1 * .G_OldStepFlowTotals$exInflow) + (f * .G_StepFlowTotals$exInflow)) * (UCF(10))
  sysFlows$v[[11]] <- ((f1 * .G_OldStepFlowTotals$flooding) + (f * .G_StepFlowTotals$flooding)) * (UCF(10))
  sysFlows$v[[12]] <- ((f1 * .G_OldStepFlowTotals$outflow) + (f * .G_StepFlowTotals$outflow)) * (UCF(10))
  sysFlows$v[[13]] <- ((f1 * .G_OldStepFlowTotals$finalStorage) + (f * .G_StepFlowTotals$finalStorage)) * (UCF(5))
}

