massbal_getRunoffError <- function() {
  .G_Nobjects <- Nobjects; .G_RunoffTotals <- RunoffTotals
  .G_RunoffTotals$finalStorage <- 0
  .G_RunoffTotals$finalSnowCover <- 0
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    .G_RunoffTotals$finalStorage <- .G_RunoffTotals$finalStorage + (subcatch_getStorage(j))
    .G_RunoffTotals$finalSnowCover <- .G_RunoffTotals$finalSnowCover + (snow_getSnowCover(j))
    j <- j + 1
  }
  .G_RunoffTotals$snowRemoved <- Snow$removed
  totalInflow <- ((.G_RunoffTotals$rainfall + .G_RunoffTotals$runon) + .G_RunoffTotals$initStorage) + .G_RunoffTotals$initSnowCover
  totalOutflow <- (((((.G_RunoffTotals$evap + .G_RunoffTotals$infil) + .G_RunoffTotals$runoff) + .G_RunoffTotals$drains) + .G_RunoffTotals$snowRemoved) + .G_RunoffTotals$finalStorage) + .G_RunoffTotals$finalSnowCover
  .G_RunoffTotals$pctError <- 0
  if (!is.na(.c <- (abs(totalInflow - totalOutflow) < 1)) && .c) {
    .G_RunoffTotals$pctError <- 1e-06
  } else if (!is.na(.c <- (totalInflow > 0)) && .c) {
    .G_RunoffTotals$pctError <- 100 * (1 - (totalOutflow / totalInflow))
  } else if (!is.na(.c <- (totalOutflow > 0)) && .c) {
    .G_RunoffTotals$pctError <- 100 * ((totalInflow / totalOutflow) - 1)
  }
  RunoffError <<- .G_RunoffTotals$pctError
  return(.G_RunoffTotals$pctError)
}

