sametext <- function(s1, s2) {
  s1; s2
  i <- 0
  while (rt_toupper(rt_cget(s1, i)) == rt_toupper(rt_cget(s2, i))) {
    if ((!(rt_cget(s1, (i + 1)) != 0)) && (!(rt_cget(s2, (i + 1)) != 0))) {
      return(1)
    }
    i <- i + 1
  }
  return(0)
}

