  while ((Pos <= .G_Len) && ((isLetter(rt_cget(.G_S, Pos)) != 0) || (isDigit(rt_cget(.G_S, Pos)) != 0))) {
    rt_cset(c_, 0, rt_cget(.G_S, Pos))
    rt_strcat(.G_Token, c_)
    Pos <<- Pos + 1
  }
  Pos <<- Pos - 1
}

