# mathexpr.c:252
getOperand <- function() {
  .G_CurLex <- CurLex; .G_S <- S
  code <- 0
  .sw1 <- rt_cget(.G_S, Pos)
  if (.sw1 == 40) {
    code <- 1
  } else if (.sw1 == 41) {
    code <- 2
  } else if (.sw1 == 43) {
    code <- 3
  } else if (.sw1 == 45) {
    code <- 4
    if (((Pos < (Len - 1)) && (isDigit(rt_cget(.G_S, (Pos + 1))) != 0)) && ((.G_CurLex <= 6) || (.G_CurLex == 31))) {
      Pos <<- Pos + 1
      Fvalue <<- -(getNumber())
      code <- 7
    }
  } else if (.sw1 == 42) {
    code <- 5
  } else if (.sw1 == 47) {
    code <- 6
  } else if (.sw1 == 94) {
    code <- 31
  } else {
