# mathexpr.c:280
getLex <- function() {
  .G_Len <- Len; .G_S <- S
  while ((Pos < .G_Len) && (rt_cget(.G_S, Pos) == 32)) {
    Pos <<- Pos + 1
  }
  if (Pos >= .G_Len) {
    return(0)
  }
  n <- getOperand()
  if (n == 0) {
    if (isLetter(rt_cget(.G_S, Pos)) != 0) {
      getToken()
      n <- getMathFunc()
      if (n == 0) {
        n <- getVariable()
      }
    } else if ((rt_cget(.G_S, Pos) == 46) || (isDigit(rt_cget(.G_S, Pos)) != 0)) {
      n <- 7
      Fvalue <<- getNumber()
    }
  }
