  PrevLex <<- CurLex
  CurLex <<- n
  return(n)
}

# mathexpr.c:314
newNode <- function() {
  node <- T_ExprTree()
  if (!(!is.null(node))) {
    Err <<- 2
  } else {
    node$opcode <- 0
    node$ivar <- -1
    node$fvalue <- 0
    node$left <- NULL
    node$right <- NULL
  }
  return(node)
}

# mathexpr.c:332
getSingleOp <- function(lex) {
  lex
  opcode <- 0
  left <- NULL
  node <- NULL
  if (lex$v == 1) {
    Bc <<- Bc + 1
    left <- getTree()
  } else {
    if (((lex$v < 7) || (lex$v == 9)) || (lex$v > 30)) {
      Err <<- 1
      return(NULL)
    }
    opcode <- lex$v
    if ((lex$v == 7) || (lex$v == 8)) {
      left <- newNode()
      left$opcode <- opcode
      if (lex$v == 7) {
        left$fvalue <- Fvalue
      }
      if (lex$v == 8) {
        left$ivar <- Ivar
      }
    } else {
      lex$v <- getLex()
      if (lex$v != 1) {
        Err <<- 1
        return(NULL)
      }
      Bc <<- Bc + 1
      left <- newNode()
      left$left <- getTree()
      left$opcode <- opcode
    }
  }
  lex$v <- getLex()
  if (lex$v == 31) {
    node <- newNode()
    node$left <- left
    node$opcode <- lex$v
    lex$v <- getLex()
    node$right <- getSingleOp(lex)
    left <- node
  }
  return(left)
}

# mathexpr.c:397
getOp <- function(lex) {
  lex
  opcode <- 0
  right <- NULL
  node <- NULL
  neg <- 0
  lex$v <- getLex()
  if ((PrevLex == 0) || (PrevLex == 1)) {
    if (lex$v == 4) {
      neg <- 1
      lex$v <- getLex()
    } else if (lex$v == 3) {
      lex$v <- getLex()
    }
  }
  left <- getSingleOp(lex)
  while ((lex$v == 5) || (lex$v == 6)) {
    opcode <- lex$v
    lex$v <- getLex()
    right <- getSingleOp(lex)
    node <- newNode()
    if (Err != 0) {
      return(NULL)
    }
    node$left <- left
    node$right <- right
    node$opcode <- opcode
    left <- node
  }
  if (neg != 0) {
    node <- newNode()
    if (Err != 0) {
      return(NULL)
    }
    node$left <- left
    node$right <- NULL
    node$opcode <- 9
    left <- node
  }
  return(left)
}

# mathexpr.c:442
getTree <- function() {
  lex <- 0
  opcode <- 0
  right <- NULL
  node <- NULL
  left <- {.b1 <- rt_box(lex); .r2 <- getOp(.b1); lex <- .b1$v; .r2}
  while (TRUE) {
    if ((lex == 0) || (lex == 2)) {
      if (lex == 2) {
        Bc <<- Bc - 1
      }
      break
    }
    if ((lex != 3) && (lex != 4)) {
      Err <<- 1
      break
    }
    opcode <- lex
    right <- {.b3 <- rt_box(lex); .r4 <- getOp(.b3); lex <- .b3$v; .r4}
    node <- newNode()
    if (Err != 0) {
      break
    }
    node$left <- left
    node$right <- right
    node$opcode <- opcode
    left <- node
  }
  return(left)
}

# mathexpr.c:479
traverseTree <- function(tree, expr) {
  tree; expr
  if (is.null(tree)) {
    return(invisible(NULL))
  }
  traverseTree(tree$left, expr)
  traverseTree(tree$right, expr)
  node <- T_MathExpr()
  if (!is.null(node)) {
    node$fvalue <- tree$fvalue
    node$opcode <- tree$opcode
    node$ivar <- tree$ivar
    node$next_ <- NULL
    node$prev <- expr$v
  }
  if (!is.null(expr$v)) {
    {.e1 <- expr$v; .e1$next_ <- node}
  }
  expr$v <- node
}

# mathexpr.c:501
deleteTree <- function(tree) {
  tree
  if (!is.null(tree)) {
    if (!is.null(tree$left)) {
      deleteTree(tree$left)
    }
    if (!is.null(tree$right)) {
      deleteTree(tree$right)
    }
    NULL
  }
}

