# mathexpr.c:743
mathexpr_create <- function(formula, getVar) {
  formula; getVar
  expr <- NULL
  result <- NULL
  mathexpr_getVariableIndex <<- getVar
  Err <<- 0
  PrevLex <<- 0
  CurLex <<- 0
  S <<- formula
  Len <<- rt_i32(rt_strlen(S))
  Pos <<- 0
  Bc <<- 0
  tree <- getTree()
  if ((Bc == 0) && (Err == 0)) {
    {.BX_mathexpr_create_expr$v <- expr; .r1 <- traverseTree(tree, .BX_mathexpr_create_expr); expr <- .BX_mathexpr_create_expr$v; .r1}
    while (!is.null(expr)) {
      result <- expr
      expr <- expr$prev
    }
  }
  deleteTree(tree)
  return(result)
}

