# node.c:200
node_validate <- function(j) {
  j
  .G_Node <- Node
  if ((!is.na(.c <- ((.G_Node[[j + 1]])$fullDepth > (.G_Node[[j + 1]])$oldDepth)) && .c) && (!is.na(.c <- ((.G_Node[[j + 1]])$oldDepth > 0)) && .c)) {
    report_writeWarningMsg(.L317, (.G_Node[[j + 1]])$ID)
  }
  if (!is.na(.c <- ((.G_Node[[j + 1]])$initDepth > ((.G_Node[[j + 1]])$fullDepth + (.G_Node[[j + 1]])$surDepth))) && .c) {
    report_writeErrorMsg(138, (.G_Node[[j + 1]])$ID)
  }
  if ((.G_Node[[j + 1]])$type == 2) {
    if (!is.na(.c <- (node_getVolume(j, (.G_Node[[j + 1]])$fullDepth) < 0)) && .c) {
      report_writeErrorMsg(140, (.G_Node[[j + 1]])$ID)
    }
  }
  if ((.G_Node[[j + 1]])$type == 3) {
    divider_validate(j)
  }
  inflow <- (.G_Node[[j + 1]])$dwfInflow
  while (!is.null(inflow)) {
    inflow_initDwfInflow(inflow)
    inflow <- inflow$next_
  }
}

