node_getSystemOutflow <- function(j, isFlooded) {
  j; isFlooded
  .G_Node <- Node
  outflow <- 0
  isFlooded$v <- 0
  if ((.G_Node[[j + 1]])$type == 1) {
    if (!is.na(.c <- ((.G_Node[[j + 1]])$outflow == 0)) && .c) {
      outflow <- (.G_Node[[j + 1]])$inflow
    } else {
      if (!is.na(.c <- ((.G_Node[[j + 1]])$inflow == 0)) && .c) {
        outflow <- -((.G_Node[[j + 1]])$outflow)
        {.e1 <- .G_Node[[j + 1]]; .e1$inflow <- abs(outflow)}
      }
    }
    {.e2 <- .G_Node[[j + 1]]; .e2$overflow <- 0}
    {.e3 <- .G_Node[[j + 1]]; .e3$newVolume <- 0}
  } else if (((RouteModel != 4) && ((.G_Node[[j + 1]])$degree == 0)) && ((.G_Node[[j + 1]])$type != 2)) {
    if (!is.na(.c <- ((.G_Node[[j + 1]])$outflow == 0)) && .c) {
      outflow <- (.G_Node[[j + 1]])$inflow
    }
    {.e4 <- .G_Node[[j + 1]]; .e4$overflow <- 0}
    {.e5 <- .G_Node[[j + 1]]; .e5$newVolume <- 0}
  } else {
    if (!is.na(.c <- ((.G_Node[[j + 1]])$newVolume <= (.G_Node[[j + 1]])$fullVolume)) && .c) {
