    }
  }
  return(outflow)
}

# node.c:497
node_getResults <- function(j, f, x) {
  j; f; x
  .G_Nobjects <- Nobjects; .G_Node <- Node
  p <- 0
  f1 <- 1 - f
  z <- ((f1 * ((.G_Node[[j + 1]])$oldDepth)) + (f * ((.G_Node[[j + 1]])$newDepth))) * (UCF(3))
  x$v[[1]] <- rt_f32(z)
  z <- (.G_Node[[j + 1]])$invertElev * (UCF(3))
  x$v[[2]] <- rt_f32(x$v[[1]] + rt_f32(z))
  z <- ((f1 * ((.G_Node[[j + 1]])$oldVolume)) + (f * ((.G_Node[[j + 1]])$newVolume))) * (UCF(5))
  x$v[[3]] <- rt_f32(z)
  z <- ((f1 * ((.G_Node[[j + 1]])$oldLatFlow)) + (f * ((.G_Node[[j + 1]])$newLatFlow))) * (UCF(10))
  x$v[[4]] <- rt_f32(z)
  z <- ((f1 * ((.G_Node[[j + 1]])$oldFlowInflow)) + (f * ((.G_Node[[j + 1]])$inflow))) * (UCF(10))
  x$v[[5]] <- rt_f32(z)
  z <- (.G_Node[[j + 1]])$overflow * (UCF(10))
  x$v[[6]] <- rt_f32(z)
  if (!(IgnoreQuality != 0)) {
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      z <- (f1 * (((.G_Node[[j + 1]])$oldQual)$v[[p + 1]])) + (f * (((.G_Node[[j + 1]])$newQual)$v[[p + 1]]))
      x$v[[(6 + p) + 1]] <- rt_f32(z)
      p <- p + 1
    }
  }
}

