# node.c:606
junc_readParams <- function(j, k, tok, ntoks) {
  j; k; tok; ntoks
  x <- rt_ra(numeric(6))
  if (ntoks < 2) {
    return(error_setInpError(203, .L0))
  }
  id <- project_findID(2, tok$v[[1]])
  if (is.null(id)) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  i <- 1
  while (i <= 5) {
    x$v[[i]] <- 0
    if (i < ntoks) {
      if (!({.b1 <- rt_box(x$v[[i]]); .r2 <- getDouble(tok$v[[i + 1]], .b1); x$v[[i]] <- .b1$v; .r2} != 0)) {
        return(error_setInpError(211, tok$v[[i + 1]]))
      }
    }
    i <- i + 1
  }
  i <- 1
  while (i <= 4) {
    if (!is.na(.c <- (x$v[[i + 1]] < 0)) && .c) {
      return(error_setInpError(211, tok$v[[(i + 1) + 1]]))
    }
    i <- i + 1
  }
  {.e3 <- Node[[j + 1]]; .e3$ID <- id}
  node_setParams(j, 0, k, x)
  return(0)
}

# node.c:654
storage_readParams <- function(j, k, tok, ntoks) {
  j; k; tok; ntoks
  n <- 0
  x <- rt_ra(numeric(10))
  y <- rt_ra(numeric(3))
  A <- 0
  B <- 0
  L <- 0
  W <- 0
  Z <- 0
  if (ntoks < 6) {
    return(error_setInpError(203, .L0))
  }
  id <- project_findID(2, tok$v[[1]])
  if (is.null(id)) {
    return(error_setInpError(209, tok$v[[1]]))
  }
  i <- 1
  while (i <= 3) {
    if (!({.b1 <- rt_box(x$v[[i]]); .r2 <- getDouble(tok$v[[i + 1]], .b1); x$v[[i]] <- .b1$v; .r2} != 0)) {
      return(error_setInpError(211, tok$v[[i + 1]]))
    }
    i <- i + 1
  }
  m <- findmatch(tok$v[[5]], RelationWords)
  if (m < 0) {
    return(error_setInpError(205, tok$v[[5]]))
  }
  x$v[[4]] <- m
  x$v[[5]] <- 0
  x$v[[6]] <- 0
  x$v[[7]] <- 0
  x$v[[8]] <- -1
  x$v[[9]] <- 0
  x$v[[10]] <- 0
  if (m == 0) {
    i <- project_findObject(7, tok$v[[6]])
    if (i < 0) {
      return(error_setInpError(209, tok$v[[6]]))
    }
    x$v[[8]] <- i
    n <- 6
  } else {
    if (ntoks < 8) {
      return(error_setInpError(203, .L0))
    }
    i <- 5
    while (i <= 7) {
      if (!({.b3 <- rt_box(y$v[[(i - 5) + 1]]); .r4 <- getDouble(tok$v[[i + 1]], .b3); y$v[[(i - 5) + 1]] <- .b3$v; .r4} != 0)) {
        return(error_setInpError(211, tok$v[[i + 1]]))
      }
      i <- i + 1
    }
    n <- 8
  }
  if (m == 1) {
    if (!is.na(.c <- (y$v[[3]] < 0)) && .c) {
      return(error_setInpError(211, tok$v[[8]]))
    }
  } else if (m == 2 || m == 3 || m == 4 || m == 5) {
    if (!is.na(.c <- (y$v[[1]] <= 0)) && .c) {
      return(error_setInpError(211, tok$v[[6]]))
    }
    if (!is.na(.c <- (y$v[[2]] <= 0)) && .c) {
      return(error_setInpError(211, tok$v[[7]]))
    }
    if (!is.na(.c <- (y$v[[3]] < 0)) && .c) {
      return(error_setInpError(211, tok$v[[8]]))
    }
  }
  if ((m == 4) && (!is.na(.c <- (y$v[[3]] == 0)) && .c)) {
    return(error_setInpError(211, tok$v[[8]]))
  }
  if (m == 1) {
    x$v[[5]] <- y$v[[1]]
    x$v[[6]] <- y$v[[2]]
    x$v[[7]] <- y$v[[3]]
  } else if (m == 2) {
    A <- y$v[[1]] / 2
    B <- y$v[[2]] / 2
    x$v[[5]] <- 0
    x$v[[6]] <- 0
    x$v[[7]] <- (3.141592654 * A) * B
  } else if (m == 3) {
    A <- y$v[[1]] / 2
    B <- y$v[[2]] / 2
    Z <- y$v[[3]]
    x$v[[5]] <- ((2 * 3.141592654) * B) * Z
    x$v[[6]] <- (((3.141592654 * B) / A) * Z) * Z
    x$v[[7]] <- (3.141592654 * A) * B
  } else if (m == 4) {
    A <- y$v[[1]] / 2
    B <- y$v[[2]] / 2
    Z <- y$v[[3]]
    x$v[[5]] <- ((3.141592654 * A) * B) / Z
    x$v[[6]] <- 0
    x$v[[7]] <- 0
  } else if (m == 5) {
    L <- y$v[[1]]
    W <- y$v[[2]]
    Z <- y$v[[3]]
    x$v[[5]] <- (2 * (L + W)) * Z
    x$v[[6]] <- (4 * Z) * Z
    x$v[[7]] <- L * W
  }
  if (ntoks > n) {
    if (!({.b5 <- rt_box(x$v[[9]]); .r6 <- getDouble(tok$v[[n + 1]], .b5); x$v[[9]] <- .b5$v; .r6} != 0)) {
      return(error_setInpError(211, tok$v[[n + 1]]))
    }
    n <- n + 1
  }
  if (ntoks > n) {
    if (!({.b7 <- rt_box(x$v[[10]]); .r8 <- getDouble(tok$v[[n + 1]], .b7); x$v[[10]] <- .b7$v; .r8} != 0)) {
      return(error_setInpError(211, tok$v[[n + 1]]))
    }
    n <- n + 1
  }
  {.e9 <- Node[[j + 1]]; .e9$ID <- id}
  node_setParams(j, 2, k, x)
  if (ntoks > n) {
    return(exfil_readStorageParams(k, tok, ntoks, n))
  }
  return(0)
}

# node.c:813
storage_getDepth <- function(j, v) {
  j; v
  .G_Node <- Node; .G_Storage <- Storage
  k <- (.G_Node[[j + 1]])$subIndex
  i <- (.G_Storage[[k + 1]])$aCurve
  shape <- (.G_Storage[[k + 1]])$shape
  a0 <- (.G_Storage[[k + 1]])$a0
  a1 <- (.G_Storage[[k + 1]])$a1
  a2 <- (.G_Storage[[k + 1]])$a2
  d <- 0
  e <- 0
  storageVol <- T_TStorageVol()
  if ((!is.na(.c <- ((.G_Node[[j + 1]])$fullVolume > 0)) && .c) && (!is.na(.c <- (v >= (.G_Node[[j + 1]])$fullVolume)) && .c)) {
    return((.G_Node[[j + 1]])$fullDepth)
  }
  if (!is.na(.c <- (v == 0)) && .c) {
    return(0)
  }
  v <- v * (UCF(5))
  storageVol$k <- k
  storageVol$v <- v
  if (shape == 0) {
    i <- (.G_Storage[[k + 1]])$aCurve
    if (i >= 0) {
      d <- table_getStorageDepth(Curve[[i + 1]], v)
    } else {
      d <- 0
    }
  } else if (shape == 2) {
    d <- v / a0
  } else if (shape == 4) {
    d <- sqrt((2 * v) / a1)
  } else if (shape == 1) {
    if (!is.na(.c <- (a2 == 0)) && .c) {
      d <- v / (a0 + a1)
    } else if (!is.na(.c <- (a0 == 0)) && .c) {
      e <- 1 / (a2 + 1)
      d <- rt_pow(v / (a1 * e), e)
    } else if ((!is.na(.c <- (a2 == 1)) && .c) && (!is.na(.c <- (a1 > 0)) && .c)) {
      d <- (sqrt((a0 * a0) + ((2 * a1) * v)) - a0) / a1
    } else {
      d <- v / (a0 + a1)
      {.BX_storage_getDepth_d$v <- d; .r1 <- findroot_Newton(0, ((.G_Node[[j + 1]])$fullDepth * (UCF(3))), .BX_storage_getDepth_d, 0.001, storage_getVolDiff, storageVol); d <- .BX_storage_getDepth_d$v; .r1}
    }
  } else if (shape == 3 || shape == 5) {
    d <- v / a0
    {.BX_storage_getDepth_d$v <- d; .r2 <- findroot_Newton(0, ((.G_Node[[j + 1]])$fullDepth * (UCF(3))), .BX_storage_getDepth_d, 0.001, storage_getVolDiff, storageVol); d <- .BX_storage_getDepth_d$v; .r2}
  } else {
    d <- 0
  }
  d <- d / (UCF(3))
  if (!is.na(.c <- (d > (.G_Node[[j + 1]])$fullDepth)) && .c) {
    d <- (.G_Node[[j + 1]])$fullDepth
  }
  return(d)
}

