}

# node.c:930
storage_getVolume <- function(j, d) {
  j; d
  .G_Node <- Node; .G_Storage <- Storage
  k <- (.G_Node[[j + 1]])$subIndex
  i <- 0
  n <- 0
  v <- 0
  if (!is.na(.c <- (d == 0)) && .c) {
    return(0)
  }
  if ((!is.na(.c <- (d >= (.G_Node[[j + 1]])$fullDepth)) && .c) && (!is.na(.c <- ((.G_Node[[j + 1]])$fullVolume > 0)) && .c)) {
    return((.G_Node[[j + 1]])$fullVolume)
  }
  .sw1 <- (.G_Storage[[k + 1]])$shape
  if (.sw1 == 0) {
    i <- (.G_Storage[[k + 1]])$aCurve
    if (i >= 0) {
      return(table_getStorageVolume(Curve[[i + 1]], (d * (UCF(3)))) / (UCF(5)))
    } else {
      return(0)
    }
  } else if (.sw1 == 1) {
    d <- d * (UCF(3))
    n <- (.G_Storage[[k + 1]])$a2 + 1
    v <- ((.G_Storage[[k + 1]])$a0 * d) + (((.G_Storage[[k + 1]])$a1 / n) * (rt_pow(d, n)))
    return(v / (UCF(5)))
  } else if (.sw1 == 2 || .sw1 == 3 || .sw1 == 4 || .sw1 == 5) {
    d <- d * (UCF(3))
    v <- d * ((.G_Storage[[k + 1]])$a0 + (d * (((.G_Storage[[k + 1]])$a1 / 2) + ((d * ((.G_Storage[[k + 1]])$a2)) / 3))))
    return(v / (UCF(5)))
  } else {
    return(0)
  }
}

# node.c:979
storage_getSurfArea <- function(j, d) {
  j; d
  .G_Storage <- Storage
  area <- 0
  k <- (Node[[j + 1]])$subIndex
  i <- 0
  .sw1 <- (.G_Storage[[k + 1]])$shape
  if (.sw1 == 0) {
    i <- (.G_Storage[[k + 1]])$aCurve
    if (i >= 0) {
      area <- table_lookupEx(Curve[[i + 1]], (d * (UCF(3))))
    }
  } else if (.sw1 == 1) {
    area <- (.G_Storage[[k + 1]])$a0 + ((.G_Storage[[k + 1]])$a1 * (rt_pow(d * (UCF(3)), (.G_Storage[[k + 1]])$a2)))
  } else if (.sw1 == 2 || .sw1 == 3 || .sw1 == 4 || .sw1 == 5) {
    d <- d * (UCF(3))
    area <- (.G_Storage[[k + 1]])$a0 + (d * ((.G_Storage[[k + 1]])$a1 + (d * ((.G_Storage[[k + 1]])$a2))))
  } else {
    return(0)
  }
  return((area / (UCF(3))) / (UCF(3)))
}

# node.c:1022
storage_getOutflow <- function(j, i) {
  j; i
  .G_Link <- Link
  if ((.G_Link[[i + 1]])$type != 0) {
    return(0)
  }
  y <- (Node[[j + 1]])$newDepth - ((.G_Link[[i + 1]])$offset1)
  if (!is.na(.c <- (y <= 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (y >= ((.G_Link[[i + 1]])$xsect)$yFull)) && .c) {
    return((.G_Link[[i + 1]])$qFull)
  }
  k <- (.G_Link[[i + 1]])$subIndex
  a <- xsect_getAofY((.G_Link[[i + 1]])$xsect, y)
  return((Conduit[[k + 1]])$beta * (xsect_getSofA((.G_Link[[i + 1]])$xsect, a)))
}

# node.c:1052
storage_getLosses <- function(j, tStep) {
  j; tStep
  .G_Node <- Node; .G_Storage <- Storage
  depth <- 0
  area <- 0
  evapRate <- 0
  exfilRate <- 0
  totalLoss <- 0
  lossRatio <- 0
  k <- (.G_Node[[j + 1]])$subIndex
  evapRate <- Evap$rate * ((.G_Storage[[k + 1]])$fEvap)
  exfil <- (.G_Storage[[k + 1]])$exfil
  if ((!is.na(.c <- (evapRate > 0)) && .c) || (!is.null(exfil))) {
    depth <- (.G_Node[[j + 1]])$newDepth
    area <- storage_getSurfArea(j, depth)
    if (!is.na(.c <- ((.G_Node[[j + 1]])$newVolume > 0.0001)) && .c) {
      evapRate <- area * evapRate
    }
    if (!is.null(exfil)) {
      exfilRate <- exfil_getLoss(exfil, tStep, depth, area)
    }
    totalLoss <- (evapRate + exfilRate) * tStep
    if (!is.na(.c <- (totalLoss > (.G_Node[[j + 1]])$newVolume)) && .c) {
      lossRatio <- (.G_Node[[j + 1]])$newVolume / totalLoss
      evapRate <- evapRate * lossRatio
      exfilRate <- exfilRate * lossRatio
    }
  }
  {.e1 <- .G_Storage[[(.G_Node[[j + 1]])$subIndex + 1]]; .e1$evapLoss <- evapRate * tStep}
  {.e2 <- .G_Storage[[(.G_Node[[j + 1]])$subIndex + 1]]; .e2$exfilLoss <- exfilRate * tStep}
  return(evapRate + exfilRate)
}

