# node.c:1216
divider_validate <- function(j) {
  j
  .G_Divider <- Divider; .G_Link <- Link; .G_Node <- Node
  k <- (.G_Node[[j + 1]])$subIndex
  i <- (.G_Divider[[k + 1]])$link
  if ((i < 0) || (((.G_Link[[i + 1]])$node1 != j) && ((.G_Link[[i + 1]])$node2 != j))) {
    report_writeErrorMsg(136, (.G_Node[[j + 1]])$ID)
  }
  if ((.G_Divider[[k + 1]])$type == 2) {
    if ((!is.na(.c <- ((.G_Divider[[k + 1]])$dhMax <= 0)) && .c) || (!is.na(.c <- ((.G_Divider[[k + 1]])$cWeir <= 0)) && .c)) {
      report_writeErrorMsg(137, (.G_Node[[j + 1]])$ID)
    } else {
      {.e1 <- .G_Divider[[k + 1]]; .e1$qMax <- ((.G_Divider[[k + 1]])$cWeir * (if ((.p <- (.G_Divider[[k + 1]])$dhMax) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))) / (UCF(10))}
      if (!is.na(.c <- ((.G_Divider[[k + 1]])$qMin > (.G_Divider[[k + 1]])$qMax)) && .c) {
        report_writeErrorMsg(137, (.G_Node[[j + 1]])$ID)
      }
    }
  }
}

# node.c:1251
divider_getOutflow <- function(j, k) {
  j; k
  .G_Divider <- Divider; .G_Node <- Node
  m <- 0
  qOut <- 0
  f <- 0
  qIn <- (.G_Node[[j + 1]])$inflow + (.G_Node[[j + 1]])$overflow
  i <- (.G_Node[[j + 1]])$subIndex
  .sw1 <- (.G_Divider[[i + 1]])$type
  if (.sw1 == 0) {
    if (!is.na(.c <- (qIn <= (.G_Divider[[i + 1]])$qMin)) && .c) {
      qOut <- 0
    } else {
      qOut <- qIn - ((.G_Divider[[i + 1]])$qMin)
    }
  } else if (.sw1 == 3) {
    if (k != (.G_Divider[[i + 1]])$link) {
      qOut <- qIn
    } else {
      qOut <- qIn - ((.G_Node[[j + 1]])$outflow)
    }
    if (!is.na(.c <- (qOut < 1e-05)) && .c) {
      qOut <- 0
    }
    return(qOut)
  } else if (.sw1 == 2) {
    if (!is.na(.c <- (qIn <= (.G_Divider[[i + 1]])$qMin)) && .c) {
      qOut <- 0
    } else {
      f <- (qIn - ((.G_Divider[[i + 1]])$qMin)) / ((.G_Divider[[i + 1]])$qMax - ((.G_Divider[[i + 1]])$qMin))
      if (!is.na(.c <- (f > 1)) && .c) {
        qOut <- (.G_Divider[[i + 1]])$qMax * (sqrt(f))
      } else {
        qOut <- ((.G_Divider[[i + 1]])$cWeir * (if ((.p <- f * ((.G_Divider[[i + 1]])$dhMax)) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))) / (UCF(10))
      }
    }
  } else if (.sw1 == 1) {
    m <- (.G_Divider[[i + 1]])$flowCurve
    if (m >= 0) {
      qOut <- table_lookup(Curve[[m + 1]], (qIn * (UCF(10)))) / (UCF(10))
    } else {
      qOut <- 0
    }
  } else {
    qOut <- 0
  }
  if (!is.na(.c <- (qOut > qIn)) && .c) {
    qOut <- qIn
  }
  if (k != (.G_Divider[[i + 1]])$link) {
    qOut <- qIn - qOut
  }
  return(qOut)
}

