# node.c:1413
outfall_setOutletDepth <- function(j, yNorm, yCrit, z) {
  j; yNorm; yCrit; z
  .G_Curve <- Curve; .G_NewRoutingTime <- NewRoutingTime; .G_Node <- Node; .G_Outfall <- Outfall
  x <- 0
  y <- 0
  yNew <- 0
  stage <- 0
  k <- 0
  i <- (.G_Node[[j + 1]])$subIndex
  currentDate <- 0
  .sw1 <- (.G_Outfall[[i + 1]])$type
  if (.sw1 == 0) {
    if (!is.na(.c <- (z > 0)) && .c) {
      {.e2 <- .G_Node[[j + 1]]; .e2$newDepth <- 0}
    } else {
      {.e3 <- .G_Node[[j + 1]]; .e3$newDepth <- if (!is.na(.c <- (yNorm <= yCrit)) && .c) yNorm else yCrit}
    }
    return(invisible(NULL))
  } else if (.sw1 == 1) {
    if (!is.na(.c <- (z > 0)) && .c) {
      {.e4 <- .G_Node[[j + 1]]; .e4$newDepth <- 0}
    } else {
      {.e5 <- .G_Node[[j + 1]]; .e5$newDepth <- yNorm}
    }
    return(invisible(NULL))
  } else if (.sw1 == 2) {
    stage <- (.G_Outfall[[i + 1]])$fixedStage
  } else if (.sw1 == 3) {
    k <- (.G_Outfall[[i + 1]])$tideCurve
    {.BX_outfall_setOutletDepth_x$v <- x; .BX_outfall_setOutletDepth_y$v <- y; .r6 <- table_getFirstEntry(.G_Curve[[k + 1]], .BX_outfall_setOutletDepth_x, .BX_outfall_setOutletDepth_y); x <- .BX_outfall_setOutletDepth_x$v; y <- .BX_outfall_setOutletDepth_y$v; .r6}
    currentDate <- .G_NewRoutingTime / 86400000
    x <- x + ((currentDate - (floor(currentDate))) * 24)
    stage <- table_lookup(.G_Curve[[k + 1]], x) / (UCF(3))
  } else if (.sw1 == 4) {
    k <- (.G_Outfall[[i + 1]])$stageSeries
    currentDate <- StartDateTime + (.G_NewRoutingTime / 86400000)
    stage <- table_tseriesLookup(Tseries[[k + 1]], currentDate, 1) / (UCF(3))
  } else {
    stage <- (.G_Node[[j + 1]])$invertElev
