project_readInput <- function() {
  createHashTables()
  input_countObjects()
  createObjects()
  input_readData()
  if (ErrorCode != 0) {
    return(invisible(NULL))
  }
  StartDateTime <<- StartDate$v + StartTime$v
  EndDateTime <<- EndDate$v + EndTime$v
  ReportStart <<- ReportStartDate$v + ReportStartTime$v
  ReportStart <<- if (!is.na(.c <- (ReportStart >= StartDateTime)) && .c) ReportStart else StartDateTime
  if (!is.na(.c <- (EndDateTime <= StartDateTime)) && .c) {
    report_writeErrorMsg(191, .L0)
  } else if (!is.na(.c <- (EndDateTime <= ReportStart)) && .c) {
    report_writeErrorMsg(193, .L0)
  } else {
    TotalDuration <<- floor((EndDateTime - StartDateTime) * 86400)
    if (!is.na(.c <- (ReportStep > TotalDuration)) && .c) {
      ReportStep <<- if (is.na(.d <- TotalDuration) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
    }
    if (!is.na(.c <- (ReportStep < RouteStep)) && .c) {
      report_writeErrorMsg(195, .L0)
    }
    TotalDuration <<- TotalDuration * 1000
  }
}

