# project.c:334
project_addObject <- function(type, id, n) {
  type; id; n
  if (project_findObject(type, id) >= 0) {
    return(0)
  }
  len <- rt_strlen(id)
  newID <- Alloc((rt_u64(len + 1) * 1))
  sstrncpy(newID, id, rt_u64(len))
  result <- HTinsert(Htable$v[[type + 1]], newID, n)
  if (result == 0) {
    result <- -1
  }
  return(result)
}

