  p <- 0
  isWet <- 0
  c_ <- 0
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    isWet <- if (!is.na(.c <- ((.G_Node[[i + 1]])$newDepth > .G_ZeroDepth)) && .c) 1 else 0
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      c_ <- 0
      if (isWet != 0) {
        c_ <- (.G_Pollut[[p + 1]])$initConcen
      }
      {.e1 <- (.G_Node[[i + 1]])$oldQual; .e1$v[[p + 1]] <- c_}
      {.e2 <- (.G_Node[[i + 1]])$newQual; .e2$v[[p + 1]] <- c_}
      p <- p + 1
    }
    i <- i + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    isWet <- if (!is.na(.c <- ((.G_Link[[i + 1]])$newDepth > .G_ZeroDepth)) && .c) 1 else 0
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      c_ <- 0
      if (isWet != 0) {
        c_ <- (.G_Pollut[[p + 1]])$initConcen
      }
      {.e3 <- (.G_Link[[i + 1]])$oldQual; .e3$v[[p + 1]] <- c_}
      {.e4 <- (.G_Link[[i + 1]])$newQual; .e4$v[[p + 1]] <- c_}
      p <- p + 1
    }
