  }
}

# qualrout.c:100
qualrout_execute <- function(tStep) {
  tStep
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_ZeroVolume <- ZeroVolume
  qIn <- 0
  vAvg <- 0
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    findLinkMassFlow(i, tStep)
    i <- i + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    {.e1 <- .G_Node[[j + 1]]; .e1$qualInflow <- (.G_Node[[j + 1]])$inflow}
    qIn <- (.G_Node[[j + 1]])$qualInflow
    vAvg <- ((.G_Node[[j + 1]])$oldVolume + (.G_Node[[j + 1]])$newVolume) / 2
    if (!is.null((.G_Node[[j + 1]])$treatment)) {
      if (!is.na(.c <- (qIn < 1e-10)) && .c) {
        qIn <- 0
      }
      treatmnt_setInflow(qIn, (.G_Node[[j + 1]])$newQual)
    }
    if (((.G_Node[[j + 1]])$type == 2) || (!is.na(.c <- ((.G_Node[[j + 1]])$oldVolume > .G_ZeroVolume)) && .c)) {
      findStorageQual(j, tStep)
    } else {
      findNodeQual(j)
    }
    if (!is.null((.G_Node[[j + 1]])$treatment)) {
      treatmnt_treat(j, qIn, vAvg, tStep)
    }
    j <- j + 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[4]]) {
    findLinkQual(i, tStep)
    i <- i + 1
  }
}

# qualrout.c:146
getMixedQual <- function(c_, v1, wIn, qIn, tStep) {
  c_; v1; wIn; qIn; tStep
  if (!is.na(.c <- (qIn <= 1e-10)) && .c) {
    return(c_)
  }
  vIn <- qIn * tStep
  cIn <- (wIn * tStep) / vIn
  cMax <- if (!is.na(.c <- (c_ >= cIn)) && .c) c_ else cIn
  c_ <- ((c_ * v1) + (wIn * tStep)) / (v1 + vIn)
  c_ <- if (!is.na(.c <- (c_ <= cMax)) && .c) c_ else cMax
  c_ <- if (!is.na(.c <- (c_ >= 0)) && .c) c_ else 0
  return(c_)
}

# qualrout.c:179
findLinkMassFlow <- function(i, tStep) {
  i; tStep
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node
  w <- 0
  qLink <- (.G_Link[[i + 1]])$newFlow
  j <- (.G_Link[[i + 1]])$node2
  if (!is.na(.c <- (qLink < 0)) && .c) {
    j <- (.G_Link[[i + 1]])$node1
  }
  qLink <- abs(qLink)
  if (RouteModel != 4) {
    qLink <- qLink - (inlet_capturedFlow(i))
  }
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    w <- qLink * (((.G_Link[[i + 1]])$oldQual)$v[[p + 1]])
    {.e1 <- (.G_Node[[j + 1]])$newQual; .e1$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
    {.e2 <- (.G_Link[[i + 1]])$totalLoad; .e2$v[[p + 1]] <- ((.G_Link[[i + 1]])$totalLoad)$v[[p + 1]] + (w * tStep)}
    p <- p + 1
  }
  {.e3 <- .G_Node[[j + 1]]; .e3$qualInflow <- (.G_Node[[j + 1]])$qualInflow + qLink}
}

# qualrout.c:221
findNodeQual <- function(j) {
  j
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_ZeroDepth <- ZeroDepth
  p <- 0
  qNode <- (.G_Node[[j + 1]])$qualInflow
  if (!is.na(.c <- (qNode > 1e-10)) && .c) {
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      {.e1 <- (.G_Node[[j + 1]])$newQual; .e1$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] / qNode}
      p <- p + 1
    }
  } else {
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      if (!is.na(.c <- ((.G_Node[[j + 1]])$newDepth > .G_ZeroDepth)) && .c) {
        {.e2 <- (.G_Node[[j + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Node[[j + 1]])$oldQual)$v[[p + 1]]}
      } else {
        {.e3 <- (.G_Node[[j + 1]])$newQual; .e3$v[[p + 1]] <- 0}
      }
      p <- p + 1
    }
  }
}

# qualrout.c:253
findLinkQual <- function(i, tStep) {
  i; tStep
  .G_Conduit <- Conduit; .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_RouteModel <- RouteModel; .G_ZeroDepth <- ZeroDepth; .G_ZeroVolume <- ZeroVolume
  p <- 0
  wIn <- 0
  c1 <- 0
  c2 <- 0
  j <- (.G_Link[[i + 1]])$node1
  if (!is.na(.c <- ((.G_Link[[i + 1]])$newFlow < 0)) && .c) {
    j <- (.G_Link[[i + 1]])$node2
  }
  if (((.G_Link[[i + 1]])$type != 0) || (((.G_Link[[i + 1]])$xsect)$type == 0)) {
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      {.e1 <- (.G_Link[[i + 1]])$newQual; .e1$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]]}
      p <- p + 1
    }
    return(invisible(NULL))
  }
  k <- (.G_Link[[i + 1]])$subIndex
  barrels <- (.G_Conduit[[k + 1]])$barrels
  qIn <- abs((.G_Conduit[[k + 1]])$q1) * barrels
  qSeep <- (.G_Conduit[[k + 1]])$seepLossRate * barrels
  vEvap <- ((.G_Conduit[[k + 1]])$evapLossRate * barrels) * tStep
  v1 <- (.G_Link[[i + 1]])$oldVolume
  v2 <- (.G_Link[[i + 1]])$newVolume
  vLosses <- (qSeep * tStep) + vEvap
  fEvap <- 1
  if ((!is.na(.c <- (vEvap > 0)) && .c) && (!is.na(.c <- (v1 > .G_ZeroVolume)) && .c)) {
    fEvap <- fEvap + (vEvap / v1)
  }
  if (.G_RouteModel == 1) {
    findSFLinkQual(i, qSeep, fEvap, tStep)
    return(invisible(NULL))
  }
  if (.G_RouteModel == 4) {
    qIn <- qIn + (((v2 + vLosses) - v1) / tStep)
    qIn <- if (!is.na(.c <- (qIn >= 0)) && .c) qIn else 0
  }
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    c1 <- ((.G_Link[[i + 1]])$oldQual)$v[[p + 1]]
    massbal_addSeepageLoss(p, (qSeep * c1))
    c1 <- c1 * fEvap
    c2 <- getReactedQual(p, c1, v1, tStep)
    wIn <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] * qIn
    c2 <- getMixedQual(c2, v1, wIn, qIn, tStep)
    if ((!is.na(.c <- (v2 < .G_ZeroVolume)) && .c) || (!is.na(.c <- ((.G_Link[[i + 1]])$newDepth <= .G_ZeroDepth)) && .c)) {
      massbal_addToFinalStorage(p, (c2 * v2))
      c2 <- 0
    }
    {.e2 <- (.G_Link[[i + 1]])$newQual; .e2$v[[p + 1]] <- c2}
    p <- p + 1
  }
}

# qualrout.c:357
findSFLinkQual <- function(i, qSeep, fEvap, tStep) {
  i; qSeep; fEvap; tStep
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Pollut <- Pollut
  j <- (.G_Link[[i + 1]])$node1
  c1 <- 0
  c2 <- 0
  lossRate <- 0
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    c1 <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]]
    massbal_addSeepageLoss(p, (qSeep * c1))
    c1 <- c1 * fEvap
    c2 <- c1
    if (!is.na(.c <- ((.G_Pollut[[p + 1]])$kDecay > 0)) && .c) {
      c2 <- c1 * (exp((-((.G_Pollut[[p + 1]])$kDecay)) * tStep))
      c2 <- if (!is.na(.c <- (0 >= c2)) && .c) 0 else c2
      lossRate <- (c1 - c2) * ((.G_Link[[i + 1]])$newFlow)
      massbal_addReactedMass(p, lossRate)
    }
    {.e1 <- (.G_Link[[i + 1]])$newQual; .e1$v[[p + 1]] <- c2}
    p <- p + 1
  }
}

# qualrout.c:398
findStorageQual <- function(j, tStep) {
  j; tStep
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Storage <- Storage; .G_ZeroDepth <- ZeroDepth; .G_ZeroVolume <- ZeroVolume
  k <- 0
  wIn <- 0
  c1 <- 0
  c2 <- 0
  qExfil <- 0
  vEvap <- 0
  fEvap <- 1
  qIn <- (.G_Node[[j + 1]])$qualInflow
  v1 <- (.G_Node[[j + 1]])$oldVolume
  if ((.G_Node[[j + 1]])$type == 2) {
    updateHRT(j, (.G_Node[[j + 1]])$oldVolume, qIn, tStep)
    k <- (.G_Node[[j + 1]])$subIndex
    qExfil <- (.G_Storage[[k + 1]])$exfilLoss / tStep
    vEvap <- (.G_Storage[[k + 1]])$evapLoss
    if ((!is.na(.c <- (vEvap > 0)) && .c) && (!is.na(.c <- (v1 > .G_ZeroVolume)) && .c)) {
      fEvap <- fEvap + (vEvap / v1)
    }
  }
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    c1 <- ((.G_Node[[j + 1]])$oldQual)$v[[p + 1]]
    massbal_addSeepageLoss(p, (qExfil * c1))
    c1 <- c1 * fEvap
    if ((is.null((.G_Node[[j + 1]])$treatment)) || (is.null((((.G_Node[[j + 1]])$treatment)[[p + 1]])$equation))) {
      c1 <- getReactedQual(p, c1, v1, tStep)
    }
    wIn <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]]
    c2 <- getMixedQual(c1, v1, wIn, qIn, tStep)
    if (((!is.na(.c <- ((.G_Node[[j + 1]])$newVolume <= .G_ZeroVolume)) && .c) || (!is.na(.c <- ((.G_Node[[j + 1]])$newDepth <= .G_ZeroDepth)) && .c)) && (!is.na(.c <- (qIn <= 1e-10)) && .c)) {
      massbal_addToFinalStorage(p, (c2 * ((.G_Node[[j + 1]])$newVolume)))
      c2 <- 0
    }
    {.e1 <- (.G_Node[[j + 1]])$newQual; .e1$v[[p + 1]] <- c2}
    p <- p + 1
  }
}

# qualrout.c:478
updateHRT <- function(j, v, q_, tStep) {
  j; v; q_; tStep
  .G_Storage <- Storage
  k <- (Node[[j + 1]])$subIndex
  hrt <- (.G_Storage[[k + 1]])$hrt
  if (!is.na(.c <- (v < 1e-10)) && .c) {
    hrt <- 0
  } else {
    hrt <- ((hrt + tStep) * v) / (v + (q_ * tStep))
  }
  {.e1 <- .G_Storage[[k + 1]]; .e1$hrt <- if (!is.na(.c <- (hrt >= 0)) && .c) hrt else 0}
}

# qualrout.c:498
getReactedQual <- function(p, c_, v1, tStep) {
  p; c_; v1; tStep
  kDecay <- (Pollut[[p + 1]])$kDecay
  if (!is.na(.c <- (kDecay == 0)) && .c) {
    return(c_)
  }
  c2 <- c_ * (1 - (kDecay * tStep))
  c2 <- if (!is.na(.c <- (0 >= c2)) && .c) 0 else c2
  lossRate <- ((c_ - c2) * v1) / tStep
  massbal_addReactedMass(p, lossRate)
  return(c2)
}

# rain.c:118
rain_open <- function() {
  .G_Frain <- Frain; .G_Gage <- Gage; .G_Nobjects <- Nobjects
  count <- 0
  i <- 0
  while (i < .G_Nobjects$v[[1]]) {
    if ((.G_Gage[[i + 1]])$dataSource == 1) {
      count <- count + 1
    }
    i <- i + 1
  }
  .G_Frain$file <- NULL
  if (count == 0) {
    .G_Frain$mode <- 0
  } else {
    .sw1 <- .G_Frain$mode
    if (.sw1 == 1) {
      getTempFileName(.G_Frain$name)
      if (is.null((.G_Frain$file <- rt_fopen(.G_Frain$name, .L166)))) {
        report_writeErrorMsg(313, .L0)
        return(invisible(NULL))
      }
    } else if (.sw1 == 2) {
      if (is.null((.G_Frain$file <- rt_fopen(.G_Frain$name, .L165)))) {
        report_writeErrorMsg(315, .G_Frain$name)
        return(invisible(NULL))
      }
    } else if (.sw1 == 3) {
      if (is.null((.G_Frain$file <- rt_fopen(.G_Frain$name, .L166)))) {
        report_writeErrorMsg(315, .G_Frain$name)
        return(invisible(NULL))
      }
    }
  }
  if ((.G_Frain$mode == 1) || (.G_Frain$mode == 3)) {
    createRainFile(count)
  }
  if (.G_Frain$mode != 0) {
    initRainFile()
  }
  rdii_openRdii()
}

