# rain.c:202
createRainFile <- function(count) {
  count
  .G_Frain <- Frain; .G_Gage <- Gage; .G_Nobjects <- Nobjects
  k <- 0
  kount <- count
  filePos3 <- 0
  interval <- 0
  dummy <- -1
  staID <- rt_cbuf(1025)
  fileStamp <- rt_cbuf_from(.L327, 11)
  if ((ErrorCode != 0) || (!(!is.null(.G_Frain$file)))) {
    return(invisible(NULL))
  }
  rt_fwrite_arr("c", 1, fileStamp, 0, rt_strlen(fileStamp), .G_Frain$file)
  rt_fwrite1("i", 4, kount, .G_Frain$file)
  filePos1 <- rt_i32(rt_ftell(.G_Frain$file))
  if (count > 0) {
    report_writeRainStats((-1), RainStats)
  }
  rt_strcpy(staID, .L33)
  i <- 0
  while (i < count) {
    rt_fwrite_arr("c", 1, staID, 0, rt_u64(1024 + 1), .G_Frain$file)
    k <- 1
    while (k <= 3) {
      rt_fwrite1("i", 4, dummy, .G_Frain$file)
      k <- k + 1
    }
    i <- i + 1
  }
  filePos2 <- rt_i32(rt_ftell(.G_Frain$file))
  i <- 0
  while (i < .G_Nobjects$v[[1]]) {
    if ((ErrorCode != 0) || ((.G_Gage[[i + 1]])$dataSource != 1)) {
      i <- i + 1
      next
    }
    if (rainFileConflict(i) != 0) {
      break
    }
    rt_fseek(.G_Frain$file, filePos2, 0)
    if (addGageToRainFile(i) != 0) {
      filePos3 <- rt_i32(rt_ftell(.G_Frain$file))
      rt_fseek(.G_Frain$file, filePos1, 0)
      sstrncpy(staID, (.G_Gage[[i + 1]])$staID, 1024)
      interval <- Interval
      rt_fwrite_arr("c", 1, staID, 0, rt_u64(1024 + 1), .G_Frain$file)
      rt_fwrite1("i", 4, interval, .G_Frain$file)
      rt_fwrite1("i", 4, filePos2, .G_Frain$file)
      rt_fwrite1("i", 4, filePos3, .G_Frain$file)
      filePos1 <- rt_i32(rt_ftell(.G_Frain$file))
      filePos2 <- filePos3
      report_writeRainStats(i, RainStats)
    }
    i <- i + 1
  }
  if (ErrorCode != 0) {
    rt_fclose(.G_Frain$file)
    .G_Frain$file <- NULL
    rt_remove(.G_Frain$name)
  }
}

# rain.c:278
rainFileConflict <- function(i) {
  i
  .G_Gage <- Gage
  staID <- (.G_Gage[[i + 1]])$staID
  fname <- (.G_Gage[[i + 1]])$fname
  j <- 0
  while (j < i) {
    if ((strcomp((.G_Gage[[j + 1]])$staID, staID) != 0) && (!(strcomp((.G_Gage[[j + 1]])$fname, fname) != 0))) {
      report_writeErrorMsg(156, (.G_Gage[[i + 1]])$ID)
      return(1)
    }
    j <- j + 1
  }
  return(0)
}

# rain.c:302
addGageToRainFile <- function(i) {
  i
  .G_Gage <- Gage
  f <- NULL
  fileFormat <- 0
  hdrLines <- 0
  StationID <<- NULL
  if (is.null((f <- rt_fopen((.G_Gage[[i + 1]])$fname, .L13)))) {
    report_writeErrorMsg(317, (.G_Gage[[i + 1]])$fname)
  } else {
    fileFormat <- {.BX_addGageToRainFile_hdrLines$v <- hdrLines; .r1 <- findFileFormat(f, i, .BX_addGageToRainFile_hdrLines); hdrLines <- .BX_addGageToRainFile_hdrLines$v; .r1}
    if (fileFormat == 0) {
      report_writeErrorMsg(319, (.G_Gage[[i + 1]])$fname)
    } else {
      GageIndex <<- i
      readFile(f, fileFormat, hdrLines, (.G_Gage[[i + 1]])$startFileDate, (.G_Gage[[i + 1]])$endFileDate)
    }
    rt_fclose(f)
  }
  if (ErrorCode != 0) {
    return(0)
  } else {
    return(1)
  }
}

# rain.c:341
initRainFile <- function() {
  .G_Frain <- Frain; .G_Gage <- Gage; .G_Nobjects <- Nobjects
  fileStamp <- rt_cbuf_from(.L327, 11)
  fStamp <- rt_cbuf_from(.L327, 11)
  kount <- 0
  if ((ErrorCode != 0) || (!(!is.null(.G_Frain$file)))) {
    return(invisible(NULL))
  }
  rt_rewind(.G_Frain$file)
  rt_fread_arr("c", 1, fStamp, 0, rt_strlen(fileStamp), .G_Frain$file)
  if (rt_strcmp(fStamp, fileStamp) != 0) {
    report_writeErrorMsg(320, .L0)
