findNWSOnlineFormat <- function(f, line) {
  f; line
  fileFormat <- 0
  str <- NULL
  rt_rewind(f)
  rt_fgets(line, 1024, f)
  if (!is.null((str <- rt_strstr(line, .L337)))) {
    Interval <<- 3600
    TimeOffset <<- Interval
    ValueOffset <<- rt_i32(rt_cdiff(str, line))
    fileFormat <- 4
  } else if (!is.null((str <- rt_strstr(line, .L338)))) {
    Interval <<- 900
    TimeOffset <<- Interval
    ValueOffset <<- rt_i32(rt_cdiff(str, line))
    fileFormat <- 5
  } else {
    return(0)
  }
  n <- 1
  while (n <= 5) {
    if (is.null(rt_fgets(line, 1024, f))) {
      return(0)
    }
    if (is.null(rt_strstr(line, .L334))) {
      n <- n + 1
      next
    }
    str <- rt_strrchr(line, 58)
    if (is.null(str)) {
      return(0)
    }
    n <- rt_i32(rt_cdiff(str, line))
    DataOffset <<- n - 11
    return(fileFormat)
    n <- n + 1
  }
  return(0)
}

