    rainInterval <- (.G_UHGroup[[j + 1]])$rainInterval
    while (!is.na(.c <- ((.G_UHGroup[[j + 1]])$gageDate < currentDate)) && .c) {
      gageDate <- (.G_UHGroup[[j + 1]])$gageDate
      .G_Adjust$rainFactor <- .G_Adjust$rain$v[[datetime_monthOfYear(gageDate)]]
      if (!((.G_Gage[[g + 1]])$isCurrent != 0)) {
