        updateDryPeriod(j, k, excessDepth, rainInterval)
        i <- (((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$period
        if (i >= (((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$maxPeriods) {
          i <- 0
        }
        {.e3 <- (((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$pastRain; .e3$v[[i + 1]] <- excessDepth}
        rt_cset((((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$pastMonth, i, month)
        {.e4 <- ((.G_UHGroup[[j + 1]])$uh)[[k + 1]]; .e4$period <- i + 1}
        k <- k + 1
      }
      {.e5 <- .G_UHGroup[[j + 1]]; .e5$gageDate <- datetime_addSeconds(gageDate, rainInterval)}
    }
