    netRainDepth <- if (!is.na(.c <- (netRainDepth >= 0)) && .c) netRainDepth else 0
    ia <- rainDepth - netRainDepth
    {.e1 <- ((.G_UHGroup[[j + 1]])$uh)[[k + 1]]; .e1$iaUsed <- (((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$iaUsed + ia}
  } else {
    {.e2 <- ((.G_UHGroup[[j + 1]])$uh)[[k + 1]]; .e2$iaUsed <- (((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$iaUsed - ((dt / 86400) * ((((.G_UnitHyd[[j + 1]])$iaRecov)$v[[m + 1]])$v[[k + 1]]))}
    {.e3 <- ((.G_UHGroup[[j + 1]])$uh)[[k + 1]]; .e3$iaUsed <- if (!is.na(.c <- (((((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$iaUsed) >= 0)) && .c) ((((.G_UHGroup[[j + 1]])$uh)[[k + 1]])$iaUsed) else 0}
    netRainDepth <- 0
  }
