# rdii.c:1411
getUnitHydOrd <- function(h, m, k, t) {
  h; m; k; t
  .G_UnitHyd <- UnitHyd
  f <- 0
  tBase <- (((.G_UnitHyd[[h + 1]])$tBase)$v[[m + 1]])$v[[k + 1]]
  if (!is.na(.c <- (t >= tBase)) && .c) {
    return(0)
  }
  qPeak <- (2 / tBase) * 3600
  t1 <- (((.G_UnitHyd[[h + 1]])$tPeak)$v[[m + 1]])$v[[k + 1]]
  t2 <- tBase - t1
  if (!is.na(.c <- (t <= t1)) && .c) {
    f <- t / t1
  } else {
    f <- 1 - ((t - t1) / t2)
  }
  return((if (!is.na(.c <- (f >= 0)) && .c) f else 0) * qPeak)
}

