report_readOptions <- function(tok, ntoks) {
  tok; ntoks
  .G_Link <- Link; .G_Node <- Node; .G_RptFlags <- RptFlags; .G_Subcatch <- Subcatch
  j <- 0
  m <- 0
  t <- 0
  if (ntoks < 2) {
    return(error_setInpError(203, .L0))
  }
  k <- findmatch(tok$v[[1]], ReportWords)
  if (k < 0) {
    return(error_setInpError(205, tok$v[[1]]))
  }
  if ((k < 2) || (k > 4)) {
    m <- findmatch(tok$v[[2]], NoYesWords)
    if ((m < 0) || (m > 1)) {
      return(error_setInpError(205, tok$v[[2]]))
    }
    if (k == 0) {
      .G_RptFlags$disabled <- m
      return(0)
    } else if (k == 1) {
      .G_RptFlags$input <- m
      return(0)
    } else if (k == 5) {
      .G_RptFlags$continuity <- m
      return(0)
    } else if (k == 6) {
      .G_RptFlags$flowStats <- m
      return(0)
    } else if (k == 7) {
      .G_RptFlags$controls <- m
      return(0)
    } else if (k == 8) {
      .G_RptFlags$averages <- m
      return(0)
    } else if (k == 9) {
      return(0)
    } else {
      return(error_setInpError(205, tok$v[[2]]))
    }
  } else {
    if (k == 2) {
      m <- 1
    } else if (k == 3) {
      m <- 2
    } else if (k == 4) {
      m <- 3
    }
  }
  if (strcomp(tok$v[[2]], .L355) != 0) {
    k <- 0
  } else if (strcomp(tok$v[[2]], .L351) != 0) {
    k <- 1
  } else {
    k <- 2
    t <- 1
    while (t < ntoks) {
      j <- project_findObject(m, tok$v[[t + 1]])
      if (j < 0) {
        return(error_setInpError(209, tok$v[[t + 1]]))
      }
      if (m == 1) {
        {.e1 <- .G_Subcatch[[j + 1]]; .e1$rptFlag <- 1}
      } else if (m == 2) {
        {.e2 <- .G_Node[[j + 1]]; .e2$rptFlag <- 1}
      } else if (m == 3) {
        {.e3 <- .G_Link[[j + 1]]; .e3$rptFlag <- 1}
      }
      t <- t + 1
    }
  }
  if (m == 1) {
    .G_RptFlags$subcatchments <- k
  } else if (m == 2) {
    .G_RptFlags$nodes <- k
  } else if (m == 3) {
    .G_RptFlags$links <- k
  }
  return(0)
}

