# report.c:183
report_writeSysTime <- function() {
  .G_Frpt <- Frpt; .G_SysTime <- SysTime
  theTime <- rt_cbuf(9)
  elapsedTime <- 0
  endTime <- 0
  if (!is.null(.G_Frpt$file)) {
    rt_fprintf(.G_Frpt$file, .L357, list(rt_ctime(.G_SysTime$v)))
    rt_time()
    rt_fprintf(.G_Frpt$file, .L358, list(rt_ctime(endTime)))
    elapsedTime <- endTime - .G_SysTime$v
    rt_fprintf(.G_Frpt$file, .L359, list())
    if (!is.na(.c <- (elapsedTime < 1)) && .c) {
      rt_fprintf(.G_Frpt$file, .L360, list())
    } else {
      elapsedTime <- elapsedTime / 86400
      if (!is.na(.c <- (elapsedTime >= 1)) && .c) {
        rt_fprintf(.G_Frpt$file, .L361, list(if (is.na(.d <- floor(elapsedTime)) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)))
        elapsedTime <- elapsedTime - (floor(elapsedTime))
      }
      datetime_timeToStr(elapsedTime, theTime)
      rt_fprintf(.G_Frpt$file, .L169, list(theTime))
    }
  }
}

