# report.c:923
report_writeMaxStats <- function(maxMassBalErrs, maxCourantCrit, nMaxStats) {
  maxMassBalErrs; maxCourantCrit; nMaxStats
  .G_Frpt <- Frpt; .G_Link <- Link; .G_Node <- Node
  i <- 0
  j <- 0
  if ((RouteModel != 4) || (Nobjects$v[[4]] == 0)) {
    return(invisible(NULL))
  }
  if (nMaxStats <= 0) {
    return(invisible(NULL))
  }
  if (maxMassBalErrs[[1]]$index >= 0) {
    report_writeLine(.L0)
    report_writeLine(.L470)
    report_writeLine(.L471)
    report_writeLine(.L470)
    i <- 0
    while (i < nMaxStats) {
      j <- (maxMassBalErrs[[i + 1]])$index
      if (j < 0) {
        i <- i + 1
        next
      }
      rt_fprintf(.G_Frpt$file, .L472, list((.G_Node[[j + 1]])$ID, (maxMassBalErrs[[i + 1]])$value))
      i <- i + 1
    }
    report_writeLine(.L0)
  }
  if (!is.na(.c <- (CourantFactor$v == 0)) && .c) {
    return(invisible(NULL))
  }
  report_writeLine(.L0)
  report_writeLine(.L473)
  report_writeLine(.L474)
  report_writeLine(.L473)
  k <- 0
  i <- 0
  while (i < nMaxStats) {
    j <- (maxCourantCrit[[i + 1]])$index
    if (j < 0) {
      i <- i + 1
      next
    }
    k <- k + 1
    if ((maxCourantCrit[[i + 1]])$objType == 2) {
      rt_fprintf(.G_Frpt$file, .L475, list((.G_Node[[j + 1]])$ID))
    } else {
      rt_fprintf(.G_Frpt$file, .L476, list((.G_Link[[j + 1]])$ID))
    }
    rt_fprintf(.G_Frpt$file, .L477, list((maxCourantCrit[[i + 1]])$value))
    i <- i + 1
  }
  if (k == 0) {
    rt_fprintf(.G_Frpt$file, .L478, list())
  }
  report_writeLine(.L0)
}

