# report.c:1037
report_writeTimeStepStats <- function(timeStepStats) {
  timeStepStats
  .G_Frpt <- Frpt
  timeStepCount <- timeStepStats$timeStepCount
  fSteadyState <- 0
  if ((Nobjects$v[[4]] == 0) || (!is.na(.c <- (timeStepStats$timeStepCount == 0)) && .c)) {
    return(invisible(NULL))
  }
  totalRoutingTime <- timeStepStats$steadyStateTime + timeStepStats$routingTime
  if (!is.na(.c <- (totalRoutingTime > 0)) && .c) {
    fSteadyState <- (100 * timeStepStats$steadyStateTime) / totalRoutingTime
  }
  report_writeLine(.L0)
  report_writeLine(.L470)
  report_writeLine(.L486)
  report_writeLine(.L470)
  rt_fprintf(.G_Frpt$file, .L487, list(timeStepStats$minTimeStep))
  rt_fprintf(.G_Frpt$file, .L488, list(timeStepStats$routingTime / timeStepCount))
  rt_fprintf(.G_Frpt$file, .L489, list(timeStepStats$maxTimeStep))
  rt_fprintf(.G_Frpt$file, .L490, list(if (!is.na(.c <- (fSteadyState <= 100)) && .c) fSteadyState else 100))
  rt_fprintf(.G_Frpt$file, .L491, list(timeStepStats$trialsCount / timeStepCount))
  rt_fprintf(.G_Frpt$file, .L492, list((100 * NonConvergeCount) / timeStepCount))
  if ((RouteModel == 4) && (!is.na(.c <- (CourantFactor$v > 0)) && .c)) {
    report_RouteStepFreq(timeStepStats)
  }
  report_writeLine(.L0)
}

# report.c:1085
report_RouteStepFreq <- function(timeStepStats) {
  timeStepStats
  .G_Frpt <- Frpt
  totalSteps <- 0
  i <- 1
  while (i < 6) {
    totalSteps <- totalSteps + (timeStepStats$timeStepCounts$v[[i + 1]])
    i <- i + 1
  }
  if (!is.na(.c <- (totalSteps == 0)) && .c) {
    return(invisible(NULL))
  }
  rt_fprintf(.G_Frpt$file, .L493, list())
  i <- 1
  while (i < 6) {
    rt_fprintf(.G_Frpt$file, .L494, list(timeStepStats$timeStepIntervals$v[[i]], timeStepStats$timeStepIntervals$v[[i + 1]], (100 * (timeStepStats$timeStepCounts$v[[i + 1]])) / totalSteps))
    i <- i + 1
  }
}

# report.c:1113
report_writeReport <- function() {
  .G_RptFlags <- RptFlags
  if (ErrorCode != 0) {
    return(invisible(NULL))
  }
  if (Nperiods == 0) {
    return(invisible(NULL))
  }
  if ((.G_RptFlags$subcatchments != 0) && (((IgnoreRainfall == 0) || (IgnoreSnowmelt == 0)) || (IgnoreGwater == 0))) {
    report_Subcatchments()
  }
  if ((IgnoreRouting == 1) && (IgnoreQuality == 1)) {
    return(invisible(NULL))
  }
  if (.G_RptFlags$nodes != 0) {
    report_Nodes()
  }
  if (.G_RptFlags$links != 0) {
    report_Links()
  }
}

# report.c:1135
report_Subcatchments <- function() {
  .G_Frpt <- Frpt; .G_Nobjects <- Nobjects; .G_Nperiods <- Nperiods; .G_Subcatch <- Subcatch; .G_SubcatchResults <- SubcatchResults
  p <- 0
  k <- 0
  period <- 0
  days <- 0
  theDate <- rt_cbuf(12)
  theTime <- rt_cbuf(9)
  hasSnowmelt <- if ((.G_Nobjects$v[[14]] > 0) && (!(IgnoreSnowmelt != 0))) 1 else 0
  hasGwater <- if ((.G_Nobjects$v[[12]] > 0) && (!(IgnoreGwater != 0))) 1 else 0
  hasQuality <- if ((.G_Nobjects$v[[5]] > 0) && (!(IgnoreQuality != 0))) 1 else 0
  if (.G_Nobjects$v[[2]] == 0) {
    return(invisible(NULL))
  }
  report_writeLine(.L0)
  report_writeLine(.L479)
  report_writeLine(.L495)
  report_writeLine(.L479)
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    k <- (.G_Subcatch[[j + 1]])$rptFlag - 1
    if (k >= 0) {
      report_SubcatchHeader((.G_Subcatch[[j + 1]])$ID)
      period <- 1
      while (period <= .G_Nperiods) {
        {.BX_report_Subcatchments_days$v <- days; .r1 <- output_readDateTime(period, .BX_report_Subcatchments_days); days <- .BX_report_Subcatchments_days$v; .r1}
        datetime_dateToStr(days, theDate)
        datetime_timeToStr(days, theTime)
        output_readSubcatchResults(period, k)
        rt_fprintf(.G_Frpt$file, .L496, list(theDate, theTime, .G_SubcatchResults$v[[1]], (.G_SubcatchResults$v[[3]] / 24) + .G_SubcatchResults$v[[4]], .G_SubcatchResults$v[[5]]))
        if (hasSnowmelt != 0) {
          rt_fprintf(.G_Frpt$file, .L497, list(.G_SubcatchResults$v[[2]]))
        }
        if (hasGwater != 0) {
          rt_fprintf(.G_Frpt$file, .L498, list(.G_SubcatchResults$v[[7]], .G_SubcatchResults$v[[6]]))
        }
        if (hasQuality != 0) {
          p <- 0
          while (p < .G_Nobjects$v[[5]]) {
            rt_fprintf(.G_Frpt$file, .L499, list(.G_SubcatchResults$v[[(8 + p) + 1]]))
            p <- p + 1
          }
        }
        period <- period + 1
      }
      report_writeLine(.L0)
    }
    j <- j + 1
  }
}

