report_writeErrorMsg <- function(code, s) {
  code; s
  .G_Frpt <- Frpt; .G_Msg <- Msg
  if (!is.null(.G_Frpt$file)) {
    report_writeLine(.L0)
    rt_fprintf(.G_Frpt$file, error_getMsg(code, .G_Msg), list(s))
  }
  ErrorCode <<- code
  if ((ErrorCode <= 200) || (ErrorCode >= 301)) {
    rt_snprintf(ErrorMsg, 1024, error_getMsg(ErrorCode, .G_Msg), list(s))
  }
}

# report.c:1446
report_writeErrorCode <- function() {
  .G_ErrorCode <- ErrorCode; .G_Frpt <- Frpt
  if (!is.null(.G_Frpt$file)) {
    if ((((.G_ErrorCode >= 101) && (.G_ErrorCode <= 107)) || ((.G_ErrorCode >= 301) && (.G_ErrorCode <= 307))) || (.G_ErrorCode == 500)) {
      rt_fprintf(.G_Frpt$file, .L169, list(error_getMsg(.G_ErrorCode, Msg)))
    }
  }
}

# report.c:1464
report_writeInputErrorMsg <- function(k, sect, line, lineCount) {
  k; sect; line; lineCount
  .G_Frpt <- Frpt
  if (!is.null(.G_Frpt$file)) {
