# roadway.c:85
roadway_getInflow <- function(j, dir, hRoad, h1, h2) {
  j; dir; hRoad; h1; h2
  .G_Link <- Link; .G_Weir <- Weir
  length_ <- 0
  q_ <- 0
  dqdh <- 0
  if ((.G_Link[[j + 1]])$type != 3) {
    return(0)
  }
  k <- (.G_Link[[j + 1]])$subIndex
  roadWidth <- (.G_Weir[[k + 1]])$roadWidth
  roadSurf <- (.G_Weir[[k + 1]])$roadSurface
  cD <- (.G_Weir[[k + 1]])$cDisch1
  if (UnitSystem == 1) {
    cD <- cD / 0.552
  }
  useVariableCd <- 0
  if ((!is.na(.c <- (roadWidth > 0)) && .c) && (roadSurf >= 1)) {
    useVariableCd <- 1
  }
  hWr <- h1 - hRoad
  ht <- h2 - hRoad
  if (!is.na(.c <- (hWr > 0.0001)) && .c) {
    if (useVariableCd != 0) {
      cD <- getCd(hWr, ht, roadWidth, roadSurf)
    }
    length_ <- ((.G_Link[[j + 1]])$xsect)$wMax
    q_ <- (cD * length_) * (if ((.p <- hWr) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
    dqdh <- (1.5 * q_) / hWr
  }
  {.e1 <- .G_Link[[j + 1]]; .e1$dqdh <- dqdh}
  {.e2 <- .G_Link[[j + 1]]; .e2$newDepth <- if (!is.na(.c <- ((h1 - hRoad) >= 0)) && .c) (h1 - hRoad) else 0}
  {.e3 <- .G_Link[[j + 1]]; .e3$flowClass <- 3}
  if (!is.na(.c <- (hRoad > h2)) && .c) {
    if (!is.na(.c <- (dir == 1)) && .c) {
      {.e4 <- .G_Link[[j + 1]]; .e4$flowClass <- 6}
    } else {
      {.e5 <- .G_Link[[j + 1]]; .e5$flowClass <- 5}
    }
  }
  return(dir * q_)
}

# roadway.c:146
getCd <- function(hWr, ht, roadWidth, roadSurf) {
  hWr; ht; roadWidth; roadSurf
  kT <- 1
  htH <- 0
  cR <- 0
  if (!is.na(.c <- (hWr <= 0)) && .c) {
    return(0)
  }
  hL <- hWr / roadWidth
  if (!is.na(.c <- (hL <= 0.15)) && .c) {
    if (roadSurf == 1) {
      cR <- getY(hWr, Cr_Low_Paved, N_Cr_Low_Paved)
    } else {
      cR <- getY(hWr, Cr_Low_Gravel, N_Cr_Low_Gravel)
    }
  } else {
    if (roadSurf == 1) {
      cR <- getY(hL, Cr_High_Paved, N_Cr_High_Paved)
    } else {
      cR <- getY(hL, Cr_High_Gravel, N_Cr_High_Gravel)
    }
  }
  if (!is.na(.c <- (ht > 0)) && .c) {
    htH <- ht / hWr
    if (roadSurf == 1) {
      kT <- getY(htH, Kt_Paved, N_Kt_Paved)
    } else {
      kT <- getY(htH, Kt_Gravel, N_Kt_Gravel)
    }
  }
  return(cR * kT)
}

# roadway.c:176
getY <- function(x, table_, n) {
  x; table_; n
  x1 <- 0
  y1 <- 0
  dx <- 0
  dy <- 0
  if (!is.na(.c <- (x <= table_$v[[1]]$v[[1]])) && .c) {
    return(table_$v[[1]]$v[[2]])
  }
  if (!is.na(.c <- (x >= (table_$v[[n]])$v[[1]])) && .c) {
    return((table_$v[[n]])$v[[2]])
  }
  i <- 1
  while (i < n) {
    if (!is.na(.c <- (x <= (table_$v[[i + 1]])$v[[1]])) && .c) {
      x1 <- (table_$v[[i]])$v[[1]]
      dx <- (table_$v[[i + 1]])$v[[1]] - x1
      y1 <- (table_$v[[i]])$v[[2]]
      dy <- (table_$v[[i + 1]])$v[[2]] - y1
      return(y1 + (((x - x1) * dy) / dx))
    }
    i <- i + 1
  }
  return((table_$v[[n]])$v[[2]])
}

# routing.c:93
routing_open <- function() {
  .G_Nobjects <- Nobjects; .G_NumEvents <- NumEvents
  if (!(treatmnt_open() != 0)) {
    return(ErrorCode)
  }
  SortedLinks <<- NULL
  if (.G_Nobjects$v[[4]] > 0) {
    SortedLinks <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[4]])))
    if (!(!is.null(SortedLinks))) {
      report_writeErrorMsg(101, .L0)
      return(ErrorCode)
    }
    toposort_sortLinks(SortedLinks)
    if (ErrorCode != 0) {
      return(ErrorCode)
    }
  }
  iface_openRoutingFiles()
  flowrout_init(RouteModel)
  if (Fhotstart1$mode == 0) {
    qualrout_init()
  }
  if (.G_NumEvents > 0) {
    sortEvents()
  }
  NextEvent <<- 0
  BetweenEvents <<- if (.G_NumEvents > 0) 1 else 0
  NewRuleTime <<- 0
  return(ErrorCode)
}

# routing.c:134
routing_close <- function(routingModel) {
  routingModel
  iface_closeRoutingFiles()
  flowrout_close(routingModel)
  treatmnt_close()
  if (!is.null(SortedLinks)) {
    NULL
    SortedLinks <<- NULL
  }
}

# routing.c:152
routing_getRoutingStep <- function(routingModel, fixedStep) {
  routingModel; fixedStep
  .G_Event <- Event; .G_NewRoutingTime <- NewRoutingTime; .G_NewRunoffTime <- NewRunoffTime; .G_NextEvent <- NextEvent; .G_ReportTime <- ReportTime; .G_RuleStep <- RuleStep
  date1 <- 0
  date2 <- 0
  nextTime <- 0
  routingStep <- 0
  nextRuleTime <- 0
  nextRoutingTime <- 0
  if (Nobjects$v[[4]] == 0) {
    return(fixedStep)
  }
  if ((NumEvents > 0) && (BetweenEvents != 0)) {
    nextTime <- if (!is.na(.c <- (.G_NewRunoffTime <= .G_ReportTime)) && .c) .G_NewRunoffTime else .G_ReportTime
    date1 <- getDateTime(.G_NewRoutingTime)
    date2 <- getDateTime(nextTime)
    if ((!is.na(.c <- (date2 > date1)) && .c) && (!is.na(.c <- (date2 < (.G_Event[[.G_NextEvent + 1]])$start)) && .c)) {
      routingStep <- (nextTime - .G_NewRoutingTime) / 1000
    } else {
      date1 <- getDateTime((.G_NewRoutingTime + (1000 * fixedStep)))
      if (!is.na(.c <- (date1 < (.G_Event[[.G_NextEvent + 1]])$start)) && .c) {
        return(fixedStep)
      }
    }
  }
  if (!is.na(.c <- (routingStep == 0)) && .c) {
    routingStep <- flowrout_getRoutingStep(routingModel, fixedStep)
  }
  if (.G_RuleStep > 0) {
    nextRuleTime <- NewRuleTime + (1000 * .G_RuleStep)
    nextRoutingTime <- .G_NewRoutingTime + (1000 * routingStep)
    if (!is.na(.c <- (nextRoutingTime >= nextRuleTime)) && .c) {
      routingStep <- (nextRuleTime - .G_NewRoutingTime) / 1000
    }
  }
  return(routingStep)
}

# routing.c:203
routing_execute <- function(routingModel, routingStep) {
  routingModel; routingStep
  .G_Nobjects <- Nobjects
  trialsCount <- 1
  actionCount <- 0
  inSteadyState <- 1
  if (ErrorCode != 0) {
    return(invisible(NULL))
  }
  massbal_updateRoutingTotals((routingStep / 2))
  currentDate <- getDateTime(NewRoutingTime)
  actionCount <- evaluateControlRules(currentDate, routingStep)
  stepFlowError <- massbal_getStepFlowError()
  massbal_initTimeStepTotals()
  initSystemInflows()
  BetweenEvents <<- isBetweenEvents(currentDate)
  if (BetweenEvents == 0) {
    addSystemInflows(currentDate, routingStep)
    inlet_findCapturedFlows(routingStep)
    inSteadyState <- isInSteadyState(actionCount, stepFlowError)
    if (inSteadyState == 0) {
      trialsCount <- routeFlow(routingModel, routingStep)
    }
    if ((.G_Nobjects$v[[5]] > 0) && (!(IgnoreQuality != 0))) {
      inlet_adjustQualInflows()
      qualrout_execute(routingStep)
    }
    removeSystemOutflows(routingStep)
    inlet_adjustQualOutflows()
    if (.G_Nobjects$v[[4]] > 0) {
      stats_updateFlowStats(routingStep, getDateTime(NewRoutingTime))
      stats_updateTimeStepStats(routingStep, trialsCount, inSteadyState)
    }
  }
  massbal_updateRoutingTotals((routingStep / 2))
}

# routing.c:269
evaluateControlRules <- function(currentDate, routingStep) {
  currentDate; routingStep
  .G_Link <- Link; .G_Nobjects <- Nobjects; .G_RuleStep <- RuleStep
  actionCount <- 0
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    link_setTargetSetting(j)
    j <- j + 1
  }
  if ((.G_RuleStep == 0) || (!is.na(.c <- (abs(NewRoutingTime - NewRuleTime) < 1)) && .c)) {
    controls_evaluate(currentDate, (currentDate - StartDateTime), (routingStep / 86400))
  }
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    if (is.na(.c <- ((.G_Link[[j + 1]])$targetSetting != (.G_Link[[j + 1]])$setting)) || .c) {
      if (!is.na(.c <- (((.G_Link[[j + 1]])$targetSetting * ((.G_Link[[j + 1]])$setting)) == 0)) && .c) {
        {.e1 <- .G_Link[[j + 1]]; .e1$timeLastSet <- currentDate}
      }
      link_setSetting(j, routingStep)
      actionCount <- actionCount + 1
    }
    j <- j + 1
  }
  OldRoutingTime <<- NewRoutingTime
  NewRoutingTime <<- NewRoutingTime + (1000 * routingStep)
  if (!is.na(.c <- (abs(NewRoutingTime - (NewRuleTime + (1000 * .G_RuleStep))) < 1)) && .c) {
    NewRuleTime <<- NewRuleTime + (1000 * .G_RuleStep)
  }
  return(actionCount)
}

# routing.c:312
initSystemInflows <- function() {
  .G_Nobjects <- Nobjects; .G_Node <- Node
  j <- 0
  if (.G_Nobjects$v[[5]] > 0) {
    j <- 0
    while (j < .G_Nobjects$v[[3]]) {
      node_setOldQualState(j)
      j <- j + 1
    }
    j <- 0
    while (j < .G_Nobjects$v[[4]]) {
      link_setOldQualState(j)
      j <- j + 1
    }
  }
  infil_setInfilFactor((-1))
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    {.e1 <- .G_Node[[j + 1]]; .e1$oldLatFlow <- (.G_Node[[j + 1]])$newLatFlow}
    {.e2 <- .G_Node[[j + 1]]; .e2$newLatFlow <- 0}
    j <- j + 1
  }
}

# routing.c:337
isBetweenEvents <- function(currentDate) {
  currentDate
  .G_Event <- Event
  if (NumEvents == 0) {
    return(0)
  }
  if (!is.na(.c <- (currentDate > (.G_Event[[NextEvent + 1]])$end)) && .c) {
    NextEvent <<- NextEvent + 1
    return(1)
  } else if (!is.na(.c <- (currentDate >= (.G_Event[[NextEvent + 1]])$start)) && .c) {
    return(0)
  }
  return(1)
}

# routing.c:359
addSystemInflows <- function(currentDate, routingStep) {
  currentDate; routingStep
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_OldRoutingTime <- OldRoutingTime
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    {.e1 <- .G_Node[[j + 1]]; .e1$losses <- node_getLosses(j, routingStep)}
    j <- j + 1
  }
  addExternalInflows(currentDate)
  addDryWeatherInflows(currentDate)
  addWetWeatherInflows(.G_OldRoutingTime)
  addGroundwaterInflows(.G_OldRoutingTime)
  addLidDrainInflows(.G_OldRoutingTime)
  addRdiiInflows(currentDate)
  addIfaceInflows(currentDate)
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    {.e2 <- .G_Node[[j + 1]]; .e2$qualInflow <- if (!is.na(.c <- (0 >= ((.G_Node[[j + 1]])$newLatFlow))) && .c) 0 else ((.G_Node[[j + 1]])$newLatFlow)}
    j <- j + 1
  }
}

# routing.c:383
isInSteadyState <- function(actionCount, stepFlowError) {
  actionCount; stepFlowError
  if (SkipSteadyState != 0) {
    if ((((!is.na(.c <- (OldRoutingTime == 0)) && .c) || (actionCount > 0)) || (!is.na(.c <- (abs(stepFlowError) > SysFlowTol$v)) && .c)) || (inflowHasChanged() != 0)) {
      return(0)
    } else {
      return(1)
    }
  }
  return(0)
}

# routing.c:399
routeFlow <- function(routingModel, routingStep) {
  routingModel; routingStep
  .G_Nobjects <- Nobjects
  stepCount <- 1
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    link_setOldHydState(j)
    j <- j + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    node_setOldHydState(j)
    j <- j + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    node_initFlows(j, routingStep)
