# routing.c:435
addExternalInflows <- function(currentDate) {
  currentDate
  .G_Nobjects <- Nobjects; .G_Node <- Node
  p <- 0
  q_ <- 0
  w <- 0
  inflow <- NULL
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    q_ <- (.G_Node[[j + 1]])$apiExtInflow
    inflow <- (.G_Node[[j + 1]])$extInflow
    while (!is.null(inflow)) {
      if (inflow$type == 5) {
        q_ <- q_ + (inflow_getExtInflow(inflow, currentDate))
        break
      } else {
        inflow <- inflow$next_
      }
    }
    if (!is.na(.c <- (abs(q_) < 1e-05)) && .c) {
      q_ <- 0
    }
    {.e1 <- .G_Node[[j + 1]]; .e1$newLatFlow <- (.G_Node[[j + 1]])$newLatFlow + q_}
    if (!is.na(.c <- (q_ >= 0)) && .c) {
      massbal_addInflowFlow(0, q_)
    } else {
      massbal_addOutflowFlow((-q_), 0)
      j <- j + 1
      next
    }
    if (((.G_Node[[j + 1]])$type == 1) && (!is.na(.c <- ((.G_Node[[j + 1]])$oldNetInflow < 0)) && .c)) {
      q_ <- q_ - ((.G_Node[[j + 1]])$oldNetInflow)
    }
    inflow <- (.G_Node[[j + 1]])$extInflow
    while (!is.null(inflow)) {
      if (inflow$type != 5) {
        p <- inflow$param
        w <- inflow_getExtInflow(inflow, currentDate)
        if (inflow$type == 6) {
          w <- w * q_
        }
        {.e2 <- (.G_Node[[j + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
        massbal_addInflowQual(0, p, w)
      }
      inflow <- inflow$next_
    }
    j <- j + 1
  }
}

# routing.c:498
addDryWeatherInflows <- function(currentDate) {
  currentDate
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Pollut <- Pollut
  p <- 0
  q_ <- 0
  w <- 0
  inflow <- NULL
  month <- datetime_monthOfYear(currentDate) - 1
  day <- datetime_dayOfWeek(currentDate) - 1
  hour <- datetime_hourOfDay(currentDate)
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    inflow <- (.G_Node[[j + 1]])$dwfInflow
    if (!(!is.null(inflow))) {
      j <- j + 1
      next
    }
    q_ <- 0
    while (!is.null(inflow)) {
      if (inflow$param < 0) {
        q_ <- inflow_getDwfInflow(inflow, month, day, hour)
        break
      }
      inflow <- inflow$next_
    }
    if (!is.na(.c <- (abs(q_) < 1e-05)) && .c) {
      q_ <- 0
    }
    {.e1 <- .G_Node[[j + 1]]; .e1$newLatFlow <- (.G_Node[[j + 1]])$newLatFlow + q_}
    massbal_addInflowFlow(1, q_)
    if (!is.na(.c <- (q_ <= 0)) && .c) {
      j <- j + 1
      next
    }
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      if (!is.na(.c <- ((.G_Pollut[[p + 1]])$dwfConcen > 0)) && .c) {
        w <- q_ * ((.G_Pollut[[p + 1]])$dwfConcen)
        {.e2 <- (.G_Node[[j + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
        massbal_addInflowQual(1, p, w)
      }
      p <- p + 1
    }
    inflow <- (.G_Node[[j + 1]])$dwfInflow
    while (!is.null(inflow)) {
      if (inflow$param >= 0) {
        p <- inflow$param
        w <- q_ * (inflow_getDwfInflow(inflow, month, day, hour))
        {.e3 <- (.G_Node[[j + 1]])$newQual; .e3$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
        massbal_addInflowQual(1, p, w)
        if (!is.na(.c <- ((.G_Pollut[[p + 1]])$dwfConcen > 0)) && .c) {
          w <- q_ * ((.G_Pollut[[p + 1]])$dwfConcen)
          {.e4 <- (.G_Node[[j + 1]])$newQual; .e4$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] - w}
          massbal_addInflowQual(1, p, (-w))
        }
      }
      inflow <- inflow$next_
    }
    j <- j + 1
  }
}

# routing.c:579
addWetWeatherInflows <- function(routingTime) {
  routingTime
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_OldRunoffTime <- OldRunoffTime; .G_Subcatch <- Subcatch
  j <- 0
  p <- 0
  q_ <- 0
  w <- 0
  if (.G_Nobjects$v[[2]] == 0) {
    return(invisible(NULL))
  }
  f <- (routingTime - .G_OldRunoffTime) / (NewRunoffTime - .G_OldRunoffTime)
  if (!is.na(.c <- (f < 0)) && .c) {
    f <- 0
  }
  if (!is.na(.c <- (f > 1)) && .c) {
    f <- 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[2]]) {
    j <- (.G_Subcatch[[i + 1]])$outNode
    if (j >= 0) {
      q_ <- subcatch_getWtdOutflow(i, f)
      {.e1 <- .G_Node[[j + 1]]; .e1$newLatFlow <- (.G_Node[[j + 1]])$newLatFlow + q_}
      massbal_addInflowFlow(2, q_)
      p <- 0
      while (p < .G_Nobjects$v[[5]]) {
        w <- surfqual_getWtdWashoff(i, p, f)
        {.e2 <- (.G_Node[[j + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
        massbal_addInflowQual(2, p, w)
        p <- p + 1
      }
    }
    i <- i + 1
  }
}

# routing.c:621
addGroundwaterInflows <- function(routingTime) {
  routingTime
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_OldRunoffTime <- OldRunoffTime; .G_Pollut <- Pollut; .G_Subcatch <- Subcatch
  j <- 0
  p <- 0
  q_ <- 0
  w <- 0
  gw <- NULL
  if (.G_Nobjects$v[[2]] == 0) {
    return(invisible(NULL))
  }
  f <- (routingTime - .G_OldRunoffTime) / (NewRunoffTime - .G_OldRunoffTime)
  if (!is.na(.c <- (f < 0)) && .c) {
    f <- 0
  }
  if (!is.na(.c <- (f > 1)) && .c) {
    f <- 1
  }
  i <- 0
  while (i < .G_Nobjects$v[[2]]) {
    gw <- (.G_Subcatch[[i + 1]])$groundwater
    if (!is.null(gw)) {
      j <- gw$node
      if (j >= 0) {
        q_ <- (((1 - f) * gw$oldFlow) + (f * gw$newFlow)) * ((.G_Subcatch[[i + 1]])$area)
        if (!is.na(.c <- (abs(q_) < 1e-05)) && .c) {
          i <- i + 1
          next
        }
        {.e1 <- .G_Node[[j + 1]]; .e1$newLatFlow <- (.G_Node[[j + 1]])$newLatFlow + q_}
        massbal_addInflowFlow(3, q_)
        if (!is.na(.c <- (q_ > 0)) && .c) {
          p <- 0
          while (p < .G_Nobjects$v[[5]]) {
            w <- q_ * ((.G_Pollut[[p + 1]])$gwConcen)
            {.e2 <- (.G_Node[[j + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]] + w}
            massbal_addInflowQual(3, p, w)
            p <- p + 1
          }
        }
      }
    }
    i <- i + 1
  }
}

# routing.c:674
addLidDrainInflows <- function(routingTime) {
  routingTime
  .G_Nobjects <- Nobjects; .G_OldRunoffTime <- OldRunoffTime; .G_Subcatch <- Subcatch
  if (.G_Nobjects$v[[2]] == 0) {
    return(invisible(NULL))
  }
  f <- (routingTime - .G_OldRunoffTime) / (NewRunoffTime - .G_OldRunoffTime)
  if (!is.na(.c <- (f < 0)) && .c) {
    f <- 0
  }
  if (!is.na(.c <- (f > 1)) && .c) {
    f <- 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    if ((!is.na(.c <- ((.G_Subcatch[[j + 1]])$area > 0)) && .c) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$lidArea > 0)) && .c)) {
      lid_addDrainInflow(j, f)
    }
    j <- j + 1
  }
}

