# routing.c:776
inflowHasChanged <- function() {
  .G_LatFlowTol <- LatFlowTol; .G_Nobjects <- Nobjects; .G_Node <- Node
  diff_ <- 0
  qOld <- 0
  qNew <- 0
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    qOld <- (.G_Node[[j + 1]])$oldLatFlow
    qNew <- (.G_Node[[j + 1]])$newLatFlow
    if (!is.na(.c <- (abs(qOld) > 1e-06)) && .c) {
      diff_ <- (qNew / qOld) - 1
    } else if (!is.na(.c <- (abs(qNew) > 1e-06)) && .c) {
      diff_ <- 1
    } else {
      diff_ <- 0
    }
    if (!is.na(.c <- (abs(diff_) > .G_LatFlowTol$v)) && .c) {
      return(1)
    }
    if (((.G_Node[[j + 1]])$type == 1) || ((.G_Node[[j + 1]])$degree == 0)) {
      qOld <- (.G_Node[[j + 1]])$oldFlowInflow
      qNew <- (.G_Node[[j + 1]])$inflow
      if (!is.na(.c <- (abs(qOld) > 1e-06)) && .c) {
        diff_ <- (qNew / qOld) - 1
      } else if (!is.na(.c <- (abs(qNew) > 1e-06)) && .c) {
        diff_ <- 1
      } else {
        diff_ <- 0
      }
      if (!is.na(.c <- (abs(diff_) > .G_LatFlowTol$v)) && .c) {
        return(1)
      }
    }
    j <- j + 1
  }
  return(0)
}

