# routing.c:872
removeOutflows <- function(tStep) {
  tStep
  .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Outfall <- Outfall
  p <- 0
  k <- 0
  isFlooded <- 0
  q_ <- 0
  w <- 0
  v <- 0
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if (((.G_Node[[i + 1]])$type == 1) && (!is.na(.c <- ((.G_Node[[i + 1]])$inflow > 0)) && .c)) {
      k <- (.G_Node[[i + 1]])$subIndex
      if ((.G_Outfall[[k + 1]])$routeTo >= 0) {
        v <- (.G_Node[[i + 1]])$inflow * tStep
        {.e1 <- .G_Outfall[[k + 1]]; .e1$vRouted <- (.G_Outfall[[k + 1]])$vRouted + v}
        p <- 0
        while (p < .G_Nobjects$v[[5]]) {
          {.e2 <- (.G_Outfall[[k + 1]])$wRouted; .e2$v[[p + 1]] <- ((.G_Outfall[[k + 1]])$wRouted)$v[[p + 1]] + (((.G_Node[[i + 1]])$newQual)$v[[p + 1]] * v)}
          p <- p + 1
        }
      }
    }
    q_ <- {.BX_removeOutflows_isFlooded$v <- isFlooded; .r3 <- node_getSystemOutflow(i, .BX_removeOutflows_isFlooded); isFlooded <- .BX_removeOutflows_isFlooded$v; .r3}
    if (!is.na(.c <- (q_ > 0)) && .c) {
      massbal_addOutflowFlow(q_, isFlooded)
      p <- 0
      while (p < .G_Nobjects$v[[5]]) {
        w <- q_ * (((.G_Node[[i + 1]])$newQual)$v[[p + 1]])
        massbal_addOutflowQual(p, w, isFlooded)
        p <- p + 1
      }
    } else {
      massbal_addInflowFlow(0, (-q_))
    }
    q_ <- (.G_Node[[i + 1]])$newLatFlow
    if (!is.na(.c <- (q_ < 0)) && .c) {
      p <- 0
      while (p < .G_Nobjects$v[[5]]) {
        w <- (-q_) * (((.G_Node[[i + 1]])$newQual)$v[[p + 1]])
        massbal_addOutflowQual(p, w, 0)
        p <- p + 1
      }
    }
    i <- i + 1
  }
}

# routing.c:929
sortEvents <- function() {
  .G_Event <- Event; .G_NumEvents <- NumEvents
  i <- 0
  j <- 0
  temp <- T_TEvent()
  gap <- trunc(.G_NumEvents / 2)
  while (gap >= 1) {
    i <- gap
    while (i < .G_NumEvents) {
      C_TEvent(temp, .G_Event[[i + 1]])
      j <- i - gap
      while ((j >= 0) && (!is.na(.c <- ((.G_Event[[j + 1]])$start > temp$start)) && .c)) {
        C_TEvent(.G_Event[[(j + gap) + 1]], .G_Event[[j + 1]])
        j <- j - gap
      }
      if (j != (i - gap)) {
        C_TEvent(.G_Event[[(j + gap) + 1]], temp)
      }
      i <- i + gap
    }
    gap <- trunc(gap / 2)
  }
  i <- 0
  while (i < (.G_NumEvents - 1)) {
    if (!is.na(.c <- ((.G_Event[[i + 1]])$end > (.G_Event[[(i + 1) + 1]])$start)) && .c) {
      {.e1 <- .G_Event[[i + 1]]; .e1$end <- (.G_Event[[(i + 1) + 1]])$start}
    }
    i <- i + 1
  }
}

# runoff.c:82
runoff_open <- function() {
  .G_Frunoff <- Frunoff; .G_Nobjects <- Nobjects
  IsRaining <<- 0
  HasRunoff <<- 0
  HasSnow <<- 0
  runoff_Nsteps$v <<- 0
  if (!(odesolve_open(4) != 0)) {
    report_writeErrorMsg(105, .L0)
  }
  OutflowLoad <<- NULL
  if (.G_Nobjects$v[[5]] > 0) {
    OutflowLoad <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[5]])))
    if (!(!is.null(OutflowLoad))) {
      report_writeErrorMsg(101, .L0)
    }
  }
  .sw1 <- .G_Frunoff$mode
  if (.sw1 == 2) {
    if (is.null((.G_Frunoff$file <- rt_fopen(.G_Frunoff$name, .L165)))) {
      report_writeErrorMsg(323, .G_Frunoff$name)
    } else {
      runoff_initFile()
    }
  } else if (.sw1 == 3) {
    if (is.null((.G_Frunoff$file <- rt_fopen(.G_Frunoff$name, .L166)))) {
      report_writeErrorMsg(323, .G_Frunoff$name)
    } else {
      runoff_initFile()
    }
  }
  return(ErrorCode)
}

# runoff.c:124
runoff_close <- function() {
  .G_Fclimate <- Fclimate; .G_Frunoff <- Frunoff
