    if (.G_Frunoff$mode == 3) {
      rt_fseek(.G_Frunoff$file, MaxStepsPos, 0)
      rt_fwrite1("i", 4, runoff_Nsteps$v, .G_Frunoff$file)
    }
    rt_fclose(.G_Frunoff$file)
  }
  if (!is.null(.G_Fclimate$file)) {
    rt_fclose(.G_Fclimate$file)
  }
}

# runoff.c:155
runoff_execute <- function() {
  .G_Frunoff <- Frunoff; .G_Gage <- Gage; .G_IgnoreQuality <- IgnoreQuality; .G_IgnoreSnowmelt <- IgnoreSnowmelt; .G_Nobjects <- Nobjects; .G_Subcatch <- Subcatch; .G_SweepEnd <- SweepEnd; .G_SweepStart <- SweepStart; .G_TotalDuration <- TotalDuration
  runoff <- 0
  if (ErrorCode != 0) {
    return(invisible(NULL))
  }
  oldRunoffStep <- (NewRunoffTime - OldRunoffTime) / 1000
  currentDate <- getDateTime(NewRunoffTime)
  climate_setState(currentDate)
  if (.G_Nobjects$v[[2]] == 0) {
    OldRunoffTime <<- NewRunoffTime
    NewRunoffTime <<- NewRunoffTime + (DryStep * 1000)
    NewRunoffTime <<- if (!is.na(.c <- (NewRunoffTime <= .G_TotalDuration)) && .c) NewRunoffTime else .G_TotalDuration
    return(invisible(NULL))
  }
  IsRaining <<- 0
  j <- 0
  while (j < .G_Nobjects$v[[1]]) {
    gage_setState(j, currentDate)
    if (!is.na(.c <- ((.G_Gage[[j + 1]])$rainfall > 0)) && .c) {
      IsRaining <<- 1
    }
    j <- j + 1
  }
  if (.G_Frunoff$mode == 2) {
    runoff_readFromFile()
    return(invisible(NULL))
  }
  day <- datetime_dayOfYear(currentDate)
  canSweep <- 0
  if (.G_SweepStart <= .G_SweepEnd) {
    if ((day >= .G_SweepStart) && (day <= .G_SweepEnd)) {
      canSweep <- 1
    }
  } else if ((day <= .G_SweepEnd) || (day >= .G_SweepStart)) {
    canSweep <- 1
  }
  runoffStep <- runoff_getTimeStep(currentDate)
  if (!is.na(.c <- (runoffStep <= 0)) && .c) {
    ErrorCode <<- 107
    return(invisible(NULL))
  }
  OldRunoffTime <<- NewRunoffTime
  NewRunoffTime <<- NewRunoffTime + (1000 * runoffStep)
  if (!is.na(.c <- (NewRunoffTime > .G_TotalDuration)) && .c) {
    runoffStep <- (.G_TotalDuration - OldRunoffTime) / 1000
    NewRunoffTime <<- .G_TotalDuration
  }
  j <- 0
  while (j < .G_Nobjects$v[[1]]) {
    gage_updatePastRain(j, (if (is.na(.d <- runoffStep) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)))
    j <- j + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    subcatch_setOldState(j)
    j <- j + 1
  }
  if (!is.na(.c <- (oldRunoffStep > 0)) && .c) {
    runoff_getOutfallRunon(oldRunoffStep)
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$area == 0)) && .c) {
      j <- j + 1
      next
    }
    subcatch_getRunon(j)
    if (!(.G_IgnoreSnowmelt != 0)) {
      snow_plowSnow(j, runoffStep)
    }
    j <- j + 1
  }
  HasSnow <<- 0
  HasRunoff <<- 0
  HasWetLids <<- 0
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$area == 0)) && .c) {
      j <- j + 1
      next
    }
    runoff <- subcatch_getRunoff(j, runoffStep)
    if (!is.na(.c <- (runoff > 0)) && .c) {
      HasRunoff <<- 1
    }
    if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$newSnowDepth > 0)) && .c) {
      HasSnow <<- 1
    }
    if (.G_IgnoreQuality != 0) {
      j <- j + 1
      next
    }
    if (!is.na(.c <- (runoff < 2.31481e-08)) && .c) {
      surfqual_getBuildup(j, runoffStep)
    }
    if ((canSweep != 0) && (!is.na(.c <- ((.G_Subcatch[[j + 1]])$rainfall <= 2.31481e-08)) && .c)) {
      surfqual_sweepBuildup(j, currentDate)
    }
    surfqual_getWashoff(j, runoff, runoffStep)
    j <- j + 1
  }
  stats_updateMaxRunoff()
  runoff_Nsteps$v <<- runoff_Nsteps$v + 1
  if (.G_Frunoff$mode == 3) {
    runoff_saveToFile(rt_f32(runoffStep))
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    {.e1 <- .G_Subcatch[[j + 1]]; .e1$runon <- 0}
    j <- j + 1
  }
}

# runoff.c:299
runoff_getTimeStep <- function(currentDate) {
  currentDate
  .G_DryStep <- DryStep; .G_Nobjects <- Nobjects
  maxStep <- .G_DryStep
  timeStep <- datetime_timeDiff(climate_getNextEvapDate(), currentDate)
  if ((!is.na(.c <- (timeStep > 0)) && .c) && (timeStep < maxStep)) {
    maxStep <- timeStep
  }
  j <- 0
  while (j < .G_Nobjects$v[[1]]) {
    timeStep <- datetime_timeDiff(gage_getNextRainDate(j, currentDate), currentDate)
    if ((timeStep > 0) && (timeStep < maxStep)) {
      maxStep <- timeStep
    }
    j <- j + 1
  }
  if ((((IsRaining != 0) || (HasSnow != 0)) || (HasRunoff != 0)) || (HasWetLids != 0)) {
    timeStep <- WetStep
  } else {
    timeStep <- .G_DryStep
  }
  if (timeStep > maxStep) {
    timeStep <- maxStep
  }
  return(timeStep)
}

# runoff.c:335
runoff_initFile <- function() {
  .G_FlowUnits <- FlowUnits; .G_Frunoff <- Frunoff; .G_MaxSteps <- MaxSteps; .G_Nobjects <- Nobjects
  nSubcatch <- 0
  nPollut <- 0
  flowUnits <- 0
  fileStamp <- rt_cbuf_from(.L533, 13)
  fStamp <- rt_cbuf_from(.L533, 13)
  .G_MaxSteps$v <- 0
  if (.G_Frunoff$mode == 3) {
    nSubcatch <- .G_Nobjects$v[[2]]
    nPollut <- .G_Nobjects$v[[5]]
    flowUnits <- .G_FlowUnits
    rt_fwrite_arr("c", 1, fileStamp, 0, rt_strlen(fileStamp), .G_Frunoff$file)
    rt_fwrite1("i", 4, nSubcatch, .G_Frunoff$file)
    rt_fwrite1("i", 4, nPollut, .G_Frunoff$file)
    rt_fwrite1("i", 4, flowUnits, .G_Frunoff$file)
    MaxStepsPos <<- rt_ftell(.G_Frunoff$file)
    rt_fwrite1("i", 4, .G_MaxSteps$v, .G_Frunoff$file)
  }
  if (.G_Frunoff$mode == 2) {
    rt_fread_arr("c", 1, fStamp, 0, rt_strlen(fileStamp), .G_Frunoff$file)
    if (rt_strcmp(fStamp, fileStamp) != 0) {
      report_writeErrorMsg(325, .L0)
      return(invisible(NULL))
    }
    nSubcatch <- -1
    nPollut <- -1
    flowUnits <- -1
    {.BX_runoff_initFile_nSubcatch$v <- nSubcatch; .r1 <- rt_fread1("i", 4, .BX_runoff_initFile_nSubcatch, .G_Frunoff$file); nSubcatch <- .BX_runoff_initFile_nSubcatch$v; .r1}
    {.BX_runoff_initFile_nPollut$v <- nPollut; .r2 <- rt_fread1("i", 4, .BX_runoff_initFile_nPollut, .G_Frunoff$file); nPollut <- .BX_runoff_initFile_nPollut$v; .r2}
    {.BX_runoff_initFile_flowUnits$v <- flowUnits; .r3 <- rt_fread1("i", 4, .BX_runoff_initFile_flowUnits, .G_Frunoff$file); flowUnits <- .BX_runoff_initFile_flowUnits$v; .r3}
    rt_fread1("i", 4, .G_MaxSteps, .G_Frunoff$file)
    if ((((nSubcatch != .G_Nobjects$v[[2]]) || (nPollut != .G_Nobjects$v[[5]])) || (flowUnits != .G_FlowUnits)) || (.G_MaxSteps$v <= 0)) {
      report_writeErrorMsg(325, .L0)
    }
  }
}

# runoff.c:391
runoff_saveToFile <- function(tStep) {
  tStep
  .G_Frunoff <- Frunoff; .G_Nobjects <- Nobjects; .G_SubcatchResults <- SubcatchResults
  n <- (9 + .G_Nobjects$v[[5]]) - 1
  rt_fwrite1("f", 4, tStep, .G_Frunoff$file)
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    subcatch_getResults(j, 1, .G_SubcatchResults)
    rt_fwrite_arr("f", 4, .G_SubcatchResults, 0, rt_u64(n), .G_Frunoff$file)
    j <- j + 1
  }
