# runoff.c:412
runoff_readFromFile <- function() {
  .G_Aquifer <- Aquifer; .G_Frunoff <- Frunoff; .G_Nobjects <- Nobjects; .G_Subcatch <- Subcatch; .G_SubcatchResults <- SubcatchResults; .G_TotalDuration <- TotalDuration; .G_runoff_Nsteps <- runoff_Nsteps
  i <- 0
  tStep <- 0
  gw <- NULL
  if (.G_runoff_Nsteps$v > MaxSteps$v) {
    report_writeErrorMsg(327, .L0)
    return(invisible(NULL))
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    subcatch_setOldState(j)
    j <- j + 1
  }
  kount <- 0
  kount <- kount + (rt_i32({.BX_runoff_readFromFile_tStep$v <- tStep; .r1 <- rt_fread1("f", 4, .BX_runoff_readFromFile_tStep, .G_Frunoff$file); tStep <- .BX_runoff_readFromFile_tStep$v; .r1}))
  nResults <- (9 + .G_Nobjects$v[[5]]) - 1
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    kount <- kount + (rt_i32(rt_fread_arr("f", 4, .G_SubcatchResults, 0, rt_u64(nResults), .G_Frunoff$file)))
    {.e2 <- .G_Subcatch[[j + 1]]; .e2$newSnowDepth <- .G_SubcatchResults$v[[2]] / (UCF(1))}
    {.e3 <- .G_Subcatch[[j + 1]]; .e3$evapLoss <- .G_SubcatchResults$v[[3]] / (UCF(0))}
    {.e4 <- .G_Subcatch[[j + 1]]; .e4$infilLoss <- .G_SubcatchResults$v[[4]] / (UCF(0))}
    {.e5 <- .G_Subcatch[[j + 1]]; .e5$newRunoff <- .G_SubcatchResults$v[[5]] / (UCF(10))}
    gw <- (.G_Subcatch[[j + 1]])$groundwater
    if (!is.null(gw)) {
      gw$newFlow <- .G_SubcatchResults$v[[6]] / (UCF(10))
      gw$lowerDepth <- (.G_Aquifer[[gw$aquifer + 1]])$bottomElev - (.G_SubcatchResults$v[[7]] / (UCF(3)))
      gw$theta <- .G_SubcatchResults$v[[8]]
    }
    i <- 0
    while (i < .G_Nobjects$v[[5]]) {
      {.e6 <- (.G_Subcatch[[j + 1]])$newQual; .e6$v[[i + 1]] <- .G_SubcatchResults$v[[(8 + i) + 1]]}
      i <- i + 1
    }
    j <- j + 1
  }
  if (kount < (1 + (.G_Nobjects$v[[2]] * nResults))) {
    report_writeErrorMsg(329, .L0)
    return(invisible(NULL))
  }
  OldRunoffTime <<- NewRunoffTime
  NewRunoffTime <<- OldRunoffTime + (tStep * 1000)
  NewRunoffTime <<- if (!is.na(.c <- (NewRunoffTime <= .G_TotalDuration)) && .c) NewRunoffTime else .G_TotalDuration
  .G_runoff_Nsteps$v <- .G_runoff_Nsteps$v + 1
}

# runoff.c:491
runoff_getOutfallRunon <- function(tStep) {
  tStep
  .G_Nnodes <- Nnodes; .G_Nobjects <- Nobjects; .G_Outfall <- Outfall; .G_Pollut <- Pollut; .G_Subcatch <- Subcatch
  k <- 0
  p <- 0
  w <- 0
  i <- 0
  while (i < .G_Nnodes$v[[2]]) {
    k <- (.G_Outfall[[i + 1]])$routeTo
    if (k < 0) {
      i <- i + 1
      next
    }
    if (!is.na(.c <- ((.G_Subcatch[[k + 1]])$area == 0)) && .c) {
      i <- i + 1
      next
    }
    subcatch_addRunonFlow(k, ((.G_Outfall[[i + 1]])$vRouted / tStep))
    massbal_updateRunoffTotals(5, (.G_Outfall[[i + 1]])$vRouted)
    {.e1 <- .G_Outfall[[i + 1]]; .e1$vRouted <- 0}
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      w <- ((.G_Outfall[[i + 1]])$wRouted)$v[[p + 1]] * 28.317
      massbal_updateLoadingTotals(1, p, (w * ((.G_Pollut[[p + 1]])$mcf)))
      {.e2 <- (.G_Subcatch[[k + 1]])$newQual; .e2$v[[p + 1]] <- ((.G_Subcatch[[k + 1]])$newQual)$v[[p + 1]] + (w / tStep)}
      {.e3 <- (.G_Outfall[[i + 1]])$wRouted; .e3$v[[p + 1]] <- 0}
      p <- p + 1
    }
    i <- i + 1
  }
}

