    }
    {.e7 <- shape$widthTbl; .e7$v[[i + 1]] <- w}
    {.e8 <- shape$areaTbl; .e8$v[[i + 1]] <- Atotal}
    if (!is.na(.c <- (Ptotal > 0)) && .c) {
      {.e9 <- shape$hradTbl; .e9$v[[i + 1]] <- Atotal / Ptotal}
