# shape.c:189
getSmax <- function(shape) {
  shape
  n <- shape$nTbl - 1
  sf <- 0
  shape$sMax <- 0
  shape$aMax <- 0
  i <- 1
  while (i <= n) {
    sf <- shape$areaTbl$v[[i + 1]] * (if ((.p <- shape$hradTbl$v[[i + 1]]) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666))
    if (!is.na(.c <- (sf > shape$sMax)) && .c) {
      shape$sMax <- sf
      shape$aMax <- shape$areaTbl$v[[i + 1]]
    }
    i <- i + 1
  }
}

# shape.c:216
normalizeShapeTables <- function(shape) {
  shape
  n <- shape$nTbl - 1
  aFull <- shape$aFull
  rFull <- shape$rFull
  wMax <- shape$wMax
  if (((!is.na(.c <- (aFull == 0)) && .c) || (!is.na(.c <- (rFull == 0)) && .c)) || (!is.na(.c <- (wMax == 0)) && .c)) {
    return(0)
  }
  i <- 0
  while (i <= n) {
    {.e1 <- shape$areaTbl; .e1$v[[i + 1]] <- shape$areaTbl$v[[i + 1]] / aFull}
    {.e2 <- shape$hradTbl; .e2$v[[i + 1]] <- shape$hradTbl$v[[i + 1]] / rFull}
    {.e3 <- shape$widthTbl; .e3$v[[i + 1]] <- shape$widthTbl$v[[i + 1]] / wMax}
    i <- i + 1
  }
  return(1)
}

# shape.c:246
getNextInterval <- function(curve, y, yLast, wLast, y1, y2, w1, w2, wMax) {
  curve; y; yLast; wLast; y1; y2; w1; w2; wMax
  while (!is.na(.c <- (y > y2$v)) && .c) {
    if (!is.na(.c <- (y2$v > yLast)) && .c) {
      Atotal <<- Atotal + (shape_getArea(y2$v, w2$v, yLast, wLast))
      Ptotal <<- Ptotal + (getPerim(y2$v, w2$v, yLast, wLast))
      yLast <- y2$v
      wLast <- w2$v
    }
    y1$v <- y2$v
    w1$v <- w2$v
    if (!(table_getNextEntry(curve, y2, w2) != 0)) {
      y2$v <- 1
      return(1)
    }
    if (!is.na(.c <- (w2$v > wMax$v)) && .c) {
      wMax$v <- w2$v
    }
    if ((!is.na(.c <- (y2$v < y1$v)) && .c) || (!is.na(.c <- (w2$v < 0)) && .c)) {
      return(0)
    }
    if (!is.na(.c <- (y2$v > 1)) && .c) {
      y2$v <- 1
    }
  }
  return(1)
}

# shape.c:307
shape_getWidth <- function(y, y1, y2, w1, w2) {
  y; y1; y2; w1; w2
  if (!is.na(.c <- (y2 == y1)) && .c) {
    return(w2)
  }
  return(w1 + (((y - y1) / (y2 - y1)) * (w2 - w1)))
}

# shape.c:328
shape_getArea <- function(y, w, y1, w1) {
  y; w; y1; w1
  wMin <- 0
  wMax <- 0
  if (!is.na(.c <- (w > w1)) && .c) {
    wMin <- w1
    wMax <- w
  } else {
    wMin <- w
    wMax <- w1
  }
  return((wMin + ((wMax - wMin) / 2)) * (y - y1))
}

# shape.c:353
getPerim <- function(y, w, y1, w1) {
  y; w; y1; w1
  dy <- y - y1
  dw <- abs(w - w1) / 2
  return(2 * (sqrt((dy * dy) + (dw * dw))))
}

