        m <- (.G_Snowmelt[[k + 1]])$toSubcatch
        if (!is.null((.G_Subcatch[[m + 1]])$snowpack)) {
          f <- (((.G_Subcatch[[m + 1]])$snowpack)$fArea)$v[[3]]
        } else {
          f <- 0
        }
        if (!is.na(.c <- (f > 0)) && .c) {
          f <- snowpack$fArea$v[[1]] / f
          {.e8 <- ((.G_Subcatch[[m + 1]])$snowpack)$wsnow; .e8$v[[3]] <- (((.G_Subcatch[[m + 1]])$snowpack)$wsnow)$v[[3]] + ((((.G_Snowmelt[[k + 1]])$sfrac)$v[[5]] * exc) * f)}
          sfracTotal <- sfracTotal + (((.G_Snowmelt[[k + 1]])$sfrac)$v[[5]])
        }
      }
      sfracTotal <- if (!is.na(.c <- (sfracTotal <= 1)) && .c) sfracTotal else 1
      {.e9 <- snowpack$wsnow; .e9$v[[1]] <- exc * (1 - sfracTotal)}
    }
  }
}

# snow.c:458
snow_getSnowMelt <- function(j, rainfall, snowfall, tStep, netPrecip) {
  j; rainfall; snowfall; tStep; netPrecip
  .G_Subcatch <- Subcatch
  smelt <- 0
  asc <- 0
  snowDepth <- 0
  impervPrecip <- 0
  snowpack <- (.G_Subcatch[[j + 1]])$snowpack
  rmelt <- getRainmelt(rainfall)
  i <- 0
  while (i <= 2) {
    if (!is.na(.c <- (snowpack$wsnow$v[[i + 1]] <= (0.001 / 12))) && .c) {
      asc <- 0
      smelt <- 0
      {.e1 <- snowpack$imelt; .e1$v[[i + 1]] <- snowpack$imelt$v[[i + 1]] + ((snowpack$wsnow$v[[i + 1]] + snowpack$fw$v[[i + 1]]) / tStep)}
      {.e2 <- snowpack$wsnow; .e2$v[[i + 1]] <- 0}
      {.e3 <- snowpack$fw; .e3$v[[i + 1]] <- 0}
      {.e4 <- snowpack$coldc; .e4$v[[i + 1]] <- 0}
    } else {
      asc <- getArealDepletion(snowpack, i, snowfall, tStep)
      smelt <- meltSnowpack(snowpack, i, rmelt, asc, snowfall, tStep)
      smelt <- routeSnowmelt(snowpack, i, smelt, asc, rainfall, tStep)
    }
    netPrecip$v[[i + 1]] <- (smelt + snowpack$imelt$v[[i + 1]]) + (rainfall * (1 - asc))
    snowDepth <- snowDepth + (snowpack$wsnow$v[[i + 1]] * (snowpack$fArea$v[[i + 1]]))
    i <- i + 1
  }
  if (!is.na(.c <- ((.G_Subcatch[[j + 1]])$fracImperv > 0)) && .c) {
    impervPrecip <- ((netPrecip$v[[1]] * snowpack$fArea$v[[1]]) + (netPrecip$v[[2]] * snowpack$fArea$v[[2]])) / ((.G_Subcatch[[j + 1]])$fracImperv)
    netPrecip$v[[1]] <- impervPrecip
    netPrecip$v[[2]] <- impervPrecip
  }
  return(snowDepth)
}

# snow.c:532
snow_getSnowCover <- function(j) {
  j
  .G_Subcatch <- Subcatch
  snowCover <- 0
  snowpack <- (.G_Subcatch[[j + 1]])$snowpack
  if (!(!is.null(snowpack))) {
    return(0)
  }
  i <- 0
