    snowCover <- snowCover + ((snowpack$wsnow$v[[i + 1]] + snowpack$fw$v[[i + 1]]) * (snowpack$fArea$v[[i + 1]]))
    i <- i + 1
  }
  return(snowCover * ((.G_Subcatch[[j + 1]])$area - ((.G_Subcatch[[j + 1]])$lidArea)))
}

# snow.c:555
getArealDepletion <- function(snowpack, i, snowfall, tStep) {
  snowpack; i; snowfall; tStep
  asc <- 0
  awesi <- 0
  awe <- 0
  sba <- 0
  sbws <- 0
  if (i == 0) {
    return(1)
  }
  k <- snowpack$snowmeltIndex
  si <- ((Snowmelt[[k + 1]])$si)$v[[i + 1]]
  if ((!is.na(.c <- (si == 0)) && .c) || (!is.na(.c <- (snowpack$wsnow$v[[i + 1]] >= si)) && .c)) {
    {.e1 <- snowpack$awe; .e1$v[[i + 1]] <- 1}
    return(1)
  }
  if (!is.na(.c <- (snowpack$wsnow$v[[i + 1]] == 0)) && .c) {
    {.e2 <- snowpack$awe; .e2$v[[i + 1]] <- 1}
    return(0)
  }
  if (!is.na(.c <- (snowfall > 0)) && .c) {
    awe <- (snowpack$wsnow$v[[i + 1]] - (snowfall * tStep)) / si
    awe <- if (!is.na(.c <- (awe >= 0)) && .c) awe else 0
    sba <- getArealSnowCover(i, awe)
    sbws <- awe + (((0.75 * snowfall) * tStep) / si)
    sbws <- if (!is.na(.c <- (sbws <= 1)) && .c) sbws else 1
    {.e3 <- snowpack$awe; .e3$v[[i + 1]] <- awe}
    {.e4 <- snowpack$sba; .e4$v[[i + 1]] <- sba}
    {.e5 <- snowpack$sbws; .e5$v[[i + 1]] <- sbws}
    return(1)
  } else {
    awe <- snowpack$awe$v[[i + 1]]
    sba <- snowpack$sba$v[[i + 1]]
    sbws <- snowpack$sbws$v[[i + 1]]
    awesi <- snowpack$wsnow$v[[i + 1]] / si
    if (!is.na(.c <- (awesi < snowpack$awe$v[[i + 1]])) && .c) {
      {.e6 <- snowpack$awe; .e6$v[[i + 1]] <- 1}
      asc <- getArealSnowCover(i, awesi)
    } else if (!is.na(.c <- (awesi >= snowpack$sbws$v[[i + 1]])) && .c) {
      asc <- 1
    } else {
      asc <- sba + (((1 - sba) / (sbws - awe)) * (awesi - awe))
    }
    return(asc)
  }
}

# snow.c:636
getArealSnowCover <- function(i, awesi) {
  i; awesi
  .G_Snow <- Snow
  k <- 0
  asc2 <- 0
  if (i == 1) {
    k <- 0
  } else if (i == 2) {
    k <- 1
  } else {
    return(1)
  }
  if (!is.na(.c <- (awesi <= 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (awesi >= 0.9999)) && .c) {
    return(1)
  }
  m <- if (is.na(.d <- (awesi * 10) + 1e-05) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  asc1 <- (.G_Snow$adc$v[[k + 1]])$v[[m + 1]]
  if (m >= 9) {
    asc2 <- 1
  } else {
    asc2 <- (.G_Snow$adc$v[[k + 1]])$v[[(m + 1) + 1]]
  }
  return(asc1 + (((asc2 - asc1) / 0.1) * (awesi - (0.1 * (rt_f32(m))))))
}

# snow.c:674
meltSnowpack <- function(snowpack, i, rmelt, asc, snowfall, tStep) {
  snowpack; i; rmelt; asc; snowfall; tStep
  .G_Snowmelt <- Snowmelt; .G_Temp <- Temp
  smelt <- 0
  k <- snowpack$snowmeltIndex
  if (!is.na(.c <- (rmelt > 0)) && .c) {
    smelt <- rmelt
  } else if (!is.na(.c <- (.G_Temp$ta >= ((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]])) && .c) {
    smelt <- ((.G_Snowmelt[[k + 1]])$dhm)$v[[i + 1]] * (.G_Temp$ta - (((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]]))
  } else {
    updateColdContent(snowpack, i, asc, snowfall, tStep)
    return(0)
  }
  smelt <- smelt * asc
  ccFactor <- (tStep * Snow$rnm) * asc
  smelt <- reduceColdContent(snowpack, i, smelt, ccFactor)
  {.e1 <- snowpack$ati; .e1$v[[i + 1]] <- ((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]]}
  return(smelt)
}

# snow.c:720
getRainmelt <- function(rainfall) {
  rainfall
  .G_Temp <- Temp
  uadj <- 0
  t1 <- 0
  t2 <- 0
  t3 <- 0
  smelt <- 0
  rainfall <- rainfall * 43200
  if (!is.na(.c <- (rainfall > 0.02)) && .c) {
    uadj <- 0.006 * Wind$ws
    t1 <- .G_Temp$ta - 32
    t2 <- (7.5 * .G_Temp$gamma) * uadj
    t3 <- (8.5 * uadj) * (.G_Temp$ea - 0.18)
    smelt <- (t1 * ((0.001167 + t2) + (0.007 * rainfall))) + t3
    return(smelt / 43200)
  } else {
    return(0)
  }
}

# snow.c:746
updateColdContent <- function(snowpack, i, asc, snowfall, tStep) {
  snowpack; i; asc; snowfall; tStep
  .G_Snow <- Snow; .G_Snowmelt <- Snowmelt; .G_Temp <- Temp
  tipm <- 0
  ati <- snowpack$ati$v[[i + 1]]
  cc <- snowpack$coldc$v[[i + 1]]
  if (!is.na(.c <- ((snowfall * 43200) > 0.02)) && .c) {
    ati <- .G_Temp$ta
  } else {
    tipm <- 1 - (rt_pow(1 - .G_Snow$tipm, tStep / (6 * 3600)))
    ati <- ati + (tipm * (.G_Temp$ta - ati))
  }
  k <- snowpack$snowmeltIndex
  ati <- if (!is.na(.c <- (ati <= (((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]]))) && .c) ati else (((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]])
  cc <- cc + ((((.G_Snow$rnm * (((.G_Snowmelt[[k + 1]])$dhm)$v[[i + 1]])) * (ati - .G_Temp$ta)) * tStep) * asc)
  cc <- if (!is.na(.c <- (cc >= 0)) && .c) cc else 0
  ccMax <- ((snowpack$wsnow$v[[i + 1]] * 0.007) / 12) * (((.G_Snowmelt[[k + 1]])$tbase)$v[[i + 1]] - ati)
  cc <- if (!is.na(.c <- (cc <= ccMax)) && .c) cc else ccMax
  {.e1 <- snowpack$coldc; .e1$v[[i + 1]] <- cc}
  {.e2 <- snowpack$ati; .e2$v[[i + 1]] <- ati}
}

# snow.c:799
reduceColdContent <- function(snowpack, i, smelt, ccFactor) {
  snowpack; i; smelt; ccFactor
  cc <- snowpack$coldc$v[[i + 1]]
  if (!is.na(.c <- ((smelt * ccFactor) > cc)) && .c) {
    smelt <- smelt - (cc / ccFactor)
    cc <- 0
  } else {
    cc <- cc - (smelt * ccFactor)
    smelt <- 0
  }
  {.e1 <- snowpack$coldc; .e1$v[[i + 1]] <- cc}
  return(smelt)
}

# snow.c:828
routeSnowmelt <- function(snowpack, i, smelt, asc, rainfall, tStep) {
  snowpack; i; smelt; asc; rainfall; tStep
  k <- snowpack$snowmeltIndex
  vmelt <- smelt * tStep
  vmelt <- if (!is.na(.c <- (vmelt <= (snowpack$wsnow$v[[i + 1]]))) && .c) vmelt else (snowpack$wsnow$v[[i + 1]])
  {.e1 <- snowpack$wsnow; .e1$v[[i + 1]] <- snowpack$wsnow$v[[i + 1]] - vmelt}
  {.e2 <- snowpack$fw; .e2$v[[i + 1]] <- snowpack$fw$v[[i + 1]] + (vmelt + ((rainfall * tStep) * asc))}
  vmelt <- snowpack$fw$v[[i + 1]] - (((Snowmelt[[k + 1]])$fwfrac)$v[[i + 1]] * (snowpack$wsnow$v[[i + 1]]))
  vmelt <- if (!is.na(.c <- (vmelt >= 0)) && .c) vmelt else 0
  {.e3 <- snowpack$fw; .e3$v[[i + 1]] <- snowpack$fw$v[[i + 1]] - vmelt}
  return(vmelt / tStep)
}

