    {.e10 <- .G_StorageStats[[k + 1]]; .e10$exfilLosses <- (.G_StorageStats[[k + 1]])$exfilLosses + ((.G_Storage[[(.G_Node[[j + 1]])$subIndex + 1]])$exfilLoss)}
