    {.e1 <- .G_LinkStats[[j + 1]]; .e1$maxFlow <- q_}
    {.e2 <- .G_LinkStats[[j + 1]]; .e2$maxFlowDate <- aDate}
  }
  v <- link_getVelocity(j, q_, (.G_Link[[j + 1]])$newDepth)
  if (!is.na(.c <- (v > (.G_LinkStats[[j + 1]])$maxVeloc)) && .c) {
    {.e3 <- .G_LinkStats[[j + 1]]; .e3$maxVeloc <- v}
