  }
  if ((.G_Link[[j + 1]])$type == 1) {
    if (!is.na(.c <- (q_ >= (.G_Link[[j + 1]])$qFull)) && .c) {
      {.e5 <- .G_LinkStats[[j + 1]]; .e5$timeFullFlow <- (.G_LinkStats[[j + 1]])$timeFullFlow + tStep}
    }
    if (!is.na(.c <- (q_ > 0.001)) && .c) {
      k <- (.G_Link[[j + 1]])$subIndex
      {.e6 <- .G_PumpStats[[k + 1]]; .e6$minFlow <- if (!is.na(.c <- (((.G_PumpStats[[k + 1]])$minFlow) <= q_)) && .c) ((.G_PumpStats[[k + 1]])$minFlow) else q_}
      {.e7 <- .G_PumpStats[[k + 1]]; .e7$maxFlow <- (.G_LinkStats[[j + 1]])$maxFlow}
      {.e8 <- .G_PumpStats[[k + 1]]; .e8$avgFlow <- (.G_PumpStats[[k + 1]])$avgFlow + q_}
      {.e9 <- .G_PumpStats[[k + 1]]; .e9$volume <- (.G_PumpStats[[k + 1]])$volume + (q_ * tStep)}
      {.e10 <- .G_PumpStats[[k + 1]]; .e10$utilized <- (.G_PumpStats[[k + 1]])$utilized + tStep}
      {.e11 <- .G_PumpStats[[k + 1]]; .e11$energy <- (.G_PumpStats[[k + 1]])$energy + ((link_getPower(j) * tStep) / 3600)}
      if ((.G_Link[[j + 1]])$flowClass == 2) {
        {.e12 <- .G_PumpStats[[k + 1]]; .e12$offCurveLow <- (.G_PumpStats[[k + 1]])$offCurveLow + tStep}
      }
      if ((.G_Link[[j + 1]])$flowClass == 1) {
        {.e13 <- .G_PumpStats[[k + 1]]; .e13$offCurveHigh <- (.G_PumpStats[[k + 1]])$offCurveHigh + tStep}
      }
      if (!is.na(.c <- ((.G_Link[[j + 1]])$oldFlow < 0.001)) && .c) {
        {.e14 <- .G_PumpStats[[k + 1]]; .e14$startUps <- (.G_PumpStats[[k + 1]])$startUps + 1}
      }
      {.e15 <- .G_PumpStats[[k + 1]]; .e15$totalPeriods <- (.G_PumpStats[[k + 1]])$totalPeriods + 1}
      {.e16 <- .G_LinkStats[[j + 1]]; .e16$timeSurcharged <- (.G_LinkStats[[j + 1]])$timeSurcharged + tStep}
      {.e17 <- .G_LinkStats[[j + 1]]; .e17$timeFullUpstream <- (.G_LinkStats[[j + 1]])$timeFullUpstream + tStep}
      {.e18 <- .G_LinkStats[[j + 1]]; .e18$timeFullDnstream <- (.G_LinkStats[[j + 1]])$timeFullDnstream + tStep}
    }
  } else if ((.G_Link[[j + 1]])$type == 0) {
    if ((.G_Link[[j + 1]])$normalFlow != 0) {
      {.e19 <- .G_LinkStats[[j + 1]]; .e19$timeNormalFlow <- (.G_LinkStats[[j + 1]])$timeNormalFlow + tStep}
    }
    if ((.G_Link[[j + 1]])$inletControl != 0) {
      {.e20 <- .G_LinkStats[[j + 1]]; .e20$timeInletControl <- (.G_LinkStats[[j + 1]])$timeInletControl + tStep}
    }
    k <- (.G_Link[[j + 1]])$flowClass
    if ((k >= 0) && (k < 7)) {
      {.e21 <- (.G_LinkStats[[j + 1]])$timeInFlowClass; .e21$v[[k + 1]] <- ((.G_LinkStats[[j + 1]])$timeInFlowClass)$v[[k + 1]] + tStep}
    }
    k <- (.G_Link[[j + 1]])$subIndex
    if (!is.na(.c <- (q_ >= ((.G_Link[[j + 1]])$qFull * ((.G_Conduit[[k + 1]])$barrels)))) && .c) {
      {.e22 <- .G_LinkStats[[j + 1]]; .e22$timeFullFlow <- (.G_LinkStats[[j + 1]])$timeFullFlow + tStep}
    }
