      {.e26 <- .G_LinkStats[[j + 1]]; .e26$timeFullUpstream <- (.G_LinkStats[[j + 1]])$timeFullUpstream + tStep}
      {.e27 <- .G_LinkStats[[j + 1]]; .e27$timeFullDnstream <- (.G_LinkStats[[j + 1]])$timeFullDnstream + tStep}
    } else if (.sw24 == 8) {
