    }
  }
  k <- (.G_LinkStats[[j + 1]])$flowTurnSign
  {.e31 <- .G_LinkStats[[j + 1]]; .e31$flowTurnSign <- if (!is.na(.c <- (dq < 0)) && .c) (-1) else 1}
  if ((!is.na(.c <- (abs(dq) > 0.001)) && .c) && ((k * ((.G_LinkStats[[j + 1]])$flowTurnSign)) < 0)) {
    {.e32 <- .G_LinkStats[[j + 1]]; .e32$flowTurns <- (.G_LinkStats[[j + 1]])$flowTurns + 1}
