# stats.c:756
stats_findMaxStats <- function() {
  .G_LinkStats <- LinkStats; .G_MaxCourantCrit <- MaxCourantCrit; .G_MaxFlowTurns <- MaxFlowTurns; .G_MaxMassBalErrs <- MaxMassBalErrs; .G_MaxNonConverged <- MaxNonConverged; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_NodeInflow <- NodeInflow; .G_NodeOutflow <- NodeOutflow; .G_NodeStats <- NodeStats; .G_ReportStepCount <- ReportStepCount; .G_RouteModel <- RouteModel
  x <- 0
  z <- 0
  stepCount <- 0
  j <- 0
  while (j < 5) {
    {.e1 <- .G_MaxMassBalErrs[[j + 1]]; .e1$objType <- 2}
    {.e2 <- .G_MaxMassBalErrs[[j + 1]]; .e2$index <- -1}
    {.e3 <- .G_MaxMassBalErrs[[j + 1]]; .e3$value <- -1}
    {.e4 <- .G_MaxCourantCrit[[j + 1]]; .e4$index <- -1}
    {.e5 <- .G_MaxCourantCrit[[j + 1]]; .e5$value <- -1}
    {.e6 <- .G_MaxFlowTurns[[j + 1]]; .e6$index <- -1}
    {.e7 <- .G_MaxFlowTurns[[j + 1]]; .e7$value <- -1}
    {.e8 <- .G_MaxNonConverged[[j + 1]]; .e8$index <- -1}
    {.e9 <- .G_MaxNonConverged[[j + 1]]; .e9$value <- 0}
    j <- j + 1
  }
  if (.G_ReportStepCount > 2) {
    stepCount <- .G_ReportStepCount
    z <- 100 / ((2 / 3) * (stepCount - 2))
    j <- 0
    while (j < .G_Nobjects$v[[4]]) {
      x <- (.G_LinkStats[[j + 1]])$flowTurns * z
      stats_updateMaxStats(.G_MaxFlowTurns, 3, j, x)
      j <- j + 1
    }
  }
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    if ((.G_Node[[j + 1]])$degree <= 0) {
      j <- j + 1
      next
    }
    if (!is.na(.c <- (.G_NodeInflow$v[[j + 1]] <= 0.1)) && .c) {
      j <- j + 1
      next
    }
    if (!is.na(.c <- (.G_NodeInflow$v[[j + 1]] > 0)) && .c) {
      x <- 1 - (.G_NodeOutflow$v[[j + 1]] / (.G_NodeInflow$v[[j + 1]]))
    } else if (!is.na(.c <- (.G_NodeOutflow$v[[j + 1]] > 0)) && .c) {
      x <- -1
    } else {
      x <- 0
    }
    stats_updateMaxStats(.G_MaxMassBalErrs, 2, j, (100 * x))
    j <- j + 1
  }
  stepCount <- TimeStepStats$timeStepCount
  if (.G_RouteModel == 4) {
    j <- 0
    while (j < .G_Nobjects$v[[3]]) {
      stats_updateMaxStats(.G_MaxNonConverged, 2, j, ((.G_NodeStats[[j + 1]])$nonConvergedCount / stepCount))
      j <- j + 1
    }
  }
  if ((.G_RouteModel != 4) || (!is.na(.c <- (CourantFactor$v == 0)) && .c)) {
    return(invisible(NULL))
  }
  if (!is.na(.c <- (stepCount == 0)) && .c) {
    return(invisible(NULL))
  }
  j <- 0
  while (j < .G_Nobjects$v[[3]]) {
    x <- (.G_NodeStats[[j + 1]])$timeCourantCritical / stepCount
    stats_updateMaxStats(.G_MaxCourantCrit, 2, j, (100 * x))
    j <- j + 1
  }
  j <- 0
  while (j < .G_Nobjects$v[[4]]) {
    x <- (.G_LinkStats[[j + 1]])$timeCourantCritical / stepCount
    stats_updateMaxStats(.G_MaxCourantCrit, 3, j, (100 * x))
    j <- j + 1
  }
}

# stats.c:841
stats_updateMaxStats <- function(maxStats, i, j, x) {
  maxStats; i; j; x
  maxStats1 <- T_TMaxStats()
  maxStats2 <- T_TMaxStats()
  maxStats1$objType <- i
  maxStats1$index <- j
  maxStats1$value <- x
  k <- 0
  while (k < 5) {
    if (!is.na(.c <- (abs(maxStats1$value) > abs((maxStats[[k + 1]])$value))) && .c) {
      C_TMaxStats(maxStats2, maxStats[[k + 1]])
      C_TMaxStats(maxStats[[k + 1]], maxStats1)
      C_TMaxStats(maxStats1, maxStats2)
    }
    k <- k + 1
  }
}

# statsrpt.c:84
statsrpt_writeReport <- function() {
  .G_FlowFmt <- FlowFmt; .G_FlowUnits <- FlowUnits; .G_IgnoreGwater <- IgnoreGwater; .G_IgnoreQuality <- IgnoreQuality; .G_Nobjects <- Nobjects
  if ((.G_FlowUnits == 2) || (.G_FlowUnits == 3)) {
    sstrncpy(.G_FlowFmt, .L534, 5)
  } else {
    sstrncpy(.G_FlowFmt, .L535, 5)
  }
  if (UnitSystem == 0) {
    Vcf <<- 7.48 / 1000000
  } else {
    Vcf <<- 28.317 / 1000000
  }
  if (.G_Nobjects$v[[2]] > 0) {
    if (((!(IgnoreRainfall != 0)) || ((.G_Nobjects$v[[14]] > 0) && (!(IgnoreSnowmelt != 0)))) || ((.G_Nobjects$v[[12]] > 0) && (!(.G_IgnoreGwater != 0)))) {
      writeSubcatchRunoff()
      lid_writeWaterBalance()
      if (!(.G_IgnoreGwater != 0)) {
        writeGroundwater()
      }
      if ((.G_Nobjects$v[[5]] > 0) && (!(.G_IgnoreQuality != 0))) {
        writeSubcatchLoads()
      }
    }
  }
  if ((.G_Nobjects$v[[4]] > 0) && (!(IgnoreRouting != 0))) {
    writeNodeDepths()
    writeNodeFlows()
    if (RouteModel == 4) {
      writeNodeSurcharge()
    }
    writeNodeFlooding()
    writeStorageVolumes()
    writeOutfallLoads()
    inlet_writeStatsReport()
    writeLinkFlows()
    writeFlowClass()
    writeLinkSurcharge()
    writePumpFlows()
    if ((.G_Nobjects$v[[5]] > 0) && (!(.G_IgnoreQuality != 0))) {
      writeLinkLoads()
    }
  }
}

