  } else {
    rt_fprintf(.G_Frpt$file, .L539, list(.G_VolUnitsWords$v[[.G_UnitSystem + 1]], .G_FlowUnitWords$v[[.G_FlowUnits + 1]]))
  }
  rt_fprintf(.G_Frpt$file, .L540, list())
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    a <- (.G_Subcatch[[j + 1]])$area
    if (!is.na(.c <- (a == 0)) && .c) {
      j <- j + 1
      next
    }
    rt_fprintf(.G_Frpt$file, .L541, list((.G_Subcatch[[j + 1]])$ID))
    x <- (.G_SubcatchStats[[j + 1]])$precip * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$runon * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$evap * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$infil * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$impervRunoff * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$pervRunoff * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$runoff * (UCF(1))
    rt_fprintf(.G_Frpt$file, .L542, list(x / a))
    x <- (.G_SubcatchStats[[j + 1]])$runoff * .G_Vcf
    rt_fprintf(.G_Frpt$file, .L543, list(x))
    x <- (.G_SubcatchStats[[j + 1]])$maxFlow * (UCF(10))
    rt_fprintf(.G_Frpt$file, .L544, list(x))
    r <- (.G_SubcatchStats[[j + 1]])$precip + (.G_SubcatchStats[[j + 1]])$runon
    if (!is.na(.c <- (r > 0)) && .c) {
      r <- (.G_SubcatchStats[[j + 1]])$runoff / r
    }
    rt_fprintf(.G_Frpt$file, .L545, list(r))
    j <- j + 1
  }
  report_writeLine(.L0)
}

# statsrpt.c:190
writeGroundwater <- function() {
  .G_FlowUnitWords <- FlowUnitWords; .G_FlowUnits <- FlowUnits; .G_Frpt <- Frpt; .G_Nobjects <- Nobjects; .G_Subcatch <- Subcatch
  i <- 0
  count <- 0
  totalSeconds <- NewRunoffTime / 1000
  x <- rt_ra(numeric(9))
  if (.G_Nobjects$v[[2]] == 0) {
    return(invisible(NULL))
  }
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    if (!is.null((.G_Subcatch[[j + 1]])$groundwater)) {
      count <- count + 1
    }
    j <- j + 1
  }
  if (count == 0) {
    return(invisible(NULL))
  }
  report_writeLine(.L0)
  report_writeLine(.L188)
  report_writeLine(.L546)
  report_writeLine(.L188)
  report_writeLine(.L0)
  rt_fprintf(.G_Frpt$file, .L547, list())
  if (UnitSystem == 0) {
    rt_fprintf(.G_Frpt$file, .L548, list(.G_FlowUnitWords$v[[.G_FlowUnits + 1]]))
  } else {
    rt_fprintf(.G_Frpt$file, .L549, list(.G_FlowUnitWords$v[[.G_FlowUnits + 1]]))
  }
  rt_fprintf(.G_Frpt$file, .L550, list())
  j <- 0
  while (j < .G_Nobjects$v[[2]]) {
    if ((!is.na(.c <- ((.G_Subcatch[[j + 1]])$area == 0)) && .c) || (is.null((.G_Subcatch[[j + 1]])$groundwater))) {
      j <- j + 1
      next
    }
    rt_fprintf(.G_Frpt$file, .L541, list((.G_Subcatch[[j + 1]])$ID))
    x$v[[1]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$infil * (UCF(1))
    x$v[[2]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$evap * (UCF(1))
    x$v[[3]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$deepFlow * (UCF(1))
    x$v[[4]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$latFlow * (UCF(1))
    x$v[[5]] <- ((((.G_Subcatch[[j + 1]])$groundwater)$stats)$maxFlow * (UCF(10))) * ((.G_Subcatch[[j + 1]])$area)
    x$v[[6]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$avgUpperMoist / totalSeconds
    x$v[[7]] <- ((((.G_Subcatch[[j + 1]])$groundwater)$stats)$avgWaterTable * (UCF(3))) / totalSeconds
    x$v[[8]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$finalUpperMoist
    x$v[[9]] <- (((.G_Subcatch[[j + 1]])$groundwater)$stats)$finalWaterTable * (UCF(3))
    i <- 0
    while (i < 9) {
      rt_fprintf(.G_Frpt$file, .L544, list(x$v[[i + 1]]))
      i <- i + 1
    }
    j <- j + 1
  }
  report_writeLine(.L0)
}

