    while (p < .G_Nobjects$v[[5]]) {
      rt_fprintf(.G_Frpt$file, .L423, list((.G_Pollut[[p + 1]])$ID))
      p <- p + 1
    }
    rt_fprintf(.G_Frpt$file, .L556, list())
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      i <- .G_UnitSystem
      if ((.G_Pollut[[p + 1]])$units == 2) {
        i <- 2
      }
      sstrncpy(units, .G_LoadUnitsWords$v[[i + 1]], 14)
      rt_fprintf(.G_Frpt$file, .L423, list(units))
      totals$v[[p + 1]] <- 0
      p <- p + 1
    }
    rt_fprintf(.G_Frpt$file, .L356, list(subcatchLine))
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      rt_fprintf(.G_Frpt$file, .L169, list(pollutLine))
      p <- p + 1
    }
    j <- 0
    while (j < .G_Nobjects$v[[2]]) {
      rt_fprintf(.G_Frpt$file, .L541, list((.G_Subcatch[[j + 1]])$ID))
      p <- 0
      while (p < .G_Nobjects$v[[5]]) {
        x <- ((.G_Subcatch[[j + 1]])$totalLoad)$v[[p + 1]]
        totals$v[[p + 1]] <- totals$v[[p + 1]] + x
        if ((.G_Pollut[[p + 1]])$units == 2) {
          x <- if (!is.na(.c <- (x > 0)) && .c) rt_log10(x) else x
        }
        rt_fprintf(.G_Frpt$file, .L427, list(x))
        p <- p + 1
      }
      j <- j + 1
    }
    rt_fprintf(.G_Frpt$file, .L356, list(subcatchLine))
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      rt_fprintf(.G_Frpt$file, .L169, list(pollutLine))
      p <- p + 1
    }
    rt_fprintf(.G_Frpt$file, .L557, list())
    p <- 0
    while (p < .G_Nobjects$v[[5]]) {
      x <- totals$v[[p + 1]]
      if ((.G_Pollut[[p + 1]])$units == 2) {
        x <- if (!is.na(.c <- (x > 0)) && .c) rt_log10(x) else x
      }
      rt_fprintf(.G_Frpt$file, .L427, list(x))
      p <- p + 1
    }
    NULL
    report_writeLine(.L0)
  }
}

