writeNodeSurcharge <- function() {
  .G_Frpt <- Frpt; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_NodeStats <- NodeStats; .G_NodeTypeWords <- NodeTypeWords; .G_UnitSystem <- UnitSystem
  n <- 0
