    if ((.G_Node[[j + 1]])$type == 1) {
      j <- j + 1
      next
    }
    if (!is.na(.c <- ((.G_NodeStats[[j + 1]])$timeSurcharged == 0)) && .c) {
      j <- j + 1
      next
    }
    t <- if (!is.na(.c <- (0.01 >= ((.G_NodeStats[[j + 1]])$timeSurcharged / 3600))) && .c) 0.01 else ((.G_NodeStats[[j + 1]])$timeSurcharged / 3600)
    if (n == 0) {
