    }
    rt_fprintf(.G_Frpt$file, .L541, list((.G_Node[[j + 1]])$ID))
    rt_fprintf(.G_Frpt$file, .L569, list(.G_NodeTypeWords$v[[(.G_Node[[j + 1]])$type + 1]]))
    d1 <- ((.G_NodeStats[[j + 1]])$maxDepth + (.G_Node[[j + 1]])$invertElev) - ((.G_Node[[j + 1]])$crownElev)
    if (!is.na(.c <- (d1 < 0)) && .c) {
      d1 <- 0
    }
    d2 <- (.G_Node[[j + 1]])$fullDepth - ((.G_NodeStats[[j + 1]])$maxDepth)
    if (!is.na(.c <- (d2 < 0)) && .c) {
      d2 <- 0
    }
    rt_fprintf(.G_Frpt$file, .L581, list(t, d1 * (UCF(3)), d2 * (UCF(3))))
    j <- j + 1
  }
  if (n == 0) {
    report_writeLine(.L582)
  }
  report_writeLine(.L0)
}

