writeStorageVolumes <- function() {
  .G_FlowFmt <- FlowFmt; .G_Frpt <- Frpt; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_NodeInflow <- NodeInflow; .G_ReportStepCount <- ReportStepCount; .G_StorageStats <- StorageStats
