# subcatch.c:907
getSubareaRunoff <- function(j, i, area, precip, evap, tStep) {
  j; i; area; precip; evap; tStep
  infil <- 0
  runoff <- 0
  if (!is.na(.c <- (area == 0)) && .c) {
    return(0)
  }
  subarea <- ((Subcatch[[j + 1]])$subArea)[[i + 1]]
  tRunoff <- tStep
  surfMoisture <- subarea$depth / tStep
  surfEvap <- if (!is.na(.c <- (surfMoisture <= evap)) && .c) surfMoisture else evap
  if (i == 2) {
    infil <- getSubareaInfil(j, subarea, precip, tStep)
  }
  subarea$inflow <- subarea$inflow + precip
  surfMoisture <- surfMoisture + subarea$inflow
  Vinflow <<- Vinflow + ((precip * area) * tStep)
  Vevap <<- Vevap + ((surfEvap * area) * tStep)
  if (i == 2) {
    Vpevap <<- Vpevap + Vevap
  }
  Vinfil <<- Vinfil + ((infil * area) * tStep)
  Alpha <<- subarea$alpha
  Dstore <<- subarea$dStore
  adjustSubareaParams(i, j)
  if (!is.na(.c <- ((surfEvap + infil) >= surfMoisture)) && .c) {
    subarea$depth <- 0
  } else {
    subarea$inflow <- subarea$inflow - (surfEvap + infil)
    {.BX_getSubareaRunoff_tRunoff$v <- tRunoff; .r1 <- updatePondedDepth(subarea, .BX_getSubareaRunoff_tRunoff); tRunoff <- .BX_getSubareaRunoff_tRunoff$v; .r1}
  }
  runoff <- findSubareaRunoff(subarea, tRunoff)
  Voutflow <<- Voutflow + (((subarea$fOutlet * runoff) * area) * tStep)
  return(runoff)
}

