# subcatch.c:1013
findSubareaRunoff <- function(subarea, tRunoff) {
  subarea; tRunoff
  .G_Dstore <- Dstore
  xDepth <- subarea$depth - .G_Dstore
  runoff <- 0
  if (!is.na(.c <- (xDepth > 1e-10)) && .c) {
    if (!is.na(.c <- (subarea$N > 0)) && .c) {
      runoff <- Alpha * (if ((.p <- xDepth) > -Inf || is.na(.p)) .p ^ 1.6666667 else rt_pow(.p, 1.6666667))
    } else {
      runoff <- xDepth / tRunoff
      subarea$depth <- .G_Dstore
    }
  } else {
    runoff <- 0
  }
  return(runoff)
}

