updatePondedDepth <- function(subarea, dt) {
  subarea; dt
  .G_Dstore <- Dstore
  ix <- subarea$inflow
  dx <- 0
  tx <- dt$v
  if (!is.na(.c <- ((subarea$depth + (ix * tx)) <= .G_Dstore)) && .c) {
    subarea$depth <- subarea$depth + (ix * tx)
  } else {
    dx <- .G_Dstore - subarea$depth
    if ((!is.na(.c <- (dx > 0)) && .c) && (!is.na(.c <- (ix > 0)) && .c)) {
      tx <- tx - (dx / ix)
      subarea$depth <- .G_Dstore
    }
    if ((!is.na(.c <- (Alpha > 0)) && .c) && (!is.na(.c <- (tx > 0)) && .c)) {
      theSubarea <<- subarea
      {.a1 <- rt_ra(c(subarea$depth)); .r2 <- odesolve_integrate(.a1, 1, 0, tx, ODETOL, tx, getDdDt); subarea$depth <- .a1$v[[1]]; .r2}
    } else {
      if (!is.na(.c <- (tx < 0)) && .c) {
        tx <- 0
      }
      subarea$depth <- subarea$depth + (ix * tx)
    }
  }
  if (!is.na(.c <- (subarea$depth < 0)) && .c) {
    subarea$depth <- 0
  }
  dt$v <- tx
}

