# surfqual.c:313
findPondedLoads <- function(j, tStep) {
  j; tStep
  .G_Nobjects <- Nobjects; .G_OutflowLoad <- OutflowLoad; .G_Pollut <- Pollut; .G_Subcatch <- Subcatch; .G_Vinfil <- Vinfil; .G_Vinflow <- Vinflow; .G_Voutflow <- Voutflow
