    return(invisible(NULL))
  }
  fullArea <- (.G_Subcatch[[j + 1]])$area
  nonLidArea <- fullArea - ((.G_Subcatch[[j + 1]])$lidArea)
  vRain <- ((.G_Subcatch[[j + 1]])$rainfall * nonLidArea) * tStep
  p <- 0
