    massbal_updateLoadingTotals(1, p, (wRain * ((.G_Pollut[[p + 1]])$mcf)))
    if (!is.na(.c <- (.G_Vinflow == 0)) && .c) {
      massbal_updateLoadingTotals(6, p, (((.G_Subcatch[[j + 1]])$pondedQual)$v[[p + 1]] * ((.G_Pollut[[p + 1]])$mcf)))
      {.e1 <- (.G_Subcatch[[j + 1]])$pondedQual; .e1$v[[p + 1]] <- 0}
    } else {
      wRunon <- ((.G_Subcatch[[j + 1]])$newQual)$v[[p + 1]] * tStep
      wPonded <- (((.G_Subcatch[[j + 1]])$pondedQual)$v[[p + 1]] + wRain) + wRunon
      cPonded <- wPonded / .G_Vinflow
      wInfil <- cPonded * .G_Vinfil
      wInfil <- if (!is.na(.c <- (wInfil <= wPonded)) && .c) wInfil else wPonded
      massbal_updateLoadingTotals(4, p, (wInfil * ((.G_Pollut[[p + 1]])$mcf)))
      wPonded <- wPonded - wInfil
      wOutflow <- cPonded * .G_Voutflow
      wOutflow <- if (!is.na(.c <- (wOutflow <= wPonded)) && .c) wOutflow else wPonded
      wPonded <- wPonded - wOutflow
      bmpRemoval <- landuse_getAvgBmpEffic(j, p) * wOutflow
      massbal_updateLoadingTotals(3, p, (bmpRemoval * ((.G_Pollut[[p + 1]])$mcf)))
      wOutflow <- wOutflow - bmpRemoval
