      while (p < .G_Nobjects$v[[5]]) {
        .G_OutflowLoad$v[[p + 1]] <- .G_OutflowLoad$v[[p + 1]] + (landuse_getWashoffLoad(i, p, area, (.G_Subcatch[[j + 1]])$landFactor, runoff, .G_Voutflow))
        p <- p + 1
      }
    }
    i <- i + 1
  }
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    k <- (.G_Pollut[[p + 1]])$coPollut
    if (k >= 0) {
      w <- (.G_Pollut[[p + 1]])$coFraction * (.G_OutflowLoad$v[[k + 1]])
      massbal_updateLoadingTotals(0, p, (w * ((.G_Pollut[[p + 1]])$mcf)))
      .G_OutflowLoad$v[[p + 1]] <- .G_OutflowLoad$v[[p + 1]] + w
    }
    p <- p + 1
  }
}

# surfqual.c:443
findLidLoads <- function(j, tStep) {
  j; tStep
  .G_Nobjects <- Nobjects; .G_OutflowLoad <- OutflowLoad; .G_Pollut <- Pollut; .G_Subcatch <- Subcatch
  wLidRain <- 0
  wLidRunon <- 0
  lidArea <- (.G_Subcatch[[j + 1]])$lidArea
  if (!is.na(.c <- (lidArea == 0)) && .c) {
    return(invisible(NULL))
  }
  vLidRain <- ((.G_Subcatch[[j + 1]])$rainfall * lidArea) * tStep
  useRunon <- if (!is.na(.c <- (lidArea == (.G_Subcatch[[j + 1]])$area)) && .c) 1 else 0
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    wLidRain <- ((.G_Pollut[[p + 1]])$pptConcen * vLidRain) * 28.317
    massbal_updateLoadingTotals(1, p, (wLidRain * ((.G_Pollut[[p + 1]])$mcf)))
    if (useRunon != 0) {
      wLidRunon <- ((.G_Subcatch[[j + 1]])$newQual)$v[[p + 1]] * tStep
    } else {
      wLidRunon <- 0
    }
    .G_OutflowLoad$v[[p + 1]] <- .G_OutflowLoad$v[[p + 1]] + (wLidRain + wLidRunon)
    p <- p + 1
  }
}

