    if (!(ErrorCode != 0)) {
      writecon(.L643)
      repeat {
        {.BX_swmm_run_elapsedTime$v <- elapsedTime; .r1 <- swmm_step(.BX_swmm_run_elapsedTime); elapsedTime <- .BX_swmm_run_elapsedTime$v; .r1}
        newHour <- if (is.na(.d <- elapsedTime * 24) || .d >= 9223372036854775808 || .d <= -9223372036854777856) -9223372036854775808 else trunc(.d)
        if (newHour > oldHour) {
          theDay <- if (is.na(.d <- elapsedTime) || .d >= 9223372036854775808 || .d <= -9223372036854777856) -9223372036854775808 else trunc(.d)
          theHour <- if (is.na(.d <- (elapsedTime - (floor(elapsedTime))) * 24) || .d >= 9223372036854775808 || .d <= -9223372036854777856) -9223372036854775808 else trunc(.d)
          writecon(.L644)
          rt_snprintf(.G_Msg, 1024, .L645, list(theDay, theHour))
          writecon(.G_Msg)
          oldHour <- newHour
        }
        if (!((!is.na(.c <- (elapsedTime > 0)) && .c) && (!(ErrorCode != 0)))) break
      }
      writecon(.L646)
      writecon(.L647)
    }
    swmm_end()
  }
  if ((!(ErrorCode != 0)) && (Fout$mode == 1)) {
    writecon(.L648)
    swmm_report()
  }
