  }
  if (!(IsStartedFlag != 0)) {
    return(ErrorCode <<- 502)
  }
  if (!is.na(.c <- (NewRoutingTime < .G_RoutingDuration)) && .c) {
    execRouting()
  }
  if (SaveResultsFlag != 0) {
