# swmm5.c:466
swmm_stride <- function(strideStep, elapsedTime) {
  strideStep; elapsedTime
  .G_TotalDuration <- TotalDuration
  realRouteStep <- RouteStep
  elapsedTime$v <- 0
  if (ErrorCode != 0) {
    return(ErrorCode)
  }
  if (!(IsOpenFlag != 0)) {
    return(ErrorCode <<- 501)
  }
  if (!(IsStartedFlag != 0)) {
    return(ErrorCode <<- 502)
  }
  RoutingDuration <<- NewRoutingTime + (1000 * strideStep)
  RoutingDuration <<- if (!is.na(.c <- (.G_TotalDuration <= RoutingDuration)) && .c) .G_TotalDuration else RoutingDuration
  if (!is.na(.c <- (strideStep < RouteStep)) && .c) {
    RouteStep <<- strideStep
  }
  repeat {
    swmm_step(elapsedTime)
    if (!((!is.na(.c <- (elapsedTime$v > 0)) && .c) && (!(ErrorCode != 0)))) break
  }
  RouteStep <<- realRouteStep
  RoutingDuration <<- .G_TotalDuration
  if (!is.na(.c <- (NewRoutingTime < .G_TotalDuration)) && .c) {
    ElapsedTime <<- NewRoutingTime / 86400000
  } else {
    ElapsedTime <<- 0
  }
  elapsedTime$v <- ElapsedTime
  return(ErrorCode)
}

# swmm5.c:514
execRouting <- function() {
  .G_DoRouting <- DoRouting; .G_ReportStep <- ReportStep; .G_RouteModel <- RouteModel; .G_RoutingDuration <- RoutingDuration; .G_WetStep <- WetStep
  nextRoutingTime <- 0
  routingStep <- 0
  TotalStepCount <<- TotalStepCount + 1
  if (!(.G_DoRouting != 0)) {
    routingStep <- if (.G_WetStep <= .G_ReportStep) .G_WetStep else .G_ReportStep
  } else {
    routingStep <- routing_getRoutingStep(.G_RouteModel, RouteStep)
  }
  if (!is.na(.c <- (routingStep <= 0)) && .c) {
    ErrorCode <<- 107
    return(invisible(NULL))
  }
  nextRoutingTime <- NewRoutingTime + (1000 * routingStep)
  if (!is.na(.c <- (nextRoutingTime > .G_RoutingDuration)) && .c) {
    routingStep <- (.G_RoutingDuration - NewRoutingTime) / 1000
    routingStep <- if (!is.na(.c <- (routingStep >= (1 / 1000))) && .c) routingStep else (1 / 1000)
    nextRoutingTime <- .G_RoutingDuration
  }
  if (DoRunoff != 0) {
    while (!is.na(.c <- (NewRunoffTime < nextRoutingTime)) && .c) {
      runoff_execute()
      if (ErrorCode != 0) {
        return(invisible(NULL))
      }
    }
  } else {
    climate_setState(getDateTime(NewRoutingTime))
  }
  if (.G_DoRouting != 0) {
    routing_execute(.G_RouteModel, routingStep)
  } else {
    NewRoutingTime <<- nextRoutingTime
  }
}

