saveResults <- function() {
  .G_NewRoutingTime <- NewRoutingTime; .G_RptFlags <- RptFlags
  if (!is.na(.c <- (.G_NewRoutingTime >= ReportTime)) && .c) {
    if (.G_RptFlags$averages != 0) {
      if (!is.na(.c <- (.G_NewRoutingTime == ReportTime)) && .c) {
        output_updateAvgResults()
      }
      output_saveResults(ReportTime)
      if (!is.na(.c <- (.G_NewRoutingTime > ReportTime)) && .c) {
        output_updateAvgResults()
      }
    } else {
      output_saveResults(ReportTime)
    }
    ReportTime <<- ReportTime + (1000 * ReportStep)
  } else if (.G_RptFlags$averages != 0) {
    output_updateAvgResults()
  }
}

