table_getStorageDepth <- function(table_, v) {
  table_; v
  a2 <- 0
  d2 <- 0
  dd <- 0
  da <- 0
  v2 <- 0
  s <- 0
  if (!is.na(.c <- (v == 0)) && .c) {
    return(0)
  }
  entry <- table_$firstEntry
  if (is.null(entry)) {
    return(0)
  }
  d1 <- entry$x
  a1 <- entry$y
  v1 <- (a1 * d1) / 2
  if (!is.na(.c <- (v <= v1)) && .c) {
    if (!is.na(.c <- (a1 > 0)) && .c) {
      return(sqrt(((2 * v) * d1) / a1))
    } else {
      return(0)
    }
  }
  while (!is.null(entry$next_)) {
    entry <- entry$next_
    d2 <- entry$x
    a2 <- entry$y
    dd <- d2 - d1
    da <- a2 - a1
    v2 <- v1 + (((a1 + a2) / 2) * dd)
    if (!is.na(.c <- (v <= v2)) && .c) {
      if (!is.na(.c <- (dd <= 0)) && .c) {
        return(d1)
      }
      if (!is.na(.c <- (da == 0)) && .c) {
        if (!is.na(.c <- (abs(v2 - v1) < 1e-06)) && .c) {
          return(d1)
        } else {
          return(d1 + ((dd * (v - v1)) / (v2 - v1)))
        }
      }
      if (!is.na(.c <- (da < 0)) && .c) {
        d1 <- d2
        a1 <- a2
        v1 <- v2
      }
      s <- da / dd
      return(d1 + ((sqrt((a1 * a1) + ((2 * s) * (v - v1))) - a1) / s))
    }
    d1 <- d2
    a1 <- a2
    v1 <- v2
  }
  if ((!is.na(.c <- (dd == 0)) && .c) || (!is.na(.c <- (da == 0)) && .c)) {
    if (!is.na(.c <- (a1 > 0)) && .c) {
      dd <- (v - v1) / a1
    } else {
