      if ((.G_Link[[i + 1]])$direction < 0) {
        n <- (.G_Link[[i + 1]])$node2
      }
      if ((.G_Node[[n + 1]])$type == 1) {
        if ((.G_Link[[i + 1]])$direction < 0) {
          n <- (.G_Link[[i + 1]])$node1
        } else {
          n <- (.G_Link[[i + 1]])$node2
        }
        {.e2 <- .G_Node[[n + 1]]; .e2$degree <- (.G_Node[[n + 1]])$degree + 1}
      } else {
        {.e3 <- .G_Node[[n + 1]]; .e3$degree <- (.G_Node[[n + 1]])$degree + 1}
      }
