    return(invisible(NULL))
  }
  InDegree <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
  StartPos <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
  AdjList <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[4]])))
  Stack <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
  if ((((is.null(InDegree)) || (is.null(StartPos))) || (is.null(AdjList))) || (is.null(Stack))) {
