# toposort.c:225
topoSort <- function(sortedLinks) {
  sortedLinks
  .G_AdjList <- AdjList; .G_InDegree <- InDegree; .G_Link <- Link; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_Stack <- Stack; .G_StartPos <- StartPos
  j <- 0
  k <- 0
  i1 <- 0
  i2 <- 0
  k1 <- 0
  k2 <- 0
  First <<- 0
  Last <<- -1
  i <- 0
  while (i < .G_Nobjects$v[[3]]) {
    if (.G_InDegree$v[[i + 1]] == 0) {
      Last <<- Last + 1
      .G_Stack$v[[Last + 1]] <- i
    }
    i <- i + 1
  }
  n <- 0
  while (First <= Last) {
    i1 <- .G_Stack$v[[First + 1]]
    k1 <- .G_StartPos$v[[i1 + 1]]
    k2 <- k1 + (.G_Node[[i1 + 1]])$degree
    k <- k1
    while (k < k2) {
      j <- .G_AdjList$v[[k + 1]]
      sortedLinks$v[[n + 1]] <- j
      n <- n + 1
      i2 <- (.G_Link[[j + 1]])$node2
      .G_InDegree$v[[i2 + 1]] <- .G_InDegree$v[[i2 + 1]] - 1
      if (.G_InDegree$v[[i2 + 1]] == 0) {
        Last <<- Last + 1
        .G_Stack$v[[Last + 1]] <- i2
      }
      k <- k + 1
    }
    First <<- First + 1
  }
  return(n)
}

# toposort.c:284
findCycles <- function() {
  .G_Nobjects <- Nobjects
  i <- 0
  AdjList <<- rt_ra(numeric(2 * (rt_u64(.G_Nobjects$v[[4]]))))
  StartPos <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
  Stack <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[3]])))
  Examined <<- rt_cbuf(rt_u64(.G_Nobjects$v[[3]]))
  InTree <<- rt_cbuf(rt_u64(.G_Nobjects$v[[4]]))
  LoopLinks <<- rt_ra(numeric(rt_u64(.G_Nobjects$v[[4]])))
  if ((((((!is.null(StartPos)) && (!is.null(AdjList))) && (!is.null(Stack))) && (!is.null(Examined))) && (!is.null(InTree))) && (!is.null(LoopLinks))) {
    createAdjList(0)
    i <- 0
    while (i < .G_Nobjects$v[[3]]) {
      rt_cset(Examined, i, 0)
      i <- i + 1
    }
    i <- 0
    while (i < .G_Nobjects$v[[4]]) {
      rt_cset(InTree, i, 0)
      i <- i + 1
    }
    i <- 0
    while (i < .G_Nobjects$v[[3]]) {
      if (rt_cget(Examined, i) != 0) {
        i <- i + 1
        next
      }
      Last <<- -1
      findSpanningTree(i)
      i <- i + 1
    }
  }
  if (!is.null(StartPos)) {
    NULL
    StartPos <<- NULL
  }
  if (!is.null(AdjList)) {
    NULL
    AdjList <<- NULL
  }
  if (!is.null(Stack)) {
    NULL
    Stack <<- NULL
  }
  if (!is.null(Examined)) {
    NULL
    Examined <<- NULL
  }
  if (!is.null(InTree)) {
    NULL
    InTree <<- NULL
  }
  if (!is.null(LoopLinks)) {
    NULL
    LoopLinks <<- NULL
  }
}

# toposort.c:330
findSpanningTree <- function(startNode) {
  startNode
  .G_AdjList <- AdjList; .G_Examined <- Examined; .G_InTree <- InTree; .G_Link <- Link; .G_Node <- Node; .G_Stack <- Stack; .G_StartPos <- StartPos
  nextNode <- 0
  j <- 0
  k <- 0
  m <- .G_StartPos$v[[startNode + 1]]
  while (m < (.G_StartPos$v[[startNode + 1]] + (.G_Node[[startNode + 1]])$degree)) {
    k <- .G_AdjList$v[[m + 1]]
    if ((.G_Link[[k + 1]])$node1 == startNode) {
      j <- (.G_Link[[k + 1]])$node2
    } else {
      j <- (.G_Link[[k + 1]])$node1
    }
    if (rt_cget(.G_InTree, k) == 0) {
      if (rt_cget(.G_Examined, j) != 0) {
        rt_cset(.G_InTree, k, 2)
        evalLoop(k)
      } else {
        rt_cset(.G_Examined, j, 1)
        Last <<- Last + 1
        .G_Stack$v[[Last + 1]] <- j
        rt_cset(.G_InTree, k, 1)
      }
    }
    m <- m + 1
  }
  if (Last >= 0) {
    nextNode <- .G_Stack$v[[Last + 1]]
    Last <<- Last - 1
    findSpanningTree(nextNode)
  }
}

# toposort.c:385
evalLoop <- function(startLink) {
  startLink
  .G_Frpt <- Frpt; .G_Link <- Link; .G_LoopLinks <- LoopLinks
  kount <- 0
  LoopLinksLast <<- 0
  .G_LoopLinks$v[[1]] <- startLink
  i1 <- (.G_Link[[startLink + 1]])$node1
  i2 <- (.G_Link[[startLink + 1]])$node2
  if (!(traceLoop(i1, i2, startLink) != 0)) {
    return(invisible(NULL))
  }
  isCycle <- 1
  j <- .G_LoopLinks$v[[1]]
  i2 <- (.G_Link[[j + 1]])$node2
  i <- 1
  while (i <= LoopLinksLast) {
    j <- .G_LoopLinks$v[[i + 1]]
    i1 <- (.G_Link[[j + 1]])$node1
    if (i1 == i2) {
      i2 <- (.G_Link[[j + 1]])$node2
    } else {
      isCycle <- 0
      break
    }
    i <- i + 1
  }
  if (isCycle != 0) {
    kount <- 0
    i <- 0
    while (i <= LoopLinksLast) {
      if ((kount - trunc(kount / 5) * 5) == 0) {
        rt_fprintf(.G_Frpt$file, .L276, list())
      }
      kount <- kount + 1
      rt_fprintf(.G_Frpt$file, .L651, list((.G_Link[[.G_LoopLinks$v[[i + 1]] + 1]])$ID))
      if (i < LoopLinksLast) {
        rt_fprintf(.G_Frpt$file, .L652, list())
      }
      i <- i + 1
    }
  }
}

# toposort.c:440
traceLoop <- function(i1, i2, k1) {
  i1; i2; k1
  .G_AdjList <- AdjList; .G_InTree <- InTree; .G_Link <- Link; .G_LoopLinks <- LoopLinks; .G_Node <- Node; .G_StartPos <- StartPos
  j <- 0
  k <- 0
  if (i1 == i2) {
    return(1)
  }
  m <- .G_StartPos$v[[i1 + 1]]
  while (m < (.G_StartPos$v[[i1 + 1]] + (.G_Node[[i1 + 1]])$degree)) {
    k <- .G_AdjList$v[[m + 1]]
    if ((k == k1) || (rt_cget(.G_InTree, k) != 1)) {
      m <- m + 1
      next
    }
    if ((.G_Link[[k + 1]])$node1 == i1) {
      j <- (.G_Link[[k + 1]])$node2
    } else {
      j <- (.G_Link[[k + 1]])$node1
    }
    if (traceLoop(j, i2, k) != 0) {
      LoopLinksLast <<- LoopLinksLast + 1
      .G_LoopLinks$v[[LoopLinksLast + 1]] <- k
      return(1)
    }
    m <- m + 1
  }
  return(0)
}

