    }
    id <- project_findID(10, tok$v[[2]])
    if (is.null(id)) {
      return(error_setInpError(209, tok$v[[2]]))
    }
    i <- 2
    while (i < 10) {
      if (!({.b3 <- rt_box(x$v[[i + 1]]); .r4 <- getDouble(tok$v[[i + 1]], .b3); x$v[[i + 1]] <- .b3$v; .r4} != 0)) {
        return(error_setInpError(211, tok$v[[i + 1]]))
      }
      i <- i + 1
    }
    count$v <- index + 1
