      if (!({.b5 <- rt_box(x$v[[2]]); .r6 <- getDouble(tok$v[[i + 1]], .b5); x$v[[2]] <- .b5$v; .r6} != 0)) {
        return(error_setInpError(211, tok$v[[i + 1]]))
