# transect.c:194
transect_validate <- function(j) {
  j
  .G_Elev <- Elev; .G_Lfactor <- Lfactor; .G_Station <- Station; .G_Transect <- Transect
  oldNchannel <- Nchannel
  if ((j < 0) || (j >= Ntransects)) {
    return(invisible(NULL))
  }
  if (Nstations < 2) {
    report_writeErrorMsg(223, (.G_Transect[[j + 1]])$ID)
    return(invisible(NULL))
  }
  if (Nstations >= 1500) {
    report_writeErrorMsg(225, (.G_Transect[[j + 1]])$ID)
    return(invisible(NULL))
  }
  if (!is.na(.c <- (Nchannel <= 0)) && .c) {
    report_writeErrorMsg(227, (.G_Transect[[j + 1]])$ID)
    return(invisible(NULL))
  }
  if (!is.na(.c <- (Xleftbank > Xrightbank)) && .c) {
    report_writeErrorMsg(229, (.G_Transect[[j + 1]])$ID)
    return(invisible(NULL))
  }
  Nchannel <<- Nchannel * (sqrt(.G_Lfactor))
  {.e1 <- .G_Transect[[j + 1]]; .e1$lengthFactor <- .G_Lfactor}
  ymax <- .G_Elev$v[[2]]
  ymin <- .G_Elev$v[[2]]
  i <- 2
  while (i <= Nstations) {
    ymax <- if (!is.na(.c <- ((.G_Elev$v[[i + 1]]) >= ymax)) && .c) (.G_Elev$v[[i + 1]]) else ymax
    ymin <- if (!is.na(.c <- ((.G_Elev$v[[i + 1]]) <= ymin)) && .c) (.G_Elev$v[[i + 1]]) else ymin
    i <- i + 1
  }
  if (!is.na(.c <- (ymin >= ymax)) && .c) {
    report_writeErrorMsg(231, (.G_Transect[[j + 1]])$ID)
    return(invisible(NULL))
  }
  .G_Station$v[[1]] <- .G_Station$v[[2]]
  .G_Elev$v[[1]] <- ymax
  Nstations <<- Nstations + 1
  .G_Station$v[[Nstations + 1]] <- .G_Station$v[[Nstations]]
  .G_Elev$v[[Nstations + 1]] <- .G_Elev$v[[1]]
  {.e2 <- .G_Transect[[j + 1]]; .e2$nTbl <- 51}
  createTables(.G_Transect[[j + 1]], ymin, ymax)
  {.e3 <- .G_Transect[[j + 1]]; .e3$roughness <- oldNchannel}
}

# transect.c:264
createTables <- function(transect, ymin, ymax) {
  transect; ymin; ymax
  transect$yFull <- ymax - ymin
  transect$wMax <- 0
  {.e1 <- transect$areaTbl; .e1$v[[1]] <- 0}
  {.e2 <- transect$hradTbl; .e2$v[[1]] <- 0}
  {.e3 <- transect$widthTbl; .e3$v[[1]] <- 0}
  dy <- (ymax - ymin) / (transect$nTbl - 1)
  y <- ymin
  i <- 1
  while (i < transect$nTbl) {
    y <- y + dy
    {.e4 <- transect$areaTbl; .e4$v[[i + 1]] <- 0}
    {.e5 <- transect$hradTbl; .e5$v[[i + 1]] <- 0}
    {.e6 <- transect$widthTbl; .e6$v[[i + 1]] <- 0}
    getGeometry(transect, i, y)
    i <- i + 1
  }
  setMaxSectionFactor(transect)
  nLast <- transect$nTbl - 1
  transect$aFull <- transect$areaTbl$v[[nLast + 1]]
  transect$rFull <- transect$hradTbl$v[[nLast + 1]]
  transect$wMax <- transect$widthTbl$v[[nLast + 1]]
  i <- 1
  while (i <= nLast) {
    {.e7 <- transect$areaTbl; .e7$v[[i + 1]] <- transect$areaTbl$v[[i + 1]] / transect$aFull}
    {.e8 <- transect$hradTbl; .e8$v[[i + 1]] <- transect$hradTbl$v[[i + 1]] / transect$rFull}
    {.e9 <- transect$widthTbl; .e9$v[[i + 1]] <- transect$widthTbl$v[[i + 1]] / transect$wMax}
    i <- i + 1
  }
  {.e10 <- transect$widthTbl; .e10$v[[1]] <- transect$widthTbl$v[[2]]}
}

# transect.c:312
setManning <- function(n) {
  n
  i <- 1
  while (i <= 3) {
    if (!is.na(.c <- (n$v[[i + 1]] < 0)) && .c) {
      return(211)
    }
    i <- i + 1
  }
  if (!is.na(.c <- (n$v[[2]] > 0)) && .c) {
    Nleft <<- n$v[[2]]
  }
  if (!is.na(.c <- (n$v[[3]] > 0)) && .c) {
    Nright <<- n$v[[3]]
  }
  if (!is.na(.c <- (n$v[[4]] > 0)) && .c) {
    Nchannel <<- n$v[[4]]
  }
  if (!is.na(.c <- (Nleft == 0)) && .c) {
    Nleft <<- Nchannel
  }
  if (!is.na(.c <- (Nright == 0)) && .c) {
    Nright <<- Nchannel
  }
  return(0)
}

# transect.c:334
setParams <- function(j, id, x) {
  j; id; x
  if ((j < 0) || (j >= Ntransects)) {
    return(211)
  }
  {.e1 <- Transect[[j + 1]]; .e1$ID <- id}
  Xleftbank <<- x$v[[4]] / (UCF(3))
  Xrightbank <<- x$v[[5]] / (UCF(3))
  Lfactor <<- x$v[[8]]
  if (!is.na(.c <- (Lfactor == 0)) && .c) {
    Lfactor <<- 1
  }
  Xfactor <<- x$v[[9]]
  if (!is.na(.c <- (Xfactor == 0)) && .c) {
    Xfactor <<- 1
  }
  Xleftbank <<- Xleftbank * Xfactor
  Xrightbank <<- Xrightbank * Xfactor
  Yfactor <<- x$v[[10]] / (UCF(3))
  Nstations <<- 0
  return(0)
