# transect.c:360
addStation <- function(y, x) {
  y; x
  .G_Station <- Station
  if (Nstations < 0) {
    return(219)
  }
  Nstations <<- Nstations + 1
  if (Nstations >= 1500) {
    return(0)
  }
  .G_Station$v[[Nstations + 1]] <- (x * Xfactor) / (UCF(3))
  {.e1 <- Elev; .e1$v[[Nstations + 1]] <- (y + Yfactor) / (UCF(3))}
  if ((Nstations > 1) && (!is.na(.c <- (.G_Station$v[[Nstations + 1]] < .G_Station$v[[Nstations]])) && .c)) {
    return(221)
  }
  return(0)
