# transect.c:388
getGeometry <- function(transect, i, y) {
  transect; i; y
  .G_Elev <- Elev; .G_Nstations <- Nstations
  ylo <- 0
  yhi <- 0
  w <- 0
  wp <- 0
  a <- 0
  q_ <- 0
  findFlow <- 0
  wpSum <- 0
  aSum <- 0
  qSum <- 0
  k <- 1
  while (k <= .G_Nstations) {
    if (!is.na(.c <- (.G_Elev$v[[k]] >= .G_Elev$v[[k + 1]])) && .c) {
      yhi <- .G_Elev$v[[k]]
      ylo <- .G_Elev$v[[k + 1]]
    } else {
      yhi <- .G_Elev$v[[k + 1]]
      ylo <- .G_Elev$v[[k]]
    }
    if (!is.na(.c <- (ylo >= y)) && .c) {
      k <- k + 1
      next
    }
    {.BX_getGeometry_w$v <- w; .BX_getGeometry_a$v <- a; .BX_getGeometry_wp$v <- wp; .r1 <- getSliceGeom(k, y, ylo, yhi, .BX_getGeometry_w, .BX_getGeometry_a, .BX_getGeometry_wp); w <- .BX_getGeometry_w$v; a <- .BX_getGeometry_a$v; wp <- .BX_getGeometry_wp$v; .r1}
    wpSum <- wpSum + wp
    aSum <- aSum + a
    {.e2 <- transect$areaTbl; .e2$v[[i + 1]] <- transect$areaTbl$v[[i + 1]] + a}
    {.e3 <- transect$widthTbl; .e3$v[[i + 1]] <- transect$widthTbl$v[[i + 1]] + w}
    if (!is.na(.c <- (.G_Elev$v[[k + 1]] >= y)) && .c) {
      findFlow <- 1
    } else {
      findFlow <- 0
    }
    q_ <- getFlow(k, aSum, wpSum, findFlow)
    if (!is.na(.c <- (q_ > 0)) && .c) {
      qSum <- qSum + q_
      aSum <- 0
      wpSum <- 0
    }
    k <- k + 1
  }
  aSum <- transect$areaTbl$v[[i + 1]]
  if (!is.na(.c <- (aSum == 0)) && .c) {
    {.e4 <- transect$hradTbl; .e4$v[[i + 1]] <- transect$hradTbl$v[[i]]}
  } else {
    {.e5 <- transect$hradTbl; .e5$v[[i + 1]] <- if ((.p <- ((qSum * Nchannel) / 1.49) / aSum) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5)}
  }
}

# transect.c:468
getSliceGeom <- function(k, y, ylo, yhi, w, a, wp) {
  k; y; ylo; yhi; w; a; wp
  .G_Station <- Station
  ratio <- 0
  width <- abs(.G_Station$v[[k + 1]] - (.G_Station$v[[k]]))
  w$v <- width
  wp$v <- sqrt((width * width) + ((yhi - ylo) * (yhi - ylo)))
  a$v <- 0
  if (!is.na(.c <- (y > yhi)) && .c) {
    a$v <- (width * ((y - yhi) + (y - ylo))) / 2
  } else if (!is.na(.c <- (yhi > ylo)) && .c) {
    ratio <- (y - ylo) / (yhi - ylo)
    a$v <- (((width * (yhi - ylo)) / 2) * ratio) * ratio
    w$v <- w$v * ratio
    wp$v <- wp$v * ratio
  }
}

# transect.c:519
getFlow <- function(k, a, wp, findFlow) {
  k; a; wp; findFlow
  .G_Nchannel <- Nchannel; .G_Nleft <- Nleft; .G_Nright <- Nright; .G_Station <- Station; .G_Xleftbank <- Xleftbank; .G_Xrightbank <- Xrightbank
  n <- 0
  if (findFlow == 0) {
    if (k == (Nstations - 1)) {
      findFlow <- 1
    } else if (!is.na(.c <- (.G_Station$v[[k + 1]] == .G_Xleftbank)) && .c) {
      if ((is.na(.c <- (.G_Nleft != .G_Nchannel)) || .c) && (is.na(.c <- (.G_Station$v[[k + 1]] != .G_Station$v[[k]])) || .c)) {
        findFlow <- 1
      }
    } else if (!is.na(.c <- (.G_Station$v[[k + 1]] == .G_Xrightbank)) && .c) {
      if ((is.na(.c <- (.G_Nright != .G_Nchannel)) || .c) && (is.na(.c <- (.G_Station$v[[k + 1]] != .G_Station$v[[(k + 1) + 1]])) || .c)) {
        findFlow <- 1
      }
    }
  }
  if (findFlow != 0) {
    n <- .G_Nchannel
    if (!is.na(.c <- (.G_Station$v[[k]] < .G_Xleftbank)) && .c) {
      n <- .G_Nleft
    }
    if (!is.na(.c <- (.G_Station$v[[k + 1]] > .G_Xrightbank)) && .c) {
      n <- .G_Nright
    }
    return(((1.486 / n) * a) * (if ((.p <- a / wp) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666)))
  }
  return(0)
}

# transect.c:570
setMaxSectionFactor <- function(transect) {
  transect
  sf <- 0
  transect$aMax <- 0
  transect$sMax <- 0
  i <- 1
  while (i < transect$nTbl) {
    sf <- transect$areaTbl$v[[i + 1]] * (if ((.p <- transect$hradTbl$v[[i + 1]]) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666))
    if (!is.na(.c <- (sf > transect$sMax)) && .c) {
