      transect$aMax <- transect$areaTbl$v[[i + 1]]
    }
    i <- i + 1
  }
}

# transect.c:596
transect_createStreetTransect <- function(street) {
  street
  .G_Elev <- Elev; .G_Station <- Station
  ymin <- 0
  w1 <- street$backWidth
  w2 <- street$gutterWidth
  w3 <- street$width
  w4 <- w3 - w2
  y3 <- street$gutterDepression + (street$slope * w2)
  y1 <- street$curbHeight + street$gutterDepression
  ymax <- (street$backSlope * street$backWidth) + y1
  y4 <- y3 + (street$slope * w4)
  ymax <- if (!is.na(.c <- (ymax >= y4)) && .c) ymax else y4
  .G_Station$v[[1]] <- 0
  .G_Elev$v[[1]] <- ymax
  .G_Station$v[[2]] <- w1
  .G_Elev$v[[2]] <- y1
  .G_Station$v[[3]] <- w1
  .G_Elev$v[[3]] <- 0
  .G_Station$v[[4]] <- w1 + w2
  .G_Elev$v[[4]] <- y3
  .G_Station$v[[5]] <- w1 + w3
  .G_Elev$v[[5]] <- y4
  if (street$sides == 1) {
    .G_Station$v[[6]] <- .G_Station$v[[5]]
    .G_Elev$v[[6]] <- ymax
    Nstations <<- 5
    {.e1 <- street$transect; .e1$nTbl <- 51}
  } else {
    .G_Station$v[[6]] <- .G_Station$v[[5]] + w4
    .G_Elev$v[[6]] <- y3
    .G_Station$v[[7]] <- .G_Station$v[[6]] + w2
    .G_Elev$v[[7]] <- 0
    .G_Station$v[[8]] <- .G_Station$v[[7]]
    .G_Elev$v[[8]] <- y1
    .G_Station$v[[9]] <- .G_Station$v[[8]] + w1
    .G_Elev$v[[9]] <- ymax
    Nstations <<- 8
    {.e2 <- street$transect; .e2$nTbl <- 51}
  }
  Nchannel <<- street$roughness
  if (!is.na(.c <- (street$backWidth == 0)) && .c) {
    Nleft <<- Nchannel
    Nright <<- Nchannel
    Xleftbank <<- .G_Station$v[[1]]
    Xrightbank <<- .G_Station$v[[Nstations + 1]]
  } else {
    Nleft <<- street$backRoughness
    Nright <<- Nleft
    Xleftbank <<- .G_Station$v[[2]]
    if (street$sides == 2) {
      Xrightbank <<- .G_Station$v[[Nstations]]
    } else {
      Xrightbank <<- .G_Station$v[[Nstations + 1]]
    }
  }
  createTables(street$transect, ymin, ymax)
  {.e3 <- street$transect; .e3$roughness <- street$roughness}
}

