        next
      }
      treatment <- ((.G_Node[[j + 1]])$treatment)[[p + 1]]
      if (treatment$treatType == 0) {
        if (!is.na(.c <- (.G_Cin$v[[p + 1]] == 0)) && .c) {
          cOut <- ((.G_Node[[j + 1]])$newQual)$v[[p + 1]]
        } else {
