# treatmnt.c:288
createTreatment <- function(j) {
  j
  .G_Nobjects <- Nobjects; .G_Node <- Node
  {.e1 <- .G_Node[[j + 1]]; .e1$treatment <- rt_recs(rt_u64(.G_Nobjects$v[[5]]), T_TTreatment)}
  if (is.null((.G_Node[[j + 1]])$treatment)) {
    return(0)
  }
  p <- 0
  while (p < .G_Nobjects$v[[5]]) {
    {.e2 <- ((.G_Node[[j + 1]])$treatment)[[p + 1]]; .e2$equation <- NULL}
    p <- p + 1
  }
  return(1)
}

# treatmnt.c:311
treatmnt_getVariableIndex <- function(s) {
  s
  m <- PVMAX
  k <- findmatch(s, ProcessVarWords)
  if (k >= 0) {
    return(k)
  }
  k <- project_findObject(4, s)
  if (k >= 0) {
    return(k + m)
  }
  if (((if (((rt_cget(s, 0)) >= 97) && ((rt_cget(s, 0)) <= 122)) (rt_band((rt_cget(s, 0)), (-32 - 1))) else (rt_cget(s, 0))) == 82) && (rt_cget(s, 1) == 95)) {
    k <- project_findObject(4, rt_cadd(s, 2))
    if (k >= 0) {
      return((Nobjects$v[[5]] + k) + m)
    }
  }
  return(-1)
}

# treatmnt.c:340
treatmnt_getVariableValue <- function(varCode) {
  varCode
  .G_J <- J; .G_Nobjects <- Nobjects; .G_Node <- Node; .G_PVMAX <- PVMAX
  p <- 0
  a1 <- 0
  a2 <- 0
  y <- 0
  treatment <- NULL
  if (varCode < .G_PVMAX) {
    if (varCode == 0) {
      if ((.G_Node[[.G_J + 1]])$type == 2) {
        return((Storage[[(.G_Node[[.G_J + 1]])$subIndex + 1]])$hrt / 3600)
      } else {
        return(0)
      }
    } else if (varCode == 1) {
      return(Dt)
    } else if (varCode == 2) {
      return(Q * (UCF(10)))
    } else if (varCode == 3) {
      y <- ((.G_Node[[.G_J + 1]])$oldDepth + (.G_Node[[.G_J + 1]])$newDepth) / 2
      return(y * (UCF(3)))
    } else if (varCode == 4) {
      a1 <- node_getSurfArea(.G_J, (.G_Node[[.G_J + 1]])$oldDepth)
      a2 <- node_getSurfArea(.G_J, (.G_Node[[.G_J + 1]])$newDepth)
      return((((a1 + a2) / 2) * (UCF(3))) * (UCF(3)))
    } else {
      return(0)
    }
  } else if (varCode < (.G_PVMAX + .G_Nobjects$v[[5]])) {
    p <- varCode - .G_PVMAX
    treatment <- ((.G_Node[[.G_J + 1]])$treatment)[[p + 1]]
    if (treatment$treatType == 0) {
      return(Cin$v[[p + 1]])
    }
    return(((.G_Node[[.G_J + 1]])$newQual)$v[[p + 1]])
  } else {
    p <- (varCode - .G_PVMAX) - .G_Nobjects$v[[5]]
    if (p >= .G_Nobjects$v[[5]]) {
      return(0)
    }
    return(getRemoval(p))
  }
}

# treatmnt.c:404
getRemoval <- function(p) {
  p
  .G_J <- J; .G_Node <- Node; .G_R <- R
  c0 <- ((.G_Node[[.G_J + 1]])$newQual)$v[[p + 1]]
  if ((!is.na(.c <- (.G_R$v[[p + 1]] > 1)) && .c) || (ErrCode != 0)) {
    ErrCode <<- 1
    return(0)
  }
  if ((!is.na(.c <- (.G_R$v[[p + 1]] >= 0)) && .c) && (!is.na(.c <- (.G_R$v[[p + 1]] <= 1)) && .c)) {
    return(.G_R$v[[p + 1]])
  }
  .G_R$v[[p + 1]] <- 10
  if (!is.na(.c <- (c0 == 0)) && .c) {
    .G_R$v[[p + 1]] <- 0
    return(0)
  }
  treatment <- ((.G_Node[[.G_J + 1]])$treatment)[[p + 1]]
  r <- mathexpr_eval(treatment$equation, treatmnt_getVariableValue)
  r <- if (!is.na(.c <- (0 >= r)) && .c) 0 else r
  if (treatment$treatType == 0) {
    r <- if (!is.na(.c <- (1 <= r)) && .c) 1 else r
    .G_R$v[[p + 1]] <- r
  } else {
    r <- if (!is.na(.c <- (c0 <= r)) && .c) c0 else r
    .G_R$v[[p + 1]] <- 1 - (r / c0)
  }
  return(.G_R$v[[p + 1]])
}

