# xsect.c:664
xsect_setCustomXsectParams <- function(xsect) {
  xsect
  .G_Shape <- Shape
  index <- (Curve[[xsect$transect + 1]])$refersTo
  yFull <- xsect$yFull
  wTbl <- (.G_Shape[[index + 1]])$widthTbl
  xsect$wMax <- (.G_Shape[[index + 1]])$wMax * yFull
  xsect$aFull <- ((.G_Shape[[index + 1]])$aFull * yFull) * yFull
  xsect$rFull <- (.G_Shape[[index + 1]])$rFull * yFull
  xsect$sFull <- xsect$aFull * (if ((.p <- xsect$rFull) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666))
  xsect$sMax <- (((.G_Shape[[index + 1]])$sMax * yFull) * yFull) * (if ((.p <- yFull) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666))
  xsect$aBot <- ((.G_Shape[[index + 1]])$aMax * yFull) * yFull
  iMax <- 0
  wMax <- wTbl$v[[1]]
  i <- 1
  while (i < 51) {
    if (!is.na(.c <- (wTbl$v[[i + 1]] < wMax)) && .c) {
      break
    }
    wMax <- wTbl$v[[i + 1]]
    iMax <- i
    i <- i + 1
  }
  xsect$ywMax <- (yFull * iMax) / (51 - 1)
}

