# xsect.c:1100
xsect_getRofA <- function(xsect, a) {
  xsect; a
  cathy <- 0
  if (!is.na(.c <- (a <= 0)) && .c) {
    return(0)
  }
  .sw1 <- xsect$type
  if (.sw1 == 12 || .sw1 == 13 || .sw1 == 14 || .sw1 == 22 || .sw1 == 2 || .sw1 == 23 || .sw1 == 25) {
    return(xsect_getRofY(xsect, xsect_getYofA(xsect, a)))
  } else if (.sw1 == 3) {
    return(rect_closed_getRofA(xsect, a))
  } else if (.sw1 == 4) {
    return(a / (xsect$wMax + (((2 - xsect$sBot) * a) / xsect$wMax)))
  } else if (.sw1 == 9) {
    return(rect_triang_getRofA(xsect, a))
  } else if (.sw1 == 10) {
    return(rect_round_getRofA(xsect, a))
  } else if (.sw1 == 11) {
    return(mod_basket_getRofA(xsect, a))
  } else if (.sw1 == 5) {
    return(trapez_getRofA(xsect, a))
  } else if (.sw1 == 6) {
    return(triang_getRofA(xsect, a))
  } else if (.sw1 == 7) {
    return(parab_getRofA(xsect, a))
  } else if (.sw1 == 8) {
    return(powerfunc_getRofA(xsect, a))
  } else {
    cathy <- xsect_getSofA(xsect, a)
    if ((!is.na(.c <- (cathy < 1e-06)) && .c) || (!is.na(.c <- (a < 1e-06)) && .c)) {
      return(0)
    }
    return(if ((.p <- cathy / a) > -Inf || is.na(.p)) .p ^ 1.5 else rt_pow(.p, 1.5))
  }
}

