  y <- 0
  r <- 0
  if (!is.na(.c <- (q2g == 0)) && .c) {
    return(0)
  }
  .sw1 <- xsect$type
  if (.sw1 == 0) {
    return(0)
  } else if (.sw1 == 4 || .sw1 == 3) {
    y <- if ((.p <- q2g / (xsect$wMax * xsect$wMax)) > -Inf || is.na(.p)) .p ^ 0.3333333333333333 else rt_pow(.p, 0.3333333333333333)
  } else if (.sw1 == 6) {
    y <- if ((.p <- (2 * q2g) / (xsect$sBot * xsect$sBot)) > -Inf || is.na(.p)) .p ^ 0.2 else rt_pow(.p, 0.2)
  } else if (.sw1 == 7) {
    y <- if ((.p <- ((27 / 32) * q2g) / (xsect$rBot * xsect$rBot)) > -Inf || is.na(.p)) .p ^ 0.25 else rt_pow(.p, 0.25)
  } else if (.sw1 == 8) {
    y <- 1 / ((2 * xsect$sBot) + 3)
    y <- rt_pow((q2g * (xsect$sBot + 1)) / (xsect$rBot * xsect$rBot), y)
  } else {
    y <- 1.01 * (if ((.p <- q2g / xsect$yFull) > -Inf || is.na(.p)) .p ^ 0.25 else rt_pow(.p, 0.25))
    if (!is.na(.c <- (y >= xsect$yFull)) && .c) {
      y <- 0.97 * xsect$yFull
    }
    r <- xsect$aFull / ((3.141592654 / 4) * (xsect$yFull * xsect$yFull))
    if ((!is.na(.c <- (r >= 0.5)) && .c) && (!is.na(.c <- (r <= 2)) && .c)) {
      y <- getYcritEnum(xsect, q_, y)
    } else {
      y <- getYcritRidder(xsect, q_, y)
    }
  }
  return(if (!is.na(.c <- (y <= xsect$yFull)) && .c) y else xsect$yFull)
}

