# xsect.c:1424
tabular_getdSdA <- function(xsect, a, table_, nItems) {
  xsect; a; table_; nItems
  alpha <- a / xsect$aFull
  delta <- 1 / (nItems - 1)
  i <- if (is.na(.d <- alpha / delta) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  if (i >= (nItems - 1)) {
    i <- nItems - 2
  }
  dSdA <- (table_$v[[(i + 1) + 1]] - (table_$v[[i + 1]])) / delta
  return((dSdA * xsect$sFull) / xsect$aFull)
}

