# xsect.c:1474
lookup <- function(x, table_, nItems) {
  x; table_; nItems
  y2 <- 0
  delta <- 1 / (nItems - 1)
  i <- if (is.na(.d <- x / delta) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  if (i >= (nItems - 1)) {
    return(table_$v[[nItems]])
  }
  x0 <- i * delta
  x1 <- (i + 1) * delta
  y <- table_$v[[i + 1]] + (((x - x0) * (table_$v[[(i + 1) + 1]] - (table_$v[[i + 1]]))) / delta)
  if (i < 2) {
    y2 <- y + ((((x - x0) * (x - x1)) / (delta * delta)) * (((table_$v[[i + 1]] / 2) - (table_$v[[(i + 1) + 1]])) + (table_$v[[(i + 2) + 1]] / 2)))
    if (!is.na(.c <- (y2 > 0)) && .c) {
      y <- y2
    }
  }
  if (!is.na(.c <- (y < 0)) && .c) {
    y <- 0
  }
  return(y)
}

# xsect.c:1511
invLookup <- function(y, table_, nItems) {
  y; table_; nItems
  x <- 0
  i <- 0
  dx <- 1 / (nItems - 1)
  n <- nItems
  if (!is.na(.c <- (table_$v[[(n - 3) + 1]] > table_$v[[n]])) && .c) {
    n <- n - 2
  }
  if ((n < nItems) && (!is.na(.c <- (y > table_$v[[nItems]])) && .c)) {
    if (!is.na(.c <- (y >= table_$v[[(nItems - 3) + 1]])) && .c) {
      return((n - 1) * dx)
    }
    if (!is.na(.c <- (y <= table_$v[[(nItems - 2) + 1]])) && .c) {
      i <- nItems - 2
    } else {
      i <- nItems - 3
    }
  } else {
    i <- locate(y, table_, (n - 1))
  }
  if (i >= (n - 1)) {
    return((n - 1) * dx)
  }
  x0 <- i * dx
  dy <- table_$v[[(i + 1) + 1]] - (table_$v[[i + 1]])
  if (!is.na(.c <- (dy == 0)) && .c) {
    x <- x0
  } else {
    x <- x0 + (((y - (table_$v[[i + 1]])) * dx) / dy)
  }
  if (!is.na(.c <- (x < 0)) && .c) {
    x <- 0
  }
  if (!is.na(.c <- (x > 1)) && .c) {
    x <- 1
  }
  return(x)
}

