# xsect.c:1634
getYcritEnum <- function(xsect, q_, y0) {
  xsect; q_; y0
  qc <- 0
  yc <- 0
  i <- 0
  xsectStar <- T_TXsectStar()
  dy <- xsect$yFull / 25
  i1 <- if (is.na(.d <- y0 / dy) || .d >= 2147483648 || .d <= -2147483649) -2147483648 else trunc(.d)
  xsectStar$xsect <- xsect
  xsectStar$qc <- 0
  q0 <- getQcritical((i1 * dy), xsectStar)
  if (!is.na(.c <- (q0 < q_)) && .c) {
    yc <- xsect$yFull
    i <- i1 + 1
    while (i <= 25) {
      qc <- getQcritical((i * dy), xsectStar)
      if (!is.na(.c <- (qc >= q_)) && .c) {
        yc <- (((q_ - q0) / (qc - q0)) + (i - 1)) * dy
        break
      }
      q0 <- qc
      i <- i + 1
    }
  } else {
    yc <- 0
    i <- i1 - 1
    while (i >= 0) {
      qc <- getQcritical((i * dy), xsectStar)
      if (!is.na(.c <- (qc < q_)) && .c) {
        yc <- (((q_ - qc) / (q0 - qc)) + i) * dy
        break
      }
      q0 <- qc
      i <- i - 1
    }
  }
  return(yc)
}

