# xsect.c:2323
powerfunc_getPofY <- function(xsect, y) {
  xsect; y
  dy1 <- 0.02 * xsect$yFull
  h <- ((xsect$sBot + 1) * xsect$rBot) / 2
  m <- xsect$sBot
  p <- 0
  y1 <- 0
  x1 <- 0
  x2 <- 0
  y2 <- 0
  dx <- 0
  dy <- 0
  repeat {
    y2 <- y1 + dy1
    if (!is.na(.c <- (y2 > y)) && .c) {
      y2 <- y
    }
    x2 <- h * (rt_pow(y2, m))
    dx <- x2 - x1
    dy <- y2 - y1
    p <- p + (sqrt((dx * dx) + (dy * dy)))
    x1 <- x2
    y1 <- y2
    if (!(!is.na(.c <- (y2 < y)) && .c)) break
  }
  return(2 * p)
}

