# xsect.c:2531
getYcircular <- function(alpha) {
  alpha
  theta <- 0
  if (!is.na(.c <- (alpha >= 1)) && .c) {
    return(1)
  }
  if (!is.na(.c <- (alpha <= 0)) && .c) {
    return(0)
  }
  if (!is.na(.c <- (alpha <= 1e-05)) && .c) {
    theta <- if ((.p <- 37.6911 * alpha) > -Inf || is.na(.p)) .p ^ 0.3333333333333333 else rt_pow(.p, 0.3333333333333333)
    return((theta * theta) / 16)
  }
  theta <- getThetaOfAlpha(alpha)
  return((1 - (cos(theta / 2))) / 2)
}

