    return((if ((.p <- theta) > -Inf || is.na(.p)) .p ^ 4.333333333333333 else rt_pow(.p, 4.333333333333333)) / 124.4797)
  }
  theta <- getThetaOfAlpha(alpha)
  return(((if ((.p <- theta - (sin(theta))) > -Inf || is.na(.p)) .p ^ 1.6666666666666667 else rt_pow(.p, 1.6666666666666667)) / (2 * 3.141592654)) / (if ((.p <- theta) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666)))
}

