    return(((theta * theta) * theta) / 37.6911)
  }
  theta <- getThetaOfPsi(psi)
  return((theta - (sin(theta))) / (2 * 3.141592654))
}

# xsect.c:2573
getThetaOfAlpha <- function(alpha) {
  alpha
  theta <- 0
  d <- 0
  if (!is.na(.c <- (alpha > 0.04)) && .c) {
    theta <- 1.2 + ((5.08 * (alpha - 0.04)) / 0.96)
  } else {
    theta <- (0.031715 - (12.79384 * alpha)) + (8.28479 * (sqrt(alpha)))
  }
  theta1 <- theta
  ap <- (2 * 3.141592654) * alpha
  k <- 1
  while (k <= 40) {
    d <- (-((ap - theta) + sin(theta))) / (1 - (cos(theta)))
    if (!is.na(.c <- (d > 1)) && .c) {
      d <- if (!is.na(.c <- (d >= 0)) && .c) abs(1) else (-(abs(1)))
    }
    theta <- theta - d
    if (!is.na(.c <- (abs(d) <= 0.0001)) && .c) {
      return(theta)
    }
    k <- k + 1
  }
  return(theta1)
}

# xsect.c:2593
getThetaOfPsi <- function(psi) {
  psi
  theta <- 0
  tt <- 0
  tt23 <- 0
  t3 <- 0
  d <- 0
  if (!is.na(.c <- (psi > 0.9)) && .c) {
    theta <- 4.17 + ((1.12 * (psi - 0.9)) / 0.176)
  } else if (!is.na(.c <- (psi > 0.5)) && .c) {
    theta <- 3.14 + ((1.03 * (psi - 0.5)) / 0.4)
  } else if (!is.na(.c <- (psi > 0.015)) && .c) {
    theta <- 1.2 + ((1.94 * (psi - 0.015)) / 0.485)
  } else {
    theta <- (0.12103 - (55.5075 * psi)) + (15.62254 * (sqrt(psi)))
  }
  theta1 <- theta
  ap <- (2 * 3.141592654) * psi
  k <- 1
  while (k <= 40) {
    theta <- abs(theta)
    tt <- theta - (sin(theta))
    tt23 <- if ((.p <- tt) > -Inf || is.na(.p)) .p ^ 0.6666666666666666 else rt_pow(.p, 0.6666666666666666)
    t3 <- if ((.p <- theta) > -Inf || is.na(.p)) .p ^ 0.3333333333333333 else rt_pow(.p, 0.3333333333333333)
    d <- ((ap * theta) / t3) - (tt * tt23)
    d <- d / (((ap * (2 / 3)) / t3) - (((5 / 3) * tt23) * (1 - (cos(theta)))))
    theta <- theta - d
    if (!is.na(.c <- (abs(d) <= 0.0001)) && .c) {
      return(theta)
    }
    k <- k + 1
  }
  return(theta1)
}

